// ─────────────────────────────────────────────────────────────────────
// HELPER — label veicolo unificata: MODELLO · TARGA · rentmeId
// Mostra sempre sia la targa reale sia il codice RentMe finché
// non saremo completamente scollegati da RentMe.
// ─────────────────────────────────────────────────────────────────────
const makeVehicleLabel = (v) => {
  if (!v) return '';
  const vr = resolveVehicleDisplay(v);
  const parts = [vr.modello || vr.marca, vr.targa, vr.idRentme || vr.rentmeId].filter(Boolean);
  return parts.join(' · ');
};

// ─────────────────────────────────────────────────────────────────────
// HELPER — risolve targa e modello reali al momento del render.
// Nessuna mutazione di stato: lookup diretto da RENTME_TARGA_MAP.
// Necessario perché usePersistentState sovrascrive sempre lo stato
// locale con i dati del backend al mount, rendendo le migrazioni
// di stato inutili (race condition).
// ─────────────────────────────────────────────────────────────────────
function resolveVehicleDisplay(v) {
  if (!v) return v;
  // Chiavi candidate: idRentme/rentmeId, id del veicolo, targa (potrebbero essere codici RentMe)
  const candidates = [
    (v.idRentme || v.rentmeId || '').toLowerCase().trim(),
    (v.id || '').toLowerCase().trim(),
    (v.targa || '').toLowerCase().trim(),
  ].filter(Boolean);
  let entry = null;
  for (const k of candidates) {
    // Chiave esatta, poi indice per-numero (es. k="78" → "superior 78")
    entry = RENTME_TARGA_MAP[k] || RENTME_TARGA_BY_NUM[k];
    if (entry) break;
    // Prova anche solo la parte numerica ("panda 81" → "81")
    const num = k.split(' ').pop();
    if (num) {
      entry = RENTME_TARGA_MAP[num] || RENTME_TARGA_BY_NUM[num];
      if (entry) break;
    }
  }
  if (!entry) return v;
  // Pulizia modello: rimuovi prefisso tipo se presente
  const modelloPulito = entry.modello || v.modello || '';
  return {
    ...v,
    targa:   entry.targa,
    modello: modelloPulito,
  };
}

