// ReadonlyBanner — DRY: era ripetuto in Fleet, Customers, Partners
const ReadonlyBanner = memo(function ReadonlyBanner({ message }) {
  return (
    <div
      role="status"
      className="text-xs p-3 rounded mb-4 flex items-center gap-2"
      style={{ background: 'var(--surface-2)', color: 'var(--ink-2)' }}
    >
      <Lock className="w-3.5 h-3.5" aria-hidden="true" />
      {message}
    </div>
  );
});

// ─── OCR MRZ parser ──────────────────────────────────────────────────────────
// Estrae dati anagrafici dalla zona MRZ di CI / Passaporto / Patente italiana.
// Supporta: TD1 (CI 3×30), TD3 (Passaporto 2×44), fallback testo libero.
function parseMRZ(ocrText) {
  if (!ocrText) return null;

  // Normalizza: toUpperCase, sostituisci spazi con < per preservare allineamento
  const lines = ocrText
    .split('\n')
    .map(l => l.toUpperCase().replace(/\s/g, '<').replace(/[^A-Z0-9<]/g, '<'))
    .filter(l => l.replace(/<+/g, '').length > 8 && l.length >= 20);

  if (lines.length === 0) return null;

  const result = {};

  // Helper: decodifica nome da stringa MRZ "COGNOME<<NOME<ALTRO"
  function decodeName(raw) {
    const parts = raw.split('<<').map(p => p.replace(/</g, ' ').trim()).filter(Boolean);
    return { cognome: parts[0] || '', nome: parts.slice(1).join(' ') || '' };
  }

  // Helper: converte YYMMDD → DD/MM/YYYY (anno ≥ 2000 se YY<30, altrimenti 1900)
  function mrzDate(yymmdd) {
    if (!yymmdd || yymmdd.length < 6) return '';
    const yy = parseInt(yymmdd.slice(0, 2));
    const mm = yymmdd.slice(2, 4);
    const dd = yymmdd.slice(4, 6);
    const yyyy = yy < 30 ? 2000 + yy : 1900 + yy;
    return `${dd}/${mm}/${yyyy}`;
  }

  // Helper: converti codice ISO 3166-1 alpha-3 → nome nazione comune
  const NATION = {
    ITA: 'Italia', FRA: 'Francia', DEU: 'Germania', GBR: 'Regno Unito',
    ESP: 'Spagna', USA: 'USA', CHE: 'Svizzera', AUT: 'Austria',
    BEL: 'Belgio', NLD: 'Paesi Bassi', POL: 'Polonia', ROU: 'Romania',
    ALB: 'Albania', TUN: 'Tunisia', MAR: 'Marocco', SEN: 'Senegal',
    BRA: 'Brasile', ARG: 'Argentina', CHN: 'Cina', JPN: 'Giappone',
    RUS: 'Russia', UKR: 'Ucraina', TUR: 'Turchia', GRC: 'Grecia',
  };

  // TD3 — Passaporto: 2 righe da 44 char
  // Cerca le 2 righe MRZ anche se precedute da rumore OCR (immagine intera)
  const td3Candidates = lines.filter(l => l.length >= 44);
  for (let i = 0; i < td3Candidates.length - 1; i++) {
    const l1 = td3Candidates[i].padEnd(44, '<');
    const l2 = td3Candidates[i + 1].padEnd(44, '<');
    if (l1[0] === 'P') {
      const natCode = l1.slice(2, 5).replace(/</g, '');
      const names = decodeName(l1.slice(5, 44));
      result.cognome = names.cognome;
      result.nome = names.nome;
      result.cittadinanza = NATION[natCode] || natCode;
      result.docNum = l2.slice(0, 9).replace(/<+$/, '');
      result.docTipo = 'PA';
      result.nascita = mrzDate(l2.slice(13, 19));
      return result;
    }
  }

  // TD1 — Carta d'Identità: 3 righe da 30 char
  // Tipi validi: I (CIE standard), A (vecchia CI), C (alcuni formati CI/CIE 3.0)
  // Cerca le 3 righe MRZ anche se l'OCR ha prodotto righe extra (immagine intera)
  const td1Candidates = lines.filter(l => l.length >= 28);
  for (let i = 0; i < td1Candidates.length - 2; i++) {
    const l1 = td1Candidates[i].padEnd(30, '<');
    const l2 = td1Candidates[i + 1].padEnd(30, '<');
    const l3 = td1Candidates[i + 2].padEnd(30, '<');
    if (l1[0] === 'I' || l1[0] === 'A' || l1[0] === 'C') {
      const natCode = l1.slice(2, 5).replace(/</g, '') || 'ITA';
      result.docNum = l1.slice(5, 14).replace(/<+$/, '');
      result.docTipo = 'CI';
      result.nascita = mrzDate(l2.slice(0, 6));
      const natCode2 = l2.slice(15, 18).replace(/<+/g, '');
      result.cittadinanza = NATION[natCode2 || natCode] || (natCode2 || natCode);
      const names = decodeName(l3.slice(0, 30));
      result.cognome = names.cognome;
      result.nome = names.nome;
      // Risultato valido solo se almeno cognome o numero documento trovati
      if (result.cognome || result.docNum) return result;
    }
  }

  // Fallback: estrai quello che si riesce dal testo OCR libero
  // Prova a trovare sequenze che sembrano num.documento (8-10 alfanum)
  const docMatch = ocrText.match(/\b([A-Z]{2}\d{7}[A-Z]?)\b/);
  if (docMatch) result.docNum = docMatch[1];
  return Object.keys(result).length > 0 ? result : null;
}

// ─── Preprocessing immagine per OCR ──────────────────────────────────────────
// Converte l'immagine in scala di grigi e aumenta il contrasto prima di Tesseract.
// Migliora significativamente il riconoscimento su foto scattate con luce variabile
// o sfondo colorato. Restituisce una nuova dataURL ottimizzata per OCR.
function preprocessForOcr(dataUrl) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        canvas.width  = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0);
        // Scala di grigi via pixel manipulation
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const data = imageData.data;
        for (let i = 0; i < data.length; i += 4) {
          // Luminosità pesata (formula BT.601)
          const gray = 0.299 * data[i] + 0.587 * data[i + 1] + 0.114 * data[i + 2];
          // Contrasto: curva S leggera (aumenta separazione chiaro/scuro)
          const c = (gray - 128) * 1.4 + 128;
          const clamped = Math.max(0, Math.min(255, c));
          data[i] = data[i + 1] = data[i + 2] = clamped;
        }
        ctx.putImageData(imageData, 0, 0);
        resolve(canvas.toDataURL('image/jpeg', 0.95));
      } catch { resolve(dataUrl); }
    };
    img.onerror = () => resolve(dataUrl);
    img.src = dataUrl;
  });
}

// ─── Preprocessing MRZ ───────────────────────────────────────────────────────
// Ritaglia la zona inferiore dell'immagine dove si trova tipicamente la banda MRZ.
// Usato come secondo tentativo OCR se la prima passata (immagine intera) fallisce.
function cropMrzZone(dataUrl, fromFraction = 0.55) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        const startY = Math.floor(img.height * fromFraction);
        canvas.width  = img.width;
        canvas.height = img.height - startY;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, startY, img.width, canvas.height, 0, 0, img.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.95));
      } catch { resolve(dataUrl); }
    };
    img.onerror = () => resolve(dataUrl);
    img.src = dataUrl;
  });
}

// DocumentScanner — componente in-line per scansione documenti o QR cliente
// Supporta: fotocamera live (getUserMedia) + upload file da galleria.
// OCR Tesseract.js on-device: legge MRZ di CI/Passaporto e pre-compila i campi.
// mode: 'document' (CI/passaporto/patente) | 'qr' (codice cliente)
function DocumentScanner({ mode = 'document', customers, onPick, onUpload, onOcrResult }) {
  const [stage, setStage] = useState('idle'); // 'idle' | 'camera' | 'captured'
  const [snapshot, setSnapshot] = useState(null);
  const [uploaded, setUploaded] = useState(null);
  const [ocrRunning, setOcrRunning] = useState(false);
  const [ocrStatus, setOcrStatus] = useState('');  // messaggio di progresso
  const [ocrResult, setOcrResult] = useState(null); // dati estratti
  const fileInputRef = useRef(null);
  const { videoRef, error: camError, ready, capture } = useCameraStream(stage === 'camera');

  // OCR Tesseract on-device: riconosce MRZ documento e chiama onOcrResult.
  // Strategia a 2 passate:
  //   1ª passata — immagine intera, pageseg_mode 11 (sparse: trova tutto il testo
  //      anche in mezzo a foto/mappe/sfondi). Cattura MRZ se il documento è ben inquadrato.
  //   2ª passata — crop zona inferiore (55–100% altezza immagine) + pageseg_mode 6
  //      (blocco uniforme). Funziona quando la 1ª passata produce rumore dall'immagine
  //      completa (sfondo, mappa, foto tessera, barcode ecc.).
  const runDocOcr = async (dataUrl) => {
    if (mode !== 'document') return;
    setOcrRunning(true);
    setOcrStatus('⏳ Caricamento motore OCR…');
    let worker;
    try {
      // OEM 3 = LSTM + Tesseract combinati — più robusto per font MRZ fissi
      worker = await Tesseract.createWorker('eng', 3, {
        logger: m => {
          if (m.status === 'recognizing text') {
            setOcrStatus(`🔍 Analisi testo… ${Math.round((m.progress || 0) * 100)}%`);
          }
        },
      });
      const MRZ_WHITELIST = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789<';

      // ── Preprocessing: scala di grigi + contrasto ─────────────────
      setOcrStatus('🔍 Ottimizzazione immagine…');
      const processedUrl = await preprocessForOcr(dataUrl);

      // ── 1ª PASSATA: immagine intera preprocessata, sparse ─────────
      setOcrStatus('🔍 Lettura documento (1/2)…');
      await worker.setParameters({
        tessedit_char_whitelist: MRZ_WHITELIST,
        tessedit_pageseg_mode: 11, // sparse text — trova righe ovunque nell'immagine
      });
      const { data: { text: fullText } } = await worker.recognize(processedUrl);
      let parsed = parseMRZ(fullText);

      // ── 2ª PASSATA: crop zona MRZ 72% (banda bassa), riga singola ─
      if (!parsed || !Object.keys(parsed).length) {
        setOcrStatus('🔍 Lettura zona MRZ (2/2)…');
        // 0.72 = crop più aggressivo, la MRZ è nell'ultimo 28% del documento
        const croppedUrl = await cropMrzZone(processedUrl, 0.72);
        await worker.setParameters({
          tessedit_char_whitelist: MRZ_WHITELIST,
          tessedit_pageseg_mode: 6, // blocco uniforme — ottimale per righe MRZ isolate
        });
        const { data: { text: croppedText } } = await worker.recognize(croppedUrl);
        parsed = parseMRZ(croppedText);
      }

      if (parsed && Object.keys(parsed).length > 0) {
        setOcrResult(parsed);
        setOcrStatus('✅ Dati estratti — verifica e conferma');
        if (onOcrResult) onOcrResult(parsed);
      } else {
        setOcrStatus('⚠️ MRZ non rilevata — compila manualmente');
      }
    } catch (err) {
      setOcrStatus('⚠️ OCR non riuscito — compila manualmente');
      console.warn('Tesseract OCR error:', err);
    } finally {
      if (worker) await worker.terminate().catch(() => {});
      setOcrRunning(false);
    }
  };

  const handleCapture = () => {
    const dataUrl = capture();
    if (dataUrl) {
      setSnapshot(dataUrl);
      setStage('captured');
      setOcrResult(null);
      setOcrStatus('');
      if (onUpload) onUpload(null, dataUrl);
      runDocOcr(dataUrl);
    }
  };

  const handleFileUpload = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const dataUrl = ev.target.result;
      setUploaded({ name: file.name, dataUrl });
      setOcrResult(null);
      setOcrStatus('');
      if (onUpload) onUpload(file, dataUrl);
      runDocOcr(dataUrl);
    };
    reader.readAsDataURL(file);
  };

  const reset = () => {
    setSnapshot(null);
    setUploaded(null);
    setStage('idle');
    setOcrResult(null);
    setOcrStatus('');
    setOcrRunning(false);
  };

  const labelDoc = mode === 'qr' ? 'codice cliente' : 'documento d\'identità';
  const hintText = mode === 'qr'
    ? 'Inquadra il QR del cliente o carica uno screenshot ricevuto via WhatsApp'
    : 'Inquadra CI / passaporto / patente sul lato MRZ, oppure carica una foto dalla galleria';

  // Stato idle: due grandi bottoni
  if (stage === 'idle' && !snapshot && !uploaded) {
    return (
      <div className="card-paper p-5 mb-6">
        <div className="text-[11px] uppercase tracking-widest mb-3 flex items-center gap-2" style={{ color: 'var(--muted)' }}>
          {mode === 'qr' ? <QrCode className="w-3.5 h-3.5" /> : <ScanLine className="w-3.5 h-3.5" />}
          Acquisisci {labelDoc}
        </div>
        <div className="text-xs mb-3" style={{ color: 'var(--ink-2)' }}>{hintText}</div>
        {mode === 'document' && (
          <div className="mb-4 rounded p-3" style={{ background: 'var(--surface-2)', border: '1px solid var(--border)' }}>
            <div className="text-[11px] font-semibold mb-2" style={{ color: 'var(--ink-1)' }}>📋 Come fotografare il documento</div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
              <div className="text-[11px]" style={{ color: 'var(--ink-2)' }}>✅ Lato con le <strong>due o tre righe</strong> di codici in basso (banda MRZ)</div>
              <div className="text-[11px]" style={{ color: 'var(--ink-2)' }}>✅ <strong>Luce uniforme</strong>, evita riflessi e ombre</div>
              <div className="text-[11px]" style={{ color: 'var(--ink-2)' }}>✅ Documento <strong>piatto</strong>, non piegato</div>
              <div className="text-[11px]" style={{ color: 'var(--ink-2)' }}>✅ <strong>Sfondo scuro</strong> o neutro dietro il documento</div>
            </div>
          </div>
        )}
        <div className="grid grid-cols-2 gap-3">
          <button
            type="button"
            onClick={() => setStage('camera')}
            className="card-paper p-5 hover:border-[var(--ink)] transition-all text-center group"
            style={{ borderColor: 'var(--border)' }}
          >
            <Camera className="w-7 h-7 mx-auto mb-2" style={{ color: 'var(--accent)' }} />
            <div className="font-medium text-sm">Fotocamera</div>
            <div className="text-[11px] mt-1" style={{ color: 'var(--muted)' }}>Scansione live</div>
          </button>
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="card-paper p-5 hover:border-[var(--ink)] transition-all text-center group"
            style={{ borderColor: 'var(--border)' }}
          >
            <Upload className="w-7 h-7 mx-auto mb-2" style={{ color: 'var(--sea)' }} />
            <div className="font-medium text-sm">Carica file</div>
            <div className="text-[11px] mt-1" style={{ color: 'var(--muted)' }}>JPG, PNG, PDF</div>
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*,application/pdf"
            className="hidden"
            onChange={handleFileUpload}
          />
        </div>
      </div>
    );
  }

  // Stato camera: video live + cattura
  if (stage === 'camera') {
    return (
      <div className="card-paper p-5 mb-6">
        <div className="flex items-center justify-between mb-3">
          <div className="text-[11px] uppercase tracking-widest flex items-center gap-2" style={{ color: 'var(--muted)' }}>
            <Camera className="w-3.5 h-3.5" /> Fotocamera live
            {ready && (
              <span className="pill pill-ok ml-2">
                <CircleDot className="w-3 h-3" /> Pronta
              </span>
            )}
          </div>
          <button type="button" onClick={reset} className="btn-ghost px-2 py-1 rounded text-xs">
            <X className="w-3.5 h-3.5 inline" /> Annulla
          </button>
        </div>
        {camError ? (
          <div className="p-6 rounded text-center" style={{ background: 'var(--surface-2)' }}>
            <AlertCircle className="w-8 h-8 mx-auto mb-2" style={{ color: 'var(--warning)' }} />
            <div className="text-sm font-medium mb-1">Fotocamera non disponibile</div>
            <div className="text-xs mb-3" style={{ color: 'var(--ink-2)' }}>{camError}</div>
            <button type="button" onClick={() => fileInputRef.current?.click()} className="btn-primary px-4 py-2 rounded text-sm font-semibold inline-flex items-center gap-2">
              <Upload className="w-4 h-4" /> Carica un file
            </button>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*,application/pdf"
              className="hidden"
              onChange={(e) => { handleFileUpload(e); setStage('idle'); }}
            />
          </div>
        ) : (
          <>
            <div className="relative rounded overflow-hidden" style={{ background: '#000', aspectRatio: '4/3' }}>
              <video ref={videoRef} className="w-full h-full object-cover" playsInline muted />
              {/* Overlay guida documento */}
              <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center">
                <div className="w-[85%] h-[55%] border-2 border-dashed rounded" style={{ borderColor: 'rgba(255,220,50,0.85)' }} />
                {mode === 'document' && (
                  <div className="mt-2 px-3 py-1 rounded text-[10px] font-medium" style={{ background: 'rgba(0,0,0,0.6)', color: '#ffd700' }}>
                    Inquadra il lato con i codici MRZ (righe in fondo)
                  </div>
                )}
              </div>
              <div className="absolute bottom-2 left-2 right-2 text-center">
                <div className="inline-block px-3 py-1 rounded text-[11px]" style={{ background: 'rgba(0,0,0,0.6)', color: '#fff' }}>
                  Allinea {labelDoc} nel riquadro
                </div>
              </div>
            </div>
            <div className="flex gap-2 mt-3">
              <button
                type="button"
                onClick={handleCapture}
                disabled={!ready}
                className="btn-primary px-4 py-2.5 rounded text-sm font-semibold flex-1 inline-flex items-center justify-center gap-2 disabled:opacity-40"
              >
                <Camera className="w-4 h-4" /> Scatta
              </button>
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="btn-ghost px-4 py-2.5 rounded text-sm border inline-flex items-center gap-2"
                style={{ borderColor: 'var(--border)' }}
              >
                <Upload className="w-4 h-4" /> File
              </button>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*,application/pdf"
                className="hidden"
                onChange={(e) => { handleFileUpload(e); setStage('idle'); }}
              />
            </div>
          </>
        )}
      </div>
    );
  }

  // Stato post-scatto o post-upload: anteprima + OCR feedback
  const previewSrc = snapshot || uploaded?.dataUrl;
  const previewName = snapshot ? 'snapshot dalla fotocamera' : uploaded?.name;

  return (
    <div className="card-paper p-5 mb-6">
      <div className="flex items-center justify-between mb-3">
        <div className="text-[11px] uppercase tracking-widest flex items-center gap-2"
          style={{ color: ocrResult ? 'var(--success)' : 'var(--muted)' }}>
          {ocrResult ? <CheckCircle2 className="w-3.5 h-3.5" /> : <ScanLine className="w-3.5 h-3.5" />}
          {ocrResult ? 'Dati estratti' : 'Acquisito'}
        </div>
        <button type="button" onClick={reset} className="btn-ghost px-2 py-1 rounded text-xs inline-flex items-center gap-1">
          <RefreshCw className="w-3.5 h-3.5" /> Ricomincia
        </button>
      </div>
      {previewSrc && previewSrc.startsWith('data:image') ? (
        <img src={previewSrc} alt={previewName} className="w-full rounded"
          style={{ maxHeight: 220, objectFit: 'contain', background: 'var(--surface-2)',
            opacity: ocrRunning ? 0.6 : 1, transition: 'opacity .3s' }} />
      ) : (
        <div className="p-6 rounded text-center" style={{ background: 'var(--surface-2)' }}>
          <FileCheck2 className="w-8 h-8 mx-auto mb-2" style={{ color: 'var(--success)' }} />
          <div className="text-sm font-medium">{previewName}</div>
        </div>
      )}

      {/* Status OCR / risultato */}
      {mode === 'document' && (
        <div className="mt-3">
          {(ocrRunning || ocrStatus) && (
            <div className="p-3 rounded text-[11px] flex items-start gap-2 mb-2"
              style={{ background: ocrResult ? 'rgba(46,110,62,.08)' : 'var(--surface-2)',
                color: ocrResult ? 'var(--success)' : 'var(--ink-2)',
                border: ocrResult ? '1px solid var(--success)' : 'none' }}>
              {ocrRunning && <span className="animate-spin inline-block mr-1">⏳</span>}
              <span>{ocrStatus || '🔍 OCR in corso…'}</span>
            </div>
          )}
          {ocrResult && (
            <div className="p-3 rounded text-xs space-y-1"
              style={{ background: 'rgba(46,110,62,.06)', border: '1px solid rgba(46,110,62,.2)' }}>
              <div className="font-semibold text-[11px] uppercase tracking-wider mb-2"
                style={{ color: 'var(--success)' }}>Dati rilevati — campi pre-compilati ↓</div>
              {ocrResult.cognome  && <div><span style={{ color: 'var(--muted)' }}>Cognome:</span> <strong>{ocrResult.cognome}</strong></div>}
              {ocrResult.nome     && <div><span style={{ color: 'var(--muted)' }}>Nome:</span> <strong>{ocrResult.nome}</strong></div>}
              {ocrResult.nascita  && <div><span style={{ color: 'var(--muted)' }}>Nascita:</span> <strong>{ocrResult.nascita}</strong></div>}
              {ocrResult.cittadinanza && <div><span style={{ color: 'var(--muted)' }}>Cittadinanza:</span> <strong>{ocrResult.cittadinanza}</strong></div>}
              {ocrResult.docNum   && <div><span style={{ color: 'var(--muted)' }}>N. documento:</span> <strong className="font-mono">{ocrResult.docNum}</strong></div>}
              {ocrResult.docTipo  && <div><span style={{ color: 'var(--muted)' }}>Tipo:</span> <strong>{TIPO_DOC[ocrResult.docTipo] || ocrResult.docTipo}</strong></div>}
            </div>
          )}
          {!ocrRunning && !ocrStatus && (
            <div className="p-3 rounded text-[11px] flex items-start gap-2"
              style={{ background: 'var(--surface-2)', color: 'var(--ink-2)' }}>
              <Info className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
              <span>OCR on-device · nessun dato inviato in rete · MRZ di CI, Passaporto</span>
            </div>
          )}
        </div>
      )}
      {mode === 'qr' && (
        <div className="mt-3 p-3 rounded text-[11px] flex items-start gap-2"
          style={{ background: 'var(--surface-2)', color: 'var(--ink-2)' }}>
          <Info className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
          <span>Seleziona il cliente dalla lista oppure compila i campi manualmente.</span>
        </div>
      )}
    </div>
  );
}

// ModalShell — DRY header/body/footer shared by all modals
function ModalShell({ id, title, subtitle, onClose, children, footer, maxWidth = 'max-w-2xl' }) {
  // Chiudi con Escape
  useEffect(() => {
    const handler = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [onClose]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center fade-in"
      style={{ background: 'rgba(26,24,21,0.55)' }}
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby={id}
    >
      <div
        className={`card-paper w-full ${maxWidth} slide-up max-h-[92vh] flex flex-col`}
        onClick={e => e.stopPropagation()}
      >
        <div className="px-6 py-4 border-b flex items-center justify-between" style={{ borderColor: 'var(--border)' }}>
          <div>
            {subtitle && <div className="text-[11px] uppercase tracking-widest" style={{ color: 'var(--muted)' }}>{subtitle}</div>}
            <h3 id={id} className="serif text-xl font-medium">{title}</h3>
          </div>
          <button type="button" onClick={onClose} className="btn-ghost p-2 rounded" aria-label="Chiudi">
            <X className="w-5 h-5" aria-hidden="true" />
          </button>
        </div>
        <div className="overflow-y-auto p-6 flex-1">{children}</div>
        {footer && (
          <div className="px-6 py-4 border-t flex items-center justify-end gap-2" style={{ borderColor: 'var(--border)' }}>
            {footer}
          </div>
        )}
      </div>
    </div>
  );
}

// ConfirmModal — sostituisce window.confirm() con un modale coerente.
// Mobile-friendly (no alert nativo iOS) e stilizzato come il resto dell'app.
// Variant 'danger' (rosso) per eliminazioni, 'warning' (giallo) per azioni reversibili.
function ConfirmModal({ title, message, confirmLabel = 'Conferma', cancelLabel = 'Annulla', variant = 'danger', icon: Icon = AlertTriangle, onConfirm, onClose }) {
  const tone = {
    danger:  { color: 'var(--accent)',  bg: 'var(--surface-2)', btnClass: 'btn-accent' },
    warning: { color: 'var(--warning)', bg: 'var(--surface-2)', btnClass: 'btn-primary' },
    info:    { color: 'var(--sea)',     bg: 'var(--surface-2)', btnClass: 'btn-primary' },
  }[variant] || { color: 'var(--accent)', bg: 'var(--surface-2)', btnClass: 'btn-accent' };

  return (
    <ModalShell
      id="confirm-title"
      title={title}
      subtitle="Conferma azione"
      onClose={onClose}
      maxWidth="max-w-md"
      footer={
        <>
          <button type="button" onClick={onClose} className="btn-ghost px-4 py-2 rounded text-sm">{cancelLabel}</button>
          <button type="button" onClick={() => { onConfirm(); onClose(); }} className={`${tone.btnClass} px-4 py-2 rounded text-sm font-semibold inline-flex items-center gap-2`}>
            {confirmLabel}
          </button>
        </>
      }
    >
      <div className="flex items-start gap-3">
        <div className="w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0" style={{ background: tone.bg, color: tone.color }}>
          <Icon className="w-5 h-5" aria-hidden="true" />
        </div>
        <div className="text-sm leading-relaxed" style={{ color: 'var(--ink-2)' }}>{message}</div>
      </div>
    </ModalShell>
  );
}

// Toast — feedback non-bloccante per azioni completate.
// Si auto-chiude dopo 3 secondi. Click sul toast per chiuderlo subito.
function Toast({ toast, onDismiss }) {
  useEffect(() => {
    const t = setTimeout(onDismiss, toast.duration || 3000);
    return () => clearTimeout(t);
  }, [toast, onDismiss]);

  const tones = {
    success: { bg: '#e8f0db', border: 'var(--success)', icon: CheckCircle2 },
    info:    { bg: '#e2eef2', border: 'var(--sea)',     icon: Info },
    warning: { bg: '#f4ebd8', border: 'var(--warning)', icon: AlertTriangle },
    error:   { bg: '#f4d8d8', border: 'var(--accent)',  icon: AlertCircle },
  };
  const t = tones[toast.tone] || tones.success;
  const Icon = t.icon;

  return (
    <button
      type="button"
      onClick={onDismiss}
      className="card-paper px-4 py-3 flex items-start gap-3 slide-up text-left max-w-sm cursor-pointer hover:shadow-lg transition-shadow"
      style={{ background: t.bg, borderLeft: `3px solid ${t.border}` }}
      role="status"
      aria-live="polite"
    >
      <Icon className="w-4 h-4 flex-shrink-0 mt-0.5" style={{ color: t.border }} aria-hidden="true" />
      <div className="flex-1 min-w-0">
        {toast.title && <div className="font-medium text-sm">{toast.title}</div>}
        <div className="text-xs" style={{ color: 'var(--ink-2)' }}>{toast.message}</div>
      </div>
      <X className="w-3.5 h-3.5 flex-shrink-0 mt-0.5 opacity-50" aria-hidden="true" />
    </button>
  );
}

// ToastContainer — fixed bottom-right, stacka i toast attivi.
function ToastContainer({ toasts, dismiss }) {
  if (!toasts.length) return null;
  return (
    <div className="fixed bottom-6 right-6 flex flex-col gap-2 z-[60]" aria-label="Notifiche">
      {toasts.map(t => <Toast key={t.id} toast={t} onDismiss={() => dismiss(t.id)} />)}
    </div>
  );
}

// BillingForm — DRY: era duplicato in Step2Customer e NewCustomerModal
function BillingForm({ fatturazione, onChange }) {
  const upd = (k, v) => onChange({ ...fatturazione, [k]: v });
  return (
    <div className="space-y-3 fade-in">
      <div className="grid grid-cols-2 gap-2">
        {['privato', 'azienda'].map(tipo => (
          <button
            key={tipo}
            type="button"
            onClick={() => upd('tipo', tipo)}
            className={`p-2.5 rounded border text-sm text-left transition-all ${fatturazione.tipo === tipo ? 'border-[var(--ink)] bg-[var(--surface)]' : 'border-[var(--border)] bg-white'}`}
            aria-pressed={fatturazione.tipo === tipo}
          >
            {tipo === 'privato'
              ? <User className="w-4 h-4 mb-1" style={{ color: fatturazione.tipo === 'privato' ? 'var(--accent)' : 'var(--muted)' }} aria-hidden="true" />
              : <Building2 className="w-4 h-4 mb-1" style={{ color: fatturazione.tipo === 'azienda' ? 'var(--accent)' : 'var(--muted)' }} aria-hidden="true" />
            }
            <div className="font-medium text-xs capitalize">{tipo === 'azienda' ? 'Azienda · libero professionista' : 'Privato'}</div>
          </button>
        ))}
      </div>

      {fatturazione.tipo === 'azienda' && (
        <div className="grid grid-cols-2 gap-3">
          <FormField label="Ragione sociale" req value={fatturazione.ragioneSociale || ''} onChange={v => upd('ragioneSociale', v)} />
          <FormField label="Partita IVA" req value={fatturazione.piva || ''} onChange={v => upd('piva', v)} mono />
        </div>
      )}

      <div className="grid grid-cols-2 gap-3">
        <FormField label="Codice fiscale" req={fatturazione.tipo === 'privato'} value={fatturazione.cf || ''} onChange={v => upd('cf', v.toUpperCase())} mono />
        <FormField label="Indirizzo fatturazione" req value={fatturazione.indirizzo || ''} onChange={v => upd('indirizzo', v)} placeholder="Via, n., CAP, Città" />
      </div>

      {fatturazione.tipo === 'azienda' && (
        <>
          <div className="text-[11px] uppercase tracking-wider font-semibold mt-2" style={{ color: 'var(--muted)' }}>Fatturazione elettronica</div>
          <div className="grid grid-cols-2 gap-3">
            <FormField label="Codice SDI" value={fatturazione.sdi || ''} onChange={v => upd('sdi', v.toUpperCase())} mono placeholder="7 caratteri" hint="alfanumerico, fornito dal cliente" />
            <FormField label="PEC fatturazione" value={fatturazione.pec || ''} onChange={v => upd('pec', v)} type="email" placeholder="...@pec.it" hint="alternativa al codice SDI" />
          </div>
          <div className="text-[10px] flex items-start gap-2 p-2 rounded" style={{ background: 'var(--surface-2)', color: 'var(--ink-2)' }}>
            <Info className="w-3 h-3 flex-shrink-0 mt-0.5" aria-hidden="true" />
            <span>Almeno uno tra SDI e PEC è richiesto per la fatturazione elettronica (D.Lgs. 127/2015). Se mancanti, si usa <span className="mono">0000000</span>.</span>
          </div>
        </>
      )}
    </div>
  );
}

// Toggle (riutilizzabile per Admin, Billing)
function Toggle({ checked, onChange, label }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
      className={`relative w-11 h-6 rounded-full transition-all focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-[var(--ink)] ${checked ? 'bg-[var(--ink)]' : 'bg-[var(--border-strong)]'}`}
    >
      <span className={`absolute top-0.5 w-5 h-5 rounded-full bg-white transition-all ${checked ? 'left-5' : 'left-0.5'}`} />
    </button>
  );
}

// ═══════════════════════════════════════════════════════════════════
// APP ROOT
// ═══════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════
// PRENOTAZIONI — modulo prenotazioni/calendario (v0.13)
// Ponte tra EDOX (booking management) e Pratica (contratti/CARGOS).
// Flusso: Preventivo → Prenotazione → [cliente arriva] → Converti in pratica
// Schema record:
//   { id, createdAt, updatedAt, operatorId,
//     clienteId, clienteNome, clienteCognome, clienteTel,
//     vehicleId, vehicleLabel, vehicleType,
//     dal, al, stato, fonte, prezzo, acconto, contractId, note }
// ═══════════════════════════════════════════════════════════════════

const PRENO_STATI = {
  attesa:      { label: 'In attesa',  color: '#b87333', bg: '#fdf3e3', dot: '#e9a44c' },
  confermata:  { label: 'Confermata', color: '#2e6e3e', bg: '#eaf4ec', dot: '#4a9e5c' },
  in_corso:    { label: 'In corso',   color: '#1f5d83', bg: '#e8f2f9', dot: '#3a8bbf' },
  completata:  { label: 'Completata', color: '#5a5047', bg: '#f2ede8', dot: '#9a8a78' },
  cancellata:  { label: 'Cancellata', color: '#8a3030', bg: '#faeaea', dot: '#c85050' },
};

// Vocabolario unico delle fonti prenotazione (source of truth). Copre sia i
// valori selezionabili a mano sia quelli scritti da codice (banco rapido,
// calendario, preventivi, RentMe, migrazioni legacy).
const PRENO_FONTI = {
  diretto:       'Diretto',
  walk_in:       'Walk-in',
  telefono:      'Telefono',
  whatsapp:      'WhatsApp',
  online:        'Online',
  sito:          'Sito web',
  email:         'Email',
  preventivo:    'Preventivo',
  calendario:    'Calendario',
  sostituzione:  'Sostituzione',
  rentme:        'RentMe',
  rentme_storico:'RentMe (storico)',
  tour_operator: 'Tour operator',
  referral:      'Referral',
  manuale:       'Manuale',
};

// Sottoinsieme mostrato nel dropdown del form (solo fonti scelte a mano).
const FONTI_SELEZIONABILI = ['diretto', 'walk_in', 'telefono', 'whatsapp', 'online', 'sito', 'email', 'tour_operator', 'referral'];

// Alias di valori legacy → chiave canonica (es. vecchio dropdown scriveva "walkin").
const FONTE_ALIAS = { walkin: 'walk_in' };
const normFonte = f => FONTE_ALIAS[f] || f || 'diretto';
const fonteLabel = f => {
  const k = normFonte(f);
  return PRENO_FONTI[k] || (k ? k.charAt(0).toUpperCase() + k.slice(1).replace(/_/g, ' ') : '—');
};

function prenoId() {
  return 'pr' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

// ── Stato pagamento prenotazione ─────────────────────────────────────
// Restituisce { pagato, residuo, completato, colore }
function statoPagamento(p) {
  const totale  = p.prezzo  != null ? Number(p.prezzo)  : null;
  const acconto = p.acconto != null ? Number(p.acconto) : 0;
  const saldato = p.saldato != null ? Number(p.saldato) : 0;
  const pagato  = acconto + saldato;
  if (totale == null) return { pagato, residuo: null, completato: false, colore: '#888' };
  const residuo     = Math.max(0, totale - pagato);
  const completato  = residuo === 0;
  const colore      = completato ? '#4a6a30' : pagato > 0 ? '#b07820' : '#c83434';
  return { pagato, residuo, totale, completato, colore };
}

// ── Codice prenotazione univoco 6 caratteri alfanumerici ─────────────
// Es. A987SA — generato alla creazione del preventivo, segue fino alla
// conferma prenotazione. Un solo codice per tutto il ciclo del noleggio.
function generateBookingCode() {
  const C = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no 0/O/1/I per chiarezza visiva
  let s = '';
  for (let i = 0; i < 6; i++) s += C[Math.floor(Math.random() * C.length)];
  return s;
}

// ── Colore cliente per timeline Gantt ────────────────────────────────
// Stesso cliente → stesso colore in tutta la griglia.
const CLIENTE_PALETTE = [
  '#c0392b','#e67e22','#d4a017','#27ae60','#16a085',
  '#2980b9','#8e44ad','#d35400','#1abc9c','#546e7a',
  '#e91e63','#ff5722','#6d4c41','#00897b','#1565c0',
  '#4caf50','#f57c00','#7b1fa2','#283593','#c62828',
];
function clienteColorHash(key) {
  if (!key) return CLIENTE_PALETTE[0];
  let h = 0;
  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) & 0x7fffffff;
  return CLIENTE_PALETTE[h % CLIENTE_PALETTE.length];
}

function formatDate(d) {
  if (!d || typeof d !== 'string') return '—';
  const parts = d.split('-');
  if (parts.length < 3) return d; // data malformata: mostra così com'è
  const [y, m, g] = parts;
  if (!y || !m || !g) return d;
  return `${g}/${m}/${y}`;
}

function daysDiff(dal, al) {
  if (!dal || !al) return 0;
  return Math.max(1, Math.round((new Date(al) - new Date(dal)) / 86400000) + 1);
}

// Formatta un numero come importo euro — restituisce '—' se il valore è NaN/null/undefined
function fmtEuro(n) {
  const num = typeof n === 'string' ? parseFloat(n) : n;
  if (num == null || isNaN(num)) return '—';
  return num % 1 === 0 ? String(num) : num.toFixed(2);
}

// Restituisce la data locale di oggi come YYYY-MM-DD.
// ⚠️  new Date().toISOString() usa UTC: tra mezzanotte e le 2 AM in Italia
//     restituisce IERI. Usiamo i metodi local getFullYear/getMonth/getDate.
function todayISO() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
// Restituisce la data locale di oggi + offsetDays come YYYY-MM-DD.
function localDateISO(offsetDays = 0) {
  const d = new Date();
  d.setDate(d.getDate() + offsetDays);
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

// ── PrenoStatPill ────────────────────────────────────────────────────
function PrenoStatPill({ stato }) {
  const s = PRENO_STATI[stato] || PRENO_STATI.attesa;
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: 5,
      padding: '2px 8px', borderRadius: 20,
      fontSize: 11, fontWeight: 600, letterSpacing: '0.02em',
      color: s.color, background: s.bg,
    }}>
      <span style={{ width: 6, height: 6, borderRadius: '50%', background: s.dot, flexShrink: 0 }} />
      {s.label}
    </span>
  );
}

// ── PrenoCard ────────────────────────────────────────────────────────
function PrenoCard({ p, onEdit, onConvert, onDelete, onFoto, onContratto, onFirma, onSaldo, onSaldoRapido, onDeposito, onRientro, onRiconsegna, onProroga, onSostituzione, onConsegna, onRicrea, onDuplica, onVediGruppo, onWaConferma, rentmePush, rentmeVehicles, pushToast, agency }) {
  const giorni = daysDiff(p.dal, p.al);
  const [saldoRapidoOpen, setSaldoRapidoOpen] = useState(false);
  const [pagamentoOpen, setPagamentoOpen] = useState(false);
  const sp = statoPagamento(p);

  // Genera messaggio pagamento via bonifico / PayPal
  const buildPagamentoMsg = useCallback(() => {
    const ag = agency || {};
    const cliente = [p.clienteCognome, p.clienteNome].filter(Boolean).join(' ') || 'Cliente';
    const importo = sp.residuo > 0 ? sp.residuo : (Number(p.prezzo)||0);
    const causale = `Noleggio ${p.id || ''} ${cliente} ${p.dal || ''}-${p.al || ''}`.trim();
    let msg = `💳 Pagamento noleggio — *${cliente}*\n`;
    msg += `Importo da saldare: *€${importo}*\n\n`;
    if (ag.iban) {
      msg += `🏦 *Bonifico bancario*\nIBAN: \`${ag.iban}\`\n`;
      if (ag.intestatario) msg += `Intestatario: ${ag.intestatario}\n`;
      if (ag.bic) msg += `BIC/SWIFT: ${ag.bic}\n`;
      msg += `Causale: _${causale}_\n\n`;
    }
    if (ag.paypalMe) {
      msg += `🅿️ *PayPal.me*\nhttps://paypal.me/${ag.paypalMe}/${importo}`;
    }
    return msg;
  }, [agency, p, sp]);

  const paypalUrl = (() => {
    const ag = agency || {};
    if (!ag.paypalMe) return null;
    const importo = sp.residuo > 0 ? sp.residuo : (Number(p.prezzo)||0);
    return `https://paypal.me/${ag.paypalMe}/${importo}`;
  })();
  return (
    <div style={{
      background: 'var(--bg)', border: '1px solid var(--border)',
      borderRadius: 8, padding: '14px 16px',
      display: 'flex', gap: 14, alignItems: 'flex-start',
    }}>
      {/* date block */}
      <div style={{
        flexShrink: 0, width: 52, textAlign: 'center',
        background: 'var(--surface-2)', borderRadius: 6, padding: '6px 4px',
      }}>
        <div style={{ fontSize: 18, fontWeight: 700, fontFamily: 'var(--font-serif)', lineHeight: 1 }}>
          {p.dal ? p.dal.slice(8) : '—'}
        </div>
        <div style={{ fontSize: 10, color: 'var(--muted)', marginTop: 2 }}>
          {p.dal ? new Date(p.dal + 'T12:00:00').toLocaleString('it-IT', { month: 'short' }).toUpperCase() : ''}
        </div>
        <div style={{ fontSize: 9, color: 'var(--muted)', marginTop: 4, borderTop: '1px solid var(--border)', paddingTop: 4 }}>
          {giorni}g
        </div>
      </div>

      {/* main content */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
          <span style={{ fontWeight: 600, fontSize: 14, color: 'var(--ink)' }}>
            {p.clienteCognome || p.clienteNome ? `${p.clienteCognome || ''} ${p.clienteNome || ''}`.trim() : 'Cliente da definire'}
          </span>
          <PrenoStatPill stato={p.stato} />
          <FotoBadge preno={p} />
          {p.firma && (
            <span style={{ fontSize: 10, background: '#e8f5e9', color: '#2e6e3e', borderRadius: 10, padding: '2px 8px', fontWeight: 600 }}>
              ✍️ firmato
            </span>
          )}
          {p.saldoRegistrato && (
            <span style={{ fontSize: 10, background: '#e8f0fa', color: '#1f5d83', borderRadius: 10, padding: '2px 8px', fontWeight: 600 }}>
              💰 saldato
            </span>
          )}
          {p.depositoRegistrato && !p.depositoRimborsato && (
            <span style={{ fontSize: 10, background: '#fef5e7', color: '#b87333', borderRadius: 10, padding: '2px 8px', fontWeight: 600 }}>
              📦 caparra €{p.depositoImporto}
            </span>
          )}
          {p.depositoRimborsato && (
            <span style={{ fontSize: 10, background: '#f5eefa', color: '#7d3c98', borderRadius: 10, padding: '2px 8px', fontWeight: 600 }}>
              ↩ caparra rimborsata
            </span>
          )}
          {p.contractId && (
            <span style={{ fontSize: 10, color: 'var(--muted)', fontFamily: 'monospace' }}>
              ⟶ pratica
            </span>
          )}
        </div>
        <div style={{ fontSize: 12, color: 'var(--ink-2)', marginBottom: 4 }}>
          {p.vehicleLabel || 'Mezzo da assegnare'}
          {p.vehicleId && p.vehicleId !== p.rentmeCode && (
            <span style={{ fontFamily: 'monospace', fontSize: 11, color: 'var(--muted)', marginLeft: 4 }}>
              {p.vehicleId}
            </span>
          )}
          {p.rentmeCode && (
            <span style={{ fontSize: 10, color: 'var(--muted)', marginLeft: 2, opacity: 0.7 }}>
              [{p.rentmeCode}]
            </span>
          )}
          {p.clienteTel && <>
            {' · '}
            <a href={`tel:${p.clienteTel}`} style={{ color: 'var(--ink-2)' }}>{p.clienteTel}</a>
            {' '}
            <a href={`https://wa.me/${p.clienteTel.replace(/\D/g,'')}`} target="_blank" rel="noreferrer"
              style={{ fontSize: 11, padding: '1px 5px', borderRadius: 4, background: '#25d36622', color: '#25d366', fontWeight: 700, textDecoration: 'none', marginLeft: 2 }}
              title="Apri WhatsApp">
              WA
            </a>
          </>}
        </div>
        <div style={{ fontSize: 11, color: 'var(--muted)' }}>
          {formatDate(p.dal)} → {formatDate(p.al)}
          {p.prezzo != null && <> · <strong style={{ color: 'var(--ink)' }}>€{p.prezzo}</strong></>}
          {p.acconto != null && p.acconto > 0 && <> · acconto €{p.acconto}</>}
          {p.fonte && <> · {fonteLabel(p.fonte)}</>}
          {/* Operatore che ha creato la pratica */}
          {p.operatorName && (
            <span style={{ marginLeft: 6, fontSize: 10, padding: '1px 5px', borderRadius: 3,
              background: 'var(--surface-3)', color: 'var(--ink-2)', fontWeight: 600 }}>
              👤 {p.operatorName}
            </span>
          )}
        </div>
        {/* Note cliente */}
        {(p.noteCliente || p.note) && (
          <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4, fontStyle: 'italic' }}>
            💬 {p.noteCliente || p.note}
          </div>
        )}
        {/* Note interne — evidenziate in arancione */}
        {p.noteInterne && (
          <div style={{ fontSize: 11, color: '#b87333', marginTop: 3, display: 'flex', alignItems: 'flex-start', gap: 4 }}>
            <span>🔒</span><span style={{ fontStyle: 'italic' }}>{p.noteInterne}</span>
          </div>
        )}
        {p.gruppoId && (
          <div style={{ marginTop: 4 }}>
            <button
              type="button"
              onClick={() => onVediGruppo && onVediGruppo(p.gruppoId)}
              title="Filtra per vedere tutte le prenotazioni di questo gruppo"
              style={{ fontSize: 10, padding: '2px 7px', borderRadius: 10, fontWeight: 700,
                background: '#e8f5e9', color: '#2e7d32', border: '1px solid #a5d6a7',
                cursor: onVediGruppo ? 'pointer' : 'default' }}
            >
              👥 Pratica multipla — vedi tutto il gruppo
            </button>
          </div>
        )}
        {p.vehicleSchedule && p.vehicleSchedule.length > 1 && (
          <div style={{ marginTop: 5, display: 'flex', flexWrap: 'wrap', gap: 3, alignItems: 'center' }}>
            <span style={{ fontSize: 10, color: 'var(--muted)', opacity: 0.8 }}>🔄 cambio mezzo:</span>
            {p.vehicleSchedule.map((s, i) => (
              <span key={i} style={{ fontSize: 10, background: 'rgba(31,93,131,.1)', color: '#1f5d83',
                borderRadius: 3, padding: '1px 6px', fontFamily: 'monospace', fontWeight: 600 }}>
                {s.vehicleId}
                <span style={{ fontWeight: 400, color: 'var(--muted)', marginLeft: 2 }}>
                  {formatDate(s.dal)}→{formatDate(s.al)}
                </span>
                {i < p.vehicleSchedule.length - 1 && <span style={{ marginLeft: 3, color: '#1f5d83' }}>›</span>}
              </span>
            ))}
          </div>
        )}
        {/* Pagamento rapido — bonifico / PayPal */}
        {(agency && (agency.iban || agency.paypalMe)) && sp.residuo > 0 && !p.saldoRegistrato && (
          <div style={{ marginTop: 6 }}>
            <button type="button" onClick={() => setPagamentoOpen(o => !o)}
              style={{ fontSize: 11, padding: '3px 8px', borderRadius: 4,
                border: '1px solid #1f5d83', background: pagamentoOpen ? '#1f5d83' : 'transparent',
                color: pagamentoOpen ? 'white' : '#1f5d83', cursor: 'pointer', fontWeight: 600 }}>
              💳 Pagamento (€{sp.residuo})
            </button>
            {pagamentoOpen && (
              <div style={{ marginTop: 6, padding: '10px 12px', borderRadius: 6,
                background: 'var(--surface-2)', border: '1px solid var(--border)', fontSize: 11 }}>
                {agency.iban && (
                  <div style={{ marginBottom: 6 }}>
                    <div style={{ fontWeight: 600, color: 'var(--ink)', marginBottom: 2 }}>🏦 Bonifico bancario</div>
                    <div style={{ fontFamily: 'monospace', fontSize: 10, color: 'var(--ink-2)',
                      wordBreak: 'break-all', marginBottom: 2 }}>{agency.iban}</div>
                    {agency.bic && <div style={{ color: 'var(--muted)', fontSize: 10 }}>BIC: {agency.bic}</div>}
                    <div style={{ color: 'var(--muted)', fontSize: 10, marginTop: 2 }}>
                      Causale: Noleggio {p.id} {[p.clienteCognome, p.clienteNome].filter(Boolean).join(' ')}
                    </div>
                    <div style={{ display: 'flex', gap: 4, marginTop: 6 }}>
                      <button type="button"
                        onClick={() => { navigator.clipboard?.writeText(agency.iban); }}
                        style={{ fontSize: 10, padding: '2px 7px', borderRadius: 3, border: '1px solid var(--border)',
                          background: 'transparent', color: 'var(--ink-2)', cursor: 'pointer' }}>
                        📋 Copia IBAN
                      </button>
                      {p.clienteTel && (
                        <a
                          href={`https://wa.me/${p.clienteTel.replace(/\D/g,'')}?text=${encodeURIComponent(buildPagamentoMsg())}`}
                          target="_blank" rel="noreferrer"
                          style={{ fontSize: 10, padding: '2px 7px', borderRadius: 3, border: 'none',
                            background: '#25d366', color: 'white', fontWeight: 600,
                            textDecoration: 'none', cursor: 'pointer' }}>
                          📲 WA dati bancari
                        </a>
                      )}
                    </div>
                  </div>
                )}
                {agency.paypalMe && (
                  <div style={{ borderTop: agency.iban ? '1px solid var(--border)' : 'none', paddingTop: agency.iban ? 6 : 0 }}>
                    <div style={{ fontWeight: 600, color: 'var(--ink)', marginBottom: 4 }}>🅿️ PayPal.me</div>
                    <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                      <a href={paypalUrl} target="_blank" rel="noreferrer"
                        style={{ fontSize: 10, padding: '3px 9px', borderRadius: 3, border: 'none',
                          background: '#003087', color: 'white', fontWeight: 600,
                          textDecoration: 'none' }}>
                        Apri PayPal €{sp.residuo}
                      </a>
                      {p.clienteTel && (
                        <a
                          href={`https://wa.me/${p.clienteTel.replace(/\D/g,'')}?text=${encodeURIComponent(`Puoi pagare €${sp.residuo} via PayPal: ${paypalUrl}`)}`}
                          target="_blank" rel="noreferrer"
                          style={{ fontSize: 10, padding: '3px 9px', borderRadius: 3, border: 'none',
                            background: '#25d366', color: 'white', fontWeight: 600,
                            textDecoration: 'none' }}>
                          📲 WA link PayPal
                        </a>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </div>

      {/* actions */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4, flexShrink: 0 }}>
        {p.stato === 'confermata' && (
          <button type="button" onClick={() => onConsegna && onConsegna(p)}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: 'none',
              background: '#2e6e3e', color: 'white', fontWeight: 700, cursor: 'pointer' }}>
            🚗 Consegna
          </button>
        )}
        <button type="button" onClick={() => onEdit(p)}
          style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid var(--border)', background: 'transparent', color: 'var(--ink-2)', cursor: 'pointer' }}>
          Modifica
        </button>
        {(p.stato === 'confermata' || p.stato === 'in_corso') && !p.contractId && (
          <button type="button" onClick={() => onConvert(p)}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: 'none', background: 'var(--accent)', color: 'white', fontWeight: 600, cursor: 'pointer' }}>
            → Pratica
          </button>
        )}
        <button type="button" onClick={() => onFoto && onFoto(p)}
          style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid var(--border)', background: 'transparent', color: '#1f5d83', cursor: 'pointer' }}>
          📷 Foto
        </button>
        <button type="button" onClick={() => onFirma && onFirma(p)}
          style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid var(--border)', background: 'transparent', color: '#2e6e3e', cursor: 'pointer' }}>
          ✍️ Firma
        </button>
        {(p.stato === 'in_corso' || p.stato === 'confermata') && !p.saldoRegistrato && (
          <button type="button" onClick={() => onSaldo && onSaldo(p)}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: 'none',
              background: '#1f5d83', color: 'white', fontWeight: 600, cursor: 'pointer' }}>
            💰 Saldo
          </button>
        )}
        {(p.stato === 'in_corso' || p.stato === 'confermata') && !p.saldoRegistrato && sp.residuo > 0 && onSaldoRapido && (
          <div style={{ position: 'relative' }}>
            <button type="button" onClick={() => setSaldoRapidoOpen(o => !o)}
              style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #1f5d83',
                background: saldoRapidoOpen ? '#1f5d83' : 'transparent',
                color: saldoRapidoOpen ? 'white' : '#1f5d83', fontWeight: 600, cursor: 'pointer' }}>
              💶 Salda €{sp.residuo}
            </button>
            {saldoRapidoOpen && (
              <div style={{
                position: 'absolute', right: 0, top: '110%', zIndex: 200,
                background: 'var(--bg)', border: '1px solid var(--border)',
                borderRadius: 8, boxShadow: '0 8px 24px rgba(0,0,0,.18)',
                padding: '12px 14px', minWidth: 180,
              }}>
                <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--ink)', marginBottom: 8 }}>
                  Saldo rapido · €{sp.residuo}
                </div>
                {['contanti','carta','bonifico','altro'].map(m => (
                  <button key={m} type="button"
                    onClick={() => { onSaldoRapido(p, sp.residuo, m); setSaldoRapidoOpen(false); }}
                    style={{ display: 'block', width: '100%', textAlign: 'left',
                      fontSize: 12, padding: '6px 8px', marginBottom: 3, borderRadius: 5,
                      border: '1px solid var(--border)', background: 'transparent',
                      color: 'var(--ink)', cursor: 'pointer' }}>
                    {m === 'contanti' ? '💵' : m === 'carta' ? '💳' : m === 'bonifico' ? '🏦' : '💶'} {m.charAt(0).toUpperCase() + m.slice(1)}
                  </button>
                ))}
                <button type="button" onClick={() => setSaldoRapidoOpen(false)}
                  style={{ fontSize: 10, color: 'var(--muted)', background: 'none', border: 'none', cursor: 'pointer', marginTop: 2 }}>
                  Annulla
                </button>
              </div>
            )}
          </div>
        )}
        {p.stato === 'in_corso' && (
          <button type="button" onClick={() => onRiconsegna && onRiconsegna(p)}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: 'none',
              background: '#2e6e3e', color: 'white', fontWeight: 700, cursor: 'pointer' }}>
            📍 Riconsegna
          </button>
        )}
        {p.stato === 'in_corso' && (
          <button type="button" onClick={() => onRientro && onRientro(p)}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #2e6e3e',
              background: 'transparent', color: '#2e6e3e', fontWeight: 600, cursor: 'pointer' }}>
            ✓ Rientrato
          </button>
        )}
        {(p.stato === 'in_corso' || p.stato === 'confermata') && (
          <button type="button" onClick={() => onProroga && onProroga(p)}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #c88a2e',
              background: 'transparent', color: '#c88a2e', cursor: 'pointer' }}>
            ⏱ Proroga
          </button>
        )}
        {p.stato === 'in_corso' && (
          <button type="button" onClick={() => onSostituzione && onSostituzione(p)}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #c85050',
              background: 'transparent', color: '#c85050', cursor: 'pointer' }}>
            🔧 Sostituzione
          </button>
        )}
        {p.stato !== 'annullata' && p.stato !== 'cancellata' && !p.depositoRegistrato && (
          <button type="button" onClick={() => onDeposito && onDeposito(p, 'prendi')}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #e8c88a',
              background: 'transparent', color: '#b87333', cursor: 'pointer' }}>
            📦 Caparra
          </button>
        )}
        {p.depositoRegistrato && !p.depositoRimborsato && (
          <button type="button" onClick={() => onDeposito && onDeposito(p, 'rimborsa')}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #d7bef0',
              background: 'transparent', color: '#7d3c98', cursor: 'pointer' }}>
            ↩ Rimborsa
          </button>
        )}
        <button type="button" onClick={() => onContratto && onContratto(p)}
          style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid var(--border)', background: 'transparent', color: '#6a3d8f', cursor: 'pointer' }}>
          🖨️ Contratto
        </button>
        {p.stato === 'confermata' && onWaConferma && (
          <button type="button" onClick={() => onWaConferma(p)}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #25d366',
              background: 'transparent', color: '#25d366', cursor: 'pointer', fontWeight: 600 }}>
            📱 WA Conferma
          </button>
        )}
        {p.stato === 'confermata' && rentmePush && (
          <button type="button" onClick={() => {
            const rmVeh = (rentmeVehicles || []).find(v => v.targa === p.vehicleId);
            rentmePush(p, rmVeh?.slug || p.vehicleType || 'auto')
              .then(() => pushToast && pushToast({ tone: 'success', title: '✅ Inviato a RentMe' }))
              .catch(err => pushToast && pushToast({ tone: 'warning', title: 'RentMe fallito', message: err.message }));
          }}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #6a3d8f',
              background: 'transparent', color: '#6a3d8f', cursor: 'pointer', fontWeight: 600 }}>
            🔄 Invia a RentMe
          </button>
        )}
        
        {(p.stato === 'completata' || p.stato === 'annullata' || p.stato === 'cancellata') && onRicrea && (
          <button type="button" onClick={() => onRicrea(p)}
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #1f5d83',
              background: 'transparent', color: '#1f5d83', cursor: 'pointer', fontWeight: 600 }}>
            🔁 Ricrea
          </button>
        )}
        {onDuplica && (
          <button type="button" onClick={() => onDuplica(p)}
            title="Duplica questa prenotazione con lo stesso cliente e le stesse date — potrai scegliere un mezzo diverso"
            style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #2e7d32',
              background: 'transparent', color: '#2e7d32', cursor: 'pointer', fontWeight: 600 }}>
            📋 Duplica
          </button>
        )}
        <button type="button" onClick={() => onDelete(p.id)}
          style={{ fontSize: 11, padding: '4px 10px', borderRadius: 4, border: '1px solid #f0d0d0', background: 'transparent', color: '#c85050', cursor: 'pointer' }}>
          Elimina
        </button>
      </div>
    </div>
  );
}


// ═══════════════════════════════════════════════════════════════════
// SMART ASSIGNMENT — trova la combinazione ottimale di mezzi
// per coprire un periodo quando nessun singolo mezzo è disponibile.
// Algoritmo greedy: assegna il mezzo che copre più giorni dall'inizio,
// poi continua con il successivo libero, e così via.
// Ritorna: null se un singolo mezzo copre tutto il periodo,
//          array di segmenti [{vehicleId, dal, al, vehicle}] altrimenti.
// ═══════════════════════════════════════════════════════════════════
function findBestVehicleCombination(tipo, dal, al, vehicles, prenotazioni, excludeBookingId = null) {
  if (!dal || !al || !tipo) return null;

  // Pool: mezzi del tipo richiesto — confronto su canonicalTipo (moto≡scooter,
  // bicicletta→ebike/bici) così una prenotazione "moto" trova i veicoli "scooter".
  const tipoCanon = canonicalTipo({ tipo });
  const pool = (vehicles || []).filter(v => (!tipoCanon || canonicalTipo(v) === tipoCanon) && v.id);

  // Prenotazioni attive (escluso quella in modifica)
  const activePreno = (prenotazioni || []).filter(p =>
    p.stato !== 'annullata' && p.stato !== 'cancellata' && p.stato !== 'completata' && p.id !== excludeBookingId
  );

  // Per ogni mezzo, calcola i giorni liberi (retrocompatibile: p.vehicleId può essere targa o fleet.id)
  function freeSegments(vehicleId, vehicleTarga) {
    const busy = activePreno
      .filter(p =>
        matchVehicle(p.vehicleId, vehicleId, vehicleTarga) ||
        (p.vehicleSchedule || []).some(s => matchVehicle(s.vehicleId, vehicleId, vehicleTarga))
      )
      .flatMap(p => {
        if (p.vehicleSchedule) {
          const segs = p.vehicleSchedule.filter(s => matchVehicle(s.vehicleId, vehicleId, vehicleTarga));
          return segs.length ? segs.map(s => ({ dal: s.dal, al: s.al })) : [{ dal: p.dal, al: p.al }];
        }
        return [{ dal: p.dal, al: p.al }];
      });
    return { vehicleId, isFreeOn: (d) => !busy.some(b => b.dal <= d && b.al >= d) };
  }

  // Controlla se un mezzo è libero per TUTTO il periodo
  const fullyCovering = pool.find(v => {
    const seg = freeSegments(v.id, v.targa);
    let d = new Date(dal + 'T12:00:00');
    const end = new Date(al + 'T12:00:00');
    while (d <= end) {
      if (!seg.isFreeOn(d.toISOString().slice(0, 10))) return false;
      d.setDate(d.getDate() + 1);
    }
    return true;
  });
  if (fullyCovering) return null; // nessuna combinazione necessaria

  // Greedy: costruisce segmenti
  const segments = [];
  let cursor = new Date(dal + 'T12:00:00');
  const endDate = new Date(al + 'T12:00:00');
  const usedVehicles = new Set();

  while (cursor <= endDate) {
    const cursorISO = cursor.toISOString().slice(0, 10);
    // Trova il mezzo libero da cursor che copre più giorni consecutivi
    let best = null;
    let bestDays = 0;
    for (const v of pool) {
      if (usedVehicles.has(v.id)) continue; // ogni mezzo usato una volta sola nel trip
      const seg = freeSegments(v.id, v.targa);
      if (!seg.isFreeOn(cursorISO)) continue;
      // Conta giorni consecutivi liberi a partire da cursor
      let count = 0;
      let probe = new Date(cursor);
      while (probe <= endDate && seg.isFreeOn(probe.toISOString().slice(0, 10))) {
        count++;
        probe.setDate(probe.getDate() + 1);
      }
      if (count > bestDays) { bestDays = count; best = v; }
    }
    if (!best || bestDays === 0) {
      // Nessun mezzo trovato per questo giorno — impossibile coprire
      return { impossible: true, segments, stuckAt: cursorISO };
    }
    // Fine segmento: fino a quando il mezzo è libero (o fine periodo)
    const segStart = cursorISO;
    let segEnd = cursor;
    const seg = freeSegments(best.id, best.targa);
    let probe = new Date(cursor);
    while (probe <= endDate && seg.isFreeOn(probe.toISOString().slice(0, 10))) {
      segEnd = new Date(probe);
      probe.setDate(probe.getDate() + 1);
    }
    const segEndISO = segEnd.toISOString().slice(0, 10);
    segments.push({ vehicleId: best.id, dal: segStart, al: segEndISO, vehicle: best });
    usedVehicles.add(best.id);
    // Avanza cursore al giorno dopo la fine del segmento
    cursor = new Date(segEnd);
    cursor.setDate(cursor.getDate() + 1);
  }

  return segments.length > 0 ? segments : null;
}

// ── PrenoForm — add/edit ─────────────────────────────────────────────
// prefillValues: valori pre-compilati dal BancoRapido / walk-in / calendario
// (vehicleId, vehicleLabel, vehicleType, dal, al, fonte) — usato solo quando initial è null
function PrenoForm({ initial, fleet, rentmeVehicles, prenotazioni, customers, onSave, onClose, prefillValues, fermiFlotta, rentmeConnected, partners }) {
  const pv = prefillValues || {};  // shorthand
  const isNew = !initial;
  const empty = {
    clienteNome: '', clienteCognome: '', clienteTel: '',
    vehicleId: pv.vehicleId || '', vehicleLabel: pv.vehicleLabel || '',
    vehicleTarga: pv.vehicleTarga || '',
    vehicleType: pv.vehicleType || 'auto',
    dal: pv.dal || todayISO(), al: pv.al || '',
    stato: 'attesa', fonte: pv.fonte || 'diretto',
    prezzo: '', acconto: '', metodoPagamento: 'contanti',
    noteCliente: '', noteInterne: '',
    consegnaStruttura: pv.consegnaStruttura || '', consegnaIndirizzo: pv.consegnaIndirizzo || '',
  };
  // Toggle: invia prenotazione anche a RentMe al salvataggio
  // Attivo di default se RentMe è connesso e stiamo creando (non modificando)
  const [sendToRentme, setSendToRentme] = useState(isNew && !!rentmeConnected);
  const [f, setF] = useState(initial ? {
    ...empty,
    clienteNome: initial.clienteNome || '',
    clienteCognome: initial.clienteCognome || '',
    clienteTel: initial.clienteTel || '',
    vehicleId: initial.vehicleId || '',
    vehicleLabel: initial.vehicleLabel || '',
    vehicleTarga: initial.vehicleTarga || '',
    vehicleType: initial.vehicleType || 'auto',
    dal: initial.dal || todayISO(),
    al: initial.al || '',
    stato: initial.stato || 'attesa',
    fonte: initial.fonte || 'diretto',
    prezzo: initial.prezzo != null ? String(initial.prezzo) : '',
    acconto: initial.acconto != null ? String(initial.acconto) : '',
    metodoPagamento: initial.metodoPagamento || 'contanti',
    // retrocompatibilità: porta 'note' vecchio in noteCliente
    noteCliente: initial.noteCliente || initial.note || '',
    noteInterne: initial.noteInterne || '',
    consegnaStruttura: initial.consegnaStruttura || '', consegnaIndirizzo: initial.consegnaIndirizzo || '',
  } : empty);

  const set = (k, v) => setF(x => ({ ...x, [k]: v }));
  const [vehicleSchedule, setVehicleSchedule] = useState(
    initial?.vehicleSchedule || null
  ); // null = mezzo singolo, array = multi-mezzo

  // ── Duplica da prenotazione esistente ─────────────────────────────────────
  // Stato: stringa di ricerca per trovare la prenotazione da copiare
  const [duplicaSearch, setDuplicaSearch]   = useState('');
  const [duplicaOpen,   setDuplicaOpen]     = useState(false);

  // ── Extra mezzi (pratica multipla) ────────────────────────────────────────
  // Lista di mezzi aggiuntivi per lo stesso cliente e stesse date.
  // Ogni elemento: { _id, vehicleType, vehicleId, vehicleLabel, vehicleTarga, prezzo, _search }
  const [extraMezzi, setExtraMezzi] = useState([]);

  function addExtraMezzo() {
    setExtraMezzi(prev => [...prev, {
      _id: `em-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,
      vehicleType:  f.vehicleType || 'scooter',
      vehicleId:    '',
      vehicleLabel: '',
      vehicleTarga: '',
      prezzo:       '',
      _search:      '',
    }]);
  }

  function removeExtraMezzo(id) {
    setExtraMezzi(prev => prev.filter(m => m._id !== id));
  }

  function updateExtraMezzo(id, patch) {
    setExtraMezzi(prev => prev.map(m => m._id === id ? { ...m, ...patch } : m));
  }

  // Veicoli disponibili per un extra mezzo (filtra per tipo e rimuove già prenotati/scelti)
  function extraAvailableVehicles(tipo, selfId) {
    const chosenIds = new Set([
      f.vehicleId,
      ...extraMezzi.filter(m => m._id !== selfId).map(m => m.vehicleId),
    ].filter(Boolean));
    return allVehicles
      .filter(v => (!tipo || v.tipo === tipo) && !bookedIds.has(v.id) && !chosenIds.has(v.id));
  }

  // Suggerimenti: filtra prenotazioni per cognome/nome/targa/codice
  const duplicaSuggestions = useMemo(() => {
    const q = duplicaSearch.trim().toLowerCase();
    if (q.length < 2) return [];
    return (prenotazioni || [])
      .filter(p => p.stato !== 'annullata' && p.stato !== 'cancellata')
      .filter(p => {
        const nome   = `${p.clienteCognome||''} ${p.clienteNome||''}`.toLowerCase();
        const targa  = (p.vehicleLabel || p.vehicleTarga || '').toLowerCase();
        const codice = (p.codice || p.id || '').toLowerCase();
        return nome.includes(q) || targa.includes(q) || codice.includes(q);
      })
      .slice(0, 8);
  }, [prenotazioni, duplicaSearch]);

  // Applica la prenotazione selezionata al form: copia tutto tranne il mezzo
  function applyDuplica(p) {
    setF(prev => ({
      ...prev,
      clienteNome:     p.clienteNome     || '',
      clienteCognome:  p.clienteCognome  || '',
      clienteTel:      p.clienteTel      || '',
      clienteId:       p.clienteId       || null,
      vehicleType:     p.vehicleType     || p.tipo || prev.vehicleType,
      dal:             p.dal             || prev.dal,
      al:              p.al              || prev.al,
      prezzo:          p.prezzo          != null ? String(p.prezzo) : '',
      metodoPagamento: p.metodoPagamento || 'contanti',
      noteCliente:     p.noteCliente     || '',
      noteInterne:     p.noteInterne     || '',
      fonte:           p.fonte           || 'diretto',
      // mezzo resettato → l'operatore sceglie
      vehicleId:    '',
      vehicleLabel: '',
      vehicleTarga: '',
      acconto:      '',  // acconto azzerato sulla nuova pratica
    }));
    setVehicleSchedule(null);
    setDuplicaSearch('');
    setDuplicaOpen(false);
  }

  // ── Ricerca targa manuale + OCR ─────────────────
  const [targaSearch, setTargaSearch] = useState('');
  const [showOcrModal, setShowOcrModal] = useState(false);
  const [ocrStatus, setOcrStatus] = useState('idle'); // idle|loading|scanning|done|error
  const [ocrMsg, setOcrMsg]       = useState('');
  const [ocrFound, setOcrFound]   = useState(null);  // { plate, vehicle, booked }
  const videoRef  = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);

  // Anti-overbooking: esclude i veicoli già prenotati nel periodo selezionato.
  // Controlla sia vehicleId principale che singoli segmenti del vehicleSchedule.
  // Retrocompatibilità: le prenotazioni pre-v0.43.10 hanno vehicleId=TARGA mentre
  // allVehicles ora usa fleet.v.id → si aggiunge anche l'id attuale del veicolo corrispondente.
  const bookedIds = useMemo(() => {
    if (!f.dal || !f.al) return new Set();
    // Mappa targa→fleet.id per tradurre booking legacy
    const fleetIdByTarga = {};
    (fleet || []).forEach(fv => { if (fv.targa && fv.id) fleetIdByTarga[fv.targa.toUpperCase().trim()] = fv.id; });
    const addId = (vid) => {
      if (!vid) return;
      ids.add(vid);
      const translated = fleetIdByTarga[vid.toUpperCase()];
      if (translated) ids.add(translated); // aggiunge anche fleet.id se vid era una targa
    };
    const ids = new Set();
    (prenotazioni || [])
      .filter(p => p.stato !== 'annullata' && p.stato !== 'cancellata' && p.stato !== 'completata' && p.id !== initial?.id)
      .forEach(p => {
        if (p.vehicleId && p.dal <= f.al && p.al >= f.dal) addId(p.vehicleId);
        if (p.vehicleSchedule) {
          p.vehicleSchedule.forEach(s => { if (s.vehicleId && s.dal <= f.al && s.al >= f.dal) addId(s.vehicleId); });
        }
      });
    (fermiFlotta || []).forEach(fermo => { if (fermo.vehicleId && fermo.dal <= f.al && fermo.al >= f.dal) addId(fermo.vehicleId); });
    return ids;
  }, [prenotazioni, fermiFlotta, fleet, f.dal, f.al, initial?.id]);

  // Lista mezzi: preferisce rentmeVehicles (fonte EDOX) se disponibili, altrimenti usa fleet locale.
  // IMPORTANTE: usa fleet.v.id come vehicleId quando il veicolo RentMe ha un corrispondente in flotta.
  // Questo garantisce che il vehicleId salvato nelle prenotazioni corrisponda a quello usato
  // da calcAvailability (che traccia per fleet v.id, non per targa) → conteggio occupati corretto.
  const allVehicles = useMemo(() => {
    if (rentmeVehicles && rentmeVehicles.length > 0) {
      // Indice targa→fleet per lookup O(1)
      const fleetByTarga = {};
      (fleet || []).forEach(fv => {
        if (fv.targa) fleetByTarga[fv.targa.toUpperCase().trim()] = fv;
      });
      const fromRentMe = rentmeVehicles
        .filter(v => v.targa)
        .map(v => {
          const targa    = (v.targa || '').trim().toUpperCase();
          const fleetV   = fleetByTarga[targa]; // veicolo locale corrispondente (se presente)
          return {
            id:      fleetV?.id || targa,        // fleet.v.id se disponibile → vehicleId consistente con calcAvailability
            tipo:    fleetV?.tipo || v.tipo || 'auto',
            marca:   fleetV?.marca || '',
            modello: fleetV?.modello || v.nome || '',
            targa,
            stato:   fleetV?.stato || 'available',
            _source: 'rentme',
          };
        });
      const rmTargas = new Set(fromRentMe.map(v => v.targa));
      const extraFleet = (fleet || []).filter(v => v.stato === 'available' && !rmTargas.has((v.targa||'').toUpperCase()));
      return [...fromRentMe, ...extraFleet];
    }
    return (fleet || []).filter(v => v.stato === 'available');
  }, [fleet, rentmeVehicles]);

  const availableVehicles = useMemo(() => {
    const TIPO_ORD = { scooter: 0, moto: 1, auto: 2, quad: 3, ebike: 4, bici: 5 };
    return allVehicles
      .filter(v => !bookedIds.has(v.id))
      // Filtra per tipo scelto: se vehicleType è settato, mostra solo quella categoria
      .filter(v => !f.vehicleType || v.tipo === f.vehicleType)
      .sort((a, b) => {
        // 1. tipo (scooter → auto → quad → ebike → bici)
        const tA = TIPO_ORD[a.tipo] ?? 9;
        const tB = TIPO_ORD[b.tipo] ?? 9;
        if (tA !== tB) return tA - tB;
        // 2. modello/nome alfabetico
        const mA = (a.modello || a.nome || '').toLowerCase();
        const mB = (b.modello || b.nome || '').toLowerCase();
        if (mA !== mB) return mA.localeCompare(mB, 'it');
        // 3. numero targa (ordinamento numerico, es. 2 < 10 < 11)
        const nA = parseInt((a.targa || a.id || '').replace(/\D+/g, '') || '0', 10);
        const nB = parseInt((b.targa || b.id || '').replace(/\D+/g, '') || '0', 10);
        return nA - nB;
      });
  }, [allVehicles, bookedIds, f.vehicleType]);

  // Smart assignment: calcola combinazione ottimale se nessun mezzo singolo è disponibile
  const smartCombo = useMemo(() => {
    if (!f.vehicleType || !f.dal || !f.al || f.vehicleId) return null;
    return findBestVehicleCombination(f.vehicleType, f.dal, f.al, allVehicles, prenotazioni, initial?.id);
  }, [f.vehicleType, f.vehicleId, f.dal, f.al, allVehicles, prenotazioni, initial?.id]);

  // Conflitto diretto: il veicolo scelto è già prenotato in quel periodo
  const conflitto = useMemo(() => {
    if (!f.vehicleId || !f.dal || !f.al) return null;
    return (prenotazioni || []).find(p => {
      if (p.id === initial?.id) return false;
      if (p.stato === 'annullata' || p.stato === 'cancellata' || p.stato === 'completata') return false;
      if (p.dal > f.al || p.al < f.dal) return false;
      // Controlla vehicleId principale con matchVehicle (retrocompatibile targa/id)
      if (matchVehicle(p.vehicleId, f.vehicleId, f.vehicleTarga)) return true;
      // Controlla segmenti vehicleSchedule: veicolo assegnato via combinazione multi-mezzo
      if ((p.vehicleSchedule || []).some(s =>
        matchVehicle(s.vehicleId, f.vehicleId, f.vehicleTarga) && s.dal <= f.al && s.al >= f.dal
      )) return true;
      return false;
    }) || null;
  }, [prenotazioni, f.vehicleId, f.vehicleTarga, f.dal, f.al, initial?.id]);

  function handleVehicleChange(e) {
    const id = e.target.value;
    // Usa allVehicles (già unifica RentMe + fleet locale con targa normalizzata)
    const v = allVehicles.find(x => x.id === id);
    if (v) {
      const vr = resolveVehicleDisplay(v);
      set('vehicleId', id);
      set('vehicleLabel', makeVehicleLabel(v));
      set('vehicleTarga', vr.targa || v.targa || v.plate || '');
      set('vehicleType', v.tipo || 'auto');
    } else {
      // fallback: cerca direttamente in fleet locale per id interno
      const fv = (fleet || []).find(x => x.id === id);
      const fvr = fv ? resolveVehicleDisplay(fv) : null;
      set('vehicleId', id);
      set('vehicleLabel', fv ? makeVehicleLabel(fv) : id);
      set('vehicleTarga', fvr?.targa || fv?.targa || fv?.plate || '');
      set('vehicleType', fv ? fv.tipo : 'auto');
    }
  }

  // Stato anti double-submit: disabilita il bottone finché il salvataggio non è completo
  const [isSubmitting, setIsSubmitting] = useState(false);
  // Errori di validazione inline
  const [formErrors, setFormErrors] = useState({});

  function validate() {
    const errors = {};
    if (!f.clienteCognome?.trim() && !f.clienteNome?.trim()) {
      errors.cliente = 'Inserisci almeno cognome o nome del cliente.';
    }
    if (!f.dal) {
      errors.dal = 'La data di inizio è obbligatoria.';
    }
    if (!f.al) {
      errors.al = 'La data di fine è obbligatoria.';
    }
    if (f.dal && f.al && f.al < f.dal) {
      errors.al = 'La data di fine non può essere precedente a quella di inizio.';
    }
    if (f.prezzo !== '' && f.prezzo !== null && f.prezzo !== undefined) {
      const p = parseFloat(f.prezzo);
      if (isNaN(p) || p < 0) errors.prezzo = 'Il prezzo deve essere un numero positivo.';
    }
    return errors;
  }

  function handleSubmit(e) {
    e.preventDefault();
    if (isSubmitting) return; // Anti double-submit

    const errors = validate();
    if (Object.keys(errors).length > 0) {
      setFormErrors(errors);
      // Scrolla al primo errore
      setTimeout(() => document.querySelector('[data-form-error]')?.scrollIntoView({ behavior: 'smooth', block: 'center' }), 50);
      return;
    }
    setFormErrors({});

    // Blocco hard: targa specifica già occupata
    if (conflitto) {
      alert(`⚠️ Conflitto orario!\n\n${[conflitto.clienteCognome, conflitto.clienteNome].filter(Boolean).join(' ') || 'Cliente'} ha già prenotato questo mezzo\ndal ${formatDate(conflitto.dal)} al ${formatDate(conflitto.al)}.\n\nScegli un altro veicolo o modifica le date.`);
      return;
    }
    // Blocco hard: categoria esaurita
    if (!f.vehicleId && !vehicleSchedule && categoriaOverbooking && categoriaOverbooking.liberi <= 0) {
      alert(`⚠️ Categoria esaurita!\n\nTutti i ${categoriaOverbooking.totale} ${f.vehicleType} sono già prenotati dal ${formatDate(f.dal)} al ${formatDate(f.al)}.\n\nVerifica disponibilità in altre date o usa la combinazione automatica di più mezzi.`);
      return;
    }

    // Prepara extra mezzi validi
    const extraValidi = extraMezzi
      .filter(m => m.vehicleType)
      .map(({ _id, _search, prezzo, ...m }) => ({
        ...m,
        prezzo: prezzo !== '' ? parseFloat(prezzo) : null,
      }));

    setIsSubmitting(true);
    try {
      onSave({
        ...f,
        prezzo: f.prezzo !== '' ? parseFloat(f.prezzo) : null,
        acconto: f.acconto !== '' ? parseFloat(f.acconto) : null,
        metodoPagamento: f.metodoPagamento || 'contanti',
        vehicleSchedule: vehicleSchedule || null,
        sendToRentme: sendToRentme,
        extraMezzi: !initial && extraValidi.length > 0 ? extraValidi : undefined,
      });
    } finally {
      // Re-abilita dopo 2s — se onSave non chiude il form (es. errore), l'utente può riprovare
      setTimeout(() => setIsSubmitting(false), 2000);
    }
  }

  // Autocomplete dalla rubrica clienti
  const acSuggestions = useMemo(() => {
    const q = f.clienteCognome.trim().toLowerCase();
    const t = f.clienteTel.replace(/\D/g, '');
    if (q.length < 2 && t.length < 4) return [];
    return (customers || []).filter(c => {
      if (q.length >= 2 && (`${c.cognome||''} ${c.nome||''}`).toLowerCase().includes(q)) return true;
      if (t.length >= 4 && (c.telefono||'').replace(/\D/g,'').includes(t)) return true;
      return false;
    }).slice(0, 5);
  }, [customers, f.clienteCognome, f.clienteTel]);

  function fillFromCustomer(c) {
    set('clienteCognome', c.cognome || '');
    set('clienteNome',    c.nome    || '');
    set('clienteTel',     c.telefono|| '');
  }

  // Overbooking per categoria (quando nessun vehicleId è selezionato)
  // Usa allVehicles (rentme preferred) come fonte di verità per il totale
  const categoriaOverbooking = useMemo(() => {
    if (f.vehicleId || !f.vehicleType || !f.dal || !f.al) return null;
    const totale = allVehicles.filter(v => v.tipo === f.vehicleType).length;
    if (totale === 0) return null;
    // Lookup targa→fleet.id per normalizzare vehicleId legacy
    const fleetIdByTarga_cat = {};
    (fleet || []).forEach(fv => { if (fv.targa && fv.id) fleetIdByTarga_cat[(fv.targa||'').toUpperCase().trim()] = fv.id; });
    const normalizeVid = (vid) => vid ? (fleetIdByTarga_cat[(vid||'').toUpperCase()] || vid) : null;

    const occupatiVehicleIds = new Set();
    let occupatiSenzaId = 0;
    (prenotazioni || []).forEach(p => {
      if (p.stato === 'annullata' || p.stato === 'cancellata' || p.stato === 'completata') return;
      if (p.id === initial?.id) return;
      if (p.dal > f.al || p.al < f.dal) return;
      const tipoP = p.vehicleType || allVehicles.find(v => v.id === p.vehicleId || matchVehicle(p.vehicleId, v.id, v.targa))?.tipo || '';
      if (tipoP !== f.vehicleType) return;
      if (p.vehicleId) {
        occupatiVehicleIds.add(normalizeVid(p.vehicleId));
      } else {
        // Booking senza targa assegnata: conta come slot consumato
        occupatiSenzaId++;
      }
      // Controlla anche i segmenti vehicleSchedule
      if (p.vehicleSchedule) {
        p.vehicleSchedule.forEach(s => {
          if (s.vehicleId && s.dal <= f.al && s.al >= f.dal) occupatiVehicleIds.add(normalizeVid(s.vehicleId));
        });
      }
    });
    // Fermi programmati: riduce i "liberi" per categoria
    (fermiFlotta || []).forEach(fermo => {
      if (!fermo.vehicleId || !fermo.dal || !fermo.al) return;
      if (fermo.dal > f.al || fermo.al < f.dal) return;
      const fermoVid = normalizeVid(fermo.vehicleId);
      const fermoV = allVehicles.find(v => v.id === fermoVid);
      if (fermoV && fermoV.tipo === f.vehicleType) occupatiVehicleIds.add(fermoVid);
    });
    const occupati = occupatiVehicleIds.size + occupatiSenzaId;
    return { totale, occupati, liberi: Math.max(0, totale - occupati) };
  }, [prenotazioni, fermiFlotta, allVehicles, fleet, f.vehicleType, f.vehicleId, f.dal, f.al, initial?.id]);

  // ── Targa search: suggerimenti da allVehicles (anche occupati) ──────
  const targaSuggestions = useMemo(() => {
    const q = targaSearch.trim().toUpperCase();
    if (q.length < 2) return [];
    return allVehicles.filter(v => {
      const t = (v.targa || v.id || '').toUpperCase();
      return t.includes(q);
    }).slice(0, 6);
  }, [targaSearch, allVehicles]);

  function selectVehicleFromTarga(v) {
    const vr = resolveVehicleDisplay(v);
    set('vehicleId', v.id);
    set('vehicleLabel', makeVehicleLabel(v));
    set('vehicleTarga', vr.targa || v.targa || v.plate || '');
    set('vehicleType', v.tipo || 'auto');
    setTargaSearch('');
    setVehicleSchedule(null);
  }

  // ── OCR helpers ────────────────────────────────
  function extractItalianPlate(text) {
    // Formato standard IT: AB123CD — oppure vecchio moto: AB12345
    const clean = text.toUpperCase().replace(/[^A-Z0-9]/g, ' ');
    const m = clean.match(/([A-Z]{2})\s*(\d{3})\s*([A-Z]{2})|([A-Z]{2})\s*(\d{5})/);
    if (!m) return null;
    if (m[1]) return `${m[1]}${m[2]}${m[3]}`;
    return `${m[4]}${m[5]}`;
  }

  async function openOcrModal() {
    setShowOcrModal(true);
    setOcrStatus('loading');
    setOcrMsg('Avvio fotocamera…');
    setOcrFound(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: { ideal: 'environment' }, width: { ideal: 1280 }, height: { ideal: 720 } }
      });
      streamRef.current = stream;
      if (videoRef.current) { videoRef.current.srcObject = stream; videoRef.current.play(); }
      setOcrStatus('scanning');
      setOcrMsg('Punta la fotocamera sulla targa e premi 📸');
    } catch (err) {
      setOcrStatus('error');
      setOcrMsg(`Fotocamera non disponibile: ${err.message}`);
    }
  }

  function closeOcrModal() {
    if (streamRef.current) { streamRef.current.getTracks().forEach(t => t.stop()); streamRef.current = null; }
    setShowOcrModal(false);
    setOcrStatus('idle');
    setOcrMsg('');
    setOcrFound(null);
  }

  async function captureAndOcr() {
    if (!videoRef.current || !canvasRef.current) return;
    setOcrStatus('loading');
    setOcrMsg('Elaborazione immagine…');
    const video  = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width  = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext('2d').drawImage(video, 0, 0);
    try {
      setOcrMsg('Riconosco targa…');
      // Tesseract già importato a livello modulo — nessun caricamento dinamico
      const result = await Tesseract.recognize(canvas, 'eng', {
        logger: m2 => { if (m2.status === 'recognizing text') setOcrMsg(`OCR: ${Math.round(m2.progress * 100)}%`); }
      });
      const plate = extractItalianPlate(result.data.text);
      if (!plate) {
        setOcrStatus('error');
        setOcrMsg(`Targa non riconosciuta — testo: "${result.data.text.trim().slice(0, 50)}" — riprova`);
        return;
      }
      const found = allVehicles.find(v => {
        const t = (v.targa || v.id || '').toUpperCase().replace(/\s/g, '');
        return t === plate || t.includes(plate) || plate.includes(t);
      });
      if (found) {
        setOcrFound({ plate, vehicle: found, booked: bookedIds.has(found.id) });
        setOcrStatus('done');
        setOcrMsg(`✅ Targa riconosciuta: ${plate}`);
      } else {
        setOcrStatus('error');
        setOcrMsg(`Targa "${plate}" non trovata in flotta — verifica manualmente`);
      }
    } catch (err) {
      setOcrStatus('error');
      setOcrMsg(`Errore OCR: ${err.message}`);
    }
  }

  const inp = { border: '1px solid var(--border)', borderRadius: 4, padding: '7px 10px', fontSize: 13, width: '100%', background: 'var(--bg)', color: 'var(--ink)', boxSizing: 'border-box' };
  const lbl = { display: 'block', fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--ink-2)', marginBottom: 4 };

  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.4)', zIndex: 9000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
      <div className="modal-box" style={{ background: 'var(--bg)', borderRadius: 10, width: '100%', maxWidth: 520, maxHeight: '90vh', overflowY: 'auto', padding: 24 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <h2 style={{ margin: 0, fontSize: 18, fontFamily: 'var(--font-serif)', fontWeight: 600 }}>
            {initial ? 'Modifica prenotazione' : 'Nuova prenotazione'}
          </h2>
          <button type="button" onClick={onClose}
            style={{ background: 'none', border: 'none', fontSize: 18, cursor: 'pointer', color: 'var(--muted)', padding: '0 4px' }}>✕</button>
        </div>

        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>

          {/* ── Banner protezione per pratiche in corso o completate ── */}
          {initial && (initial.stato === 'in_corso' || initial.stato === 'completata') && (
            <div style={{ padding: '10px 14px', borderRadius: 6, fontSize: 12, fontWeight: 600,
              background: initial.stato === 'completata' ? '#fff8e1' : '#fff3e0',
              border: `1.5px solid ${initial.stato === 'completata' ? '#ffca28' : '#ef6c00'}`,
              color: initial.stato === 'completata' ? '#7a5a00' : '#bf360c' }}>
              {initial.stato === 'completata'
                ? '⚠️ Stai modificando una pratica completata. Le modifiche non aggiornano i pagamenti già registrati in cassa.'
                : '⚠️ Pratica in corso — mezzo attualmente fuori. Modifica solo in caso di necessità.'}
            </div>
          )}

          {/* ── Duplica da prenotazione esistente (solo nuove pratiche) ── */}
          {!initial && (
            <div style={{ position: 'relative' }}>
              <button
                type="button"
                onClick={() => setDuplicaOpen(v => !v)}
                style={{ width: '100%', padding: '9px 14px', borderRadius: 6,
                  border: '1.5px dashed var(--border)', background: 'var(--surface-2)',
                  color: 'var(--ink-2)', cursor: 'pointer', fontSize: 13,
                  display: 'flex', alignItems: 'center', gap: 8, justifyContent: 'center',
                  fontWeight: 500 }}
              >
                <span>📋</span>
                <span>Duplica da prenotazione esistente</span>
                <span style={{ marginLeft: 'auto', fontSize: 10, color: 'var(--muted)' }}>
                  {duplicaOpen ? '▲' : '▼'}
                </span>
              </button>

              {duplicaOpen && (
                <div style={{ marginTop: 6, border: '1px solid var(--border)', borderRadius: 8,
                  background: 'var(--bg)', boxShadow: '0 4px 20px rgba(0,0,0,0.12)', zIndex: 300,
                  padding: 12 }}>
                  <div style={{ fontSize: 11, color: 'var(--muted)', marginBottom: 8 }}>
                    Cerca per cognome, targa o codice pratica — verranno copiati cliente, date, prezzo e note. Il mezzo dovrà essere scelto.
                  </div>
                  <input
                    autoFocus
                    style={{ width: '100%', padding: '8px 10px', borderRadius: 5,
                      border: '1px solid var(--border)', fontSize: 13,
                      background: 'var(--bg)', color: 'var(--ink)', boxSizing: 'border-box' }}
                    placeholder="Es: Rossi, AB123CD, EDO-2026…"
                    value={duplicaSearch}
                    onChange={e => setDuplicaSearch(e.target.value)}
                  />
                  {duplicaSearch.length >= 2 && duplicaSuggestions.length === 0 && (
                    <div style={{ padding: '10px 4px', fontSize: 12, color: 'var(--muted)', textAlign: 'center' }}>
                      Nessuna prenotazione trovata
                    </div>
                  )}
                  {duplicaSuggestions.map(p => {
                    const nome   = [p.clienteCognome, p.clienteNome].filter(Boolean).join(' ') || '—';
                    const mezzo  = p.vehicleLabel || p.vehicleTarga || p.vehicleType || '—';
                    const dal    = p.dal ? p.dal.split('-').reverse().join('/') : '';
                    const al     = p.al  ? p.al.split('-').reverse().join('/') : '';
                    return (
                      <button
                        key={p.id}
                        type="button"
                        onClick={() => applyDuplica(p)}
                        style={{ width: '100%', textAlign: 'left', padding: '10px 10px',
                          borderRadius: 5, border: 'none', background: 'none', cursor: 'pointer',
                          display: 'flex', flexDirection: 'column', gap: 2,
                          borderBottom: '1px solid var(--border)' }}
                        onMouseOver={e => e.currentTarget.style.background = 'var(--surface-2)'}
                        onMouseOut={e => e.currentTarget.style.background = 'none'}
                      >
                        <span style={{ fontWeight: 600, fontSize: 13, color: 'var(--ink)' }}>{nome}</span>
                        <span style={{ fontSize: 11, color: 'var(--ink-2)' }}>
                          {mezzo} &nbsp;·&nbsp; {dal}{al ? ` → ${al}` : ''}
                          {p.prezzo != null ? ` &nbsp;·&nbsp; €${p.prezzo}` : ''}
                        </span>
                        {p.codice && (
                          <span style={{ fontSize: 10, color: 'var(--muted)', fontFamily: 'monospace' }}>{p.codice}</span>
                        )}
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {/* Avviso blacklist */}
          {(() => {
            const matchBl = (customers || []).find(c => c.blacklist &&
              c.cognome?.toLowerCase() === f.clienteCognome?.toLowerCase() &&
              c.nome?.toLowerCase()    === f.clienteNome?.toLowerCase()    &&
              f.clienteCognome.length > 1);
            return matchBl ? (
              <div style={{ background: 'var(--accent-soft)', border: '1.5px solid var(--accent)', borderRadius: 6, padding: '10px 14px', fontSize: 12, color: 'var(--accent-deep)', fontWeight: 600 }}>
                ⛔ Attenzione: {matchBl.cognome} {matchBl.nome} è in <strong>blacklist</strong>{matchBl.blacklistNote ? ` — ${matchBl.blacklistNote}` : ''}. Verifica prima di procedere.
              </div>
            ) : null;
          })()}
          {/* Cliente */}
          {formErrors.cliente && (
            <div data-form-error style={{ color: '#c85050', fontSize: 12, padding: '6px 10px', background: '#fdf0f0', borderRadius: 5, border: '1px solid #f5c6c6' }}>
              ⚠️ {formErrors.cliente}
            </div>
          )}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
            <div>
              <label style={lbl}>Cognome</label>
              <input style={{ ...inp, ...(formErrors.cliente ? { borderColor: '#c85050' } : {}) }}
                value={f.clienteCognome}
                onChange={e => { set('clienteCognome', e.target.value); if (formErrors.cliente) setFormErrors(p => ({ ...p, cliente: '' })); }}
                placeholder="Rossi" />
            </div>
            <div>
              <label style={lbl}>Nome</label>
              <input style={{ ...inp, ...(formErrors.cliente ? { borderColor: '#c85050' } : {}) }}
                value={f.clienteNome}
                onChange={e => { set('clienteNome', e.target.value); if (formErrors.cliente) setFormErrors(p => ({ ...p, cliente: '' })); }}
                placeholder="Mario" />
            </div>
          </div>
          <div>
            <label style={lbl}>Telefono</label>
            <input style={inp} type="tel" value={f.clienteTel} onChange={e => set('clienteTel', e.target.value)} placeholder="+39 333 123 4567" />
          </div>

          {/* Mezzo */}
          <div>
            <label style={lbl}>Mezzo</label>

            {/* ── Ricerca targa manuale + pulsante OCR ── */}
            <div style={{ display: 'flex', gap: 8, marginBottom: 6, alignItems: 'stretch' }}>
              <div style={{ flex: 1, position: 'relative' }}>
                <input
                  style={{ ...inp, fontFamily: 'monospace', textTransform: 'uppercase', letterSpacing: 1, paddingLeft: 28 }}
                  value={targaSearch}
                  onChange={e => setTargaSearch(e.target.value.toUpperCase())}
                  placeholder="🔍  Cerca targa  (es. AB123CD)"
                />
                {/* Suggestions */}
                {targaSuggestions.length > 0 && (
                  <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 200,
                    background: 'var(--bg)', border: '1px solid var(--border)', borderRadius: 6,
                    boxShadow: '0 4px 16px rgba(0,0,0,0.15)', maxHeight: 220, overflowY: 'auto' }}>
                    {targaSuggestions.map(v => {
                      const isBooked = bookedIds.has(v.id);
                      return (
                        <div key={v.id}
                          onClick={() => { if (!isBooked) selectVehicleFromTarga(v); }}
                          style={{ padding: '8px 12px', cursor: isBooked ? 'not-allowed' : 'pointer',
                            display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                            borderBottom: '1px solid var(--border)', opacity: isBooked ? 0.5 : 1,
                            background: 'var(--bg)', transition: 'background 0.1s' }}
                          onMouseEnter={e => { if (!isBooked) e.currentTarget.style.background = 'var(--accent-soft)'; }}
                          onMouseLeave={e => { e.currentTarget.style.background = 'var(--bg)'; }}>
                          <span style={{ fontFamily: 'monospace', fontWeight: 700, fontSize: 13 }}>
                            {v.targa || v.id}
                          </span>
                          <span style={{ fontSize: 11, color: 'var(--muted)' }}>
                            {makeVehicleLabel(v)}{v.tipo ? ` · ${v.tipo}` : ''}
                            {isBooked ? <span style={{ color: '#c85050' }}> · ⛔ occupato</span> : ''}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
              <button type="button" onClick={openOcrModal} title="Scansiona targa con fotocamera"
                style={{ padding: '0 14px', borderRadius: 6, border: '1px solid var(--border)',
                  background: 'var(--bg-subtle)', cursor: 'pointer', fontSize: 20, flexShrink: 0,
                  display: 'flex', alignItems: 'center' }}>
                📷
              </button>
            </div>

            {/* Dropdown mezzi: mostra solo disponibili per il periodo scelto */}
            {(!f.dal || !f.al) ? (
              <div style={{ ...inp, display: 'flex', alignItems: 'center', gap: 8,
                color: 'var(--muted)', background: 'var(--bg-subtle)', cursor: 'default',
                fontStyle: 'italic', fontSize: 13 }}>
                📅 Seleziona prima le date per vedere i mezzi disponibili
              </div>
            ) : (
              <select style={inp} value={f.vehicleId} onChange={handleVehicleChange}>
                <option value="">
                  — Categoria generica —{availableVehicles.length > 0 ? ` (${availableVehicles.length} disponibili)` : ' (nessuno libero)'}
                </option>
                {availableVehicles.map(v => (
                  <option key={v.id} value={v.id}>
                    {makeVehicleLabel(v)}{v.tipo ? ` (${v.tipo})` : ''}
                  </option>
                ))}
              </select>
            )}
            {!f.vehicleId && (
              <input style={{ ...inp, marginTop: 6 }} value={f.vehicleLabel}
                onChange={e => set('vehicleLabel', e.target.value)}
                placeholder="es. Scooter 125cc standard" />
            )}
            {!f.vehicleId && categoriaOverbooking && categoriaOverbooking.liberi === 0 && (
              <div style={{ marginTop: 6, padding: '7px 10px', borderRadius: 5,
                background: '#fff0f0', border: '1px solid #f0d0d0', fontSize: 11, color: '#c85050' }}>
                ⚠️ <strong>Categoria esaurita</strong> · {categoriaOverbooking.occupati}/{categoriaOverbooking.totale} {f.vehicleType} già prenotati in questo periodo
              </div>
            )}
            {!f.vehicleId && categoriaOverbooking && categoriaOverbooking.liberi > 0 && f.dal && f.al && (
              <div style={{ marginTop: 5, fontSize: 11, color: '#2e6e3e' }}>
                ✓ {categoriaOverbooking.liberi}/{categoriaOverbooking.totale} {f.vehicleType} disponibili nel periodo
              </div>
            )}
            {conflitto && (
              <div style={{ marginTop: 6, padding: '7px 10px', borderRadius: 5,
                background: '#fff0f0', border: '1px solid #f0d0d0', fontSize: 11, color: '#c85050' }}>
                ⚠️ <strong>Mezzo già occupato</strong> · {[conflitto.clienteCognome, conflitto.clienteNome].filter(Boolean).join(' ') || '—'}
                &nbsp;·&nbsp;{formatDate(conflitto.dal)} → {formatDate(conflitto.al)}
              </div>
            )}
            {/* Smart combo: nessun mezzo singolo disponibile → propone combinazione */}
            {!f.vehicleId && f.vehicleType && f.dal && f.al && smartCombo && !smartCombo.impossible && (
              <div style={{ marginTop: 8, padding: '10px 12px', borderRadius: 6,
                background: '#f0f4ff', border: '1px solid #aac0f0', fontSize: 12 }}>
                <div style={{ fontWeight: 700, color: '#1f5d83', marginBottom: 6 }}>
                  🧩 Nessun mezzo singolo disponibile — combinazione automatica trovata:
                </div>
                {smartCombo.map((seg, i) => (
                  <div key={seg.vehicleId} style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 3, color: '#1f5d83' }}>
                    <span style={{ fontWeight: 600, fontFamily: 'monospace', fontSize: 11 }}>{seg.vehicleId}</span>
                    <span style={{ fontSize: 11, color: 'var(--muted)' }}>
                      {formatDate(seg.dal)} → {formatDate(seg.al)}
                    </span>
                    {seg.vehicle && <span style={{ fontSize: 10, color: 'var(--muted)' }}>({seg.vehicle.modello || seg.vehicle.tipo})</span>}
                  </div>
                ))}
                <button type="button"
                  onClick={() => {
                    // Usa il primo mezzo come vehicleId principale, salva schedule completo
                    const first = smartCombo[0];
                    set('vehicleId', first.vehicleId);
                    set('vehicleLabel', first.vehicle ? makeVehicleLabel(first.vehicle) : first.vehicleId);
                    set('vehicleType', first.vehicle?.tipo || f.vehicleType);
                    setVehicleSchedule(smartCombo.map(s => ({ vehicleId: s.vehicleId, dal: s.dal, al: s.al })));
                  }}
                  style={{ marginTop: 8, padding: '6px 14px', borderRadius: 5, border: 'none',
                    background: '#1f5d83', color: 'white', fontWeight: 700, fontSize: 12, cursor: 'pointer' }}>
                  ✓ Usa questa combinazione
                </button>
              </div>
            )}
            {!f.vehicleId && f.vehicleType && f.dal && f.al && smartCombo?.impossible && (
              <div style={{ marginTop: 8, padding: '10px 12px', borderRadius: 6,
                background: '#fff0f0', border: '1px solid #f0b0b0', fontSize: 12, color: '#c85050' }}>
                ⛔ <strong>Impossibile coprire il periodo</strong> · nessuna combinazione di {f.vehicleType} disponibile.
                Considera date diverse o un tipo diverso.
              </div>
            )}
            {/* Preview schedule attivo */}
            {vehicleSchedule && vehicleSchedule.length > 1 && (
              <div style={{ marginTop: 8, padding: '8px 12px', borderRadius: 6,
                background: '#e8f5e9', border: '1px solid #a5d6a7', fontSize: 11 }}>
                <span style={{ fontWeight: 700, color: '#1b5e20' }}>🔄 Cambio mezzo programmato:</span>
                {vehicleSchedule.map((s, i) => (
                  <span key={s.vehicleId} style={{ marginLeft: 6, color: '#2e6e3e' }}>
                    {s.vehicleId} ({formatDate(s.dal)}→{formatDate(s.al)}){i < vehicleSchedule.length - 1 ? ' →' : ''}
                  </span>
                ))}
                <button type="button" onClick={() => { setVehicleSchedule(null); set('vehicleId', ''); }}
                  style={{ marginLeft: 10, fontSize: 10, color: '#c85050', background: 'none', border: 'none', cursor: 'pointer', textDecoration: 'underline' }}>
                  rimuovi
                </button>
              </div>
            )}
            {f.vehicleId && !conflitto && f.dal && f.al && (
              <div style={{ marginTop: 5, fontSize: 11, color: '#2e6e3e' }}>
                ✓ Mezzo libero nel periodo selezionato
              </div>
            )}
          </div>

          {/* Date */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
            <div>
              <label style={lbl}>Dal *</label>
              <input
                style={{ ...inp, ...(formErrors.dal ? { borderColor: '#c85050' } : {}) }}
                type="date" required value={f.dal}
                onChange={e => { set('dal', e.target.value); setFormErrors(p => ({ ...p, dal: '' })); }}
              />
              {formErrors.dal && <div data-form-error style={{ color: '#c85050', fontSize: 11, marginTop: 3 }}>⚠️ {formErrors.dal}</div>}
            </div>
            <div>
              <label style={lbl}>Al *</label>
              <input
                style={{ ...inp, ...(formErrors.al ? { borderColor: '#c85050' } : {}) }}
                type="date" value={f.al} min={f.dal}
                onChange={e => { set('al', e.target.value); setFormErrors(p => ({ ...p, al: '' })); }}
              />
              {formErrors.al && <div data-form-error style={{ color: '#c85050', fontSize: 11, marginTop: 3 }}>⚠️ {formErrors.al}</div>}
            </div>
          </div>

          {/* Stato e fonte */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
            <div>
              <label style={lbl}>Stato</label>
              <select style={inp} value={f.stato} onChange={e => set('stato', e.target.value)}>
                {Object.entries(PRENO_STATI).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
              </select>
            </div>
            <div>
              <label style={lbl}>Fonte</label>
              <select style={inp} value={f.fonte} onChange={e => set('fonte', e.target.value)}>
                {FONTI_SELEZIONABILI.map(k => <option key={k} value={k}>{PRENO_FONTI[k]}</option>)}
              </select>
            </div>
          </div>

          {/* Prezzi */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
            <div>
              <label style={lbl}>Prezzo totale €</label>
              <input
                style={{ ...inp, ...(formErrors.prezzo ? { borderColor: '#c85050' } : {}) }}
                type="number" min="0" step="0.01" value={f.prezzo}
                onChange={e => { set('prezzo', e.target.value); setFormErrors(p => ({ ...p, prezzo: '' })); }}
                placeholder="0.00"
              />
              {formErrors.prezzo && <div data-form-error style={{ color: '#c85050', fontSize: 11, marginTop: 3 }}>⚠️ {formErrors.prezzo}</div>}
            </div>
            <div>
              <label style={lbl}>Acconto €</label>
              <input style={inp} type="number" min="0" step="0.01" value={f.acconto} onChange={e => set('acconto', e.target.value)} placeholder="0.00" />
            </div>
          </div>

          {/* Metodo pagamento acconto */}
          <div>
            <label style={lbl}>Metodo pagamento acconto</label>
            <select style={inp} value={f.metodoPagamento} onChange={e => set('metodoPagamento', e.target.value)}>
              <option value="contanti">💵 Contanti</option>
              <option value="carta">💳 Carta</option>
              <option value="bonifico">🏦 Bonifico</option>
              <option value="paypal">🅿 PayPal</option>
              <option value="altro">• Altro</option>
            </select>
          </div>

          {/* Luogo di consegna (dove alloggia il cliente / dove va il mezzo) */}
          <div>
            <label style={lbl}>
              Luogo di consegna
              <span style={{ fontWeight: 400, color: 'var(--muted)', marginLeft: 6, fontSize: 10 }}>dove va il mezzo · si conferma alla consegna</span>
            </label>
            <StructureSelect partners={partners || []}
              structureId={f.consegnaStruttura} onStructureChange={v => set('consegnaStruttura', v)}
              freeText={f.consegnaIndirizzo} onFreeTextChange={v => set('consegnaIndirizzo', v)} />
          </div>

          {/* Note cliente (visibili sul contratto) */}
          <div>
            <label style={lbl}>
              Note cliente
              <span style={{ fontWeight: 400, color: 'var(--muted)', marginLeft: 6, fontSize: 10 }}>visibili sul contratto</span>
            </label>
            <textarea style={{ ...inp, resize: 'vertical', minHeight: 50 }} value={f.noteCliente} onChange={e => set('noteCliente', e.target.value)} placeholder="Richieste speciali, preferenze, accordi…" />
          </div>

          {/* Note interne (solo operatori) */}
          <div>
            <label style={lbl}>
              Note interne
              <span style={{ fontWeight: 400, color: 'var(--accent)', marginLeft: 6, fontSize: 10 }}>🔒 solo operatori</span>
            </label>
            <textarea style={{ ...inp, resize: 'vertical', minHeight: 50, borderColor: 'var(--border)' }} value={f.noteInterne} onChange={e => set('noteInterne', e.target.value)} placeholder="Osservazioni interne, avvisi staff…" />
          </div>

          {/* ── Extra mezzi: pratica multipla (solo nuove prenotazioni) ── */}
          {!initial && (
            <div style={{ borderTop: '1px solid var(--border)', paddingTop: 14 }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
                <div style={{ fontSize: 12, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--ink-2)' }}>
                  👥 Mezzi aggiuntivi — stessa pratica
                </div>
                <button
                  type="button"
                  onClick={addExtraMezzo}
                  style={{ fontSize: 12, padding: '4px 12px', borderRadius: 5,
                    border: '1.5px solid #2e7d32', background: 'transparent',
                    color: '#2e7d32', cursor: 'pointer', fontWeight: 700 }}
                >
                  ＋ Aggiungi mezzo
                </button>
              </div>

              {extraMezzi.length === 0 && (
                <div style={{ fontSize: 11, color: 'var(--muted)', textAlign: 'center', padding: '8px 0' }}>
                  Stesso cliente, stesse date — mezzi di categorie diverse salvati insieme
                </div>
              )}

              {extraMezzi.map((m, idx) => {
                const disponibili = extraAvailableVehicles(m.vehicleType, m._id);
                const TIPI = ['auto','scooter','quad','ebike','bici','moto'];
                return (
                  <div key={m._id} style={{ display: 'grid', gridTemplateColumns: '90px 1fr 80px 30px',
                    gap: 6, alignItems: 'center', marginBottom: 8,
                    padding: '10px 10px', borderRadius: 6,
                    background: 'var(--surface-2)', border: '1px solid var(--border)' }}>
                    {/* Tipo */}
                    <select
                      value={m.vehicleType}
                      onChange={e => updateExtraMezzo(m._id, { vehicleType: e.target.value, vehicleId: '', vehicleLabel: '', vehicleTarga: '', _search: '' })}
                      style={{ fontSize: 12, padding: '5px 6px', borderRadius: 4, border: '1px solid var(--border)', background: 'var(--bg)', color: 'var(--ink)' }}
                    >
                      {TIPI.map(t => <option key={t} value={t}>{t.charAt(0).toUpperCase()+t.slice(1)}</option>)}
                    </select>

                    {/* Mezzo (search + select) */}
                    <div style={{ position: 'relative' }}>
                      {m.vehicleId ? (
                        <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                          <span style={{ fontSize: 12, fontFamily: 'monospace', fontWeight: 700, padding: '4px 8px', background: '#e8f5e9', borderRadius: 4, color: '#2e7d32' }}>
                            {m.vehicleTarga || m.vehicleLabel || m.vehicleId}
                          </span>
                          <button type="button" onClick={() => updateExtraMezzo(m._id, { vehicleId: '', vehicleLabel: '', vehicleTarga: '', _search: '' })}
                            style={{ fontSize: 10, background: 'none', border: 'none', cursor: 'pointer', color: 'var(--muted)' }}>✕</button>
                        </div>
                      ) : (
                        <>
                          <input
                            style={{ fontSize: 12, padding: '5px 8px', borderRadius: 4,
                              border: '1px solid var(--border)', background: 'var(--bg)',
                              color: 'var(--ink)', width: '100%', boxSizing: 'border-box',
                              fontFamily: 'monospace', textTransform: 'uppercase' }}
                            placeholder="Cerca targa…"
                            value={m._search}
                            onChange={e => updateExtraMezzo(m._id, { _search: e.target.value.toUpperCase() })}
                          />
                          {m._search.length >= 2 && (
                            <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 400,
                              background: 'var(--bg)', border: '1px solid var(--border)', borderRadius: 5,
                              boxShadow: '0 4px 12px rgba(0,0,0,0.15)', maxHeight: 180, overflowY: 'auto' }}>
                              {disponibili
                                .filter(v => (v.targa||v.id||'').toUpperCase().includes(m._search))
                                .slice(0, 6)
                                .map(v => (
                                  <button key={v.id} type="button"
                                    onClick={() => updateExtraMezzo(m._id, {
                                      vehicleId:    v.id,
                                      vehicleLabel: makeVehicleLabel(v),
                                      vehicleTarga: v.targa || '',
                                      vehicleType:  v.tipo || m.vehicleType,
                                      _search:      '',
                                    })}
                                    style={{ width: '100%', textAlign: 'left', padding: '7px 10px',
                                      border: 'none', background: 'none', cursor: 'pointer', fontSize: 12 }}
                                    onMouseOver={e => e.currentTarget.style.background = 'var(--surface-2)'}
                                    onMouseOut={e => e.currentTarget.style.background = 'none'}
                                  >
                                    <span style={{ fontFamily: 'monospace', fontWeight: 700 }}>{v.targa || v.id}</span>
                                    {v.modello ? <span style={{ color: 'var(--muted)', marginLeft: 6 }}>{v.modello}</span> : null}
                                  </button>
                                ))}
                              {disponibili.filter(v => (v.targa||v.id||'').toUpperCase().includes(m._search)).length === 0 && (
                                <div style={{ padding: '8px 10px', fontSize: 11, color: 'var(--muted)' }}>Nessun mezzo libero trovato</div>
                              )}
                            </div>
                          )}
                        </>
                      )}
                    </div>

                    {/* Prezzo */}
                    <input
                      type="number"
                      min="0"
                      step="0.01"
                      placeholder="€"
                      value={m.prezzo}
                      onChange={e => updateExtraMezzo(m._id, { prezzo: e.target.value })}
                      style={{ fontSize: 12, padding: '5px 6px', borderRadius: 4,
                        border: '1px solid var(--border)', background: 'var(--bg)',
                        color: 'var(--ink)', textAlign: 'right' }}
                    />

                    {/* Rimuovi */}
                    <button type="button" onClick={() => removeExtraMezzo(m._id)}
                      style={{ fontSize: 16, background: 'none', border: 'none', cursor: 'pointer',
                        color: '#c85050', lineHeight: 1, padding: 0, textAlign: 'center' }}>
                      ×
                    </button>
                  </div>
                );
              })}

              {extraMezzi.length > 0 && (
                <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4 }}>
                  Verranno create {extraMezzi.length + 1} prenotazioni collegate con lo stesso cliente e le stesse date.
                </div>
              )}
            </div>
          )}

          {/* Toggle RentMe — visibile sia per nuove prenotazioni che in modifica */}
          {rentmeConnected && (
            <div style={{ borderTop: '1px solid var(--border)', paddingTop: 12 }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: 10, cursor: 'pointer', userSelect: 'none' }}>
                <input
                  type="checkbox"
                  checked={sendToRentme}
                  onChange={e => setSendToRentme(e.target.checked)}
                  style={{ width: 16, height: 16, accentColor: 'var(--accent)', cursor: 'pointer' }}
                />
                <span style={{ fontSize: 13 }}>
                  <strong>📡 {isNew ? 'Invia anche a RentMe' : 'Re-invia a RentMe'}</strong>
                  <span style={{ color: 'var(--ink-2)', marginLeft: 6, fontSize: 12 }}>
                    {sendToRentme
                      ? isNew ? '— la prenotazione sarà creata nel gestionale RentMe' : '— i dati aggiornati saranno inviati a RentMe'
                      : '— solo locale, RentMe non verrà aggiornato'}
                  </span>
                </span>
              </label>
            </div>
          )}

          <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', paddingTop: 4 }}>
            <button type="button" onClick={onClose}
              style={{ padding: '9px 18px', borderRadius: 5, border: '1px solid var(--border)', background: 'transparent', cursor: 'pointer', fontSize: 13 }}>
              Annulla
            </button>
            <button type="submit"
              disabled={isSubmitting}
              style={{ padding: '9px 18px', borderRadius: 5, border: 'none',
                background: isSubmitting ? 'var(--muted)' : 'var(--accent)',
                color: 'white', fontWeight: 600,
                cursor: isSubmitting ? 'not-allowed' : 'pointer', fontSize: 13,
                opacity: isSubmitting ? 0.7 : 1, transition: 'all 0.2s' }}>
              {isSubmitting
                ? '⏳ Salvataggio…'
                : initial
                  ? 'Salva modifiche'
                  : extraMezzi.length > 0
                    ? `Crea ${extraMezzi.length + 1} prenotazioni collegate`
                    : (sendToRentme && isNew && rentmeConnected ? 'Crea prenotazione + RentMe' : 'Crea prenotazione')}
            </button>
          </div>

          {/* ── Modal OCR fotocamera ── */}
          {showOcrModal && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.88)', zIndex: 10000,
              display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
              padding: 20, gap: 14 }}>

              {/* Messaggio stato */}
              <div style={{ color: '#fff', fontSize: 14, textAlign: 'center', maxWidth: 380,
                padding: '8px 16px', borderRadius: 8,
                background: ocrStatus === 'error' ? 'rgba(200,80,80,0.4)' : ocrStatus === 'done' ? 'rgba(46,110,62,0.4)' : 'rgba(255,255,255,0.1)' }}>
                {ocrMsg || 'Preparazione…'}
              </div>

              {/* Video preview */}
              <div style={{ position: 'relative', borderRadius: 12, overflow: 'hidden',
                maxWidth: 420, width: '100%', border: '2px solid rgba(255,255,255,0.2)' }}>
                <video ref={videoRef} autoPlay playsInline muted
                  style={{ width: '100%', display: 'block', maxHeight: 280, objectFit: 'cover' }} />
                {/* Viewfinder: rettangolo giallo dove inquadrare la targa */}
                <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center',
                  justifyContent: 'center', pointerEvents: 'none' }}>
                  <div style={{ border: '3px solid #FFD700', borderRadius: 4, width: '82%', height: 56,
                    boxShadow: '0 0 0 9999px rgba(0,0,0,0.35)' }} />
                </div>
                {/* Label */}
                <div style={{ position: 'absolute', bottom: 8, left: 0, right: 0, textAlign: 'center',
                  color: '#FFD700', fontSize: 11, fontWeight: 700, letterSpacing: 1, textShadow: '0 1px 4px #000' }}>
                  INQUADRA LA TARGA
                </div>
              </div>

              {/* Canvas nascosto per capture */}
              <canvas ref={canvasRef} style={{ display: 'none' }} />

              {/* Risultato trovato */}
              {ocrFound && (
                <div style={{ background: ocrFound.booked ? 'rgba(200,80,80,0.2)' : 'rgba(46,110,62,0.25)',
                  border: `1px solid ${ocrFound.booked ? '#c85050' : '#2e6e3e'}`,
                  borderRadius: 10, padding: '14px 22px', textAlign: 'center', maxWidth: 380, width: '100%' }}>
                  <div style={{ fontFamily: 'monospace', fontWeight: 800, fontSize: 22, color: '#fff', letterSpacing: 2, marginBottom: 4 }}>
                    {ocrFound.plate}
                  </div>
                  <div style={{ fontSize: 13, color: 'rgba(255,255,255,0.8)', marginBottom: 12 }}>
                    {makeVehicleLabel(ocrFound.vehicle)} · <em>{ocrFound.vehicle.tipo}</em>
                    {ocrFound.booked && <span style={{ color: '#f87171', fontWeight: 700 }}> · ⛔ occupato nel periodo</span>}
                  </div>
                  {!ocrFound.booked && (
                    <button type="button"
                      onClick={() => { selectVehicleFromTarga(ocrFound.vehicle); closeOcrModal(); }}
                      style={{ padding: '10px 28px', borderRadius: 8, border: 'none',
                        background: '#2e6e3e', color: '#fff', fontWeight: 800, fontSize: 15, cursor: 'pointer' }}>
                      ✓ Usa questo mezzo
                    </button>
                  )}
                </div>
              )}

              {/* Azioni */}
              <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', justifyContent: 'center' }}>
                {(ocrStatus === 'scanning') && (
                  <button type="button" onClick={captureAndOcr}
                    style={{ padding: '13px 32px', borderRadius: 10, border: 'none',
                      background: '#FFD700', color: '#111', fontWeight: 800, fontSize: 17, cursor: 'pointer',
                      display: 'flex', alignItems: 'center', gap: 8 }}>
                    <Camera size={20} /> Leggi targa
                  </button>
                )}
                {ocrStatus === 'loading' && (
                  <div style={{ color: '#FFD700', fontSize: 14, display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={{ animation: 'spin 1s linear infinite', display: 'inline-block' }}>⏳</span> Elaborazione…
                  </div>
                )}
                {ocrStatus === 'error' && (
                  <button type="button"
                    onClick={() => { setOcrStatus('scanning'); setOcrMsg('Punta la fotocamera sulla targa e premi 📸'); setOcrFound(null); }}
                    style={{ padding: '10px 24px', borderRadius: 8, border: 'none',
                      background: 'rgba(255,255,255,0.15)', color: '#fff', fontWeight: 700, cursor: 'pointer' }}>
                    🔄 Riprova
                  </button>
                )}
                <button type="button" onClick={closeOcrModal}
                  style={{ padding: '10px 24px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.3)',
                    background: 'transparent', color: '#fff', fontWeight: 600, cursor: 'pointer' }}>
                  ✕ Chiudi
                </button>
              </div>
            </div>
          )}
        </form>
      </div>
    </div>
  );
}

// ── PrenotazioniPage ─────────────────────────────────────────────────
function PrenotazioniPage({ prenotazioni, setPrenotazioni, setCassa, fleet, rentmeVehicles, customers, partners, operator, onOpenWizard, pushToast, prefill, onClearPrefill, fermiFlotta, rentmePush, rentmeConnected, agency }) {
  const [form, setForm] = useState(null); // null | 'new' | {record}
  const [showDisp, setShowDisp] = useState(false);

  // focusId: ID prenotazione da mettere in evidenza (arriva da Calendario)
  const [focusId, setFocusId] = useState(null);
  const focusRef  = useRef(null); // ref aggiornato dalla PrenoCard evidenziata

  // Quando arriva un prefill:
  // · editId → trova la prenotazione e apri direttamente il form di modifica
  // · focusId solo → scorri e evidenzia la card senza aprire il form
  // · altri campi (vehicleId, vehicleLabel, ecc.) → nuova prenotazione con prefill
  useEffect(() => {
    if (!prefill) return;
    if (prefill.editId) {
      // Apri il form di modifica direttamente per la prenotazione con quell'ID
      const target = (prenotazioni || []).find(p => p.id === prefill.editId);
      if (target) {
        setFilterStato('tutti');
        setSearch('');
        setForm(target);
      }
      onClearPrefill && onClearPrefill();
    } else if (prefill.focusId && !prefill.vehicleId && !prefill.vehicleLabel) {
      // Solo focus: non aprire form, solo scorrere e evidenziare
      setFocusId(prefill.focusId);
      setFilterStato('tutti');
      setSearch('');
      onClearPrefill && onClearPrefill();
    } else {
      setForm({ ...prefill, id: '__new__' }); // id fittizio che segnala "è una nuova prenotazione con prefill"
      onClearPrefill && onClearPrefill();
    }
  }, [prefill]);

  // Scroll + highlight: appena focusId cambia e il DOM si aggiorna
  useEffect(() => {
    if (!focusId) return;
    const timer = setTimeout(() => {
      const el = document.getElementById(`preno-card-${focusId}`);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.classList.add('preno-highlight');
        setTimeout(() => el.classList.remove('preno-highlight'), 2200);
      }
      setFocusId(null);
    }, 120); // piccolo ritardo per lasciar rendere la lista
    return () => clearTimeout(timer);
  }, [focusId]);
  const [filterStato, setFilterStato] = useState('tutti');
  const [search, setSearch] = useState('');
  const [sortDir, setSortDir] = useState('asc'); // asc = prossime prima
  // Filtri avanzati
  const [filterDal, setFilterDal] = useState('');
  const [filterAl, setFilterAl] = useState('');
  const [filterTipo, setFilterTipo] = useState('');
  const [showAdvFilter, setShowAdvFilter] = useState(false);
  const [prePage, setPrePage] = useState(1);
  const PAGE_SIZE = 20;
  // Filtro gruppo: mostra solo le prenotazioni con lo stesso gruppoId
  const [filterGruppo, setFilterGruppo] = useState(null);
  const [viewMode, setViewMode] = useState('gruppi'); // 'lista' | 'gruppi'
  // Modali contratto e firma
  const [contrattoPreno, setContrattoPreno] = useState(null);
  const [firmaPreno, setFirmaPreno] = useState(null);
  const [saldoPreno, setSaldoPreno]     = useState(null);
  const [depositoPreno, setDepositoPreno] = useState(null); // { preno, mode }
  const [fotoPreno, setFotoPreno] = useState(null); // prenotazione di cui vedere/aggiornare le foto
  const [prorogaPreno, setProrogaPreno] = useState(null); // {preno, giorni}
  const [sostituzionePreno, setSostituzionePreno] = useState(null); // prenotazione da sostituire
  const [consegnaPreno, setConsegnaPreno] = useState(null);     // prenotazione da consegnare
  const [riconsegnaPreno, setRiconsegnaPreno] = useState(null); // prenotazione da riconsegnare

  // CRUD
  function createPreno(data) {
    const { sendToRentme, extraMezzi: extra, ...cleanData } = data;
    const now = new Date().toISOString();
    const baseRec = {
      createdAt: now,
      updatedAt: now,
      operatorId: operator?.id || '',
      operatorName: operator?.nome || '',  // nome leggibile per la card
      clienteId: null,
      contractId: null,
    };

    // ── Pratica singola (caso normale) ─────────────────────────────
    if (!extra || extra.length === 0) {
      const rec = { id: prenoId(), ...baseRec, ...cleanData };
      setPrenotazioni(ps => [...ps, rec]);
      setForm(null);
      pushToast && pushToast({ tone: 'success', title: 'Prenotazione creata', message: `${rec.clienteCognome || ''} ${rec.clienteNome || ''} · ${formatDate(rec.dal)}` });
      if (sendToRentme && rentmePush) {
        const rmVeh = (rentmeVehicles || []).find(v => v.targa === rec.vehicleId || v.rentmeCode === rec.vehicleId);
        rentmePush(rec, rmVeh?.slug || rec.vehicleType || 'auto')
          .then(() => pushToast && pushToast({ tone: 'success', title: '📡 Inviato a RentMe', message: `${[rec.clienteCognome, rec.clienteNome].filter(Boolean).join(' ')}` }))
          .catch(err => pushToast && pushToast({ tone: 'warning', title: 'RentMe: invio fallito', message: err.message, duration: 6000 }));
      }
      return;
    }

    // ── Pratica multipla: crea N+1 prenotazioni collegate da gruppoId ──
    const gruppoId = `grp-${Date.now()}-${Math.random().toString(36).slice(2,6)}`;
    const clienteBase = {
      clienteNome:     cleanData.clienteNome,
      clienteCognome:  cleanData.clienteCognome,
      clienteTel:      cleanData.clienteTel,
      clienteId:       cleanData.clienteId,
      dal:             cleanData.dal,
      al:              cleanData.al,
      fonte:           cleanData.fonte,
      metodoPagamento: cleanData.metodoPagamento,
      noteCliente:     cleanData.noteCliente,
      stato:           cleanData.stato || 'attesa',
    };

    const recPrimario = { id: prenoId(), ...baseRec, ...cleanData, gruppoId };
    const recExtra    = extra.map(m => ({
      id: prenoId(),
      ...baseRec,
      ...clienteBase,
      gruppoId,
      vehicleId:    m.vehicleId    || '',
      vehicleLabel: m.vehicleLabel || '',
      vehicleTarga: m.vehicleTarga || '',
      vehicleType:  m.vehicleType  || 'auto',
      prezzo:       m.prezzo       != null ? m.prezzo : null,
      acconto:      null,
      noteInterne:  cleanData.noteInterne || '',
    }));

    const tutti = [recPrimario, ...recExtra];
    setPrenotazioni(ps => [...ps, ...tutti]);
    setForm(null);
    const nomeCliente = `${cleanData.clienteCognome || ''} ${cleanData.clienteNome || ''}`.trim();
    pushToast && pushToast({
      tone: 'success',
      title: `${tutti.length} prenotazioni create`,
      message: `${nomeCliente} · ${tutti.length} mezzi · ${formatDate(cleanData.dal)}–${formatDate(cleanData.al)}`,
    });

    // Push RentMe per tutti i mezzi del gruppo
    if (sendToRentme && rentmePush) {
      tutti.filter(r => r.vehicleId).forEach(r => {
        const rmVeh = (rentmeVehicles || []).find(v => v.targa === r.vehicleId || v.rentmeCode === r.vehicleId);
        rentmePush(r, rmVeh?.slug || r.vehicleType || 'auto').catch(() => {});
      });
    }
  }

  function updatePreno(data) {
    const { sendToRentme, ...cleanData } = data;
    const updatedRec = {
      ...cleanData,
      updatedAt: new Date().toISOString(),
      updatedByName: operator?.nome || '',  // chi ha fatto l'ultima modifica
    };
    setPrenotazioni(ps => ps.map(p => p.id === form.id ? { ...p, ...updatedRec } : p));
    setForm(null);
    pushToast && pushToast({ tone: 'success', title: 'Prenotazione aggiornata', message: `${data.clienteCognome || ''} ${data.clienteNome || ''}`.trim() });
    // Re-invio opzionale a RentMe
    if (sendToRentme && rentmePush) {
      const rmVeh = (rentmeVehicles || []).find(v =>
        v.targa === cleanData.vehicleId || v.rentmeCode === cleanData.vehicleId
      );
      const slug = rmVeh?.slug || cleanData.vehicleType || 'auto';
      rentmePush({ ...cleanData, id: form.id }, slug)
        .then(() => pushToast && pushToast({ tone: 'success', title: '📡 Re-inviato a RentMe', message: `${[cleanData.clienteCognome, cleanData.clienteNome].filter(Boolean).join(' ')}` }))
        .catch(err => pushToast && pushToast({ tone: 'warning', title: 'RentMe: invio fallito', message: err.message, duration: 6000 }));
    }
  }

  function deletePreno(id) {
    if (!confirm('Eliminare questa prenotazione?')) return;
    setPrenotazioni(ps => ps.filter(p => p.id !== id));
    pushToast && pushToast({ tone: 'warning', title: 'Prenotazione eliminata' });
  }

  function handleRientro(p) {
    setPrenotazioni(ps => ps.map(x => x.id === p.id
      ? { ...x, stato: 'completata', rientroEffettivo: todayISO(), updatedAt: new Date().toISOString() }
      : x
    ));
    pushToast && pushToast({ tone: 'success', title: '✓ Rientro confermato',
      message: `${[p.clienteCognome, p.clienteNome].filter(Boolean).join(' ')} — ${p.vehicleLabel || 'mezzo'}` });
  }

  function handleConsegna({ vehicleId, vehicleLabel, vehicleTarga, vehicleSchedule, kmPartenza, carburante, noteConsegna, consegnaStruttura, consegnaIndirizzo }) {
    const p = consegnaPreno;
    setPrenotazioni(ps => ps.map(x => x.id === p.id ? {
      ...x,
      stato:           'in_corso',
      vehicleId:       vehicleId       || x.vehicleId    || null,
      vehicleLabel:    vehicleLabel    || x.vehicleLabel || '',
      vehicleTarga:    vehicleTarga    || x.vehicleTarga || '',
      vehicleSchedule: vehicleSchedule || x.vehicleSchedule || null,
      kmPartenza:      kmPartenza      != null ? kmPartenza : (x.kmPartenza ?? null),
      carburante:      carburante      || null,
      noteConsegna:    noteConsegna    || '',
      // Luogo di consegna (dove va il mezzo) — conferma/aggiorna quello della prenotazione
      consegnaStruttura: consegnaStruttura || x.consegnaStruttura || '',
      consegnaIndirizzo: consegnaIndirizzo || x.consegnaIndirizzo || '',
      consegnaAt:      new Date().toISOString(),
      updatedAt:       new Date().toISOString(),
    } : x));
    setConsegnaPreno(null);
    pushToast && pushToast({
      tone: 'success',
      title: '🚗 Consegna confermata',
      message: `${vehicleLabel || vehicleId || 'mezzo'} → ${[p.clienteCognome, p.clienteNome].filter(Boolean).join(' ')}`,
    });
  }

  function handleRiconsegna({ kmRientro, carburanteRientro, danniRiscontrati, noteDanni, noteRientro }) {
    const p = riconsegnaPreno;
    const hasDanni = danniRiscontrati && danniRiscontrati.length > 0;
    setPrenotazioni(ps => ps.map(x => x.id === p.id ? {
      ...x,
      stato:              hasDanni ? 'completata' : 'completata',
      rientroEffettivo:   todayISO(),
      kmRientro:          kmRientro != null ? kmRientro : (x.kmRientro ?? null),
      carburanteRientro:  carburanteRientro || null,
      danniRiscontrati:   danniRiscontrati || null,
      noteDanni:          noteDanni || '',
      noteRientro:        noteRientro || '',
      riconsegnaAt:       new Date().toISOString(),
      updatedAt:          new Date().toISOString(),
    } : x));
    setRiconsegnaPreno(null);
    pushToast && pushToast({
      tone: hasDanni ? 'warning' : 'success',
      title: hasDanni ? '⚠ Rientro con danni' : '📍 Riconsegna completata',
      message: [
        [p.clienteCognome, p.clienteNome].filter(Boolean).join(' '),
        hasDanni ? `Danni: ${danniRiscontrati.join(', ')}` : null,
      ].filter(Boolean).join(' · '),
    });
  }

  function applyProroga(p, giorni) {
    const nuovaFine = new Date(p.al + 'T12:00:00');
    nuovaFine.setDate(nuovaFine.getDate() + giorni);
    const nuovaFineISO = nuovaFine.toISOString().slice(0, 10);
    setPrenotazioni(ps => ps.map(x => x.id === p.id
      ? { ...x, al: nuovaFineISO, updatedAt: new Date().toISOString() }
      : x
    ));
    pushToast && pushToast({ tone: 'success', title: `Proroga +${giorni}gg`,
      message: `Nuovo rientro: ${formatDate(nuovaFineISO)}` });
    setProrogaPreno(null);
  }

  function applySostituzione({ dataGuasto, motivazione, noteExtra, mezzoNuovo, candidati }) {
    const groupId = `sost_${Date.now()}`;
    // Giorno prima del guasto = nuova fine prenotazione originale
    const finePrima = new Date(dataGuasto + 'T12:00:00');
    finePrima.setDate(finePrima.getDate() - 1);
    const fineISO = finePrima.toISOString().slice(0, 10);
    const p = sostituzionePreno;
    const sostituto = (candidati || []).find(v => v.id === mezzoNuovo);
    const labelSost = sostituto
      ? `${sostituto.modello || sostituto.tipo || ''} · ${sostituto.targa || mezzoNuovo}`.trim()
      : mezzoNuovo;

    setPrenotazioni(ps => {
      const updated = ps.map(x => x.id === p.id ? {
        ...x, al: fineISO, stato: 'completata',
        note: [x.note, `Sostituzione ${motivazione} il ${dataGuasto}${noteExtra ? ' — ' + noteExtra : ''}`].filter(Boolean).join(' | '),
        sostituzioneGroupId: groupId,
        updatedAt: new Date().toISOString(),
      } : x);
      const nuova = {
        id: `preno_${Date.now()}_sost`,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        clienteNome:    p.clienteNome,
        clienteCognome: p.clienteCognome,
        clienteTel:     p.clienteTel,
        vehicleId:      mezzoNuovo,
        vehicleLabel:   labelSost,
        vehicleType:    sostituto?.tipo || p.vehicleType,
        vehicleTarga:   (sostituto ? resolveVehicleDisplay(sostituto)?.targa : null) || sostituto?.targa || sostituto?.plate || '',
        dal:   dataGuasto,
        al:    p.al,
        stato: 'in_corso',
        fonte: 'sostituzione',
        prezzo: null, acconto: null,
        note: `Sostituzione di ${p.vehicleLabel || p.vehicleId} (${motivazione})${noteExtra ? ' — ' + noteExtra : ''}`,
        sostituzioneGroupId: groupId,
        sostituzioneOriginaleId: p.id,
      };
      return [...updated, nuova];
    });
    pushToast && pushToast({ tone: 'success', title: '🔧 Sostituzione effettuata',
      message: `${labelSost} · dal ${formatDate(dataGuasto)} al ${formatDate(p.al)}` });
    setSostituzionePreno(null);
  }

  function convertToPratica(p) {
    // Auto-registra acconto in cassa se presente e non ancora registrato
    if (setCassa && p.acconto > 0) {
      setCassa(prev => {
        const already = (prev || []).some(r => r.prenotazioneId === p.id && r.tipo === 'acconto');
        if (already) return prev;
        return [{
          id: 'cassa_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
          createdAt: new Date().toISOString(),
          data: todayISO(),
          clienteNome: [p.clienteCognome, p.clienteNome].filter(Boolean).join(' ') || '',
          prenotazioneId: p.id,
          vehicleLabel: p.vehicleLabel || '',
          importo: p.acconto,
          metodo: p.metodoPagamento || 'contanti',
          tipo: 'acconto',
          nota: `Acconto pren. ${formatDate(p.dal)}→${formatDate(p.al)}`,
          operatorId: operator?.id || '',
          operatorName: operator?.nome || '',
        }, ...(prev || [])];
      });
    }
    // Precompila il wizard Pratica con i dati della prenotazione
    const prefill = {
      cognome: p.clienteCognome || '',
      nome: p.clienteNome || '',
      tel: p.clienteTel || '',
      vehicleId: p.vehicleId || null,
      dal: p.dal, al: p.al,
    };
    // Segna la prenotazione come "in_corso"
    setPrenotazioni(ps => ps.map(x => x.id === p.id ? { ...x, stato: 'in_corso', updatedAt: new Date().toISOString() } : x));
    onOpenWizard && onOpenWizard(prefill);
    pushToast && pushToast({ tone: 'info', title: 'Wizard aperto', message: 'Dati prenotazione trasferiti nella pratica' });
  }

  // ── Saldo rapido (one-click, senza modal) ───────────────────────
  function handleSaldoRapido(preno, importo, metodo) {
    const record = {
      id: 'cassa_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
      createdAt: new Date().toISOString(),
      data: todayISO(),
      clienteNome: [preno.clienteCognome, preno.clienteNome].filter(Boolean).join(' ') || '',
      prenotazioneId: preno.id,
      vehicleLabel: preno.vehicleLabel || '',
      importo,
      metodo,
      tipo: 'saldo',
      nota: `Saldo rapido · ${formatDate(preno.dal)}→${formatDate(preno.al)}`,
      operatorId: operator?.id || '',
      operatorName: operator?.nome || '',
    };
    setCassa && setCassa(prev => [record, ...(prev || [])]);
    setPrenotazioni(ps => ps.map(p => p.id === preno.id ? {
      ...p, saldoRegistrato: true, saldato: importo,
      stato: p.stato === 'in_corso' ? 'completata' : p.stato,
      updatedAt: new Date().toISOString(),
    } : p));
    pushToast && pushToast({ tone: 'success', title: '💶 Saldo registrato', message: `€${importo} · ${metodo}` });
  }

  // ── Duplica prenotazione (stesso cliente + date, mezzo da scegliere) ─────────
  // A differenza di "Ricrea" (che aggiorna le date a oggi), Duplica mantiene
  // esattamente le stesse date e tutti i dati ma svuota il mezzo:
  // l'operatore può così scegliere un veicolo alternativo per lo stesso periodo.
  function handleDuplica(p) {
    const prefill = {
      id: '__new__',
      clienteNome:      p.clienteNome      || '',
      clienteCognome:   p.clienteCognome   || '',
      clienteTel:       p.clienteTel       || '',
      clienteId:        p.clienteId        || null,
      vehicleType:      p.vehicleType      || p.tipo || 'auto',
      dal:              p.dal              || todayISO(),
      al:               p.al              || '',
      stato:            'attesa',
      fonte:            p.fonte            || 'diretto',
      prezzo:           p.prezzo           != null ? p.prezzo : '',
      acconto:          '',                 // acconto azzerato sulla nuova pratica
      metodoPagamento:  p.metodoPagamento  || 'contanti',
      noteCliente:      p.noteCliente      || '',
      noteInterne:      p.noteInterne      || '',
      // vehicleId / vehicleLabel / vehicleTarga VUOTI → l'operatore sceglie il mezzo
      vehicleId:    '',
      vehicleLabel: '',
      vehicleTarga: '',
    };
    setForm(prefill);
    pushToast && pushToast({ tone: 'info', title: '📋 Duplica prenotazione', message: `${p.clienteCognome || ''} ${p.clienteNome || ''} · seleziona il nuovo mezzo` });
  }

  // ── Ricrea prenotazione ──────────────────────────────────────────
  function handleRicrea(p) {
    const t = todayISO();
    const durataGiorni = p.dal && p.al
      ? Math.max(1, Math.round((new Date(p.al) - new Date(p.dal)) / 86400000) + 1)
      : 1;
    const newAl = (() => {
      const d = new Date(t);
      // +durataGiorni-1 perché il periodo [dal, al] include entrambi gli estremi:
      // es. durata=4 → al = oggi+3 (oggi, dom, lun, mar = 4 giorni)
      d.setDate(d.getDate() + durataGiorni - 1);
      return d.toISOString().slice(0, 10);
    })();
    const prefill = {
      id: '__new__',
      clienteNome:     p.clienteNome     || '',
      clienteCognome:  p.clienteCognome  || '',
      clienteTel:      p.clienteTel      || '',
      clienteId:       p.clienteId       || null,
      vehicleId:       p.vehicleId       || null,
      vehicleLabel:    p.vehicleLabel    || '',
      vehicleType:     p.vehicleType     || p.tipo || '',
      fonte:           p.fonte           || '',
      dal:             t,
      al:              newAl,
    };
    setForm(prefill);
    pushToast && pushToast({ tone: 'info', title: '🔁 Ricrea prenotazione', message: `${p.clienteCognome || ''} ${p.clienteNome || ''} · date aggiornate a oggi` });
  }

  // ── WA Conferma ──────────────────────────────────────────────────
  function buildWaConferma(p) {
    const nome   = [p.clienteCognome, p.clienteNome].filter(Boolean).join(' ') || 'Cliente';
    const mezzo  = p.vehicleLabel || p.vehicleType || 'mezzo';
    const dal    = formatDate(p.dal);
    const al     = formatDate(p.al);
    const giorni = p.dal && p.al
      ? Math.max(1, Math.round((new Date(p.al) - new Date(p.dal)) / 86400000) + 1)
      : '?';
    const totale  = p.prezzo  != null ? `€${p.prezzo}` : 'da definire';
    const acconto = p.acconto != null && p.acconto > 0 ? `€${p.acconto}` : null;
    const sp      = statoPagamento(p);
    const residuo = sp.residuo != null ? `€${sp.residuo}` : null;

    const testo =
      `✅ Prenotazione confermata — Edonoleggio Lampedusa\n\n` +
      `👤 ${nome}\n` +
      `🛵 ${mezzo}\n` +
      `📅 Dal *${dal}* al *${al}* (${giorni} giorni)\n` +
      `💶 Totale: *${totale}*` +
      (acconto ? ` · Acconto: ${acconto}` : '') +
      (residuo && !sp.completato ? ` · Saldo alla consegna: *${residuo}*` : '') +
      (p.codice ? `\n🔖 Codice: *${p.codice}*` : '') +
      `\n\nTi aspettiamo! 🌊 Lampedusa`;
    const phone = (p.clienteTel || '').replace(/\D/g, '');
    const base  = phone ? `https://wa.me/${phone.startsWith('39') ? phone : '39' + phone}` : 'https://wa.me/';
    return `${base}?text=${encodeURIComponent(testo)}`;
  }

  // Filtri e ordinamento — memoizzati per evitare ricalcolo ad ogni render
  const today = todayISO();
  const filtered = useMemo(() => {
    // Filtro gruppo: bypass di tutti gli altri filtri, mostra solo il gruppo
    if (filterGruppo) {
      return (prenotazioni || [])
        .filter(p => p.gruppoId === filterGruppo)
        .sort((a, b) => (a.dal || '').localeCompare(b.dal || ''));
    }
    const q = search.trim().toLowerCase();
    return (prenotazioni || [])
      .filter(p => {
        if (filterStato !== 'tutti' && p.stato !== filterStato) return false;
        if (q) {
          const hay = `${p.clienteNome} ${p.clienteCognome} ${p.clienteTel} ${p.vehicleLabel} ${p.note} ${p.codice || ''}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }
        if (filterDal && p.dal && p.dal < filterDal) return false;
        if (filterAl  && p.al  && p.al  > filterAl)  return false;
        if (filterTipo && p.vehicleType !== filterTipo) return false;
        return true;
      })
      .sort((a, b) => {
        const da = a.dal || '9999', db = b.dal || '9999';
        return sortDir === 'asc' ? da.localeCompare(db) : db.localeCompare(da);
      });
  }, [prenotazioni, filterStato, search, filterDal, filterAl, filterTipo, sortDir, filterGruppo]);

  // Paginazione — reset pagina quando cambiano i filtri
  useEffect(() => { setPrePage(1); }, [search, filterStato, filterDal, filterAl, filterTipo, filterGruppo]);
  const paginated = useMemo(
    () => filtered.slice((prePage - 1) * PAGE_SIZE, prePage * PAGE_SIZE),
    [filtered, prePage]
  );

  // KPI veloci — memoizzati separatamente (dipendono solo da prenotazioni + today)
  const { attive, inAttesa, oggi } = useMemo(() => ({
    attive:    (prenotazioni || []).filter(p => p.stato === 'confermata' || p.stato === 'in_corso').length,
    inAttesa:  (prenotazioni || []).filter(p => p.stato === 'attesa').length,
    oggi:      (prenotazioni || []).filter(p => p.dal === today || p.al === today).length,
  }), [prenotazioni, today]);

  const btnFilter = (stato, label) => (
    <button type="button"
      onClick={() => setFilterStato(stato)}
      style={{
        padding: '5px 12px', borderRadius: 20, fontSize: 12, cursor: 'pointer',
        border: filterStato === stato ? 'none' : '1px solid var(--border)',
        background: filterStato === stato ? 'var(--ink)' : 'transparent',
        color: filterStato === stato ? 'var(--bg)' : 'var(--ink-2)',
        fontWeight: filterStato === stato ? 600 : 400,
      }}>
      {label}
    </button>
  );

  return (
    <div style={{ padding: '28px 32px', maxWidth: 860, margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 24 }}>
        <div>
          <div className="label" style={{ color: 'var(--edo-sea)', marginBottom: 2 }}>Tutte le prenotazioni</div>
          <h1 style={{ margin: 0, fontSize: 22, fontFamily: 'var(--font-serif)', fontWeight: 600, letterSpacing: '-0.01em' }}>Prenotazioni</h1>
          <p style={{ margin: '4px 0 0', fontSize: 13, color: 'var(--muted)' }}>
            Gestisci le prenotazioni future — poi convertile in pratica al ritiro del cliente.
          </p>
        </div>
        <button type="button"
          onClick={() => setForm('new')}
          style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '9px 16px', borderRadius: 6, border: 'none', background: 'var(--accent)', color: 'white', fontWeight: 600, fontSize: 13, cursor: 'pointer' }}>
          <Plus style={{ width: 15, height: 15 }} /> Nuova prenotazione
        </button>
      </div>

      {/* KPI */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 12, marginBottom: 20 }}>
        {[
          { label: 'Confermate / In corso', value: attive, color: '#2e6e3e' },
          { label: 'In attesa conferma',    value: inAttesa, color: '#b87333' },
          { label: 'Movimenti oggi',        value: oggi,    color: '#1f5d83' },
        ].map(k => (
          <div key={k.label} className="card-paper" style={{ padding: '14px 16px', borderTop: `3px solid ${k.color}` }}>
            <div style={{ fontSize: 28, fontWeight: 700, fontFamily: 'var(--font-serif)', color: k.color }}>{k.value}</div>
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 2 }}>{k.label}</div>
          </div>
        ))}
      </div>

      {/* Barra filtri */}
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 16, flexWrap: 'wrap' }}>
        <div style={{ position: 'relative', flex: '1 1 260px', maxWidth: 360 }}>
          <Search style={{ position: 'absolute', left: 10, top: '50%', transform: 'translateY(-50%)', width: 15, height: 15, color: 'var(--muted)' }} />
          <input
            style={{ paddingLeft: 34, padding: '8px 12px 8px 34px', border: '1px solid var(--border)', borderRadius: 6, fontSize: 13, width: '100%', background: 'var(--bg)', color: 'var(--ink)', boxSizing: 'border-box' }}
            placeholder="Cerca cliente, mezzo, targa…"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        {btnFilter('tutti', 'Tutte')}
        {btnFilter('attesa', 'In attesa')}
        {btnFilter('confermata', 'Confermate')}
        {btnFilter('in_corso', 'In corso')}
        {btnFilter('completata', 'Completate')}
        <button type="button"
          onClick={() => setSortDir(d => d === 'asc' ? 'desc' : 'asc')}
          style={{ marginLeft: 'auto', padding: '5px 12px', borderRadius: 20, fontSize: 12, border: '1px solid var(--border)', background: 'transparent', color: 'var(--ink-2)', cursor: 'pointer' }}>
          {sortDir === 'asc' ? '↑ Prossime' : '↓ Recenti'}
        </button>
        <button type="button"
          onClick={() => setViewMode(m => m === 'lista' ? 'gruppi' : 'lista')}
          title={viewMode === 'lista' ? 'Passa alla vista raggruppata per mese' : 'Torna alla lista'}
          style={{ padding: '5px 12px', borderRadius: 20, fontSize: 12, border: viewMode === 'gruppi' ? 'none' : '1px solid var(--border)', background: viewMode === 'gruppi' ? 'var(--ink)' : 'transparent', color: viewMode === 'gruppi' ? 'var(--bg)' : 'var(--ink-2)', cursor: 'pointer' }}>
          {viewMode === 'lista' ? '≡ Lista' : '▦ Gruppi'}
        </button>
        <button type="button"
          onClick={() => setShowAdvFilter(v => !v)}
          style={{ padding: '5px 12px', borderRadius: 20, fontSize: 12, border: showAdvFilter ? 'none' : '1px solid var(--border)', background: showAdvFilter ? 'var(--ink)' : 'transparent', color: showAdvFilter ? 'var(--bg)' : 'var(--ink-2)', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 4 }}>
          <Filter style={{ width: 12, height: 12 }} /> Filtri
          {(filterDal || filterAl || filterTipo) && <span style={{ background: 'var(--accent)', color: '#fff', borderRadius: '50%', width: 14, height: 14, display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: 9, fontWeight: 700 }}>!</span>}
        </button>
      </div>

      {/* Banner vista gruppo — appare quando si filtra per gruppoId */}
      {filterGruppo && (() => {
        const gruppo = (prenotazioni || []).filter(p => p.gruppoId === filterGruppo);
        const nomeCliente = [gruppo[0]?.clienteCognome, gruppo[0]?.clienteNome].filter(Boolean).join(' ') || '—';
        const totale = gruppo.reduce((s, p) => s + safePrezzo(p), 0);
        const dal = gruppo[0]?.dal ? gruppo[0].dal.split('-').reverse().join('/') : '';
        const al  = gruppo[0]?.al  ? gruppo[0].al.split('-').reverse().join('/')  : '';
        return (
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap',
            background: '#e8f5e9', border: '1.5px solid #a5d6a7', borderRadius: 8,
            padding: '10px 16px', marginBottom: 12 }}>
            <span style={{ fontSize: 18 }}>👥</span>
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 700, fontSize: 13, color: '#1b5e20' }}>
                Pratica multipla — {nomeCliente}
              </div>
              <div style={{ fontSize: 11, color: '#2e7d32' }}>
                {gruppo.length} mezzi · {dal}→{al}
                {totale > 0 ? ` · Totale gruppo €${totale.toFixed(2)}` : ''}
              </div>
            </div>
            <button type="button"
              onClick={() => setFilterGruppo(null)}
              style={{ padding: '5px 14px', borderRadius: 20, fontSize: 12, fontWeight: 600,
                border: '1px solid #2e7d32', background: 'transparent', color: '#2e7d32', cursor: 'pointer' }}>
              ✕ Esci dalla vista gruppo
            </button>
          </div>
        );
      })()}

      {/* Filtri avanzati — pannello espandibile */}
      {showAdvFilter && (
        <div style={{ background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 8, padding: '14px 16px', marginBottom: 16, display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'flex-end' }}>
          <div>
            <div style={{ fontSize: 10, color: 'var(--muted)', marginBottom: 4, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Dal</div>
            <input type="date" value={filterDal} onChange={e => setFilterDal(e.target.value)}
              style={{ padding: '5px 8px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 12, background: 'var(--bg)', color: 'var(--ink)', cursor: 'pointer' }} />
          </div>
          <div>
            <div style={{ fontSize: 10, color: 'var(--muted)', marginBottom: 4, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Al</div>
            <input type="date" value={filterAl} onChange={e => setFilterAl(e.target.value)}
              style={{ padding: '5px 8px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 12, background: 'var(--bg)', color: 'var(--ink)', cursor: 'pointer' }} />
          </div>
          <div>
            <div style={{ fontSize: 10, color: 'var(--muted)', marginBottom: 4, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Categoria</div>
            <select value={filterTipo} onChange={e => setFilterTipo(e.target.value)}
              style={{ padding: '5px 8px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 12, background: 'var(--bg)', color: 'var(--ink)', cursor: 'pointer' }}>
              <option value="">Tutte</option>
              <option value="auto">Auto</option>
              <option value="scooter">Scooter</option>
              <option value="quad">Quad</option>
              <option value="ebike">E-Bike</option>
            </select>
          </div>
          <button type="button"
            onClick={() => { setFilterDal(''); setFilterAl(''); setFilterTipo(''); }}
            style={{ padding: '5px 12px', borderRadius: 5, border: '1px solid var(--border)', background: 'transparent', color: 'var(--ink-2)', fontSize: 12, cursor: 'pointer' }}>
            ✕ Reset filtri
          </button>
          <div style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--muted)', alignSelf: 'center' }}>
            {filtered.length} / {(prenotazioni||[]).length} prenotazioni
          </div>
        </div>
      )}

      {/* Lista / Gruppi */}
      {filtered.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '60px 20px', color: 'var(--muted)' }}>
          <CalendarDays style={{ width: 40, height: 40, margin: '0 auto 12px', opacity: 0.3 }} />
          <div style={{ fontSize: 15, fontFamily: 'var(--font-serif)', marginBottom: 6 }}>
            {(prenotazioni || []).length === 0 ? 'Nessuna prenotazione ancora' : 'Nessun risultato per i filtri applicati'}
          </div>
          <div style={{ fontSize: 12 }}>
            {(prenotazioni || []).length === 0 && 'Crea la prima prenotazione con il pulsante qui sopra.'}
          </div>
        </div>
      ) : viewMode === 'gruppi' ? (() => {
        // Raggruppa per mese (dal)
        const byMonth = {};
        filtered.forEach(p => {
          const key = (p.dal || '9999-12').slice(0, 7); // YYYY-MM
          if (!byMonth[key]) byMonth[key] = [];
          byMonth[key].push(p);
        });
        const monthKeys = Object.keys(byMonth).sort(sortDir === 'asc' ? undefined : (a,b) => b.localeCompare(a));
        return (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
            {monthKeys.map(ym => {
              const [year, month] = ym.split('-');
              const monthLabel = new Date(`${ym}-15`).toLocaleDateString('it-IT', { month: 'long', year: 'numeric' });
              const items = byMonth[ym];
              // Raggruppa per settimana del mese
              const byWeek = {};
              items.forEach(p => {
                const d = new Date((p.dal || ym + '-01') + 'T12:00:00');
                const weekNum = Math.ceil(d.getDate() / 7);
                const wk = `${ym}-W${weekNum}`;
                if (!byWeek[wk]) byWeek[wk] = { weekNum, items: [] };
                byWeek[wk].items.push(p);
              });
              const weekKeys = Object.keys(byWeek).sort();
              return (
                <div key={ym}>
                  {/* Intestazione mese */}
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
                    <span style={{ fontFamily: 'var(--font-serif)', fontWeight: 700, fontSize: 16, color: 'var(--ink)', textTransform: 'capitalize' }}>
                      {monthLabel}
                    </span>
                    <span style={{ fontSize: 11, padding: '1px 8px', borderRadius: 10, background: 'var(--surface-2)', color: 'var(--muted)', fontWeight: 600 }}>
                      {items.length} prenotazion{items.length === 1 ? 'e' : 'i'}
                    </span>
                    <span style={{ fontSize: 11, color: 'var(--muted)' }}>
                      €{items.reduce((s, p) => s + safePrezzo(p), 0).toLocaleString('it-IT')}
                    </span>
                    <div style={{ flex: 1, height: 1, background: 'var(--border)' }} />
                  </div>
                  {weekKeys.map(wk => {
                    const { weekNum, items: wItems } = byWeek[wk];
                    const wStart = (wItems[0]?.dal || '');
                    const wEnd   = (wItems[wItems.length - 1]?.al || '');
                    return (
                      <div key={wk} style={{ marginBottom: 12 }}>
                        {/* Intestazione settimana */}
                        <div style={{ fontSize: 11, fontWeight: 600, color: 'var(--muted)', textTransform: 'uppercase',
                          letterSpacing: '0.06em', marginBottom: 6, paddingLeft: 4,
                          display: 'flex', alignItems: 'center', gap: 8 }}>
                          <span>Settimana {weekNum}</span>
                          {wStart && <span style={{ fontWeight: 400 }}>{formatDate(wStart)}{wEnd && wEnd !== wStart ? ` – ${formatDate(wEnd)}` : ''}</span>}
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 6, paddingLeft: 8, borderLeft: '2px solid var(--border)' }}>
                          {wItems.map(p => (
                            <div key={p.id} id={`preno-card-${p.id}`}
                              style={{ borderRadius: 8, transition: 'box-shadow 0.3s, outline 0.3s' }}>
                              <PrenoCard p={p}
                                onEdit={(rec) => setForm(rec)}
                                onConvert={convertToPratica}
                                onDelete={deletePreno}
                                onFoto={(rec) => setFotoPreno(rec)}
                                onFirma={(rec) => setFirmaPreno(rec)}
                                onContratto={(rec) => setContrattoPreno(rec)}
                                onSaldo={(rec) => setSaldoPreno(rec)}
                                onDeposito={(rec, mode) => setDepositoPreno({ preno: rec, mode })}
                                onRientro={handleRientro}
                                onRiconsegna={(rec) => setRiconsegnaPreno(rec)}
                                onProroga={(rec) => setProrogaPreno(rec)}
                                onSostituzione={(rec) => setSostituzionePreno(rec)}
                                onConsegna={(rec) => setConsegnaPreno(rec)}
                                onRicrea={handleRicrea}
                                onDuplica={handleDuplica}
                                onVediGruppo={(gid) => setFilterGruppo(gid)}
                                onSaldoRapido={handleSaldoRapido}
                                onWaConferma={(rec) => { window.open(buildWaConferma(rec), '_blank', 'noopener'); }}
                                rentmePush={rentmePush}
                                rentmeVehicles={rentmeVehicles}
                                pushToast={pushToast}
                                agency={agency}
                              />
                            </div>
                          ))}
                        </div>
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>
        );
      })() : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          {paginated.map(p => (
            <div key={p.id} id={`preno-card-${p.id}`}
              style={{ borderRadius: 8, transition: 'box-shadow 0.3s, outline 0.3s' }}>
            <PrenoCard
              key={p.id}
              p={p}
              onEdit={(rec) => setForm(rec)}
              onConvert={convertToPratica}
              onDelete={deletePreno}
              onFoto={(rec) => setFotoPreno(rec)}
              onFirma={(rec) => setFirmaPreno(rec)}
              onContratto={(rec) => setContrattoPreno(rec)}
              onSaldo={(rec) => setSaldoPreno(rec)}
              onDeposito={(rec, mode) => setDepositoPreno({ preno: rec, mode })}
              onRientro={handleRientro}
              onRiconsegna={(rec) => setRiconsegnaPreno(rec)}
              onProroga={(rec) => setProrogaPreno(rec)}
              onSostituzione={(rec) => setSostituzionePreno(rec)}
              onConsegna={(rec) => setConsegnaPreno(rec)}
              onRicrea={handleRicrea}
              onDuplica={handleDuplica}
              onVediGruppo={(gid) => setFilterGruppo(gid)}
              onSaldoRapido={handleSaldoRapido}
              onWaConferma={(rec) => { window.open(buildWaConferma(rec), '_blank', 'noopener'); }}
              rentmePush={rentmePush}
              rentmeVehicles={rentmeVehicles}
              pushToast={pushToast}
              agency={agency}
            />
            </div>
          ))}
        </div>
      )}

      {/* Paginazione */}
      {filtered.length > PAGE_SIZE && (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 0 6px' }}>
          <button type="button"
            onClick={() => setPrePage(p => Math.max(1, p - 1))}
            disabled={prePage === 1}
            style={{ padding: '6px 14px', borderRadius: 6, border: '1px solid var(--border)', background: 'transparent',
              color: prePage === 1 ? 'var(--muted)' : 'var(--ink)', cursor: prePage === 1 ? 'default' : 'pointer', fontSize: 12 }}>
            ← Precedente
          </button>
          <span style={{ fontSize: 12, color: 'var(--muted)' }}>
            {(prePage - 1) * PAGE_SIZE + 1}–{Math.min(prePage * PAGE_SIZE, filtered.length)} di {filtered.length}
          </span>
          <button type="button"
            onClick={() => setPrePage(p => p + 1)}
            disabled={prePage * PAGE_SIZE >= filtered.length}
            style={{ padding: '6px 14px', borderRadius: 6, border: '1px solid var(--border)', background: 'transparent',
              color: prePage * PAGE_SIZE >= filtered.length ? 'var(--muted)' : 'var(--ink)',
              cursor: prePage * PAGE_SIZE >= filtered.length ? 'default' : 'pointer', fontSize: 12 }}>
            Successiva →
          </button>
        </div>
      )}

      {/* Vista disponibilità */}
      <div style={{ marginTop: 8, marginBottom: 8 }}>
        <button type="button"
          onClick={() => setShowDisp(s => !s)}
          style={{ fontSize: 12, padding: '5px 14px', borderRadius: 20, border: '1px solid var(--border)', background: 'transparent', color: 'var(--ink-2)', cursor: 'pointer' }}>
          {showDisp ? '▲ Nascondi calendario' : '▼ Mostra disponibilità 4 settimane'}
        </button>
      </div>
      {showDisp && <DisponibilitaView prenotazioni={prenotazioni} rentmeVehicles={rentmeVehicles || []} fleet={fleet} fermiFlotta={fermiFlotta} />}

      {/* Form modal */}
      {form && (
        <PrenoForm
          initial={form === 'new' || form?.id === '__new__' ? null : form}
          fleet={fleet}
          rentmeVehicles={rentmeVehicles}
          prenotazioni={prenotazioni}
          customers={customers}
          prefillValues={form?.id === '__new__' ? form : null}
          fermiFlotta={fermiFlotta}
          rentmeConnected={rentmeConnected}
          onSave={form === 'new' || form?.id === '__new__' ? createPreno : updatePreno}
          onClose={() => setForm(null)}
        />
      )}
      {/* Modal foto check-in / check-out */}
      {firmaPreno && (
        <FirmaModal
          preno={firmaPreno}
          onSave={data => { setPrenotazioni(ps => ps.map(p => p.id === data.id ? data : p)); setFirmaPreno(null); pushToast && pushToast({ tone: 'success', title: 'Firma salvata' }); }}
          onClose={() => setFirmaPreno(null)}
        />
      )}
      {contrattoPreno && (
        <ContractPdfModal
          data={prenoToContractData(contrattoPreno, fleet, customers)}
          operator={operator}
          partners={partners || []}
          agency={agency}
          contractId={`EDO-${new Date(contrattoPreno.dal || Date.now()).getFullYear()}-${contrattoPreno.codice || '?'}`}
          contractDate={formatDate(contrattoPreno.dal)}
          onClose={() => setContrattoPreno(null)}
        />
      )}
      {fotoPreno && (
        <FotoModal
          prenotazione={fotoPreno}
          onSave={(updated) => {
            setPrenotazioni(ps => ps.map(p => p.id === updated.id ? updated : p));
            setFotoPreno(null);
            pushToast && pushToast({ tone: 'success', title: 'Foto salvate', message: `${(updated.foto?.consegna?.length||0) + (updated.foto?.rientro?.length||0)} foto` });
          }}
          onClose={() => setFotoPreno(null)}
        />
      )}

      {/* Modal proroga noleggio */}
      {prorogaPreno && (
        <ProrogaModal
          preno={prorogaPreno}
          onConfirm={(giorni) => applyProroga(prorogaPreno, giorni)}
          onClose={() => setProrogaPreno(null)}
        />
      )}
      {sostituzionePreno && (
        <SostituzioneModal
          preno={sostituzionePreno}
          prenotazioni={prenotazioni}
          fleet={fleet}
          rentmeVehicles={rentmeVehicles}
          fermiFlotta={fermiFlotta}
          onConfirm={applySostituzione}
          onClose={() => setSostituzionePreno(null)}
        />
      )}
      {consegnaPreno && (
        <ConsegnaModal
          preno={consegnaPreno}
          prenotazioni={prenotazioni}
          fleet={fleet}
          rentmeVehicles={rentmeVehicles}
          fermiFlotta={fermiFlotta}
          partners={partners}
          onConfirm={handleConsegna}
          onClose={() => setConsegnaPreno(null)}
        />
      )}
      {riconsegnaPreno && (
        <RiconsegnaModal
          preno={riconsegnaPreno}
          onConfirm={handleRiconsegna}
          onClose={() => setRiconsegnaPreno(null)}
        />
      )}

      {/* ── SaldoModal ── */}
      {saldoPreno && (
        <SaldoModal
          preno={saldoPreno}
          operator={operator}
          onSave={({ record, completata }) => {
            // Registra movimento in cassa
            setCassa && setCassa(prev => [...(prev || []), record]);
            // Aggiorna prenotazione: saldoRegistrato + eventuale completata
            setPrenotazioni(ps => ps.map(p => p.id === saldoPreno.id ? {
              ...p,
              saldoRegistrato: true,
              stato: completata ? 'completata' : p.stato,
              updatedAt: new Date().toISOString(),
            } : p));
            setSaldoPreno(null);
            pushToast && pushToast({ tone: 'success', title: '💰 Saldo registrato',
              message: `€${record.importo} · ${record.metodo}` });
          }}
          onClose={() => setSaldoPreno(null)}
        />
      )}

      {/* ── DepositoModal ── */}
      {depositoPreno && (
        <DepositoModal
          preno={depositoPreno.preno}
          operator={operator}
          mode={depositoPreno.mode}
          onSave={({ record, importo: imp }) => {
            const isRimborso = depositoPreno.mode === 'rimborsa';
            // Registra movimento in cassa
            setCassa && setCassa(prev => [...(prev || []), record]);
            // Aggiorna prenotazione
            setPrenotazioni(ps => ps.map(p => p.id === depositoPreno.preno.id ? {
              ...p,
              ...(isRimborso
                ? { depositoRimborsato: true }
                : { depositoRegistrato: true, depositoImporto: imp }),
              updatedAt: new Date().toISOString(),
            } : p));
            setDepositoPreno(null);
            pushToast && pushToast({ tone: 'success',
              title: isRimborso ? '↩ Caparra rimborsata' : '📦 Caparra registrata',
              message: `€${imp}` });
          }}
          onClose={() => setDepositoPreno(null)}
        />
      )}
    </div>
  );
}

// ── ProrogaModal ──────────────────────────────────────────────────────

// ═══════════════════════════════════════════════════════════════════
// SOSTITUZIONE VEICOLO — emergenza guasto / incidente
// Chiude la prenotazione corrente alla data guasto, crea la nuova
// sullo stesso cliente con mezzo sostitutivo. Collega via groupId.
// ═══════════════════════════════════════════════════════════════════
function SostituzioneModal({ preno, prenotazioni, fleet, rentmeVehicles, onConfirm, onClose, fermiFlotta }) {
  const today = todayISO();
  const [dataGuasto,  setDataGuasto]  = useState(today);
  const [motivazione, setMotivazione] = useState('guasto');
  const [noteExtra,   setNoteExtra]   = useState('');
  const [mezzoNuovo,  setMezzoNuovo]  = useState('');

  // Mezzi dello stesso tipo liberi dal giorno del guasto alla fine prenotazione
  const candidati = useMemo(() => {
    if (!dataGuasto) return [];
    const tipo = preno.vehicleType || preno.tipo || '';
    // Costruisce pool veicoli
    const pool = rentmeVehicles && rentmeVehicles.length > 0
      ? rentmeVehicles.filter(v => v.targa).map(v => ({
          id:      (v.targa || '').trim().toUpperCase(),
          tipo:    v.tipo || '',
          modello: v.nome || '',
          targa:   (v.targa || '').trim().toUpperCase(),
        }))
      : (fleet || []).filter(v => v.stato === 'available');

    // Stesso tipo, non il mezzo corrente
    const stessoTipo = pool.filter(v =>
      v.id !== preno.vehicleId &&
      (!tipo || v.tipo === tipo)
    );

    // Liberi nel periodo dataGuasto → preno.al
    const occupati = new Set();
    (prenotazioni || [])
      .filter(p =>
        p.id !== preno.id &&
        p.stato !== 'annullata' && p.stato !== 'cancellata' && p.stato !== 'completata' &&
        p.dal <= preno.al && p.al >= dataGuasto
      )
      .forEach(p => {
        if (p.vehicleId) occupati.add(p.vehicleId);
        (p.vehicleSchedule || []).forEach(s => {
          if (s.vehicleId && s.dal <= preno.al && s.al >= dataGuasto) occupati.add(s.vehicleId);
        });
      });
    // Fermi programmati — aggiungiamo sia fleet UUID che targa (pool può usare entrambi)
    const fleetIdToTarga = {};
    (fleet || []).forEach(fv => { if (fv.id && fv.targa) fleetIdToTarga[fv.id] = (fv.targa||'').trim().toUpperCase(); });
    (fermiFlotta || []).forEach(f => {
      if (!f.vehicleId || !f.dal || !f.al) return;
      if (f.dal <= preno.al && f.al >= dataGuasto) {
        occupati.add(f.vehicleId);
        const targa = fleetIdToTarga[f.vehicleId];
        if (targa) occupati.add(targa);
      }
    });

    return stessoTipo.filter(v => !occupati.has(v.id));
  }, [dataGuasto, preno, prenotazioni, fleet, rentmeVehicles, fermiFlotta]);

  const inp = {
    padding: '7px 10px', border: '1px solid var(--border)', borderRadius: 5,
    fontSize: 13, background: 'var(--bg)', color: 'var(--ink)',
    fontFamily: 'var(--font-sans)', width: '100%', boxSizing: 'border-box',
  };

  const giorni = dataGuasto && preno.al
    ? Math.max(0, Math.round((new Date(preno.al + 'T12:00:00') - new Date(dataGuasto + 'T12:00:00')) / 86400000))
    : 0;

  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.5)', zIndex: 700,
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
      <div className="modal-box" style={{ background: 'var(--bg)', borderRadius: 12, padding: '24px 28px',
        maxWidth: 500, width: '100%', boxShadow: '0 20px 60px rgba(0,0,0,.3)',
        border: '2px solid #c85050', maxHeight: '90vh', overflowY: 'auto' }}>

        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
          <div>
            <h2 style={{ margin: 0, fontSize: 17, fontFamily: 'var(--font-serif)', fontWeight: 700, color: '#c85050' }}>
              🔧 Sostituzione veicolo
            </h2>
            <p style={{ margin: '4px 0 0', fontSize: 12, color: 'var(--muted)' }}>
              {[preno.clienteCognome, preno.clienteNome].filter(Boolean).join(' ')} · {preno.vehicleLabel || preno.vehicleId}
            </p>
          </div>
          <button onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer',
            fontSize: 20, color: 'var(--muted)', lineHeight: 1 }}>×</button>
        </div>

        {/* Info prenotazione originale */}
        <div style={{ background: 'var(--surface-2)', borderRadius: 7, padding: '10px 14px',
          marginBottom: 18, fontSize: 12, color: 'var(--ink-2)' }}>
          <strong>Prenotazione originale:</strong> {formatDate(preno.dal)} → {formatDate(preno.al)}
          {preno.vehicleId && <> · <span style={{ fontFamily: 'monospace' }}>{preno.vehicleId}</span></>}
        </div>

        {/* Data guasto */}
        <div style={{ marginBottom: 14 }}>
          <label style={{ display: 'block', fontSize: 11, fontWeight: 700, textTransform: 'uppercase',
            letterSpacing: '.06em', color: 'var(--muted)', marginBottom: 6 }}>
            Data guasto / incidente
          </label>
          <input type="date" value={dataGuasto}
            min={preno.dal} max={preno.al}
            onChange={e => { setDataGuasto(e.target.value); setMezzoNuovo(''); }}
            style={inp} />
          <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4 }}>
            La prenotazione originale verrà chiusa il giorno prima ({dataGuasto
              ? (() => { const d = new Date(dataGuasto + 'T12:00:00'); d.setDate(d.getDate()-1); return formatDate(d.toISOString().slice(0,10)); })()
              : '—'
            })
          </div>
        </div>

        {/* Motivazione */}
        <div style={{ marginBottom: 14 }}>
          <label style={{ display: 'block', fontSize: 11, fontWeight: 700, textTransform: 'uppercase',
            letterSpacing: '.06em', color: 'var(--muted)', marginBottom: 6 }}>
            Motivo
          </label>
          <select value={motivazione} onChange={e => setMotivazione(e.target.value)} style={inp}>
            <option value="guasto">Guasto meccanico</option>
            <option value="incidente">Incidente</option>
            <option value="foratura">Foratura / problema pneumatico</option>
            <option value="altro">Altro</option>
          </select>
        </div>

        {/* Mezzo sostitutivo */}
        <div style={{ marginBottom: 14 }}>
          <label style={{ display: 'block', fontSize: 11, fontWeight: 700, textTransform: 'uppercase',
            letterSpacing: '.06em', color: 'var(--muted)', marginBottom: 6 }}>
            Mezzo sostitutivo — libero {formatDate(dataGuasto)} → {formatDate(preno.al)} ({giorni}gg)
          </label>
          {candidati.length === 0 ? (
            <div style={{ padding: '10px 14px', borderRadius: 6, background: '#fff0f0',
              border: '1px solid #f0b0b0', fontSize: 12, color: '#c85050' }}>
              ⚠️ Nessun mezzo dello stesso tipo disponibile per questo periodo.
              Puoi scegliere una categoria diversa modificando manualmente dopo.
            </div>
          ) : (
            <select value={mezzoNuovo} onChange={e => setMezzoNuovo(e.target.value)} style={inp}>
              <option value="">— Seleziona mezzo sostitutivo —</option>
              {candidati.map(v => (
                <option key={v.id} value={v.id}>
                  {makeVehicleLabel(v) || v.id}
                </option>
              ))}
            </select>
          )}
        </div>

        {/* Note extra */}
        <div style={{ marginBottom: 20 }}>
          <label style={{ display: 'block', fontSize: 11, fontWeight: 700, textTransform: 'uppercase',
            letterSpacing: '.06em', color: 'var(--muted)', marginBottom: 6 }}>
            Note (opzionale)
          </label>
          <input value={noteExtra} onChange={e => setNoteExtra(e.target.value)}
            placeholder="Es. cliente avvisato, mezzo in officina..."
            style={inp} />
        </div>

        {/* Anteprima risultato */}
        {mezzoNuovo && (
          <div style={{ background: '#e8f5e9', border: '1px solid #a5d6a7', borderRadius: 7,
            padding: '10px 14px', marginBottom: 18, fontSize: 12, color: '#1b5e20' }}>
            <div style={{ fontWeight: 700, marginBottom: 4 }}>✓ Cosa verrà creato:</div>
            <div>1. Prenotazione originale <strong>chiusa</strong> il {
              (() => { const d = new Date(dataGuasto + 'T12:00:00'); d.setDate(d.getDate()-1); return formatDate(d.toISOString().slice(0,10)); })()
            } · nota: {motivazione}</div>
            <div style={{ marginTop: 3 }}>2. Nuova prenotazione su <strong>{mezzoNuovo}</strong> dal {formatDate(dataGuasto)} al {formatDate(preno.al)} — stesso cliente</div>
          </div>
        )}

        {/* Bottoni */}
        <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end' }}>
          <button onClick={onClose} style={{ padding: '8px 18px', borderRadius: 6,
            border: '1px solid var(--border)', background: 'transparent', color: 'var(--ink-2)',
            cursor: 'pointer', fontSize: 13 }}>
            Annulla
          </button>
          <button
            disabled={!mezzoNuovo || !dataGuasto}
            onClick={() => onConfirm({ dataGuasto, motivazione, noteExtra, mezzoNuovo, candidati })}
            style={{ padding: '8px 20px', borderRadius: 6, border: 'none',
              background: !mezzoNuovo ? 'var(--border)' : '#c85050',
              color: !mezzoNuovo ? 'var(--muted)' : 'white',
              fontWeight: 700, cursor: !mezzoNuovo ? 'not-allowed' : 'pointer', fontSize: 13 }}>
            🔧 Effettua sostituzione
          </button>
        </div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// CONSEGNA VEICOLO — assegnazione targa + km + carburante
// Apre quando si clicca "🚗 Consegna" su una prenotazione confermata.
// L'operatore sceglie il mezzo esatto (con griglia smart), registra
// km partenza e livello carburante, poi imposta stato → in_corso.
// ═══════════════════════════════════════════════════════════════════
function ConsegnaModal({ preno, prenotazioni, fleet, rentmeVehicles, onConfirm, onClose, fermiFlotta, partners }) {
  const today = todayISO();

  // Costruisce lista mezzi disponibili (stessa logica di PrenoForm con fix id=fleet.v.id)
  const allVehicles = useMemo(() => {
    if (rentmeVehicles && rentmeVehicles.length > 0) {
      const fleetByTarga = {};
      (fleet || []).forEach(fv => { if (fv.targa) fleetByTarga[fv.targa.toUpperCase().trim()] = fv; });
      const fromRentMe = rentmeVehicles.filter(v => v.targa).map(v => {
        const targa  = (v.targa || '').trim().toUpperCase();
        const fleetV = fleetByTarga[targa];
        return {
          id:      fleetV?.id || targa, // usa fleet.v.id se disponibile → vehicleId consistente
          tipo:    fleetV?.tipo || v.tipo || 'auto',
          modello: fleetV?.modello || v.nome || '',
          targa,
          stato:   fleetV?.stato || 'available',
          _source: 'rentme',
        };
      });
      const rmTargas = new Set(fromRentMe.map(v => v.targa));
      return [...fromRentMe, ...(fleet || []).filter(v => v.stato === 'available' && !rmTargas.has((v.targa||'').toUpperCase()))];
    }
    return (fleet || []).filter(v => v.stato === 'available');
  }, [fleet, rentmeVehicles]);

  // Calcola quanti giorni liberi ha ogni mezzo a partire dal dal del noleggio
  const vehicleFitScore = useMemo(() => {
    const scores = {};
    // Confronto tipo su canonicalTipo (moto≡scooter, ecc.): una prenotazione
    // "moto" deve trovare i veicoli "scooter" e viceversa.
    const tipoCanon = canonicalTipo({ tipo: preno.vehicleType || preno.tipo || '' });
    const candidates = allVehicles.filter(v => !tipoCanon || canonicalTipo(v) === tipoCanon);
    const dalDate = preno.dal;
    const alDate  = preno.al;
    const nNoleggio = Math.round((new Date(alDate+'T12:00:00') - new Date(dalDate+'T12:00:00')) / 86400000) + 1;

    candidates.forEach(v => {
      // Trova occupazioni di questo veicolo nel periodo (prenotazioni + fermi programmati)
      const occupato = (prenotazioni || []).some(p =>
        p.id !== preno.id && p.stato !== 'annullata' && p.stato !== 'cancellata' && p.stato !== 'completata' &&
        (matchVehicle(p.vehicleId, v.id, v.targa) ||
         (p.vehicleSchedule||[]).some(s => matchVehicle(s.vehicleId, v.id, v.targa) && s.dal <= alDate && s.al >= dalDate)) &&
        p.dal <= alDate && p.al >= dalDate
      ) || (fermiFlotta || []).some(f =>
        f.vehicleId && f.dal && f.al &&
        matchVehicle(f.vehicleId, v.id, v.targa) &&
        f.dal <= alDate && f.al >= dalDate
      );
      if (occupato) { scores[v.id] = -1; return; }

      // Conta i giorni liberi consecutivi dalla data di partenza
      let cursor = dalDate;
      let freeCount = 0;
      while (cursor <= alDate) {
        const busy = (prenotazioni || []).some(p =>
          p.id !== preno.id && p.stato !== 'annullata' && p.stato !== 'cancellata' && p.stato !== 'completata' &&
          matchVehicle(p.vehicleId, v.id, v.targa) && p.dal <= cursor && p.al >= cursor
        ) || (fermiFlotta || []).some(f =>
          f.vehicleId && f.dal && f.al &&
          matchVehicle(f.vehicleId, v.id, v.targa) && f.dal <= cursor && f.al >= cursor
        );
        if (busy) break;
        freeCount++;
        const d = new Date(cursor + 'T12:00:00');
        d.setDate(d.getDate() + 1);
        cursor = d.toISOString().slice(0, 10);
      }
      scores[v.id] = freeCount;
    });
    return scores;
  }, [allVehicles, prenotazioni, preno, fermiFlotta]);

  // Tipologie disponibili (filtra per tipo del noleggio)
  const tipo = preno.vehicleType || preno.tipo || '';
  const tipoCanon = canonicalTipo({ tipo });
  const nNoleggio = Math.round((new Date(preno.al+'T12:00:00') - new Date(preno.dal+'T12:00:00')) / 86400000) + 1;

  const candidati = useMemo(() => {
    return allVehicles
      .filter(v => !tipoCanon || canonicalTipo(v) === tipoCanon)
      .map(v => ({ ...v, freeScore: vehicleFitScore[v.id] ?? 0 }))
      .sort((a, b) => {
        // -1 = occupato → in fondo
        if (a.freeScore < 0 && b.freeScore >= 0) return 1;
        if (b.freeScore < 0 && a.freeScore >= 0) return -1;
        // Perfetto = copre esattamente il periodo → priorità assoluta
        const aPerfect = a.freeScore >= nNoleggio;
        const bPerfect = b.freeScore >= nNoleggio;
        if (aPerfect && !bPerfect) return -1;
        if (bPerfect && !aPerfect) return 1;
        // Altrimenti: più giorni liberi → meglio
        return b.freeScore - a.freeScore;
      });
  }, [allVehicles, vehicleFitScore, tipo, nNoleggio]);

  // Combo smart se nessun singolo mezzo copre l'intero periodo
  const smartCombo = useMemo(() => {
    if (!tipo || !preno.dal || !preno.al) return null;
    const hasSingle = candidati.some(v => v.freeScore >= nNoleggio);
    if (hasSingle) return null;
    return findBestVehicleCombination(tipo, preno.dal, preno.al, allVehicles, prenotazioni, preno.id);
  }, [candidati, tipo, preno, allVehicles, prenotazioni, nNoleggio]);

  // Stato locale
  const [selectedId,     setSelectedId]     = useState(preno.vehicleId || '');
  const [useCombo,       setUseCombo]        = useState(false);
  const [kmPartenza,     setKmPartenza]      = useState(preno.kmPartenza ?? '');
  const [carburante,     setCarburante]      = useState(preno.carburante || '');
  const [noteConsegna,   setNoteConsegna]    = useState(preno.noteConsegna || '');
  // Luogo di consegna (dove va il mezzo): struttura partner o indirizzo libero.
  // Default dal valore già impostato in prenotazione, se presente.
  const [consegnaStruttura, setConsegnaStruttura] = useState(preno.consegnaStruttura || '');
  const [consegnaIndirizzo, setConsegnaIndirizzo] = useState(preno.consegnaIndirizzo || '');

  const selVehicle  = candidati.find(v => v.id === selectedId);
  const isAvailable = selVehicle ? selVehicle.freeScore >= 0 : false;
  const coversAll   = selVehicle ? selVehicle.freeScore >= nNoleggio : false;
  const canConfirm  = useCombo ? (smartCombo && !smartCombo.impossible) : (selectedId && isAvailable && coversAll);

  const FUEL_OPTS = [
    { val: '100', label: '🟢 Pieno',   color: '#2e6e3e' },
    { val: '75',  label: '🟡 3/4',     color: '#8a7a1a' },
    { val: '50',  label: '🟠 Metà',    color: '#c88a2e' },
    { val: '25',  label: '🔴 1/4',     color: '#c85050' },
  ];

  const inp = { background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 6,
    padding: '8px 10px', fontSize: 13, color: 'var(--ink)', width: '100%', boxSizing: 'border-box' };

  function doConfirm() {
    if (!canConfirm) return;
    if (useCombo && smartCombo && !smartCombo.impossible) {
      const first = smartCombo[0];
      const fv = candidati.find(v => v.id === first.vehicleId);
      const label = fv ? makeVehicleLabel(fv) : first.vehicleId;
      const fvr = fv ? resolveVehicleDisplay(fv) : null;
      onConfirm({
        vehicleId: first.vehicleId,
        vehicleLabel: label,
        vehicleTarga: fvr?.targa || fv?.targa || fv?.plate || '',
        vehicleSchedule: smartCombo.map(s => ({ vehicleId: s.vehicleId, dal: s.dal, al: s.al })),
        kmPartenza: kmPartenza !== '' ? Number(kmPartenza) : null,
        carburante,
        noteConsegna,
        consegnaStruttura, consegnaIndirizzo,
      });
    } else {
      const label = selVehicle ? makeVehicleLabel(selVehicle) : selectedId;
      const svr = selVehicle ? resolveVehicleDisplay(selVehicle) : null;
      onConfirm({
        vehicleId: selectedId,
        vehicleLabel: label,
        vehicleTarga: svr?.targa || selVehicle?.targa || selVehicle?.plate || '',
        vehicleSchedule: null,
        kmPartenza: kmPartenza !== '' ? Number(kmPartenza) : null,
        carburante,
        noteConsegna,
        consegnaStruttura, consegnaIndirizzo,
      });
    }
  }

  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.5)', zIndex: 700,
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '20px' }}
      onClick={onClose}>
      <div className="modal-box" style={{ background: 'var(--bg)', borderRadius: 12, width: '100%', maxWidth: 640,
        maxHeight: '90vh', overflowY: 'auto', boxShadow: '0 24px 72px rgba(0,0,0,.3)' }}
        onClick={e => e.stopPropagation()}>

        {/* Header */}
        <div style={{ padding: '20px 24px 14px', borderBottom: '1px solid var(--border)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
            <div>
              <h2 style={{ margin: 0, fontSize: 18, fontFamily: 'var(--font-serif)', fontWeight: 600 }}>
                🚗 Consegna veicolo
              </h2>
              <div style={{ fontSize: 13, color: 'var(--muted)', marginTop: 3 }}>
                {[preno.clienteCognome, preno.clienteNome].filter(Boolean).join(' ') || 'Cliente'}
                {preno.clienteTel && <> · <a href={`tel:${preno.clienteTel}`} style={{ color: 'var(--accent)' }}>{preno.clienteTel}</a></>}
              </div>
              <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 2 }}>
                {formatDate(preno.dal)} → {formatDate(preno.al)} &nbsp;·&nbsp;
                <strong>{nNoleggio} {nNoleggio === 1 ? 'giorno' : 'giorni'}</strong>
                {tipo && <> &nbsp;·&nbsp; <span style={{ textTransform: 'capitalize' }}>{tipo}</span></>}
              </div>
            </div>
            <button type="button" onClick={onClose}
              style={{ background: 'none', border: 'none', fontSize: 22, cursor: 'pointer',
                color: 'var(--muted)', lineHeight: 1, padding: '0 4px' }}>×</button>
          </div>
        </div>

        <div style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column', gap: 20 }}>

          {/* ── Sezione: Scelta mezzo ── */}
          <div>
            <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--muted)', textTransform: 'uppercase',
              letterSpacing: '.08em', marginBottom: 10 }}>
              Assegnazione mezzo
            </div>

            {/* Griglia veicoli disponibili */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(145px, 1fr))', gap: 8 }}>
              {candidati.slice(0, 18).map(v => {
                const free  = v.freeScore;
                const isSel = v.id === selectedId && !useCombo;
                const covers = free >= nNoleggio;
                const partial = free > 0 && free < nNoleggio;
                const busy  = free < 0;

                let borderColor = 'var(--border)';
                let bgColor     = 'var(--surface)';
                let scoreLabel  = '';
                let scoreColor  = 'var(--muted)';

                if (busy)    { borderColor = '#e0c0c0'; bgColor = '#fff5f5'; scoreLabel = 'Occupato'; scoreColor = '#c85050'; }
                else if (covers)  { borderColor = '#4a9e5c'; bgColor = '#f0f9f2'; scoreLabel = `✓ ${free}gg liberi`; scoreColor = '#2e6e3e'; }
                else if (partial) { borderColor = '#c88a2e'; bgColor = '#fffbf0'; scoreLabel = `⚠ ${free}/${nNoleggio}gg`; scoreColor = '#c88a2e'; }
                else { scoreLabel = `${free}gg liberi`; scoreColor = 'var(--muted)'; }

                if (isSel) { borderColor = '#1f5d83'; bgColor = '#e8f2f9'; }

                return (
                  <button key={v.id} type="button"
                    disabled={busy}
                    onClick={() => { setSelectedId(v.id); setUseCombo(false); }}
                    style={{
                      border: `2px solid ${borderColor}`,
                      background: bgColor, borderRadius: 8,
                      padding: '10px 10px 8px', textAlign: 'left', cursor: busy ? 'not-allowed' : 'pointer',
                      transition: 'border-color .12s, background .12s',
                      opacity: busy ? 0.55 : 1,
                    }}>
                    <div style={{ fontFamily: 'monospace', fontWeight: 700, fontSize: 13, color: 'var(--ink)', letterSpacing: '.04em' }}>
                      {v.targa || v.id}
                    </div>
                    <div style={{ fontSize: 10, color: 'var(--muted)', marginTop: 1 }}>
                      {v.modello || v.tipo || '—'}
                    </div>
                    <div style={{ fontSize: 10, color: scoreColor, marginTop: 3, fontWeight: 600 }}>
                      {scoreLabel}
                    </div>
                  </button>
                );
              })}
            </div>

            {/* Combo automatica se nessun mezzo copre tutto */}
            {smartCombo && !smartCombo.impossible && (
              <div style={{ marginTop: 12, padding: '12px 14px', borderRadius: 8,
                border: `2px solid ${useCombo ? '#1f5d83' : '#c88a2e'}`,
                background: useCombo ? '#e8f2f9' : '#fffbf0' }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: '#c88a2e', marginBottom: 6 }}>
                  🧩 Nessun mezzo copre i {nNoleggio} giorni — combinazione automatica
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginBottom: 8 }}>
                  {smartCombo.map((seg, i) => (
                    <span key={i} style={{ fontSize: 11, background: 'rgba(31,93,131,.1)', color: '#1f5d83',
                      borderRadius: 4, padding: '2px 8px', fontFamily: 'monospace', fontWeight: 600 }}>
                      {seg.vehicleId}
                      <span style={{ fontWeight: 400, color: 'var(--muted)', marginLeft: 4 }}>
                        {formatDate(seg.dal)}→{formatDate(seg.al)}
                      </span>
                      {i < smartCombo.length - 1 && <span style={{ marginLeft: 4 }}>›</span>}
                    </span>
                  ))}
                </div>
                <button type="button" onClick={() => { setUseCombo(true); setSelectedId(''); }}
                  style={{ fontSize: 11, padding: '5px 14px', borderRadius: 5,
                    border: 'none', background: useCombo ? '#1f5d83' : '#c88a2e',
                    color: 'white', fontWeight: 700, cursor: 'pointer' }}>
                  {useCombo ? '✓ Combinazione selezionata' : 'Usa questa combinazione'}
                </button>
              </div>
            )}
            {smartCombo?.impossible && (
              <div style={{ marginTop: 10, padding: '10px 14px', borderRadius: 8,
                border: '1px solid #e0c0c0', background: '#fff5f5', fontSize: 12, color: '#c85050' }}>
                ⚠ Nessuna combinazione possibile per questo periodo. Verifica le prenotazioni esistenti.
              </div>
            )}

            {/* Avviso mezzo già assegnato */}
            {preno.vehicleId && !selectedId && !useCombo && (
              <div style={{ marginTop: 8, fontSize: 12, color: 'var(--muted)', fontStyle: 'italic' }}>
                Mezzo precedentemente assegnato: <strong style={{ fontFamily: 'monospace' }}>{preno.vehicleId}</strong> — selezionalo dalla griglia o scegli un altro.
              </div>
            )}

            {/* Stato selezione corrente */}
            {selectedId && !useCombo && selVehicle && (
              <div style={{ marginTop: 10, padding: '8px 12px', borderRadius: 7,
                background: coversAll ? 'rgba(46,110,62,.08)' : 'rgba(200,138,46,.1)',
                border: `1px solid ${coversAll ? '#4a9e5c' : '#c88a2e'}`,
                fontSize: 12 }}>
                {coversAll
                  ? <span style={{ color: '#2e6e3e', fontWeight: 600 }}>✓ <strong style={{ fontFamily: 'monospace' }}>{selectedId}</strong> disponibile per tutti i {nNoleggio} giorni</span>
                  : <span style={{ color: '#c88a2e', fontWeight: 600 }}>⚠ <strong style={{ fontFamily: 'monospace' }}>{selectedId}</strong> libero solo {selVehicle.freeScore}/{nNoleggio} giorni — considera la combo automatica</span>
                }
              </div>
            )}
          </div>

          {/* ── Sezione: Check-out iniziale ── */}
          <div>
            <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--muted)', textTransform: 'uppercase',
              letterSpacing: '.08em', marginBottom: 10 }}>
              Stato alla partenza
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>

              {/* Km partenza */}
              <div>
                <label style={{ fontSize: 12, color: 'var(--muted)', display: 'block', marginBottom: 4 }}>
                  Km partenza
                </label>
                <input type="number" min={0} step={1} placeholder="es. 12430"
                  value={kmPartenza} onChange={e => setKmPartenza(e.target.value)}
                  style={inp} />
              </div>

              {/* Data consegna (read-only) */}
              <div>
                <label style={{ fontSize: 12, color: 'var(--muted)', display: 'block', marginBottom: 4 }}>
                  Data consegna
                </label>
                <input type="text" readOnly value={formatDate(today)}
                  style={{ ...inp, background: 'var(--surface-2)', color: 'var(--muted)' }} />
              </div>
            </div>

            {/* Luogo di consegna (struttura/alloggio dove va il mezzo) */}
            <div style={{ marginTop: 14 }}>
              <StructureSelect label="Luogo di consegna (dove va il mezzo)" partners={partners || []}
                structureId={consegnaStruttura} onStructureChange={setConsegnaStruttura}
                freeText={consegnaIndirizzo} onFreeTextChange={setConsegnaIndirizzo} />
            </div>

            {/* Carburante */}
            <div style={{ marginTop: 14 }}>
              <label style={{ fontSize: 12, color: 'var(--muted)', display: 'block', marginBottom: 6 }}>
                Livello carburante
              </label>
              <div style={{ display: 'flex', gap: 8 }}>
                {FUEL_OPTS.map(opt => (
                  <button key={opt.val} type="button"
                    onClick={() => setCarburante(carburante === opt.val ? '' : opt.val)}
                    style={{
                      flex: 1, padding: '8px 4px', borderRadius: 6, fontSize: 11, fontWeight: 700,
                      cursor: 'pointer',
                      border: carburante === opt.val ? `2px solid ${opt.color}` : '1px solid var(--border)',
                      background: carburante === opt.val ? opt.color + '22' : 'var(--surface)',
                      color: carburante === opt.val ? opt.color : 'var(--muted)',
                    }}>
                    {opt.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Note consegna */}
            <div style={{ marginTop: 14 }}>
              <label style={{ fontSize: 12, color: 'var(--muted)', display: 'block', marginBottom: 4 }}>
                Note consegna
              </label>
              <textarea rows={2} placeholder="Graffi presenti, accessori consegnati, altro…"
                value={noteConsegna} onChange={e => setNoteConsegna(e.target.value)}
                style={{ ...inp, resize: 'vertical', lineHeight: 1.5 }} />
            </div>
          </div>

          {/* ── Footer ── */}
          <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', paddingTop: 4,
            borderTop: '1px solid var(--border)' }}>
            <button type="button" onClick={onClose}
              style={{ padding: '9px 20px', borderRadius: 7, border: '1px solid var(--border)',
                background: 'transparent', color: 'var(--ink-2)', fontSize: 13, cursor: 'pointer' }}>
              Annulla
            </button>
            <button type="button" onClick={doConfirm} disabled={!canConfirm}
              style={{ padding: '9px 24px', borderRadius: 7, border: 'none',
                background: canConfirm ? '#2e6e3e' : 'var(--muted)',
                color: 'white', fontSize: 13, fontWeight: 700,
                cursor: canConfirm ? 'pointer' : 'not-allowed', transition: 'background .15s' }}>
              🚗 Conferma Consegna
            </button>
          </div>
        </div>

      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// RICONSEGNA MODAL — registra km finale, carburante, danni al rientro
// ═══════════════════════════════════════════════════════════════════
function RiconsegnaModal({ preno, onConfirm, onClose }) {
  const [kmRientro, setKmRientro] = useState(preno.kmRientro ?? '');
  const [carburante, setCarburante] = useState(preno.carburante || '');
  const [danniCheck, setDanniCheck] = useState({
    carrozzeria: false, cristalli: false, pneumatici: false,
    interni: false, specchietti: false, altro: false,
  });
  const [noteDanni, setNoteDanni] = useState(preno.noteDanni || '');
  const [noteRientro, setNoteRientro] = useState(preno.noteRientro || '');

  const kmPartenza = preno.kmPartenza;
  const kmPercorsi = (kmRientro !== '' && kmPartenza != null)
    ? Math.max(0, Number(kmRientro) - Number(kmPartenza))
    : null;
  const hasDanni = Object.values(danniCheck).some(Boolean);

  const CARBURANTE_OPTIONS = [
    { val: 'vuoto',  label: '▭ Vuoto',   color: '#c85050' },
    { val: '1/4',    label: '¼',          color: '#e07030' },
    { val: '1/2',    label: '½',          color: '#c88a2e' },
    { val: '3/4',    label: '¾',          color: '#4a7a3a' },
    { val: 'pieno',  label: '▮ Pieno',   color: '#2a6e20' },
  ];

  const DANNI_LABELS = {
    carrozzeria: 'Carrozzeria', cristalli: 'Cristalli', pneumatici: 'Pneumatici',
    interni: 'Interni', specchietti: 'Specchietti', altro: 'Altro',
  };

  const doConfirm = () => {
    const danni = Object.entries(danniCheck).filter(([, v]) => v).map(([k]) => DANNI_LABELS[k]);
    onConfirm({
      kmRientro:   kmRientro !== '' ? Number(kmRientro) : null,
      carburanteRientro: carburante || null,
      danniRiscontrati:  danni.length ? danni : null,
      noteDanni:   hasDanni ? noteDanni : '',
      noteRientro: noteRientro || '',
    });
  };

  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.45)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: 16 }}>
      <div className="modal-box" style={{ background: 'var(--surface)', borderRadius: 12, padding: 28, width: '100%', maxWidth: 520, maxHeight: '90vh', overflowY: 'auto', boxShadow: '0 8px 40px rgba(0,0,0,.18)' }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 20 }}>
          <div>
            <div className="serif" style={{ fontSize: 20, fontWeight: 600 }}>📍 Riconsegna</div>
            <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 2 }}>
              {[preno.clienteCognome, preno.clienteNome].filter(Boolean).join(' ')}
              {preno.vehicleLabel && <> · <span className="mono font-semibold">{preno.vehicleLabel}</span></>}
            </div>
          </div>
          <button type="button" onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--muted)', padding: 4 }}>
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* KM */}
        <div style={{ marginBottom: 18 }}>
          <label style={{ display: 'block', fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--ink-2)', marginBottom: 8 }}>
            Chilometri al rientro
          </label>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <input
              type="number" min="0" value={kmRientro}
              onChange={e => setKmRientro(e.target.value)}
              placeholder="es. 12450"
              style={{ width: 160, padding: '9px 12px', border: '1.5px solid var(--border)', borderRadius: 6, fontSize: 16, fontFamily: 'var(--font-mono)', outline: 'none', color: 'var(--ink)' }}
            />
            {kmPercorsi !== null && (
              <div style={{ fontSize: 13, color: 'var(--muted)' }}>
                <span style={{ fontWeight: 600, color: 'var(--ink)' }}>{kmPercorsi}</span> km percorsi
                {kmPartenza != null && <span style={{ marginLeft: 6 }}>(da {kmPartenza})</span>}
              </div>
            )}
          </div>
        </div>

        {/* CARBURANTE AL RIENTRO */}
        <div style={{ marginBottom: 18 }}>
          <label style={{ display: 'block', fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--ink-2)', marginBottom: 8 }}>
            Carburante al rientro
            {preno.carburante && <span style={{ fontWeight: 400, color: 'var(--muted)', marginLeft: 8, textTransform: 'none' }}>
              (alla partenza: {preno.carburante})
            </span>}
          </label>
          <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
            {CARBURANTE_OPTIONS.map(opt => (
              <button key={opt.val} type="button"
                onClick={() => setCarburante(v => v === opt.val ? '' : opt.val)}
                style={{ padding: '7px 14px', borderRadius: 6, border: `2px solid ${carburante === opt.val ? opt.color : 'var(--border)'}`, background: carburante === opt.val ? opt.color + '20' : 'transparent', color: carburante === opt.val ? opt.color : 'var(--ink-2)', fontWeight: 600, fontSize: 13, cursor: 'pointer', transition: 'all .15s' }}>
                {opt.label}
              </button>
            ))}
          </div>
        </div>

        {/* DANNI */}
        <div style={{ marginBottom: 18 }}>
          <label style={{ display: 'block', fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--ink-2)', marginBottom: 8 }}>
            Danni riscontrati
          </label>
          <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: hasDanni ? 10 : 0 }}>
            {Object.entries(DANNI_LABELS).map(([key, label]) => (
              <button key={key} type="button"
                onClick={() => setDanniCheck(d => ({ ...d, [key]: !d[key] }))}
                style={{ padding: '6px 13px', borderRadius: 6, border: `2px solid ${danniCheck[key] ? 'var(--accent)' : 'var(--border)'}`, background: danniCheck[key] ? 'var(--accent-soft)' : 'transparent', color: danniCheck[key] ? 'var(--accent-deep)' : 'var(--ink-2)', fontWeight: danniCheck[key] ? 700 : 400, fontSize: 12, cursor: 'pointer', transition: 'all .15s' }}>
                {danniCheck[key] ? '⚠ ' : ''}{label}
              </button>
            ))}
          </div>
          {hasDanni && (
            <textarea
              value={noteDanni} onChange={e => setNoteDanni(e.target.value)}
              placeholder="Descrivi i danni riscontrati…"
              rows={2}
              style={{ width: '100%', padding: '8px 10px', border: '1.5px solid var(--accent)', borderRadius: 6, fontSize: 13, resize: 'vertical', outline: 'none', color: 'var(--ink)', background: 'var(--bg)', marginTop: 4 }}
            />
          )}
          {!hasDanni && (
            <div style={{ fontSize: 12, color: 'var(--success)', fontStyle: 'italic', marginTop: 4 }}>
              ✓ Nessun danno selezionato
            </div>
          )}
        </div>

        {/* NOTE RIENTRO */}
        <div style={{ marginBottom: 22 }}>
          <label style={{ display: 'block', fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--ink-2)', marginBottom: 6 }}>
            Note operatore
          </label>
          <textarea
            value={noteRientro} onChange={e => setNoteRientro(e.target.value)}
            placeholder="Note interne sul rientro…"
            rows={2}
            style={{ width: '100%', padding: '8px 10px', border: '1px solid var(--border)', borderRadius: 6, fontSize: 13, resize: 'vertical', outline: 'none', color: 'var(--ink)', background: 'var(--bg)' }}
          />
        </div>

        {/* ACTIONS */}
        <div style={{ display: 'flex', gap: 10 }}>
          <button type="button" onClick={doConfirm}
            style={{ flex: 1, padding: '11px 0', borderRadius: 6, border: 'none', background: hasDanni ? 'var(--accent)' : '#2a6e20', color: '#fff', fontWeight: 700, fontSize: 14, cursor: 'pointer' }}>
            {hasDanni ? '⚠ Conferma rientro con danni' : '✓ Conferma rientro'}
          </button>
          <button type="button" onClick={onClose}
            style={{ padding: '11px 18px', borderRadius: 6, border: '1px solid var(--border)', background: 'transparent', color: 'var(--ink-2)', fontWeight: 500, fontSize: 13, cursor: 'pointer' }}>
            Annulla
          </button>
        </div>
      </div>
    </div>
  );
}

function ProrogaModal({ preno, onConfirm, onClose }) {
  const [giorni, setGiorni] = useState(1);
  const nuovaFine = new Date(preno.al + 'T12:00:00');
  nuovaFine.setDate(nuovaFine.getDate() + giorni);
  const nuovaFineISO = nuovaFine.toISOString().slice(0, 10);
  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.45)', zIndex: 600,
      display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ background: 'var(--bg)', borderRadius: 10, padding: '28px 32px',
        width: 380, boxShadow: '0 20px 60px rgba(0,0,0,.25)' }}>
        <h2 style={{ margin: '0 0 4px', fontSize: 18, fontFamily: 'var(--font-serif)', fontWeight: 600 }}>
          Proroga noleggio
        </h2>
        <p style={{ margin: '0 0 20px', fontSize: 13, color: 'var(--muted)' }}>
          {[preno.clienteCognome, preno.clienteNome].filter(Boolean).join(' ')} · {preno.vehicleLabel || '—'}
        </p>
        <div style={{ marginBottom: 16 }}>
          <div style={{ fontSize: 11, color: 'var(--muted)', marginBottom: 4, textTransform: 'uppercase', letterSpacing: '.06em' }}>
            Rientro attuale
          </div>
          <div style={{ fontWeight: 600, fontSize: 15 }}>{formatDate(preno.al)}</div>
        </div>
        <div style={{ marginBottom: 20 }}>
          <div style={{ fontSize: 11, color: 'var(--muted)', marginBottom: 8, textTransform: 'uppercase', letterSpacing: '.06em' }}>
            Giorni di proroga
          </div>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
            {[1, 2, 3, 5, 7, 14].map(g => (
              <button key={g} type="button"
                onClick={() => setGiorni(g)}
                style={{ padding: '6px 14px', borderRadius: 20, fontSize: 13, cursor: 'pointer', fontWeight: giorni === g ? 700 : 400,
                  border: giorni === g ? 'none' : '1px solid var(--border)',
                  background: giorni === g ? 'var(--accent)' : 'transparent',
                  color: giorni === g ? 'white' : 'var(--ink-2)' }}>
                +{g}g
              </button>
            ))}
            <input type="number" min={1} max={90} value={giorni} onChange={e => setGiorni(Math.max(1, parseInt(e.target.value)||1))}
              style={{ width: 60, padding: '6px 8px', border: '1px solid var(--border)', borderRadius: 6, fontSize: 13,
                background: 'var(--bg)', color: 'var(--ink)', textAlign: 'center' }} />
          </div>
          <div style={{ marginTop: 12, fontSize: 13, color: 'var(--ink-2)' }}>
            Nuovo rientro: <strong style={{ color: 'var(--ink)' }}>{formatDate(nuovaFineISO)}</strong>
          </div>
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <button type="button" onClick={onClose}
            style={{ flex: 1, padding: '9px', borderRadius: 6, border: '1px solid var(--border)',
              background: 'transparent', color: 'var(--ink-2)', cursor: 'pointer', fontSize: 13 }}>
            Annulla
          </button>
          <button type="button" onClick={() => onConfirm(giorni)}
            style={{ flex: 2, padding: '9px', borderRadius: 6, border: 'none',
              background: 'var(--accent)', color: 'white', fontWeight: 700, cursor: 'pointer', fontSize: 13 }}>
            ⏱ Conferma proroga +{giorni}g
          </button>
        </div>
      </div>
    </div>
  );
}


// ═══════════════════════════════════════════════════════════════════
// PREVENTIVI — listino prezzi + calcolo preventivo (v0.14)
// Porta in Pratica il sistema tariffario di EDOX:
//   · 12 categorie veicoli · 3 stagioni (bassa/media/alta)
//   · Calcolo automatico: tariffa giornaliera vs settimanale
//   · Regola agosto: solo settimanale, minimo 7 giorni
//   · Bottone WhatsApp · Aggiungi a Prenotazione
// ═══════════════════════════════════════════════════════════════════

// ── Stagioni ────────────────────────────────────────────────────────
const EDO_SEASONS = {
  bassa: { name: 'Bassa stagione', months: [0,1,2,3,9,10,11], color: '#4a6a35', bg: '#eaf3e3', label: 'BASSA' },
  media: { name: 'Media stagione', months: [4,5,6,8],         color: '#b87333', bg: '#fdf3e3', label: 'MEDIA' },
  alta:  { name: 'Alta stagione',  months: [7],               color: '#c14a2b', bg: '#faeaea', label: 'ALTA'  },
};

function getSeason(dateStr) {
  if (!dateStr) return 'bassa';
  const m = new Date(dateStr + 'T12:00:00').getMonth();
  if (EDO_SEASONS.alta.months.includes(m))  return 'alta';
  if (EDO_SEASONS.media.months.includes(m)) return 'media';
  return 'bassa';
}

function isAugust(dateStr) {
  if (!dateStr) return false;
  return new Date(dateStr + 'T12:00:00').getMonth() === 7;
}

