// ═══════════════════════════════════════════════════════════════════
// FUNZIONI DI MIGRAZIONE DATI PERSISTITI
// Queste funzioni vengono passate come opzione `migrate` a usePersistentState.
// Girano SIA sui dati localStorage all'avvio SIA sui dati caricati dal
// backend Render, garantendo che nessun re-fetch remoto possa annullare
// la migrazione (bug delle migration-useEffect, rimosso in v0.43.2).
// Ogni funzione è pura: restituisce lo stesso riferimento se nulla cambia.
// ═══════════════════════════════════════════════════════════════════

// ── migrateListino ───────────────────────────────────────────────
// Garantisce che TUTTE le entry di LISTINO siano presenti nel dato
// persistito, aggiunge quelle mancanti, aggiorna nome/tipo/categoria
// dai valori master. I prezzi modificati dall'utente restano intatti.
function migrateListino(ls) {
  if (!Array.isArray(ls)) return LISTINO;
  const masterIds = new Set(LISTINO.map(m => m.id));
  const idMap = Object.fromEntries(ls.map(e => [e.id, e]));
  let changed = false;

  // 1. Rimuovi voci non più nel master (es. vecchio 'mehari' → ora 'auto_aperta')
  const senzaObsoleti = ls.filter(e => {
    if (!masterIds.has(e.id)) { changed = true; return false; } // rimuovi
    return true;
  });

  // 2. Aggiorna nome/tipo/categoria dal master, preserva i prezzi dell'utente
  const updated = senzaObsoleti.map(e => {
    const master = LISTINO.find(m => m.id === e.id);
    if (!master) return e;
    const patch = {};
    if (e.nome      !== master.nome)      patch.nome      = master.nome;
    if (e.tipo      !== master.tipo)      patch.tipo      = master.tipo;
    if (e.categoria !== master.categoria) patch.categoria = master.categoria;
    if (!Object.keys(patch).length) return e;
    changed = true;
    return { ...e, ...patch };
  });

  // 3. Aggiungi voci nuove presenti nel master ma assenti nel dato persistito
  const toAdd = LISTINO.filter(m => !idMap[m.id]);
  if (toAdd.length) changed = true;

  return changed ? [...updated, ...toAdd] : ls;
}

// ── migratePartners ──────────────────────────────────────────────
// • Sincronizza nome/tipo/indirizzo/fissa dei partner sistema (s1–sN)
//   con i valori master di INITIAL_PARTNERS. I partner aggiunti dall'utente
//   (id non in INITIAL_PARTNERS) non vengono toccati.
// • Aggiunge i partner di INITIAL_PARTNERS non ancora presenti nel dato
//   persistito (es. s23/s24 aggiunti in v0.42.7–8 ma non ancora nel backend).
function migratePartners(ps) {
  if (!Array.isArray(ps)) return INITIAL_PARTNERS;
  const masterMap = Object.fromEntries(INITIAL_PARTNERS.map(p => [p.id, p]));
  let changed = false;
  const next = ps.map(p => {
    const ref = masterMap[p.id];
    if (!ref) return p;
    const patch = {};
    if (ref.nome      !== undefined && p.nome      !== ref.nome)      patch.nome      = ref.nome;
    if (ref.tipo      !== undefined && p.tipo      !== ref.tipo)      patch.tipo      = ref.tipo;
    if (ref.indirizzo !== undefined && p.indirizzo !== ref.indirizzo) patch.indirizzo = ref.indirizzo;
    if (ref.fissa     !== undefined && p.fissa     !== ref.fissa)     patch.fissa     = ref.fissa;
    if (!Object.keys(patch).length) return p;
    changed = true;
    return { ...p, ...patch };
  });
  // Aggiunge partner di sistema non ancora presenti nel dato persistito
  const existingIds = new Set(ps.map(p => p.id));
  const toAdd = INITIAL_PARTNERS.filter(p => !existingIds.has(p.id));
  if (toAdd.length) changed = true;
  return changed ? [...next, ...toAdd] : ps;
}

// ── migrateAgency ────────────────────────────────────────────────
// Aggiunge campi mancanti da INITIAL_AGENCY (solo se absent/null,
// non sovrascrive le scelte dell'utente). Corregge cellulari da
// stringa → array (cambio struttura pre-v0.36, causa crash su .join).
function migrateAgency(ag) {
  if (!ag || typeof ag !== 'object') return INITIAL_AGENCY;
  const patch = {};
  for (const [k, v] of Object.entries(INITIAL_AGENCY)) {
    if (ag[k] === undefined || ag[k] === null) patch[k] = v;
  }
  if (typeof ag.cellulari === 'string') {
    patch.cellulari = ag.cellulari ? [ag.cellulari] : INITIAL_AGENCY.cellulari;
  }
  return Object.keys(patch).length ? { ...ag, ...patch } : ag;
}

// ── migrateCargos ────────────────────────────────────────────────
// Aggiunge istatLuogo, questuraPec, autoSendTimeout se assenti.
// Critici per la generazione contratti CARGOS.
function migrateCargos(cfg) {
  if (!cfg || typeof cfg !== 'object') return INITIAL_CARGOS_CONFIG;
  const patch = {};
  for (const [k, v] of Object.entries(INITIAL_CARGOS_CONFIG)) {
    if (cfg[k] === undefined || cfg[k] === null) patch[k] = v;
  }
  return Object.keys(patch).length ? { ...cfg, ...patch } : cfg;
}

// ── migrateOperators ─────────────────────────────────────────────
// Aggiunge role e enabled agli operatori che ne sono privi.
// Tutti gli operatori esistenti erano di fatto admin.
function migrateOperators(ops) {
  if (!Array.isArray(ops) || !ops.length) return MOCK_OPERATORS;
  let changed = false;
  const next = ops.map(op => {
    const patch = {};
    if (op.enabled === undefined) patch.enabled = true;
    if (!op.role)                 patch.role    = 'admin';
    if (!Object.keys(patch).length) return op;
    changed = true;
    return { ...op, ...patch };
  });
  return changed ? next : ops;
}

// ── migrateFleet ─────────────────────────────────────────────────
// • normalizza tipo 'moto' → 'scooter' (rinomina pre-v0.35)
// • assegna id deterministico ai veicoli privi (import ante-v0.32)
//   usando targa o combinazione marca+modello+anno per stabilità
function migrateFleet(fl) {
  if (!Array.isArray(fl)) return fl;
  let changed = false;
  const next = fl.map(v => {
    const patch = {};
    if ((v.tipo || '').toLowerCase() === 'moto') patch.tipo = 'scooter';
    if (!v.id) {
      // ID deterministico: stabile tra refresh, unico per veicolo
      const key = (v.targa || `${v.marca || ''}-${v.modello || ''}-${v.anno || ''}`);
      patch.id = `migrated-${key.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '')}`;
    }
    if (!Object.keys(patch).length) return v;
    changed = true;
    return { ...v, ...patch };
  });
  return changed ? next : fl;
}

// ── migratePrenotazioni ──────────────────────────────────────────
// • aggiunge codice EDO mancante (prenotazioni ante-v0.38)
// • aggiunge fonte='manuale' se assente (ante-v0.38)
// • normalizza stato='annullata' → 'cancellata' (annullata non è mai stato
//   in PRENO_STATI ma potrebbe esistere in dati storici ante-v0.43.12)
// Nota: generateBookingCode() è deterministicamente random —
// in caso di doppio caricamento (localStorage poi backend) il codice
// potrebbe differire, ma al secondo avvio app il backend ha già il
// valore migrato e restituisce lo stesso → stabile dopo la prima run.
function migratePrenotazioni(ps) {
  if (!Array.isArray(ps)) return ps;
  let changed = false;
  const next = ps.map(p => {
    const patch = {};
    if (!p.codice) patch.codice = generateBookingCode();
    if (!p.fonte)  patch.fonte  = 'manuale';
    if (p.stato === 'annullata') patch.stato = 'cancellata'; // normalizza legacy
    if (!Object.keys(patch).length) return p;
    changed = true;
    return { ...p, ...patch };
  });
  return changed ? next : ps;
}

// ── Calcolo preventivo (multi-stagione) ──────────────────────────────
// Divide il periodo in segmenti per stagione:
//   es. 28 lug → 5 ago = 4g luglio (media) + 5g agosto (alta)
//   · agosto: €weekly/7 × giorni, nessun rincaro
//   · altri mesi: ceil(weekly/7) [+ €5 se totale soggiorno < 7gg, esclusi bici/ebike]
// Il rincaro +€5 è calcolato sul TOTALE giorni, non sul singolo segmento.
function calcPreventivo(cat, dal, al) {
  const dalDate     = new Date(dal + 'T12:00:00');
  const alDate      = new Date(al  + 'T12:00:00');
  const totalGiorni = Math.max(1, Math.round((alDate - dalDate) / 86400000) + 1);
  if (totalGiorni <= 0) return null;

  const isBici     = cat.tipo === 'ebike' || cat.tipo === 'bici' || cat.tipo === 'bicicletta';
  const conRincaro = !isBici && totalGiorni < 7; // basato sul totale soggiorno

  // ── Raggruppa giorni consecutivi per stagione ─────────────────────
  const segments = [];
  for (let i = 0; i < totalGiorni; i++) {
    const d      = new Date(dalDate.getTime() + i * 86400000);
    const m      = d.getMonth();
    const agosto = m === 7;
    const season = agosto ? 'alta'
      : EDO_SEASONS.media.months.includes(m) ? 'media'
      : 'bassa';
    const last = segments[segments.length - 1];
    if (last && last.season === season && last.agosto === agosto) {
      last.giorni++;
    } else {
      segments.push({ season, agosto, giorni: 1 });
    }
  }

  // ── Calcola costo per ogni segmento ──────────────────────────────
  let totale = 0;
  const righe = [];
  const multiSeason = segments.length > 1;

  for (const seg of segments) {
    const rates = cat[seg.season];
    if (!rates) continue;
    const weeklyRate = rates.weekly || 0; // guard su weekly mancante → mai NaN
    if (weeklyRate === 0) continue;       // categoria non configurata per questa stagione
    let segCosto;
    if (seg.agosto) {
      // Agosto: weekly/7 × giorni (senza maggiorazione)
      const dailyAgo = weeklyRate / 7;
      segCosto = Math.round(seg.giorni * dailyAgo);
      righe.push({
        desc: `${seg.giorni}g agosto × €${dailyAgo.toFixed(2)}/g`,
        sub: segCosto, season: 'alta',
      });
    } else {
      const effectiveDaily = conRincaro
        ? Math.ceil(weeklyRate / 7 + 5)
        : Math.ceil(weeklyRate / 7);
      segCosto = seg.giorni * effectiveDaily;
      const stagLabel = multiSeason ? ` (${EDO_SEASONS[seg.season]?.label || seg.season})` : '';
      righe.push({
        desc: `${seg.giorni}g${stagLabel} × €${effectiveDaily}/g`,
        sub: segCosto, season: seg.season,
      });
    }
    totale += segCosto;
  }

  // ── Campi backward-compat (basati sulla data di inizio) ──────────
  const primarySeason = getSeason(dal);
  const primaryAgosto = isAugust(dal);
  const primaryRates  = cat[primarySeason] || {};
  const effectiveDailyReturn = primaryAgosto
    ? Math.round((primaryRates.weekly || 0) / 7 * 100) / 100
    : conRincaro
      ? Math.ceil((primaryRates.weekly || 0) / 7 + 5)
      : Math.ceil((primaryRates.weekly || 0) / 7);

  return {
    totale, righe, risparmio: 0, giorni: totalGiorni,
    season: primarySeason, agosto: primaryAgosto,
    rates: primaryRates, effectiveDaily: effectiveDailyReturn,
    isBici, conRincaro, multiSeason,
  };
}

// ── QuoteCard — singola categoria con prezzo calcolato ───────────────
function QuoteCard({ cat, dal, al, onPrenota, fleet, rentmeVehicles, prenotazioni, fermiFlotta }) {
  const [open, setOpen] = useState(false);
  const [lang, setLang] = useState('it');
  // Codice univoco generato una volta per questo preventivo — segue fino alla prenotazione
  const [bookingCode] = useState(() => generateBookingCode());

  // Mini disponibilità per le date selezionate
  // Preferisce rentmeVehicles (tipo già normalizzato da normalizzaTipoEdox)
  // su fleet locale che può avere tipo='auto' come fallback per tutti i veicoli.
  // Se rentmeVehicles non contiene veicoli di questo tipo (es. bici muscolari),
  // ricade automaticamente sul fleet locale per quel tipo.
  const disponibilita = useMemo(() => {
    if (!dal || !al) return null;
    const ct = (cat.tipo || '').toLowerCase();
    const tipoMatch = v => {
      const t = canonicalTipo(v);
      return t === ct || (t === 'moto' && ct === 'scooter') || (t === 'scooter' && ct === 'moto');
    };
    // Scegli sorgente: RentMe se ha veicoli di questo tipo (canonicalTipo gestisce quad150/300/bicicletta),
    // altrimenti fleet locale. Con i fix canonicalTipo, quad150/300 e bici muscolari sono trovati in RentMe.
    const rmVehicles = (rentmeVehicles && rentmeVehicles.length > 0) ? rentmeVehicles : [];
    const hasRmForTipo = rmVehicles.some(tipoMatch);
    const source = hasRmForTipo ? rmVehicles : (fleet || []);
    if (!source.length) return null;
    // Primo filtro: stesso tipo (usa canonicalTipo per alias moto→scooter, bicicletta→ebike/bici, quad150→quad)
    let stessoTipo = source.filter(tipoMatch);
    // Secondo filtro: sottocategoria (cc/categoria) se la card ha un campo categoria
    if (cat.categoria && stessoTipo.length > 0) {
      stessoTipo = stessoTipo.filter(v => {
        let vcat = getVehicleCategoria(v) || '';
        if ((v.tipo || '').toLowerCase() === 'auto') vcat = normalizeAutoCategoria(vcat);
        const targetCat = (v.tipo || '').toLowerCase() === 'auto' ? normalizeAutoCategoria(cat.categoria) : cat.categoria;
        return vcat === targetCat;
      });
    }
    if (!stessoTipo.length) return null;
    const occupati = new Set();
    (prenotazioni || [])
      .filter(p => p.dal <= al && p.al >= dal && p.stato !== 'annullata' && p.stato !== 'cancellata' && p.stato !== 'completata')
      .forEach(p => {
        if (p.vehicleId) occupati.add(p.vehicleId);
        (p.vehicleSchedule || []).forEach(s => {
          if (s.vehicleId && s.dal <= al && s.al >= dal) occupati.add(s.vehicleId);
        });
      });
    // Fermi programmati: manutenzione blocca il veicolo
    (fermiFlotta || []).forEach(f => {
      if (f.vehicleId && f.dal <= al && f.al >= dal) occupati.add(f.vehicleId);
    });
    // Normalizza id: rentmeVehicles usa targa come vehicleId (come in PrenoForm)
    const liberi = stessoTipo.filter(v => {
      const id = (v.targa || v.id || '').toUpperCase().trim();
      return !id || !occupati.has(id);
    }).length;
    return { liberi, totale: stessoTipo.length };
  }, [fleet, rentmeVehicles, prenotazioni, fermiFlotta, dal, al, cat.tipo, cat.categoria]);
  // Modal dati cliente prima di generare il PDF
  const [showClienteModal, setShowClienteModal] = useState(false);
  const [clientePdf, setClientePdf] = useState({ nome: '', tel: '', email: '', note: '' });
  // Pre-PDF: prezzo override e note interne (solo uso interno, non nel PDF al cliente)
  const [prezzoOverride, setPrezzoOverride] = useState('');
  const [noteInterne, setNoteInterne] = useState('');
  // Reset prezzoOverride quando il calcolo cambia
  useEffect(() => { setPrezzoOverride(q ? String(q.totale ?? '') : ''); }, [dal, al]);

  const q = calcPreventivo(cat, dal, al);
  if (!q) return null;

  const seas = EDO_SEASONS[q.season];
  const displayDaily = q.effectiveDaily || q.rates.daily;

  function buildWhatsApp() {
    const i18n = PREVENTIVO_I18N[lang] || PREVENTIVO_I18N.it;
    const testo = i18n.waText(cat.nome, formatDate(dal), formatDate(al), q.giorni, seas.name, q.totale, q.risparmio||0)
      + `\n\nCodice preventivo: *${bookingCode}*`;
    return `https://wa.me/?text=${encodeURIComponent(testo)}`;
  }

  return (
    <div style={{
      background: 'var(--bg)', border: '1px solid var(--border)',
      borderRadius: 8, overflow: 'hidden',
    }}>
      {/* Row principale */}
      <div
        style={{ display: 'flex', alignItems: 'center', padding: '12px 14px', cursor: 'pointer', gap: 12 }}
        onClick={() => setOpen(o => !o)}
      >
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 600, fontSize: 14, color: 'var(--ink)' }}>{cat.nome}</div>
          <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 2, display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: '0 6px' }}>
            <span style={{
              padding: '1px 7px', borderRadius: 10, fontSize: 10, fontWeight: 700,
              color: seas.color, background: seas.bg,
            }}>{seas.label}</span>
            <span>
              {q.agosto && <span style={{ color: '#c14a2b', fontWeight: 600 }}>Regola agosto · </span>}
              {!q.agosto && q.effectiveDaily && q.effectiveDaily !== q.rates.daily && (
                <span style={{ color: '#b87333', fontWeight: 600 }}>€{q.effectiveDaily}/g </span>
              )}
              {!q.agosto && (!q.effectiveDaily || q.effectiveDaily === q.rates.daily) && `€${q.rates.daily}/g `}
              · €{q.rates.weekly}/sett
              {q.conRincaro && <span style={{ color: 'var(--muted)', marginLeft: 4, fontSize: 9 }}>(+€5/g rincaro)</span>}
            </span>
            {/* Mini disponibilità — visibile solo se le date sono impostate e ci sono mezzi in flotta */}
            {disponibilita && (
              <span style={{
                fontSize: 10, fontWeight: 600,
                color: disponibilita.liberi === 0 ? '#c0392b'
                     : disponibilita.liberi === 1 ? '#e67e22'
                     : '#27ae60',
              }}>
                {'· '}
                <span style={{
                  display: 'inline-block', width: 6, height: 6, borderRadius: '50%', marginRight: 3,
                  background: disponibilita.liberi === 0 ? '#c0392b'
                            : disponibilita.liberi === 1 ? '#e67e22'
                            : '#27ae60',
                  verticalAlign: 'middle', marginBottom: 1,
                }} />
                {disponibilita.liberi === 0
                  ? 'nessuno libero'
                  : `${disponibilita.liberi} di ${disponibilita.totale} liber${disponibilita.liberi === 1 ? 'o' : 'i'}`}
              </span>
            )}
          </div>
        </div>

        <div style={{ textAlign: 'right', flexShrink: 0 }}>
          <div style={{ fontSize: 22, fontWeight: 700, fontFamily: 'var(--font-serif)', color: 'var(--ink)' }}>
            €{q.totale}
          </div>
          {q.risparmio > 0 && (
            <div style={{ fontSize: 10, color: '#4a9e5c', fontWeight: 600 }}>
              risparmi €{q.risparmio}
            </div>
          )}
        </div>

        <ChevronDown style={{
          width: 16, height: 16, color: 'var(--muted)', flexShrink: 0,
          transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s',
        }} />
      </div>

      {/* Dettaglio breakdown */}
      {open && (
        <div style={{ borderTop: '1px solid var(--border)', padding: '10px 14px 12px', background: 'var(--surface-2)' }}>
          <div style={{ fontSize: 12, marginBottom: 10 }}>
            {q.righe.map((r, i) => (
              <div key={i} style={{
                display: 'flex', justifyContent: 'space-between',
                color: r.warn ? '#c14a2b' : 'var(--ink-2)',
                fontWeight: r.warn ? 600 : 400,
                marginBottom: 3,
              }}>
                <span>{r.desc}</span>
                {r.sub != null && <span style={{ fontFamily: 'monospace' }}>€{r.sub}</span>}
              </div>
            ))}
            <div style={{
              display: 'flex', justifyContent: 'space-between',
              borderTop: '1px solid var(--border)', paddingTop: 6, marginTop: 4,
              fontWeight: 700, color: 'var(--ink)',
            }}>
              <span>Totale {q.giorni} giorni</span>
              <span>€{q.totale}</span>
            </div>
          </div>

          {/* Selettore lingua */}
          <div style={{ display: 'flex', gap: 5, marginBottom: 8 }}>
            {PREVENTIVO_LANGS.map(l => (
              <button key={l.id} type="button" onClick={() => setLang(l.id)}
                title={l.label}
                style={{ padding: '3px 9px', borderRadius: 5, border: `1px solid ${lang===l.id ? 'var(--ink)' : 'var(--border)'}`, background: lang===l.id ? 'var(--ink)' : 'var(--bg)', color: lang===l.id ? 'var(--bg)' : 'var(--ink-2)', fontSize: 13, cursor: 'pointer', fontWeight: lang===l.id ? 700 : 400 }}>
                {l.flag}
              </button>
            ))}
            <span style={{ fontSize: 10, color: 'var(--muted)', alignSelf: 'center', marginLeft: 4 }}>
              {PREVENTIVO_LANGS.find(l => l.id === lang)?.label}
            </span>
          </div>
          {/* Codice prenotazione */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10, padding: '7px 10px', borderRadius: 6, background: 'var(--bg)', border: '1px dashed var(--border)' }}>
            <span style={{ fontSize: 10, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '.06em' }}>Codice</span>
            <span style={{ fontFamily: 'monospace', fontWeight: 700, fontSize: 14, letterSpacing: '.12em', color: 'var(--ink)' }}>{bookingCode}</span>
            <span style={{ fontSize: 10, color: 'var(--muted)', marginLeft: 'auto' }}>segue nella prenotazione</span>
          </div>

          {/* ── Riga azioni preventivo ── */}
          <div style={{ display: 'flex', gap: 8 }}>
            <a
              href={buildWhatsApp()}
              target="_blank"
              rel="noreferrer"
              style={{
                flex: 1, padding: '7px 0', borderRadius: 5, textAlign: 'center',
                fontSize: 12, fontWeight: 600, textDecoration: 'none',
                background: '#25d366', color: 'white',
              }}
            >
              📲 WhatsApp
            </a>
            <button
              type="button"
              onClick={() => setShowClienteModal(true)}
              style={{
                padding: '7px 12px', borderRadius: 5, border: 'none',
                fontSize: 12, fontWeight: 600, cursor: 'pointer',
                background: '#1a1815', color: 'white', display: 'flex', alignItems: 'center', gap: 4,
              }}
              title="Inserisci dati cliente e genera PDF preventivo"
            >
              <Printer className="w-3 h-3" /> PDF
            </button>
            <button
              type="button"
              onClick={() => onPrenota({ cat, dal, al, totale: q.totale, giorni: q.giorni, codice: bookingCode })}
              style={{
                flex: 1, padding: '7px 0', borderRadius: 5, border: 'none',
                fontSize: 12, fontWeight: 600, cursor: 'pointer',
                background: 'var(--accent)', color: 'white',
              }}
            >
              + Prenota
            </button>
          </div>

          {/* ── Invia contratto firmato / per accettazione ── */}
          <div style={{ marginTop: 10, paddingTop: 10, borderTop: '1px solid var(--border)' }}>
            <div style={{ fontSize: 10, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '.06em', marginBottom: 6 }}>
              Invia contratto / accettazione
            </div>
            <div style={{ display: 'flex', gap: 6 }}>
              {/* WhatsApp contratto */}
              <a
                href={(() => {
                  const tel = clientePdf.tel ? clientePdf.tel.replace(/\D/g,'') : '';
                  const msg = `Edonoleggio Lampedusa — contratto noleggio ${cat.nome}\nDal ${formatDate(dal)} al ${formatDate(al)}\nCodice: ${bookingCode}\n\nIn allegato il contratto firmato.`;
                  return tel
                    ? `https://wa.me/${tel.startsWith('39') ? tel : '39' + tel}?text=${encodeURIComponent(msg)}`
                    : `https://wa.me/?text=${encodeURIComponent(msg)}`;
                })()}
                target="_blank"
                rel="noreferrer"
                style={{
                  flex: 1, padding: '6px 0', borderRadius: 5, textAlign: 'center',
                  fontSize: 11, fontWeight: 600, textDecoration: 'none',
                  background: '#25d366', color: 'white',
                }}
                title="Apri WhatsApp — allega manualmente il PDF del contratto"
              >
                📲 WA
              </a>
              {/* Email contratto */}
              <a
                href={(() => {
                  const to = clientePdf.email || '';
                  const sub = `Contratto noleggio — ${cat.nome} ${formatDate(dal)}–${formatDate(al)}`;
                  const body = `Gentile Cliente,\n\nIn allegato il contratto di noleggio per:\nMezzo: ${cat.nome}\nDal ${formatDate(dal)} al ${formatDate(al)}\nCodice: ${bookingCode}\n\nEdonoleggio Lampedusa`;
                  return `mailto:${to}?subject=${encodeURIComponent(sub)}&body=${encodeURIComponent(body)}`;
                })()}
                style={{
                  flex: 1, padding: '6px 0', borderRadius: 5, textAlign: 'center',
                  fontSize: 11, fontWeight: 600, textDecoration: 'none',
                  background: '#1a6fbf', color: 'white',
                }}
                title="Apri client email — allega il PDF del contratto"
              >
                ✉ Email
              </a>
              {/* SMS — predisposto, disabilitato fino ad abbonamento */}
              <button
                type="button"
                disabled
                style={{
                  flex: 1, padding: '6px 0', borderRadius: 5, border: '1px dashed var(--border)',
                  fontSize: 11, fontWeight: 600, cursor: 'not-allowed', opacity: 0.5,
                  background: 'transparent', color: 'var(--muted)',
                }}
                title="SMS — disponibile con abbonamento servizio SMS"
              >
                💬 SMS
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Modal dati cliente per PDF ──────────────────────────────── */}
      {showClienteModal && (
        <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.45)', zIndex: 500, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          onClick={() => setShowClienteModal(false)}>
          <div style={{ background: 'var(--bg)', borderRadius: 12, padding: '24px 28px', width: 380, boxShadow: '0 24px 60px rgba(0,0,0,.3)' }}
            onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
              <div style={{ fontFamily: 'var(--font-serif)', fontWeight: 600, fontSize: 16 }}>Preventivo PDF</div>
              <button type="button" onClick={() => setShowClienteModal(false)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--muted)', fontSize: 20 }}>×</button>
            </div>
            <div style={{ fontSize: 11, color: 'var(--muted)', marginBottom: 14 }}>
              Codice: <strong style={{ fontFamily: 'monospace', letterSpacing: '.1em' }}>{bookingCode}</strong> · Compila i dati e personalizza il preventivo prima di stamparlo.
            </div>

            {/* ── Prezzi (solo interno — non visibile al cliente) ── */}
            <div style={{ background:'var(--surface-2)', border:'1px solid var(--border)', borderRadius:8, padding:'12px 14px', marginBottom:14 }}>
              <div style={{ fontSize:11, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'#b87333', marginBottom:8 }}>
                🔒 Solo interno — non compare nel PDF al cliente
              </div>
              <div style={{ display:'flex', gap:10, alignItems:'flex-end' }}>
                <div style={{ flex:1 }}>
                  <label style={{ display:'block', fontSize:11, fontWeight:600, color:'var(--ink-2)', textTransform:'uppercase', letterSpacing:'.05em', marginBottom:4 }}>
                    Prezzo (€) <span style={{ fontWeight:400, color:'var(--muted)' }}>— calcolato: €{q.totale}</span>
                  </label>
                  <input
                    type="number" min="0" step="1"
                    value={prezzoOverride}
                    onChange={e => setPrezzoOverride(e.target.value)}
                    placeholder={String(q.totale || '')}
                    style={{ width:'100%', padding:'7px 10px', borderRadius:6, border:'1.5px solid #b87333', fontSize:15, fontWeight:700, background:'var(--bg)', color:'var(--ink)' }}
                  />
                </div>
                <button type="button" onClick={() => setPrezzoOverride(String(q.totale || ''))}
                  style={{ padding:'7px 10px', borderRadius:6, border:'1px solid var(--border)', background:'transparent', color:'var(--muted)', fontSize:12, cursor:'pointer', whiteSpace:'nowrap', flexShrink:0 }}>
                  Reset
                </button>
              </div>
              <div style={{ marginTop:8 }}>
                <label style={{ display:'block', fontSize:11, fontWeight:600, color:'var(--ink-2)', textTransform:'uppercase', letterSpacing:'.05em', marginBottom:4 }}>Note interne</label>
                <input
                  type="text"
                  value={noteInterne}
                  onChange={e => setNoteInterne(e.target.value)}
                  placeholder="Appunti per uso interno (non nel PDF)…"
                  style={{ width:'100%', padding:'7px 10px', borderRadius:6, border:'1px solid var(--border)', fontSize:12, background:'var(--bg)', color:'var(--ink)' }}
                />
              </div>
            </div>

            {/* ── Dati cliente per il PDF ── */}
            {[
              { key: 'nome',  label: 'Nome e cognome',  placeholder: 'Es. Mario Rossi' },
              { key: 'tel',   label: 'Telefono',        placeholder: '+39 320 …' },
              { key: 'email', label: 'Email',           placeholder: 'cliente@email.com' },
              { key: 'note',  label: 'Note per il cliente', placeholder: 'Volo, ora arrivo…' },
            ].map(f => (
              <div key={f.key} style={{ marginBottom: 10 }}>
                <label style={{ display: 'block', fontSize: 11, fontWeight: 600, color: 'var(--ink-2)', textTransform: 'uppercase', letterSpacing: '.05em', marginBottom: 4 }}>{f.label}</label>
                <input value={clientePdf[f.key]} onChange={e => setClientePdf(c => ({ ...c, [f.key]: e.target.value }))}
                  placeholder={f.placeholder}
                  style={{ width: '100%', padding: '7px 10px', borderRadius: 6, border: '1px solid var(--border)', fontSize: 13, background: 'var(--bg)', color: 'var(--ink)' }} />
              </div>
            ))}
            <div style={{ display: 'flex', gap: 8, marginTop: 18 }}>
              <button type="button" onClick={() => setShowClienteModal(false)}
                style={{ flex: 1, padding: '9px', borderRadius: 6, border: '1px solid var(--border)', background: 'transparent', color: 'var(--ink-2)', cursor: 'pointer', fontSize: 13 }}>
                Annulla
              </button>
              <button type="button" onClick={() => {
                const prezzoFinal = prezzoOverride !== '' && !isNaN(Number(prezzoOverride)) ? Number(prezzoOverride) : q.totale;
                setShowClienteModal(false);
                exportPreventivoPDF({
                  catName: cat.nome, dal, al,
                  stagione: q.season, isWeekly: false,
                  total: prezzoFinal,
                  totalDays: q.giorni,
                  codice: bookingCode,
                  cliente: clientePdf,
                  breakdown: [
                    ...q.righe.map(r => ({ label: r.desc || '', gg: 0, price: 0, subtotal: r.sub || 0 })),
                    ...(prezzoFinal !== q.totale ? [{ label: 'Prezzo personalizzato', gg: 0, price: 0, subtotal: prezzoFinal }] : []),
                  ],
                }, null, lang);
              }}
                style={{ flex: 1, padding: '9px', borderRadius: 6, border: 'none', background: '#1a1815', color: 'white', cursor: 'pointer', fontSize: 13, fontWeight: 700 }}>
                🖨 Genera PDF
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ── ListinoTable — tabella prezzi senza date ─────────────────────────
function ListinoTable({ filter }) {
  const cats = filter ? LISTINO.filter(c => c.id.startsWith(filter) || c.nome.toLowerCase().includes(filter)) : LISTINO;
  const thStyle = {
    padding: '9px 12px', textAlign: 'left', fontSize: 11, fontWeight: 700,
    textTransform: 'uppercase', letterSpacing: '0.08em',
    color: 'var(--bg)', background: 'var(--ink)',
  };
  const tdStyle = { padding: '9px 12px', fontSize: 13, borderBottom: '1px solid var(--border)' };
  const num = { ...tdStyle, textAlign: 'right', fontFamily: 'monospace', fontWeight: 600 };

  return (
    <div style={{ overflowX: 'auto', border: '1px solid var(--border)', borderRadius: 8, background: 'var(--bg)' }}>
      <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 580 }}>
        <thead>
          <tr>
            <th style={thStyle}>Mezzo</th>
            {['Bassa', 'Media', 'Alta'].map(s => (
              <th key={s} style={{ ...thStyle, textAlign: 'right' }} colSpan={2}>{s}</th>
            ))}
          </tr>
          <tr style={{ background: 'var(--surface-2)' }}>
            <th style={{ ...tdStyle, fontWeight: 600, fontSize: 11 }}></th>
            {['bassa', 'media', 'alta'].map(s => (
              <>
                <th key={s+'d'} style={{ ...tdStyle, textAlign: 'right', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>Giorno</th>
                <th key={s+'w'} style={{ ...tdStyle, textAlign: 'right', fontSize: 10, color: 'var(--muted)', fontWeight: 600 }}>Settimana</th>
              </>
            ))}
          </tr>
        </thead>
        <tbody>
          {cats.map(c => (
            <tr key={c.id} style={{ transition: 'background 0.1s' }}
              onMouseEnter={e => e.currentTarget.style.background = 'var(--surface-2)'}
              onMouseLeave={e => e.currentTarget.style.background = ''}>
              <td style={{ ...tdStyle, fontWeight: 600, fontFamily: 'var(--font-serif)' }}>{c.nome}</td>
              {['bassa', 'media', 'alta'].map(s => (
                <>
                  <td key={s+'d'} style={num}>€{c[s].daily}</td>
                  <td key={s+'w'} style={num}>€{c[s].weekly}</td>
                </>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// ── PreventiviPage ───────────────────────────────────────────────────
function PreventiviPage({ setPage, setPrenotazioniPrefill, listino: listinoProps, fleet, rentmeVehicles, prenotazioni, pushToast, fermiFlotta }) {
  // Merge: parte sempre dalle categorie MASTER (tutte e 11) per garantire
  // che nessuna categoria sparisca se il listino persistito è incompleto.
  // I prezzi personalizzati dall'utente (bassa/media/alta) sovrascrivono il master.
  // tipo e categoria vengono SEMPRE presi dal master per evitare valori obsoleti.
  const userPriceMap = Object.fromEntries((listinoProps || []).map(c => [c.id, c]));
  const listinoCats = LISTINO.map(master => {
    const saved = userPriceMap[master.id];
    if (!saved) return master; // categoria non ancora salvata → usa il master
    // Prezzi utente prevalgono, nome/tipo/categoria sempre dal master
    return {
      ...saved,
      nome:      master.nome,
      tipo:      master.tipo,
      categoria: master.categoria,
    };
  });
  const today = todayISO();
  const [dal, setDal] = useState(today);
  const [al, setAl]   = useState('');
  const [vehicleModal, setVehicleModal] = useState(null); // null | { cat, vehicles, totale }

  // Stessa logica di BancoRapido: raccoglie i veicoli di una categoria con stato libero/occupato
  function getVehiclesForCat(cat) {
    const ct = (cat.tipo || '').toLowerCase();
    const tipoMatch = t => {
      const tl = (t || '').toLowerCase();
      return tl === ct || (tl === 'moto' && ct === 'scooter') || (tl === 'scooter' && ct === 'moto');
    };
    // Filtro categoria: mostra solo i veicoli della sotto-categoria corretta
    const catMatch = v => {
      if (!cat.categoria) return true;
      let vcat = getVehicleCategoria(v) || '';
      const isAuto = (v.tipo || '').toLowerCase() === 'auto';
      if (isAuto) vcat = normalizeAutoCategoria(vcat);
      const targetCat = isAuto ? normalizeAutoCategoria(cat.categoria) : cat.categoria;
      return vcat === targetCat;
    };
    const fleetVehicles = (fleet || [])
      .filter(v => v.stato !== 'venduto' && v.stato !== 'fuori_uso' && tipoMatch(v.tipo) && catMatch(v))
      .map(v => ({
        ...v,
        label: (v.marca && v.modello) ? `${v.marca} ${v.modello}` : (v.nome || v.targa || v.id),
        targa: resolveVehicleDisplay(v).targa || v.targa || '',
      }));
    const rmVehicles = (rentmeVehicles || [])
      .filter(v => tipoMatch(v.tipo) && catMatch(v))
      .map(v => ({
        ...v,
        label: v.nome || v.modello || v.marca || '',
        targa: resolveVehicleDisplay(v).targa || v.targa || '',
      }));
    const seen = new Set();
    const merged = [];
    for (const v of [...fleetVehicles, ...rmVehicles]) {
      const id = v.id || v.targa;
      if (!id || seen.has(id)) continue;
      seen.add(id);
      merged.push(v);
    }
    const occupati = new Set();
    if (dal && al) {
      (prenotazioni || [])
        .filter(p => p.dal <= al && p.al >= dal && p.stato !== 'annullata' && p.stato !== 'cancellata' && p.stato !== 'completata')
        .forEach(p => {
          if (p.vehicleId) occupati.add(p.vehicleId);
          (p.vehicleSchedule || []).forEach(s => {
            if (s.vehicleId && s.dal <= al && s.al >= dal) occupati.add(s.vehicleId);
          });
        });
      // Fermi programmati: manutenzione blocca il veicolo
      (fermiFlotta || []).forEach(f => {
        if (f.vehicleId && f.dal <= al && f.al >= dal) occupati.add(f.vehicleId);
      });
    }
    return merged.map(v => ({ ...v, libero: !occupati.has(v.id) }));
  }

  function handleVehicleBook(cat, v, totale) {
    setVehicleModal(null);
    const label = v.label || v.targa || cat.nome;
    const targa = v.targa || '';
    if (setPrenotazioniPrefill) {
      setPrenotazioniPrefill({
        vehicleId:    v.id,
        vehicleLabel: label,
        vehicleTarga: targa,
        vehicleType:  cat.tipo,
        dal, al,
        prezzo: totale,
        fonte: 'preventivo',
      });
    }
    setPage('prenotazioni');
    pushToast && pushToast({ tone: 'success', title: '📋 Preventivo → Prenotazione', message: `${v.label || v.targa || cat.nome} · ${dal} → ${al}` });
  }
  const [filterTipo, setFilterTipo] = useState('tutti');
  const [view, setView] = useState('preventivo'); // 'preventivo' | 'listino'
  const [linkCopiato, setLinkCopiato] = useState(false);

  // Leggi ?preventivo=tipo|dal|al dalla URL al mount
  useEffect(() => {
    try {
      const params = new URLSearchParams(window.location.search);
      const val = params.get('preventivo');
      if (val) {
        const [tipo, d, a] = val.split('|');
        if (d) setDal(d);
        if (a) setAl(a);
        if (tipo && tipo !== 'tutti') setFilterTipo(tipo);
      }
    } catch {}
  }, []);

  function copiaLinkPreventivo() {
    try {
      const base = window.location.origin + window.location.pathname;
      const param = [filterTipo !== 'tutti' ? filterTipo : 'tutti', dal, al].join('|');
      const url = `${base}?preventivo=${encodeURIComponent(param)}`;
      navigator.clipboard.writeText(url).then(() => {
        setLinkCopiato(true);
        setTimeout(() => setLinkCopiato(false), 2200);
      });
    } catch {}
  }

  const giorni = dal && al
    ? Math.max(1, Math.round((new Date(al + 'T12:00:00') - new Date(dal + 'T12:00:00')) / 86400000) + 1)
    : 0;

  const season = getSeason(dal);
  const seasInfo = EDO_SEASONS[season];

  const categorieVisibili = listinoCats.filter(c =>
    filterTipo === 'tutti' || c.tipo === filterTipo
  );

  function handlePrenota({ cat, dal, al, totale, giorni }) {
    // Mostra modal selezione veicolo (come BancoRapido) → poi naviga con vehicleId specifico
    const vehicles = getVehiclesForCat(cat);
    setVehicleModal({ cat, vehicles, totale });
  }

  const btnTipo = (id, label) => (
    <button
      key={id}
      type="button"
      onClick={() => setFilterTipo(id)}
      style={{
        padding: '5px 14px', borderRadius: 20, fontSize: 12, cursor: 'pointer',
        border: filterTipo === id ? 'none' : '1px solid var(--border)',
        background: filterTipo === id ? 'var(--ink)' : 'transparent',
        color: filterTipo === id ? 'var(--bg)' : 'var(--ink-2)',
        fontWeight: filterTipo === id ? 600 : 400,
      }}
    >
      {label}
    </button>
  );

  return (
    <>
    <div style={{ padding: '28px 32px', maxWidth: 860, margin: '0 auto' }}>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 24 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 22, fontFamily: 'var(--font-serif)', fontWeight: 600 }}>Preventivi</h1>
          <p style={{ margin: '4px 0 0', fontSize: 13, color: 'var(--muted)' }}>
            Seleziona le date e vedi subito il prezzo per ogni categoria.
          </p>
        </div>
        <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          {dal && al && (
            <button type="button" onClick={copiaLinkPreventivo}
              title="Copia link condivisibile con queste date e categoria"
              style={{
                padding: '7px 12px', borderRadius: 6, fontSize: 12, cursor: 'pointer',
                border: '1px solid var(--border)',
                background: linkCopiato ? '#e8f5e9' : 'transparent',
                color: linkCopiato ? '#2e6e3e' : 'var(--ink-2)',
                fontWeight: 500, display: 'flex', alignItems: 'center', gap: 5,
              }}>
              {linkCopiato ? '✓ Link copiato!' : '🔗 Copia link'}
            </button>
          )}
          {['preventivo', 'listino'].map(v => (
            <button
              key={v}
              type="button"
              onClick={() => setView(v)}
              style={{
                padding: '7px 14px', borderRadius: 6, fontSize: 12, cursor: 'pointer',
                border: '1px solid var(--border)',
                background: view === v ? 'var(--ink)' : 'transparent',
                color: view === v ? 'var(--bg)' : 'var(--ink-2)',
                fontWeight: view === v ? 600 : 400,
                textTransform: 'capitalize',
              }}
            >
              {v === 'preventivo' ? 'Calcola' : 'Listino'}
            </button>
          ))}
        </div>
      </div>

      {/* Date picker */}
      <div style={{
        background: 'var(--bg)', border: '1px solid var(--border)',
        borderRadius: 10, padding: '16px 20px', marginBottom: 20,
        display: 'flex', gap: 16, alignItems: 'flex-end', flexWrap: 'wrap',
      }}>
        <div style={{ flex: '1 1 140px' }}>
          <div style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--ink-2)', marginBottom: 5 }}>
            Dal (ritiro)
          </div>
          <input
            type="date"
            value={dal}
            onChange={e => { setDal(e.target.value); if (al && e.target.value > al) setAl(''); }}
            style={{ width: '100%', padding: '8px 10px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 14, fontFamily: 'monospace', background: 'var(--bg)', color: 'var(--ink)', boxSizing: 'border-box' }}
          />
        </div>
        <div style={{ flex: '1 1 140px' }}>
          <div style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--ink-2)', marginBottom: 5 }}>
            Al (riconsegna)
          </div>
          <input
            type="date"
            value={al}
            min={dal}
            onChange={e => setAl(e.target.value)}
            style={{ width: '100%', padding: '8px 10px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 14, fontFamily: 'monospace', background: 'var(--bg)', color: 'var(--ink)', boxSizing: 'border-box' }}
          />
        </div>

        {/* Riepilogo periodo */}
        {giorni > 0 && (
          <div style={{
            flex: '0 0 auto', padding: '8px 16px', borderRadius: 8,
            background: seasInfo.bg, border: `1px solid ${seasInfo.color}22`,
            textAlign: 'center',
          }}>
            <div style={{ fontSize: 22, fontWeight: 700, fontFamily: 'var(--font-serif)', color: seasInfo.color, lineHeight: 1 }}>
              {giorni}
            </div>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.08em', color: seasInfo.color, marginTop: 2 }}>
              giorni · {seasInfo.label}
            </div>
            {isAugust(dal) && (
              <div style={{ fontSize: 9, color: '#c14a2b', fontWeight: 600, marginTop: 3 }}>
                ⚠ Regola agosto
              </div>
            )}
          </div>
        )}
      </div>

      {/* Filtro tipo */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 16, flexWrap: 'wrap' }}>
        {btnTipo('tutti', 'Tutti')}
        {btnTipo('auto', 'Auto')}
        {btnTipo('scooter', 'Scooter')}
        {btnTipo('quad', 'Quad')}
        {btnTipo('ebike', 'E-bike')}
      </div>

      {/* Contenuto principale */}
      {view === 'listino' ? (
        <ListinoTable />
      ) : giorni > 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          {categorieVisibili.map(cat => (
            <QuoteCard key={cat.id} cat={cat} dal={dal} al={al} onPrenota={handlePrenota} fleet={fleet} rentmeVehicles={rentmeVehicles} prenotazioni={prenotazioni} fermiFlotta={fermiFlotta} />
          ))}
        </div>
      ) : (
        /* Stato vuoto — nessuna data selezionata */
        <div style={{ textAlign: 'center', padding: '48px 20px' }}>
          <div style={{ fontSize: 40, marginBottom: 12, opacity: 0.3 }}>📅</div>
          <div style={{ fontSize: 15, fontFamily: 'var(--font-serif)', color: 'var(--ink)', marginBottom: 6 }}>
            Seleziona le date del noleggio
          </div>
          <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 24 }}>
            Appena scegli dal e al, vedi subito il prezzo per ogni categoria.
          </div>
          <button
            type="button"
            onClick={() => setView('listino')}
            style={{
              padding: '8px 18px', borderRadius: 6, border: '1px solid var(--border)',
              background: 'transparent', color: 'var(--ink-2)', fontSize: 13, cursor: 'pointer',
            }}
          >
            Vedi listino completo →
          </button>
        </div>
      )}
    </div>

    {/* Modal selezione veicolo — identico a BancoRapido */}
    {vehicleModal && (
      <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.55)', zIndex:1000,
        display:'flex', alignItems:'center', justifyContent:'center', padding:20 }}
        onClick={() => setVehicleModal(null)}>
        <div style={{ background:'var(--bg)', borderRadius:14, width:'100%', maxWidth:480,
          maxHeight:'80vh', display:'flex', flexDirection:'column', boxShadow:'0 24px 60px rgba(0,0,0,.35)' }}
          onClick={e => e.stopPropagation()}>
          {/* Header */}
          <div style={{ padding:'18px 22px', borderBottom:'1px solid var(--border)', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
            <div>
              <div style={{ fontFamily:'var(--font-serif)', fontWeight:600, fontSize:17, color:'var(--ink)' }}>
                {vehicleModal.cat.nome}
              </div>
              <div style={{ fontSize:12, color:'var(--muted)', marginTop:2 }}>
                Scegli il mezzo per la prenotazione · {dal} → {al}
              </div>
            </div>
            <button type="button" onClick={() => setVehicleModal(null)}
              style={{ background:'none', border:'none', cursor:'pointer', color:'var(--muted)', fontSize:22, lineHeight:1 }}>×</button>
          </div>
          {/* Lista veicoli */}
          <div style={{ overflowY:'auto', flex:1, padding:'10px 14px' }}>
            {vehicleModal.vehicles.length === 0 && (
              <div style={{ padding:'32px 20px', textAlign:'center', color:'var(--muted)', fontSize:13 }}>
                Nessun veicolo trovato in questa categoria.<br/>
                <button type="button" onClick={() => {
                  setVehicleModal(null);
                  if (setPrenotazioniPrefill) setPrenotazioniPrefill({ vehicleType: vehicleModal.cat.tipo, vehicleLabel: vehicleModal.cat.nome, dal, al, prezzo: vehicleModal.totale, fonte: 'preventivo' });
                  setPage('prenotazioni');
                }} style={{ marginTop:12, padding:'8px 18px', background:'var(--ink)', color:'var(--paper)', border:'none', borderRadius:6, fontSize:13, cursor:'pointer', fontWeight:600 }}>
                  Prenota senza mezzo specifico →
                </button>
              </div>
            )}
            {vehicleModal.vehicles.map(v => {
              const TIPO_EMOJI = { auto:'🚗', scooter:'🛵', moto:'🛵', quad:'🏎', ebike:'⚡', bici:'🚲' };
              const emoji = TIPO_EMOJI[v.tipo] || '🚗';
              // label e targa già risolti da getVehiclesForCat
              const label = v.label || v.targa || v.id;
              const targa = v.targa || '';
              return (
                <button key={v.id || label} type="button"
                  onClick={() => v.libero ? handleVehicleBook(vehicleModal.cat, v, vehicleModal.totale) : null}
                  disabled={!v.libero}
                  style={{
                    width:'100%', display:'flex', alignItems:'center', gap:12,
                    padding:'12px 14px', borderRadius:8, border:'1.5px solid var(--border)',
                    marginBottom:8, textAlign:'left', cursor: v.libero ? 'pointer' : 'not-allowed',
                    background: v.libero ? 'var(--bg)' : 'var(--surface-2)',
                    opacity: v.libero ? 1 : 0.55,
                    transition: 'border-color 0.15s, box-shadow 0.15s',
                  }}
                  onMouseEnter={e => { if (v.libero) { e.currentTarget.style.borderColor='var(--accent)'; e.currentTarget.style.boxShadow='0 2px 10px rgba(0,0,0,.1)'; }}}
                  onMouseLeave={e => { e.currentTarget.style.borderColor='var(--border)'; e.currentTarget.style.boxShadow=''; }}
                >
                  <span style={{ fontSize:24 }}>{emoji}</span>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontWeight:600, fontSize:14, color:'var(--ink)', display:'flex', alignItems:'center', gap:6 }}>
                      {label}
                      {targa && targa !== label && (
                        <span style={{ fontFamily:'monospace', fontSize:11, padding:'1px 6px', background:'var(--surface-2)', borderRadius:4, border:'1px solid var(--border)', color:'var(--ink-2)' }}>
                          {targa}
                        </span>
                      )}
                    </div>
                    <div style={{ fontSize:12, color:'var(--muted)', marginTop:2 }}>
                      {v.tipo ? v.tipo.charAt(0).toUpperCase() + v.tipo.slice(1) : ''}
                      {v.anno && ` · ${v.anno}`}
                      {v.colore && ` · ${v.colore}`}
                    </div>
                  </div>
                  <div style={{
                    fontSize:11, fontWeight:700, padding:'3px 10px', borderRadius:10,
                    background: v.libero ? '#eafaf1' : '#fdecea',
                    color: v.libero ? '#1e8449' : '#c0392b',
                    flexShrink: 0,
                  }}>
                    {v.libero ? 'Libero' : 'Occupato'}
                  </div>
                  {v.libero && <span style={{ color:'var(--accent)', fontWeight:700, fontSize:16, flexShrink:0 }}>→</span>}
                </button>
              );
            })}
          </div>
          {/* Footer */}
          <div style={{ padding:'12px 22px', borderTop:'1px solid var(--border)' }}>
            <button type="button" onClick={() => {
              setVehicleModal(null);
              if (setPrenotazioniPrefill) setPrenotazioniPrefill({ vehicleType: vehicleModal.cat.tipo, vehicleLabel: vehicleModal.cat.nome, dal, al, prezzo: vehicleModal.totale, fonte: 'preventivo' });
              setPage('prenotazioni');
            }} style={{ width:'100%', padding:'9px', borderRadius:7, border:'1px solid var(--border)',
              background:'transparent', color:'var(--ink-2)', cursor:'pointer', fontSize:13 }}>
              Prenota senza mezzo specifico
            </button>
          </div>
        </div>
      </div>
    )}
    </>
  );
}


// ═══════════════════════════════════════════════════════════════════
// DISPONIBILITÀ — heatmap calendario prenotazioni (v0.15)
// Mostra saturazione per categoria su 4 settimane
// ═══════════════════════════════════════════════════════════════════

function DisponibilitaView({ prenotazioni, rentmeVehicles, fleet, fermiFlotta }) {
  const [refDate, setRefDate] = useState(() => todayISO());

  // Costruisce array di 28 giorni a partire dal lunedì della settimana di refDate
  const days = useMemo(() => {
    const d = new Date(refDate + 'T12:00:00');
    const dow = (d.getDay() + 6) % 7; // 0=lun
    d.setDate(d.getDate() - dow);
    const arr = [];
    for (let i = 0; i < 28; i++) {
      arr.push(d.toISOString().slice(0,10));
      d.setDate(d.getDate() + 1);
    }
    return arr;
  }, [refDate]);

  const today = todayISO();

  // Categorie: da RentMe se disponibili, altrimenti hardcoded
  const defaultCats = ['Auto chiusa','Auto cabrio','Auto superior','Mehari',
    'Scooter 50 cc','Scooter 125 cc','Scooter 125 superior',
    'Quad base','Quad 150 cc','E-bike'];

  // Per ogni categoria conta occupazione per giorno
  const matrix = useMemo(() => {
    // Categoria names: da RentMe o fallback
    const catNames = rentmeVehicles && rentmeVehicles.length > 0
      ? [...new Set(rentmeVehicles.map(v => v.nome || v.slug))]
      : defaultCats;

    const result = {};
    catNames.forEach(cat => {
      result[cat] = {};
      days.forEach(day => {
        // Usa calcAvailability per i dati reali quando disponibili
        if (rentmeVehicles && rentmeVehicles.length > 0) {
          const av = calcAvailability(day, day, rentmeVehicles, prenotazioni, fleet, fermiFlotta);
          const match = av.find(c => c.nome === cat || c.id === cat);
          result[cat][day] = match ? match.booked : 0;
        } else {
          // Fallback locale
          const count = (prenotazioni || []).filter(p =>
            p.stato !== 'cancellata' && p.stato !== 'completata' &&
            p.dal <= day && p.al >= day &&
            (p.vehicleLabel || '').toLowerCase().includes(cat.toLowerCase().split(' ')[0].toLowerCase())
          ).length;
          result[cat][day] = count;
        }
      });
    });
    return result;
  }, [prenotazioni, rentmeVehicles, days]);

  const navigate = (delta) => {
    const d = new Date(refDate + 'T12:00:00');
    d.setDate(d.getDate() + delta * 28);
    setRefDate(d.toISOString().slice(0,10));
  };

  const weekLabels = ['Sett 1','Sett 2','Sett 3','Sett 4'];
  const dayLetters = ['L','M','M','G','V','S','D'];

  const cellColor = (count) => {
    if (count === 0) return { bg: '#eaf4ec', color: '#4a9e5c' };
    if (count <= 2)  return { bg: '#fdf3e3', color: '#b87333' };
    return { bg: '#faeaea', color: '#c14a2b' };
  };

  return (
    <div style={{ marginTop: 24, border: '1px solid var(--border)', borderRadius: 10, overflow: 'hidden' }}>
      {/* Header navigazione */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 16px', background: 'var(--surface-2)', borderBottom: '1px solid var(--border)' }}>
        <button type="button" onClick={() => navigate(-1)}
          style={{ background: 'none', border: '1px solid var(--border)', borderRadius: 5, padding: '4px 10px', cursor: 'pointer', fontSize: 13, color: 'var(--ink-2)' }}>‹</button>
        <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--ink)' }}>
          {new Date(days[0] + 'T12:00:00').toLocaleDateString('it-IT', { day:'numeric', month:'short' })} →{' '}
          {new Date(days[27] + 'T12:00:00').toLocaleDateString('it-IT', { day:'numeric', month:'short', year:'numeric' })}
        </div>
        <div style={{ display: 'flex', gap: 6 }}>
          <button type="button" onClick={() => setRefDate(today)}
            style={{ background: 'none', border: '1px solid var(--border)', borderRadius: 5, padding: '4px 10px', cursor: 'pointer', fontSize: 11, color: 'var(--ink-2)' }}>Oggi</button>
          <button type="button" onClick={() => navigate(1)}
            style={{ background: 'none', border: '1px solid var(--border)', borderRadius: 5, padding: '4px 10px', cursor: 'pointer', fontSize: 13, color: 'var(--ink-2)' }}>›</button>
        </div>
      </div>

      {/* Griglia */}
      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 11 }}>
          <thead>
            <tr>
              <th style={{ padding: '6px 10px', textAlign: 'left', fontSize: 10, color: 'var(--muted)', fontWeight: 600, width: 130, borderBottom: '1px solid var(--border)' }}>Categoria</th>
              {days.map((day, i) => {
                const isToday = day === today;
                const dow = new Date(day + 'T12:00:00').getDay();
                const isWeekend = dow === 0 || dow === 6;
                return (
                  <th key={day} style={{
                    padding: '4px 2px', textAlign: 'center', fontSize: 9, fontWeight: isToday ? 800 : 500,
                    color: isToday ? 'var(--accent)' : isWeekend ? 'var(--ink)' : 'var(--muted)',
                    borderBottom: '1px solid var(--border)',
                    borderLeft: i % 7 === 0 ? '2px solid var(--border)' : 'none',
                    minWidth: 22,
                  }}>
                    <div>{dayLetters[(i) % 7]}</div>
                    <div style={{ fontSize: 10, fontWeight: 600 }}>{day.slice(8)}</div>
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {Object.entries(matrix).map(([cat, dayCounts], ri) => (
              <tr key={cat} style={{ background: ri % 2 === 0 ? 'var(--bg)' : 'var(--surface-2)' }}>
                <td style={{ padding: '5px 10px', fontSize: 11, fontWeight: 600, color: 'var(--ink)', whiteSpace: 'nowrap', borderBottom: '1px solid var(--border)' }}>
                  {cat}
                </td>
                {days.map((day, i) => {
                  const count = dayCounts[day] || 0;
                  const { bg, color } = cellColor(count);
                  const isToday = day === today;
                  return (
                    <td key={day} style={{
                      padding: '3px 2px', textAlign: 'center',
                      borderBottom: '1px solid var(--border)',
                      borderLeft: i % 7 === 0 ? '2px solid var(--border)' : 'none',
                      background: isToday ? '#e8f2f9' : count > 0 ? bg : '',
                    }}>
                      {count > 0 && (
                        <span style={{
                          display: 'inline-block', width: 18, height: 18, lineHeight: '18px',
                          borderRadius: 4, fontSize: 10, fontWeight: 700,
                          color, background: bg,
                        }}>{count}</span>
                      )}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div style={{ padding: '8px 16px', fontSize: 10, color: 'var(--muted)', borderTop: '1px solid var(--border)', display: 'flex', gap: 16 }}>
        <span style={{ color: '#4a9e5c', fontWeight: 600 }}>● Libero</span>
        <span style={{ color: '#b87333', fontWeight: 600 }}>● 1–2 prenotazioni</span>
        <span style={{ color: '#c14a2b', fontWeight: 600 }}>● 3+ prenotazioni</span>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// REPORT — dashboard analitica (v0.16)
// KPI, andamento prenotazioni, categorie più richieste, incasso stimato
// ═══════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════
// REPORT AVANZATO v0.18
// Occupazione %, revenue per mese, top clienti, export CSV/Excel
// Props: prenotazioni, contracts, cassa, customers, fleet, operators
// ═══════════════════════════════════════════════════════════════════

function useReportData({ prenotazioni, contracts, cassa, customers, fleet, operators, year }) {
  return useMemo(() => {
    // allP: tutte le prenotazioni dell'anno (per conteggi e revenue)
    const allP = (prenotazioni || []).filter(p => (p.dal || '').startsWith(year));
    // Helper: prezzo validato — esclude valori anomali (>9999) che indicano
    // un dato non-prezzo finito nel campo (es. timestamp, ID, data YYYYMMDD dal sync RentMe).
    // Nessun noleggio a Lampedusa può costare più di €9.999 — qualsiasi valore superiore
    // è sicuramente un errore di import e non deve entrare nei calcoli finanziari.
    // allPLocali: alias per compatibilità con usi successivi (coincide con allP in questo contesto)
    const allPLocali = allP;
    const allC = (contracts    || []).filter(c => (c.createdAt || '').startsWith(year));
    const allK = (cassa        || []).filter(k => (k.data || '').startsWith(year));
    const allFleet = (fleet    || []).filter(v => v.stato !== 'venduto');

    // ── KPI annuali ──────────────────────────────────────────────
    const totPreno     = allP.length;
    const totContratti = allC.length;
    // Revenue prenotazioni: somma dei prezzi NON anomali delle prenotazioni non annullate.
    // safePrezzo() filtra valori > €9.999 (timestamp o ID finiti nel campo prezzo per errore).
    const incassoPreno = allP.filter(p => p.stato !== 'annullata' && p.stato !== 'cancellata').reduce((s,p) => s + safePrezzo(p), 0);
    // Incasso cassa: movimenti fisici registrati nel registro (acconto/saldo)
    const incassoCassa = allK.filter(k => k.tipo !== 'rimborso').reduce((s,k) => s + (Number(k.importo)||0), 0);
    const rimborsiCassa= allK.filter(k => k.tipo === 'rimborso').reduce((s,k) => s + (Number(k.importo)||0), 0);
    // Netto = revenue prenotazioni − rimborsi registrati
    const nettoCassa   = incassoPreno - rimborsiCassa;
    // Da incassare ancora (prezzo prenotazione − quanto già registrato in cassa)
    const daIncassare  = Math.max(0, incassoPreno - incassoCassa);

    // ── Mensile: prenotazioni + revenue ─────────────────────────
    const mesi = Array.from({length:12}, (_,i) => {
      const ym = `${year}-${String(i+1).padStart(2,'0')}`;
      const prenoMese = allP.filter(p => (p.dal||'').startsWith(ym));
      const prenoLocaliMese = allPLocali.filter(p => (p.dal||'').startsWith(ym));
      const prenoMeseAttive = prenoLocaliMese.filter(p => p.stato !== 'annullata' && p.stato !== 'cancellata');
      const cassaMese = allK.filter(k => (k.data||'').startsWith(ym) && k.tipo !== 'rimborso');
      const label = new Date(`${ym}-15`).toLocaleDateString('it-IT', { month:'short' });
      return {
        ym, label, i,
        preno: prenoMese.length, // conteggio totale incluso RentMe (occupazione)
        revPreno: prenoMeseAttive.reduce((s,p) => s + safePrezzo(p), 0),
        revCassa: cassaMese.reduce((s,k) => s+(Number(k.importo)||0), 0),
      };
    });
    const maxPreno = Math.max(...mesi.map(m => m.preno), 1);
    const maxRev   = Math.max(...mesi.map(m => Math.max(m.revPreno, m.revCassa)), 1);

    // ── Occupazione % per categoria per mese ────────────────────
    // Per ogni mese calcola quanti giorni totali disponibili vs occupati per tipo
    const tipiVehicle = ['auto','scooter','quad','ebike'];
    const fleetByTipo = {};
    // 'moto' è alias di 'scooter' (veicoli importati da RentMe)
    tipiVehicle.forEach(t => {
      fleetByTipo[t] = allFleet.filter(v => v.tipo === t || (t === 'scooter' && v.tipo === 'moto')).length;
    });

    const occupazione = mesi.map(m => {
      const daysInMonth = new Date(parseInt(year), m.i+1, 0).getDate();
      const result = { ym: m.ym, label: m.label };
      tipiVehicle.forEach(tipo => {
        const total = (fleetByTipo[tipo] || 0) * daysInMonth;
        if (total === 0) { result[tipo] = 0; return; }
        // Conta giorni-prenotazione per questo tipo in questo mese (escluse cancellate/annullate)
        let giorni = 0;
        allP.filter(p => {
          if (p.stato === 'annullata' || p.stato === 'cancellata') return false;
          const vt = (p.vehicleType||'').toLowerCase();
          const vl = (p.vehicleLabel||'').toLowerCase();
          return vt === tipo || vt === ({auto:'a',scooter:'m',quad:'m',ebike:'e'}[tipo]||'') || vl.startsWith(tipo);
        }).forEach(p => {
          if (!p.dal || !p.al) return;
          const start = new Date(Math.max(new Date(p.dal), new Date(`${m.ym}-01`)));
          const end   = new Date(Math.min(new Date(p.al),  new Date(`${m.ym}-${String(daysInMonth).padStart(2,'0')}`)));
          if (end >= start) giorni += Math.round((end - start) / 86400000) + 1;
        });
        result[tipo] = Math.min(100, Math.round((giorni / total) * 100));
      });
      return result;
    });

    // ── Top categorie ────────────────────────────────────────────
    const catCount = {};
    allP.forEach(p => {
      const k = (p.vehicleLabel||'Non spec.').split('·')[0].trim() || 'Non spec.';
      catCount[k] = (catCount[k]||0) + 1;
    });
    const topCats = Object.entries(catCount).sort((a,b)=>b[1]-a[1]).slice(0,8);

    // ── Top 10 clienti per spesa ─────────────────────────────────
    const clienteSpesa = {};
    allK.filter(k => k.prenotazioneId && k.tipo !== 'rimborso').forEach(k => {
      const id = k.clienteId || k.prenotazioneId;
      if (!clienteSpesa[id]) clienteSpesa[id] = { id, nome: k.clienteNome || '—', spesa: 0, movimenti: 0 };
      clienteSpesa[id].spesa     += (Number(k.importo)||0);
      clienteSpesa[id].movimenti += 1;
    });
    // Arricchisci con dati clienti se disponibili
    const topClienti = Object.values(clienteSpesa)
      .sort((a,b) => b.spesa - a.spesa).slice(0,10)
      .map(c => {
        const cust = (customers||[]).find(x => x.id === c.id);
        return { ...c, nome: cust ? `${cust.cognome} ${cust.nome}` : c.nome };
      });

    // ── Revenue per operatore ────────────────────────────────────
    const opRev = {};
    allK.filter(k => k.tipo !== 'rimborso').forEach(k => {
      const op = k.operatore || 'Non assegnato';
      if (!opRev[op]) opRev[op] = { nome: op, incasso: 0, movimenti: 0 };
      opRev[op].incasso    += (Number(k.importo)||0);
      opRev[op].movimenti  += 1;
    });
    const topOp = Object.values(opRev).sort((a,b) => b.incasso - a.incasso);

    // ── Stato prenotazioni ───────────────────────────────────────
    const statiPreno = {};
    allP.forEach(p => { statiPreno[p.stato||'attesa'] = (statiPreno[p.stato||'attesa']||0)+1; });

    // ── KPI derivati (basati su prenotazioni locali, escluse RentMe) ────
    const prenoConPrezzo = allP.filter(p => safePrezzo(p) > 0 && p.stato !== 'annullata' && p.stato !== 'cancellata');
    const avgTicket = prenoConPrezzo.length > 0
      ? Math.round(prenoConPrezzo.reduce((s,p) => s + safePrezzo(p), 0) / prenoConPrezzo.length) : 0;
    const prenoConDate = allP.filter(p => p.dal && p.al); // durata media: tutte le prenotazioni
    const avgDurata = prenoConDate.length > 0
      ? Math.round(prenoConDate.reduce((s,p) =>
          s + Math.max(1, Math.round((new Date(p.al) - new Date(p.dal)) / 86400000) + 1), 0
        ) / prenoConDate.length) : 0;
    // Clienti unici: solo prenotazioni locali (RentMe ha spesso dati cliente incompleti)
    const clientiUniciSet = new Set(allPLocali.map(p =>
      p.clienteId || `${(p.clienteCognome||'').toLowerCase()}:${(p.clienteNome||'').toLowerCase()}`
    ).filter(Boolean));
    const clientiUnici = clientiUniciSet.size;
    const tassoAnnullamento = allPLocali.length > 0
      ? Math.round(((allPLocali.filter(p => p.stato === 'annullata' || p.stato === 'cancellata').length) / allPLocali.length) * 100) : 0;

    // ── Metodi pagamento (dalla cassa) ───────────────────────────
    const metodiMap = {};
    allK.filter(k => k.tipo !== 'rimborso').forEach(k => {
      const m = k.metodo || 'altro';
      if (!metodiMap[m]) metodiMap[m] = { metodo: m, importo: 0, count: 0 };
      metodiMap[m].importo += (Number(k.importo)||0);
      metodiMap[m].count   += 1;
    });
    const metodi = Object.values(metodiMap).sort((a,b) => b.importo - a.importo);

    // ── Split acconto / saldo / deposito ─────────────────────────
    const tipiCassa = { acconto: 0, saldo: 0, deposito: 0, rimborso: 0, altro: 0 };
    allK.forEach(k => {
      const t = tipiCassa.hasOwnProperty(k.tipo) ? k.tipo : 'altro';
      tipiCassa[t] += (Number(k.importo)||0);
    });

    // ── Fonti prenotazione ───────────────────────────────────────
    const fontiMap = {};
    allP.forEach(p => {
      const f = normFonte(p.fonte);   // unifica alias legacy (walkin→walk_in)
      fontiMap[f] = (fontiMap[f] || 0) + 1;
    });
    const fonti = Object.entries(fontiMap).sort((a,b) => b[1]-a[1]);

    // ── Distribuzione durate ─────────────────────────────────────
    const durBuckets = { '1 giorno': 0, '2–3 gg': 0, '4–7 gg': 0, '1–2 sett.': 0, '> 2 sett.': 0 };
    allP.filter(p => p.dal && p.al).forEach(p => {
      const d = Math.max(1, Math.round((new Date(p.al) - new Date(p.dal)) / 86400000) + 1);
      if (d === 1)      durBuckets['1 giorno']   += 1;
      else if (d <= 3)  durBuckets['2–3 gg']     += 1;
      else if (d <= 7)  durBuckets['4–7 gg']     += 1;
      else if (d <= 14) durBuckets['1–2 sett.']  += 1;
      else              durBuckets['> 2 sett.']   += 1;
    });

    // ── Funnel stati ─────────────────────────────────────────────
    const funnel = [
      { label: 'Bozze',       n: allP.filter(p => p.stato === 'bozza').length,       color: '#888' },
      { label: 'Confermate',  n: allP.filter(p => p.stato === 'confermata').length,  color: '#2e6e3e' },
      { label: 'In corso',    n: allP.filter(p => p.stato === 'in_corso').length,    color: '#1f5d83' },
      { label: 'Completate',  n: allP.filter(p => p.stato === 'completata').length,  color: '#4a6a30' },
      { label: 'Annullate',   n: allP.filter(p => p.stato === 'annullata' || p.stato === 'cancellata').length, color: '#c85050' },
    ];

    // ── Per veicolo (top 15 per revenue stimata) — solo prenotazioni locali
    const veicoloMap = {};
    allPLocali.filter(p => p.vehicleId || p.vehicleLabel).forEach(p => {
      const key = p.vehicleId || p.vehicleLabel || '—';
      if (!veicoloMap[key]) veicoloMap[key] = {
        id: key,
        label: p.vehicleLabel || p.vehicleId || '—',
        tipo: p.vehicleType || p.tipo || '—',
        revenue: 0, giorni: 0, noleggi: 0,
      };
      veicoloMap[key].revenue += safePrezzo(p);
      veicoloMap[key].noleggi += 1;
      veicoloMap[key].giorni  += p.dal && p.al
        ? Math.max(1, Math.round((new Date(p.al) - new Date(p.dal)) / 86400000) + 1) : 0;
    });
    const perVeicolo = Object.values(veicoloMap)
      .sort((a,b) => b.revenue - a.revenue).slice(0, 15);
    const maxVRevenue = perVeicolo[0]?.revenue || 1;

    // ── Retention clienti (tutti gli anni) ───────────────────────
    const clienteCountAll = {};
    (prenotazioni || []).filter(p => p.stato !== 'annullata' && p.stato !== 'cancellata').forEach(p => {
      const key = p.clienteId || `${(p.clienteCognome||'').toLowerCase()}:${(p.clienteNome||'').toLowerCase()}`;
      if (key && key !== ':') clienteCountAll[key] = (clienteCountAll[key] || 0) + 1;
    });
    const clientiTotaliUnici = Object.keys(clienteCountAll).length;
    const clientiRitornati   = Object.values(clienteCountAll).filter(n => n > 1).length;
    const tassoRetention     = clientiTotaliUnici > 0 ? Math.round((clientiRitornati / clientiTotaliUnici) * 100) : 0;

    // ── Previsione revenue futura ─────────────────────────────────
    const todayStr = todayISO();
    const prenoFuture = (prenotazioni || []).filter(p =>
      p.dal > todayStr && (p.stato === 'confermata' || p.stato === 'bozza')
    );
    const revenueFutura     = prenoFuture.filter(p => p.stato === 'confermata').reduce((s,p) => s + safePrezzo(p), 0);
    const revenuePotenziale = prenoFuture.filter(p => p.stato === 'bozza').reduce((s,p) => s + safePrezzo(p), 0);
    const previsioneMap = {};
    prenoFuture.forEach(p => {
      const ym = p.dal.slice(0, 7);
      if (!previsioneMap[ym]) previsioneMap[ym] = {
        ym, label: new Date(`${ym}-15`).toLocaleDateString('it-IT', { month:'short', year:'2-digit' }),
        confermata: 0, bozza: 0, n: 0,
      };
      previsioneMap[ym].n += 1;
      if (p.stato === 'confermata') previsioneMap[ym].confermata += safePrezzo(p);
      if (p.stato === 'bozza')      previsioneMap[ym].bozza      += safePrezzo(p);
    });
    const previsioneList = Object.values(previsioneMap).sort((a,b) => a.ym.localeCompare(b.ym)).slice(0, 9);
    const maxPrev = Math.max(...previsioneList.map(m => m.confermata + m.bozza), 1);

    // ── Distribuzione per giorno della settimana ─────────────────
    const DOW_LABEL = ['Dom','Lun','Mar','Mer','Gio','Ven','Sab'];
    const dowMap = [0,0,0,0,0,0,0];
    allP.filter(p => p.dal).forEach(p => {
      const dow = new Date(p.dal + 'T12:00:00').getDay();
      dowMap[dow] += 1;
    });
    const giorniSettimana = DOW_LABEL.map((label, i) => ({ label, n: dowMap[i] }));
    const maxDow = Math.max(...dowMap, 1);

    // ── Insight automatici ───────────────────────────────────────
    const insights = [];
    if (totPreno > 0) {
      const bestMese = [...mesi].sort((a,b) => b.revCassa - a.revCassa)[0];
      if (bestMese?.revCassa > 0)
        insights.push({ icon:'🏆', text:`${bestMese.label} è il mese con più incassi: €${bestMese.revCassa.toLocaleString('it-IT')}` });
      if (tassoRetention > 0)
        insights.push({ icon:'🔁', text:`${tassoRetention}% dei clienti è tornato più di una volta` });
      if (avgTicket > 0)
        insights.push({ icon:'💶', text:`Ticket medio €${avgTicket} · durata media ${avgDurata} giorni a noleggio` });
      if (fonti.length > 0) {
        const tf = fonti[0];
        insights.push({ icon:'📌', text:`${Math.round((tf[1]/totPreno)*100)}% delle prenotazioni arriva da ${fonteLabel(tf[0])}` });
      }
      if (tassoAnnullamento > 15)
        insights.push({ icon:'⚠️', text:`Tasso annullamento elevato: ${tassoAnnullamento}% — verifica le cause` });
      if (perVeicolo.length > 0 && perVeicolo[0].revenue > 0)
        insights.push({ icon:'🚗', text:`Mezzo più redditizio: ${perVeicolo[0].label} — €${perVeicolo[0].revenue.toLocaleString('it-IT')}` });
      if (revenueFutura > 0)
        insights.push({ icon:'🔮', text:`€${revenueFutura.toLocaleString('it-IT')} di revenue futura già confermata` });
    }

    return { totPreno, totContratti, incassoPreno, incassoCassa, rimborsiCassa, nettoCassa, daIncassare,
             avgTicket, avgDurata, clientiUnici, tassoAnnullamento,
             metodi, tipiCassa, fonti, durBuckets, funnel, perVeicolo, maxVRevenue,
             mesi, maxPreno, maxRev, occupazione, topCats, topClienti, topOp, statiPreno, allP, allK,
             clientiRitornati, clientiTotaliUnici, tassoRetention,
             revenueFutura, revenuePotenziale, prenoFuture, previsioneList, maxPrev,
             giorniSettimana, maxDow, insights };
  }, [prenotazioni, contracts, cassa, customers, fleet, operators, year]);
}

// Esporta dati in CSV
// Carica SheetJS da CDN la prima volta che serve
function loadSheetJS() {
  return new Promise((resolve, reject) => {
    if (window.XLSX) { resolve(window.XLSX); return; }
    const s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
    s.onload  = () => resolve(window.XLSX);
    s.onerror = () => reject(new Error('Impossibile caricare SheetJS'));
    document.head.appendChild(s);
  });
}

async function exportReportXLSX(data, year, pushToast) {
  let XLSX;
  try {
    XLSX = await loadSheetJS();
  } catch(e) {
    pushToast && pushToast({ tone: 'warning', title: 'Export CSV (offline)', message: 'SheetJS non disponibile' });
    const rows = [
      ['REPORT EDONOLEGGIO', year], [],
      ['Prenotazioni', data.totPreno], ['Incassato (cassa)', data.incassoCassa], ['Netto cassa', data.nettoCassa], [],
      ['MESE','N.','Rev. Cassa €'], ...data.mesi.map(m => [m.label, m.preno, m.revCassa]), [],
      ['TOP CLIENTI','Spesa €','Movimenti'], ...data.topClienti.map(c => [c.nome, c.spesa, c.movimenti]),
    ];
    const csv  = rows.map(r => r.join(',')).join('\n');
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url; a.download = `edonoleggio-report-${year}.csv`; a.click();
    URL.revokeObjectURL(url);
    return;
  }

  const wb = XLSX.utils.book_new();

  // Foglio 1: Riepilogo
  const wsR = XLSX.utils.aoa_to_sheet([
    ['REPORT EDONOLEGGIO', year], [],
    ['Prenotazioni totali',            data.totPreno],
    ['Contratti CARGOS',               data.totContratti],
    ['Incasso stimato (preventivi) €', data.incassoPreno],
    ['Incassato (cassa) €',            data.incassoCassa],
    ['Rimborsi €',                     data.rimborsiCassa],
    ['Netto cassa €',                  data.nettoCassa],
  ]);
  wsR['!cols'] = [{ wch: 34 }, { wch: 16 }];
  XLSX.utils.book_append_sheet(wb, wsR, 'Riepilogo');

  // Foglio 2: Mensile
  const wsM = XLSX.utils.aoa_to_sheet([
    ['Mese', 'Prenotazioni', 'Rev. Preventivi €', 'Rev. Cassa €'],
    ...data.mesi.map(m => [m.label + ' ' + year, m.preno, m.revPreno, m.revCassa]),
    [], ['TOTALE',
      data.mesi.reduce((s,m)=>s+m.preno,0),
      data.mesi.reduce((s,m)=>s+m.revPreno,0),
      data.mesi.reduce((s,m)=>s+m.revCassa,0)],
  ]);
  wsM['!cols'] = [{ wch: 14 }, { wch: 14 }, { wch: 20 }, { wch: 16 }];
  XLSX.utils.book_append_sheet(wb, wsM, 'Mensile');

  // Foglio 3: Occupazione %
  const wsO = XLSX.utils.aoa_to_sheet([
    ['Mese', 'Auto %', 'Scooter %', 'Quad %', 'E-bike %'],
    ...data.occupazione.map(m => [m.label + ' ' + year, m.auto, m.scooter, m.quad, m.ebike]),
  ]);
  wsO['!cols'] = [{ wch: 14 }, { wch: 10 }, { wch: 12 }, { wch: 10 }, { wch: 10 }];
  XLSX.utils.book_append_sheet(wb, wsO, 'Occupazione');

  // Foglio 4: Top clienti
  if (data.topClienti.length > 0) {
    const wsC = XLSX.utils.aoa_to_sheet([
      ['#', 'Cliente', 'Spesa €', 'Movimenti'],
      ...data.topClienti.map((c,i) => [i+1, c.nome, c.spesa, c.movimenti]),
    ]);
    wsC['!cols'] = [{ wch: 4 }, { wch: 28 }, { wch: 12 }, { wch: 12 }];
    XLSX.utils.book_append_sheet(wb, wsC, 'Top clienti');
  }

  // Foglio 5: Per operatore
  if (data.topOp.length > 0) {
    const wsP = XLSX.utils.aoa_to_sheet([
      ['Operatore', 'Incasso €', 'Movimenti'],
      ...data.topOp.map(o => [o.nome, o.incasso, o.movimenti]),
    ]);
    wsP['!cols'] = [{ wch: 22 }, { wch: 12 }, { wch: 12 }];
    XLSX.utils.book_append_sheet(wb, wsP, 'Per operatore');
  }

  XLSX.writeFile(wb, `edonoleggio-report-${year}.xlsx`);
  pushToast && pushToast({ tone: 'success', title: 'Excel esportato', message: `edonoleggio-report-${year}.xlsx · 5 fogli` });
}


function ReportPage({ prenotazioni, contracts, cassa, customers, fleet, operators, pushToast }) {
  const currentYear = new Date().getFullYear().toString();
  const [year, setYear] = useState(currentYear);
  const [tab,  setTab]  = useState('overview'); // overview | occupazione | clienti | operatori
  const [showKpiInfo, setShowKpiInfo] = useState(false);

  const availYears = useMemo(() => {
    const years = new Set();
    (prenotazioni||[]).forEach(p => { if (p.dal) years.add(p.dal.slice(0,4)); });
    (cassa||[]).forEach(k => { if (k.data) years.add(k.data.slice(0,4)); });
    years.add(currentYear);
    return [...years].sort((a,b) => b-a);
  }, [prenotazioni, cassa, currentYear]);

  const d = useReportData({ prenotazioni, contracts, cassa, customers, fleet, operators, year });
  const thisMonth = todayISO().slice(0,7);

  const TABS = [
    { id:'overview',    label:'Panoramica' },
    { id:'previsione',  label:'Previsione 🔮' },
    { id:'occupazione', label:'Occupazione %' },
    { id:'clienti',     label:'Clienti 👤' },
    { id:'operatori',   label:'Per operatore' },
    { id:'stagionale',  label:'Stagionale 📅' },
    { id:'cassa',       label:'Cassa 💵' },
    { id:'flotta',      label:'Flotta 🚗' },
    { id:'mix',         label:'Mix 📊' },
    { id:'yoy',         label:'Anno su Anno 📈' },
  ];

  // Dati mensili per grafico stagionale
  const mesiLabels = ['Gen','Feb','Mar','Apr','Mag','Giu','Lug','Ago','Set','Ott','Nov','Dic'];
  const datiMensili = useMemo(() => {
    return mesiLabels.map((label, mi) => {
      const meseStr = `${year}-${String(mi+1).padStart(2,'0')}`;
      const prenoMese = (prenotazioni||[]).filter(p => (p.dal||'').startsWith(meseStr) && p.stato !== 'annullata' && p.stato !== 'cancellata');
      const revenueMese = prenoMese.reduce((s,p) => s + safePrezzo(p), 0);
      const cassaMese = (cassa||[]).filter(k => (k.data||'').startsWith(meseStr) && k.importo > 0).reduce((s,k) => s + (Number(k.importo)||0), 0);
      const fleetCount = (fleet||[]).length || 1;
      const giorni = new Date(Number(year), mi+1, 0).getDate();
      const giorniOccupati = prenoMese.reduce((s,p) => {
        const dal = new Date(Math.max(new Date(p.dal), new Date(`${meseStr}-01`)));
        const al  = new Date(Math.min(new Date(p.al),  new Date(`${meseStr}-${String(giorni).padStart(2,'0')}`)));
        const diff = Math.max(0, Math.round((al - dal) / 86400000) + 1);
        return s + diff;
      }, 0);
      const occ = Math.min(100, Math.round(giorniOccupati / (fleetCount * giorni) * 100));
      return { label, mese: meseStr, prenotazioni: prenoMese.length, revenue: revenueMese, cassa: cassaMese, occupazione: occ };
    });
  }, [prenotazioni, cassa, fleet, year]);

  // Dati YoY: anno selezionato vs anno precedente, stessa struttura mensile
  const prevYear = String(Number(year) - 1);
  const datiMensiliPrev = useMemo(() => {
    return mesiLabels.map((label, mi) => {
      const meseStr = `${prevYear}-${String(mi+1).padStart(2,'0')}`;
      const prenoMese = (prenotazioni||[]).filter(p => (p.dal||'').startsWith(meseStr) && p.stato !== 'annullata' && p.stato !== 'cancellata');
      const revenueMese = prenoMese.reduce((s,p) => s + safePrezzo(p), 0);
      const cassaMese = (cassa||[]).filter(k => (k.data||'').startsWith(meseStr) && k.importo > 0).reduce((s,k) => s + (Number(k.importo)||0), 0);
      const fleetCount = (fleet||[]).length || 1;
      const giorni = new Date(Number(prevYear), mi+1, 0).getDate();
      const giorniOccupati = prenoMese.reduce((s,p) => {
        const dal = new Date(Math.max(new Date(p.dal), new Date(`${meseStr}-01`)));
        const al  = new Date(Math.min(new Date(p.al),  new Date(`${meseStr}-${String(giorni).padStart(2,'0')}`)));
        const diff = Math.max(0, Math.round((al - dal) / 86400000) + 1);
        return s + diff;
      }, 0);
      const occ = Math.min(100, Math.round(giorniOccupati / (fleetCount * giorni) * 100));
      return { label, mese: meseStr, prenotazioni: prenoMese.length, revenue: revenueMese, cassa: cassaMese, occupazione: occ };
    });
  }, [prenotazioni, cassa, fleet, prevYear]);

  const tabBtn = (t) => (
    <button key={t.id} type="button" onClick={() => setTab(t.id)}
      style={{ padding:'7px 18px', fontSize:13, fontWeight:600, borderRadius:5, border:'none', cursor:'pointer',
        background: tab===t.id ? 'var(--ink)' : 'var(--surface-2)',
        color:      tab===t.id ? 'var(--bg)'  : 'var(--ink-2)' }}>
      {t.label}
    </button>
  );

  const card = (label, value, sub, color='var(--ink)') => (
    <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'16px 18px' }}>
      <div style={{ fontSize:11, color:'var(--muted)', textTransform:'uppercase', letterSpacing:'.06em', marginBottom:6 }}>{label}</div>
      <div style={{ fontSize:26, fontWeight:700, fontFamily:'var(--font-serif)', color, lineHeight:1 }}>{value}</div>
      {sub && <div style={{ fontSize:11, color:'var(--muted)', marginTop:4 }}>{sub}</div>}
    </div>
  );

  const maxTopCat = d.topCats[0]?.[1] || 1;

  return (
    <div style={{ padding:'28px 32px', maxWidth:960, margin:'0 auto' }}>
      {/* Header */}
      <div style={{ display:'flex', alignItems:'flex-end', justifyContent:'space-between', marginBottom:20 }}>
        <div>
          <h1 style={{ margin:0, fontSize:22, fontFamily:'var(--font-serif)', fontWeight:600 }}>Report</h1>
          <p style={{ margin:'4px 0 0', fontSize:13, color:'var(--muted)' }}>
            Analisi occupazione, incassi e clienti · anno {year}
          </p>
        </div>
        <div style={{ display:'flex', gap:8, alignItems:'center' }}>
          <select value={year} onChange={e => setYear(e.target.value)}
            style={{ padding:'7px 12px', border:'1px solid var(--border)', borderRadius:5, fontSize:13, background:'var(--bg)', color:'var(--ink)', cursor:'pointer' }}>
            {availYears.map(y => <option key={y} value={y}>{y}</option>)}
          </select>
          <button type="button" onClick={() => exportReportXLSX(d, year, pushToast)}
            style={{ display:'flex', alignItems:'center', gap:6, padding:'7px 16px', background:'var(--ink)', color:'var(--bg)', border:'none', borderRadius:5, fontSize:13, fontWeight:600, cursor:'pointer' }}>
            <Download className="w-4 h-4" /> Export Excel (.xlsx)
          </button>
        </div>
      </div>

      {/* KPI — 2 righe × 3 */}
      <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12, marginBottom:12 }}>
        {card('Prenotazioni '+year, d.totPreno, `${d.totContratti} contratti CARGOS`)}
        {card('Revenue prenotazioni', `€${d.incassoPreno.toLocaleString('it-IT')}`, `In cassa: €${d.incassoCassa.toLocaleString('it-IT')} · Da incassare: €${d.daIncassare.toLocaleString('it-IT')}`, '#1f5d83')}
        {card('Netto (revenue − rimborsi)', `€${d.nettoCassa.toLocaleString('it-IT')}`, `Rimborsi registrati: €${d.rimborsiCassa}`, '#2e6e3e')}
        {card('Ticket medio', d.avgTicket > 0 ? `€${d.avgTicket}` : '—', 'valore medio prenotazione', '#b87333')}
        {card('Durata media', d.avgDurata > 0 ? `${d.avgDurata}g` : '—', 'giorni medi per noleggio', '#6a3d8f')}
        {card('Clienti unici', d.clientiUnici, `annullamenti: ${d.tassoAnnullamento}%`, d.tassoAnnullamento > 15 ? '#c85050' : 'var(--ink)')}
      </div>

      {/* ── Spiegazione KPI ─────────────────────────────────────────── */}
      <div style={{ marginBottom:20 }}>
        <button type="button" onClick={() => setShowKpiInfo(v => !v)}
          style={{ display:'flex', alignItems:'center', gap:5, fontSize:11, color:'var(--muted)',
            background:'none', border:'none', cursor:'pointer', padding:'4px 0' }}>
          <span style={{ width:16, height:16, borderRadius:'50%', border:'1px solid var(--muted)',
            display:'inline-flex', alignItems:'center', justifyContent:'center', fontSize:10, fontWeight:700, flexShrink:0 }}>?</span>
          {showKpiInfo ? 'Nascondi spiegazione' : 'Come si calcolano questi numeri?'}
        </button>
        {showKpiInfo && (
          <div style={{ background:'var(--surface-2)', border:'1px solid var(--border)', borderRadius:8,
            padding:'14px 18px', marginTop:8, fontSize:12, color:'var(--ink-2)', lineHeight:1.7 }}>
            <div style={{ fontWeight:700, color:'var(--ink)', marginBottom:8, fontSize:13 }}>📊 Guida ai numeri del report</div>
            <div style={{ display:'flex', flexDirection:'column', gap:8 }}>
              <div>
                <strong>Prenotazioni {year}</strong> — totale prenotazioni con data inizio nell'anno selezionato (tutti gli stati, incluse annullate e completate).
              </div>
              <div>
                <strong>Revenue prenotazioni</strong> — somma dei <em>prezzi</em> di tutte le prenotazioni non annullate. È il fatturato concordato con i clienti, indipendentemente da quando i soldi arrivano fisicamente.
              </div>
              <div>
                <strong>In cassa</strong> (sottotitolo) — movimenti fisici registrati nel registro (acconti, saldi). Può essere inferiore alla revenue se non tutti i pagamenti sono stati ancora riscossi e registrati.
              </div>
              <div>
                <strong>Da incassare</strong> (sottotitolo) — differenza tra revenue e quanto già in cassa: soldi dovuti ma non ancora riscossi.
              </div>
              <div>
                <strong>Rimborsi</strong> — movimenti di tipo "rimborso" nel registro cassa; sottratti per calcolare il netto.
              </div>
              <div>
                <strong>Netto (revenue − rimborsi)</strong> — fatturato prenotazioni meno i rimborsi registrati: il risultato economico reale dell'anno.
              </div>
              <div>
                <strong>Ticket medio</strong> — media del campo prezzo delle prenotazioni non annullate.
              </div>
              <div>
                <strong>Durata media</strong> — media giorni tra <em>dal</em> e <em>al</em> delle prenotazioni non annullate.
              </div>
              <div>
                <strong>Clienti unici</strong> — clienti distinti per cognome+nome o ID. Il tasso annullamento è la % di prenotazioni con stato "cancellata" (o il legacy "annullata").
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Tab nav */}
      <div style={{ display:'flex', gap:6, marginBottom:20 }}>
        {TABS.map(tabBtn)}
      </div>

      {/* ── PANORAMICA ────────────────────────────────────────── */}
      {tab === 'overview' && (
        <div style={{ display:'flex', flexDirection:'column', gap:20 }}>

          {/* ── Insight strip ─────────────────────────────────── */}
          {d.insights.length > 0 && (
            <div style={{ background:'var(--surface-2)', border:'1px solid var(--border)', borderRadius:8, padding:'14px 18px' }}>
              <div style={{ fontSize:11, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)', marginBottom:10 }}>
                💡 Insight · {year}
              </div>
              <div style={{ display:'flex', flexDirection:'column', gap:6 }}>
                {d.insights.map((ins, i) => (
                  <div key={i} style={{ display:'flex', alignItems:'flex-start', gap:8, fontSize:12, color:'var(--ink)' }}>
                    <span style={{ fontSize:14, lineHeight:1.4 }}>{ins.icon}</span>
                    <span style={{ lineHeight:1.5 }}>{ins.text}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* ── Grafico combinato: prenotazioni + revenue ─────── */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'16px 18px' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:4 }}>
              Prenotazioni e revenue mensile
            </div>
            <div style={{ fontSize:11, color:'var(--muted)', marginBottom:14 }}>
              Barre scure = prenotazioni · barre verdi = incassato · barre sottili = stimato (preventivi)
            </div>
            <div style={{ display:'flex', alignItems:'flex-end', gap:3, height:120 }}>
              {d.mesi.map(m => {
                const hPreno  = Math.max(4, (m.preno / d.maxPreno) * 100);
                const hCassa  = d.maxRev > 0 ? Math.max(m.revCassa > 0 ? 4 : 0,  (m.revCassa  / d.maxRev) * 100) : 0;
                const hPreno2 = d.maxRev > 0 ? Math.max(m.revPreno > 0 ? 4 : 0, (m.revPreno  / d.maxRev) * 100) : 0;
                const isCurrent = m.ym === thisMonth;
                return (
                  <div key={m.ym} title={`${m.label}: ${m.preno} preno · €${m.revCassa} cassa · €${m.revPreno} stima`}
                    style={{ flex:1, display:'flex', alignItems:'flex-end', gap:1, position:'relative', cursor:'default' }}>
                    {/* colonna prenotazioni */}
                    <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:2 }}>
                      <div style={{ width:'100%', borderRadius:'2px 2px 0 0', height:`${hPreno}px`,
                        background: isCurrent ? '#1f5d83' : 'var(--ink)',
                        opacity: isCurrent ? 1 : 0.25+(m.preno/d.maxPreno)*0.6 }} />
                    </div>
                    {/* colonna revenue cassa */}
                    <div style={{ flex:1.4, display:'flex', flexDirection:'column', alignItems:'center', gap:2 }}>
                      <div style={{ fontSize:8, color:'var(--muted)', fontWeight:600, lineHeight:1 }}>
                        {m.revCassa>0?`${(m.revCassa/1000).toFixed(1)}k`:''}
                      </div>
                      <div style={{ width:'100%', borderRadius:'2px 2px 0 0', height:`${hCassa}px`,
                        background:'#2e6e3e', opacity: m.revCassa>0 ? 0.65+(m.revCassa/d.maxRev)*0.35 : 0.1 }} />
                    </div>
                    {/* colonna revenue preventivi (sottile) */}
                    {hPreno2 > 0 && (
                      <div style={{ width:3, alignSelf:'flex-end', borderRadius:'2px 2px 0 0',
                        height:`${hPreno2}px`, background:'#b87333', opacity:0.4 }} />
                    )}
                  </div>
                );
              })}
            </div>
            {/* Asse mesi */}
            <div style={{ display:'flex', gap:3, marginTop:4 }}>
              {d.mesi.map(m => (
                <div key={m.ym} style={{ flex:1, textAlign:'center', fontSize:9, color: m.ym===thisMonth?'#1f5d83':'var(--muted)',
                  fontWeight: m.ym===thisMonth ? 700 : 400 }}>{m.label}</div>
              ))}
            </div>
            <div style={{ display:'flex', gap:14, marginTop:10, fontSize:10, color:'var(--muted)' }}>
              {[['var(--ink)','Prenotazioni'],['#2e6e3e','Incassato (cassa)'],['#b87333','Stimato (preventivi)']].map(([c,l]) => (
                <span key={l} style={{ display:'flex', alignItems:'center', gap:4 }}>
                  <span style={{ width:10, height:10, borderRadius:2, background:c, display:'inline-block', opacity: c==='var(--ink)'?.4:1 }} />
                  {l}
                </span>
              ))}
            </div>
          </div>

          {/* Top categorie + stati */}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:20 }}>
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'16px 18px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
                Categorie più richieste
              </div>
              {d.topCats.length===0
                ? <div style={{ fontSize:12, color:'var(--muted)', fontStyle:'italic' }}>Nessuna prenotazione</div>
                : d.topCats.map(([cat,n]) => (
                  <div key={cat} style={{ marginBottom:8 }}>
                    <div style={{ display:'flex', justifyContent:'space-between', fontSize:12, marginBottom:3 }}>
                      <span style={{ color:'var(--ink)', fontWeight:500 }}>{cat}</span>
                      <span style={{ color:'var(--muted)' }}>{n}</span>
                    </div>
                    <div style={{ height:6, background:'var(--surface-2)', borderRadius:3, overflow:'hidden' }}>
                      <div style={{ height:'100%', width:`${(n/maxTopCat)*100}%`, background:'var(--ink)', borderRadius:3 }} />
                    </div>
                  </div>
                ))
              }
            </div>

            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'16px 18px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
                Stato prenotazioni · {year}
              </div>
              <div style={{ display:'flex', flexDirection:'column', gap:8 }}>
                {Object.entries({
                  confermata:'Confermate', completata:'Completate', in_corso:'In corso',
                  attesa:'In attesa', cancellata:'Cancellate'
                }).map(([stato, label]) => {
                  const n = d.statiPreno[stato]||0;
                  const s = PRENO_STATI[stato] || { color:'var(--ink)', bg:'var(--surface-2)' };
                  return (
                    <div key={stato} style={{ display:'flex', alignItems:'center', gap:10 }}>
                      <div style={{ width:80, fontSize:12, color:'var(--ink-2)' }}>{label}</div>
                      <div style={{ flex:1, height:8, background:'var(--surface-2)', borderRadius:4, overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${d.totPreno>0?(n/d.totPreno)*100:0}%`, background:s.color, borderRadius:4 }} />
                      </div>
                      <div style={{ width:24, fontSize:12, fontWeight:600, textAlign:'right', color:s.color }}>{n}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Retention + upcoming */}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:20 }}>
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'16px 18px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:12 }}>
                Retention clienti
              </div>
              <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
                {[
                  { label:'Clienti totali unici', val: d.clientiTotaliUnici, color:'var(--ink)' },
                  { label:'Clienti ritornati',    val: d.clientiRitornati,   color:'#2e6e3e' },
                  { label:'Tasso retention',      val: `${d.tassoRetention}%`, color: d.tassoRetention>30?'#2e6e3e':d.tassoRetention>15?'#b87333':'#c85050' },
                ].map(r => (
                  <div key={r.label} style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                    <span style={{ fontSize:12, color:'var(--ink-2)' }}>{r.label}</span>
                    <span style={{ fontSize:16, fontWeight:700, color:r.color, fontFamily:'var(--font-serif)' }}>{r.val}</span>
                  </div>
                ))}
                <div style={{ marginTop:4 }}>
                  <div style={{ height:8, background:'var(--surface-2)', borderRadius:4, overflow:'hidden' }}>
                    <div style={{ height:'100%', width:`${d.tassoRetention}%`, borderRadius:4,
                      background: d.tassoRetention>30?'#2e6e3e':d.tassoRetention>15?'#b87333':'#c85050' }} />
                  </div>
                </div>
              </div>
            </div>

            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'16px 18px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:12 }}>
                Prossime prenotazioni
              </div>
              {d.prenoFuture.length === 0
                ? <div style={{ fontSize:12, color:'var(--muted)', fontStyle:'italic', paddingTop:8 }}>Nessuna prenotazione futura confermata</div>
                : (
                  <div style={{ display:'flex', flexDirection:'column', gap:4 }}>
                    {d.prenoFuture.slice(0,5).map((p, i) => {
                      const nome = [p.clienteCognome, p.clienteNome].filter(Boolean).join(' ') || '—';
                      const statoCl = p.stato === 'confermata' ? '#2e6e3e' : '#b87333';
                      return (
                        <div key={i} style={{ display:'flex', justifyContent:'space-between', alignItems:'center',
                          padding:'5px 8px', borderRadius:5, background:'var(--surface-2)', fontSize:12 }}>
                          <span style={{ fontWeight:500, color:'var(--ink)' }}>{nome}</span>
                          <span style={{ color:'var(--muted)', fontSize:11 }}>{p.dal}</span>
                          <span style={{ color:statoCl, fontWeight:600, fontSize:11 }}>
                            {p.stato === 'confermata' ? '✓ conf.' : '○ bozza'}
                          </span>
                        </div>
                      );
                    })}
                    {d.prenoFuture.length > 5 && (
                      <div style={{ fontSize:11, color:'var(--muted)', textAlign:'center', paddingTop:4 }}>
                        +{d.prenoFuture.length - 5} altre — vedi tab Previsione
                      </div>
                    )}
                  </div>
                )
              }
            </div>
          </div>
        </div>
      )}

      {/* ── PREVISIONE 🔮 ─────────────────────────────────────────── */}
      {tab === 'previsione' && (
        <div style={{ display:'flex', flexDirection:'column', gap:16 }}>

          {/* KPI forward */}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12 }}>
            {card('Preno. future conf.',
              d.prenoFuture.filter(p => p.stato === 'confermata').length,
              'Con data futura, già confermate', '#2e6e3e')}
            {card('Revenue confermata',
              d.revenueFutura > 0 ? `€${d.revenueFutura.toLocaleString('it-IT')}` : '—',
              'Da prenotazioni confermate', '#1f5d83')}
            {card('Revenue potenziale',
              d.revenuePotenziale > 0 ? `€${d.revenuePotenziale.toLocaleString('it-IT')}` : '—',
              'Da bozze ancora aperte', '#b87333')}
          </div>

          {/* Barchart previsione per mese */}
          {d.previsioneList.length === 0 ? (
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'32px 20px',
              textAlign:'center', color:'var(--muted)', fontSize:13, fontStyle:'italic' }}>
              Nessuna prenotazione futura con prezzo. Aggiungi prenotazioni con data futura per vedere la previsione.
            </div>
          ) : (
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:6 }}>
                Previsione revenue per mese (futuro)
              </div>
              <div style={{ fontSize:11, color:'var(--muted)', marginBottom:16 }}>
                Verde = confermata · Ambra = potenziale (bozze)
              </div>
              <div style={{ display:'flex', alignItems:'flex-end', gap:8, height:140 }}>
                {d.previsioneList.map(m => {
                  const hConf = Math.max(m.confermata > 0 ? 6 : 0, (m.confermata / d.maxPrev) * 120);
                  const hBozz = Math.max(m.bozza > 0 ? 6 : 0, (m.bozza / d.maxPrev) * 120);
                  return (
                    <div key={m.ym} title={`${m.label}: €${m.confermata} conf. + €${m.bozza} bozze · ${m.n} prenotazioni`}
                      style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:2 }}>
                      <div style={{ fontSize:9, color:'var(--muted)', fontWeight:600, marginBottom:2 }}>
                        {(m.confermata + m.bozza) > 0 ? `€${((m.confermata+m.bozza)/1000).toFixed(1)}k` : ''}
                      </div>
                      <div style={{ width:'100%', display:'flex', gap:2, alignItems:'flex-end', height:120 }}>
                        {m.confermata > 0 && (
                          <div style={{ flex:1, borderRadius:'3px 3px 0 0', height:`${hConf}px`,
                            background:'#2e6e3e', opacity:0.85 }} />
                        )}
                        {m.bozza > 0 && (
                          <div style={{ flex:1, borderRadius:'3px 3px 0 0', height:`${hBozz}px`,
                            background:'#b87333', opacity:0.7 }} />
                        )}
                      </div>
                      <div style={{ fontSize:10, color:'var(--muted)', marginTop:4 }}>{m.label}</div>
                      <div style={{ fontSize:9, color:'var(--ink-2)' }}>{m.n} preno.</div>
                    </div>
                  );
                })}
              </div>
              <div style={{ display:'flex', gap:14, marginTop:10, fontSize:10, color:'var(--muted)' }}>
                <span style={{ display:'flex', alignItems:'center', gap:4 }}>
                  <span style={{ width:10, height:10, borderRadius:2, background:'#2e6e3e', display:'inline-block' }} />
                  Revenue confermata
                </span>
                <span style={{ display:'flex', alignItems:'center', gap:4 }}>
                  <span style={{ width:10, height:10, borderRadius:2, background:'#b87333', display:'inline-block' }} />
                  Revenue potenziale (bozze)
                </span>
              </div>
            </div>
          )}

          {/* Lista prenotazioni future */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
              Prenotazioni future ({d.prenoFuture.length})
            </div>
            {d.prenoFuture.length === 0 ? (
              <div style={{ fontSize:12, color:'var(--muted)', fontStyle:'italic' }}>Nessuna prenotazione futura</div>
            ) : (
              <div style={{ overflowX:'auto' }}>
                <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
                  <thead>
                    <tr style={{ background:'var(--surface-2)' }}>
                      {['Data','Cliente','Mezzo','Prezzo','Stato'].map(h => (
                        <th key={h} style={{ padding:'7px 12px', textAlign:'left', fontSize:10,
                          fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em',
                          color:'var(--ink-2)', borderBottom:'1px solid var(--border)' }}>{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {d.prenoFuture.slice(0,30).map((p, i) => {
                      const nome = [p.clienteCognome, p.clienteNome].filter(Boolean).join(' ') || '—';
                      const statoCol = p.stato === 'confermata' ? '#2e6e3e' : '#b87333';
                      const statoLabel = p.stato === 'confermata' ? '✓ Confermata' : '○ Bozza';
                      return (
                        <tr key={i} style={{ borderTop:'1px solid var(--border)', background: i%2===0?'transparent':'var(--surface-2)' }}>
                          <td style={{ padding:'8px 12px', fontWeight:500, color:'var(--ink)' }}>{p.dal}{p.al && p.al !== p.dal ? ` → ${p.al}` : ''}</td>
                          <td style={{ padding:'8px 12px' }}>{nome}</td>
                          <td style={{ padding:'8px 12px', color:'var(--muted)' }}>{p.vehicleLabel || p.vehicleType || '—'}</td>
                          <td style={{ padding:'8px 12px', fontWeight:700, color:'#2e6e3e', fontFamily:'monospace' }}>
                            {p.prezzo != null ? `€${p.prezzo.toLocaleString('it-IT')}` : '—'}
                          </td>
                          <td style={{ padding:'8px 12px' }}>
                            <span style={{ fontSize:11, padding:'2px 8px', borderRadius:10,
                              background:statoCol+'18', color:statoCol, fontWeight:600 }}>{statoLabel}</span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
                {d.prenoFuture.length > 30 && (
                  <div style={{ textAlign:'center', fontSize:11, color:'var(--muted)', padding:'8px 0' }}>
                    Mostrate prime 30 di {d.prenoFuture.length} prenotazioni future
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── OCCUPAZIONE % ─────────────────────────────────────── */}
      {tab === 'occupazione' && (
        <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
          <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:20 }}>
            Occupazione % per categoria · {year}
          </div>
          <div style={{ overflowX:'auto' }}>
            <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
              <thead>
                <tr>
                  <th style={{ padding:'8px 12px', textAlign:'left', fontSize:11, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)', borderBottom:'2px solid var(--border)' }}>Mese</th>
                  {['auto','scooter','quad','ebike'].map(t => (
                    <th key={t} style={{ padding:'8px 12px', textAlign:'center', fontSize:11, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)', borderBottom:'2px solid var(--border)' }}>{t}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {d.occupazione.map(m => (
                  <tr key={m.ym} style={{ borderBottom:'1px solid var(--border)' }}>
                    <td style={{ padding:'10px 12px', fontWeight:500 }}>{m.label} {year}</td>
                    {['auto','scooter','quad','ebike'].map(tipo => {
                      const pct = m[tipo];
                      const color = pct>=80 ? '#c0392b' : pct>=50 ? '#e67e22' : pct>=20 ? '#27ae60' : 'var(--muted)';
                      return (
                        <td key={tipo} style={{ padding:'10px 12px', textAlign:'center' }}>
                          {pct > 0 ? (
                            <div style={{ display:'inline-flex', flexDirection:'column', alignItems:'center', gap:3, minWidth:60 }}>
                              <span style={{ fontWeight:700, color, fontSize:14 }}>{pct}%</span>
                              <div style={{ width:52, height:5, background:'var(--surface-2)', borderRadius:3, overflow:'hidden' }}>
                                <div style={{ height:'100%', width:`${pct}%`, background:color, borderRadius:3 }} />
                              </div>
                            </div>
                          ) : <span style={{ color:'var(--muted)', fontSize:12 }}>—</span>}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div style={{ marginTop:14, display:'flex', gap:16, fontSize:11, color:'var(--muted)' }}>
            <span style={{ display:'flex', alignItems:'center', gap:5 }}><span style={{ width:10,height:10,borderRadius:2,background:'#27ae60',display:'inline-block' }} /> &lt;50% normale</span>
            <span style={{ display:'flex', alignItems:'center', gap:5 }}><span style={{ width:10,height:10,borderRadius:2,background:'#e67e22',display:'inline-block' }} /> 50–79% alta domanda</span>
            <span style={{ display:'flex', alignItems:'center', gap:5 }}><span style={{ width:10,height:10,borderRadius:2,background:'#c0392b',display:'inline-block' }} /> ≥80% saturazione</span>
          </div>
        </div>
      )}

      {/* ── CLIENTI 👤 ─────────────────────────────────────────── */}
      {tab === 'clienti' && (
        <div style={{ display:'flex', flexDirection:'column', gap:16 }}>

          {/* Retention KPI */}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12 }}>
            {card('Clienti unici (anno)', d.clientiUnici, `su ${d.totPreno} prenotazioni totali`, '#1f5d83')}
            {card('Clienti ritornati', d.clientiRitornati, 'hanno prenotato più di una volta', '#2e6e3e')}
            {card('Tasso retention', `${d.tassoRetention}%`,
              d.tassoRetention > 30 ? '🟢 Ottima fidelizzazione' : d.tassoRetention > 15 ? '🟡 Discreta' : '🔴 Da migliorare',
              d.tassoRetention > 30 ? '#2e6e3e' : d.tassoRetention > 15 ? '#b87333' : '#c85050')}
          </div>

          {/* Grafico distribuzione spesa clienti */}
          {d.topClienti.length > 0 && (
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
                Distribuzione spesa per cliente · {year}
              </div>
              {(() => {
                const maxSpesa = d.topClienti[0]?.spesa || 1;
                return d.topClienti.map((c, i) => (
                  <div key={c.id} style={{ marginBottom:9 }}>
                    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', fontSize:12, marginBottom:3 }}>
                      <span style={{ fontWeight: i < 3 ? 700 : 500, color:'var(--ink)' }}>
                        {i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `${i+1}.`} {c.nome}
                      </span>
                      <span style={{ display:'flex', gap:10, color:'var(--muted)' }}>
                        <span style={{ fontWeight:700, color:'#1f5d83', fontFamily:'monospace' }}>€{c.spesa.toLocaleString('it-IT')}</span>
                        <span>{c.movimenti} mov.</span>
                      </span>
                    </div>
                    <div style={{ height:7, background:'var(--surface-2)', borderRadius:3, overflow:'hidden' }}>
                      <div style={{ height:'100%', width:`${(c.spesa/maxSpesa)*100}%`,
                        background: i === 0 ? '#b87333' : i === 1 ? '#888' : i === 2 ? '#c87941' : '#1f5d83',
                        borderRadius:3, opacity: 0.5 + (1 - i/d.topClienti.length)*0.5 }} />
                    </div>
                  </div>
                ));
              })()}
            </div>
          )}

          {/* Tabella completa top clienti */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
              Classifica clienti per spesa · {year}
            </div>
            {d.topClienti.length === 0 ? (
              <div style={{ fontSize:13, color:'var(--muted)', fontStyle:'italic', padding:'12px 0' }}>
                Nessun movimento di cassa per {year}. I dati appaiono quando si usano i pagamenti nel Registro Cassa.
              </div>
            ) : (
              <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
                <thead>
                  <tr style={{ background:'var(--surface-2)' }}>
                    {['#','Cliente','Spesa (€)','Movimenti','Ticket medio'].map(h => (
                      <th key={h} style={{ padding:'8px 12px', textAlign: h==='Cliente'?'left':'center', fontSize:10,
                        fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em',
                        color:'var(--ink-2)', borderBottom:'1px solid var(--border)' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {d.topClienti.map((c, i) => (
                    <tr key={c.id} style={{ borderTop:'1px solid var(--border)', background: i%2===0?'transparent':'var(--surface-2)' }}>
                      <td style={{ padding:'10px 12px', textAlign:'center', color:'var(--muted)', fontSize:12 }}>
                        {i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : i+1}
                      </td>
                      <td style={{ padding:'10px 12px', fontWeight:500 }}>{c.nome}</td>
                      <td style={{ padding:'10px 12px', textAlign:'center', fontWeight:700, color:'#1f5d83', fontFamily:'monospace' }}>
                        €{c.spesa.toLocaleString('it-IT')}
                      </td>
                      <td style={{ padding:'10px 12px', textAlign:'center', color:'var(--muted)' }}>{c.movimenti}</td>
                      <td style={{ padding:'10px 12px', textAlign:'center', color:'var(--ink-2)' }}>
                        {c.movimenti > 0 ? `€${Math.round(c.spesa/c.movimenti).toLocaleString('it-IT')}` : '—'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      )}

      {/* ── OPERATORI ─────────────────────────────────────────── */}
      {tab === 'operatori' && (
        <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
          <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:16 }}>
            Revenue per operatore · {year}
          </div>
          {d.topOp.length === 0 ? (
            <div style={{ fontSize:13, color:'var(--muted)', fontStyle:'italic', padding:'20px 0' }}>
              Nessun movimento con operatore assegnato per {year}.
            </div>
          ) : (
            <>
              <div style={{ display:'flex', flexDirection:'column', gap:12, marginBottom:20 }}>
                {d.topOp.map((o,i) => {
                  const maxInc = d.topOp[0].incasso || 1;
                  return (
                    <div key={o.nome}>
                      <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, marginBottom:4 }}>
                        <span style={{ fontWeight:600 }}>{o.nome}</span>
                        <span style={{ color:'#2e6e3e', fontWeight:700 }}>€{o.incasso.toLocaleString('it-IT')}</span>
                      </div>
                      <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                        <div style={{ flex:1, height:8, background:'var(--surface-2)', borderRadius:4, overflow:'hidden' }}>
                          <div style={{ height:'100%', width:`${(o.incasso/maxInc)*100}%`, background:'#2e6e3e', borderRadius:4 }} />
                        </div>
                        <span style={{ fontSize:11, color:'var(--muted)', width:60, textAlign:'right' }}>{o.movimenti} mov.</span>
                      </div>
                    </div>
                  );
                })}
              </div>
              <div style={{ borderTop:'1px solid var(--border)', paddingTop:12, display:'flex', gap:20, fontSize:13 }}>
                <span style={{ color:'var(--muted)' }}>Totale incassato: <strong style={{ color:'var(--ink)' }}>€{d.incassoCassa.toLocaleString('it-IT')}</strong></span>
                <span style={{ color:'var(--muted)' }}>Movimenti: <strong style={{ color:'var(--ink)' }}>{d.topOp.reduce((s,o)=>s+o.movimenti,0)}</strong></span>
              </div>
            </>
          )}
        </div>
      )}

      {/* ── CASSA 💵 ──────────────────────────────────────────────── */}
      {tab === 'cassa' && (
        <div style={{ display:'flex', flexDirection:'column', gap:16 }}>

          {/* Flusso mensile entrate / uscite */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:18 }}>
              Flusso mensile · entrate e uscite · {year}
            </div>
            <div style={{ display:'flex', alignItems:'flex-end', gap:6, height:130, marginBottom:6 }}>
              {d.mesi.map(m => {
                const allKmese = (d.allK||[]).filter(k => (k.data||'').startsWith(m.ym));
                const entrate  = allKmese.filter(k => k.tipo !== 'rimborso').reduce((s,k) => s+(Number(k.importo)||0), 0);
                const uscite   = allKmese.filter(k => k.tipo === 'rimborso').reduce((s,k) => s+(Number(k.importo)||0), 0);
                const maxE = Math.max(...d.mesi.map(mx => (d.allK||[]).filter(k=>(k.data||'').startsWith(mx.ym)&&k.tipo!=='rimborso').reduce((s,k)=>s+(Number(k.importo)||0),0)), 1);
                const hE = Math.round((entrate / maxE) * 110);
                const hU = Math.round((uscite  / maxE) * 110);
                return (
                  <div key={m.ym} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:2 }}>
                    <div style={{ fontSize:8, color:'var(--muted)', fontWeight:600 }}>
                      {entrate >= 1000 ? `€${Math.round(entrate/1000)}k` : entrate > 0 ? `€${entrate}` : ''}
                    </div>
                    <div style={{ width:'100%', display:'flex', gap:2, alignItems:'flex-end', height:110 }}>
                      <div style={{ flex:1, height:`${Math.max(hE,2)}px`, background:'#2e6e3e', borderRadius:'3px 3px 0 0', minHeight:2 }} title={`Entrate: €${entrate}`} />
                      {uscite > 0 && <div style={{ flex:1, height:`${Math.max(hU,2)}px`, background:'#c85050', borderRadius:'3px 3px 0 0', opacity:.75, minHeight:2 }} title={`Uscite: €${uscite}`} />}
                    </div>
                    <div style={{ fontSize:8, color:'var(--muted)' }}>{m.label}</div>
                  </div>
                );
              })}
            </div>
            <div style={{ display:'flex', gap:16, fontSize:10, color:'var(--muted)', marginTop:4 }}>
              <span style={{ display:'flex', alignItems:'center', gap:4 }}><span style={{ width:10,height:10,borderRadius:2,background:'#2e6e3e',display:'inline-block' }} /> Entrate</span>
              <span style={{ display:'flex', alignItems:'center', gap:4 }}><span style={{ width:10,height:10,borderRadius:2,background:'#c85050',display:'inline-block',opacity:.75 }} /> Rimborsi / uscite</span>
            </div>
          </div>

          {/* Split tipo movimento + metodi pagamento */}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16 }}>

            {/* Split tipo movimento */}
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'18px 20px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
                Tipo movimento
              </div>
              {[
                { key:'acconto',  label:'Acconti',   color:'#b87333' },
                { key:'saldo',    label:'Saldi',     color:'#2e6e3e' },
                { key:'deposito', label:'Caparre',   color:'#1f5d83' },
                { key:'rimborso', label:'Rimborsi',  color:'#c85050' },
                { key:'altro',    label:'Altro',     color:'var(--muted)' },
              ].map(({ key, label, color }) => {
                const importo = d.tipiCassa[key] || 0;
                const totImporti = Object.values(d.tipiCassa).reduce((s,v) => s+v, 0) || 1;
                return importo > 0 ? (
                  <div key={key} style={{ marginBottom:10 }}>
                    <div style={{ display:'flex', justifyContent:'space-between', fontSize:12, marginBottom:3 }}>
                      <span style={{ color:'var(--ink)', fontWeight:500 }}>{label}</span>
                      <span style={{ fontWeight:700, color }}>{`€${importo.toLocaleString('it-IT')}`}</span>
                    </div>
                    <div style={{ height:6, background:'var(--surface-2)', borderRadius:3, overflow:'hidden' }}>
                      <div style={{ height:'100%', width:`${(importo/totImporti)*100}%`, background:color, borderRadius:3 }} />
                    </div>
                  </div>
                ) : null;
              })}
            </div>

            {/* Metodi pagamento */}
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'18px 20px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
                Metodi di pagamento
              </div>
              {d.metodi.length === 0
                ? <div style={{ fontSize:12, color:'var(--muted)', fontStyle:'italic' }}>Nessun dato cassa</div>
                : d.metodi.map(m => {
                  const maxM = d.metodi[0].importo || 1;
                  const EMOJI = { contanti:'💵', carta:'💳', bonifico:'🏦', paypal:'🅿️', altro:'💶' };
                  const COL   = { contanti:'#b87333', carta:'#1f5d83', bonifico:'#2e6e3e', altro:'#888' };
                  const col   = COL[m.metodo] || COL.altro;
                  return (
                    <div key={m.metodo} style={{ marginBottom:10 }}>
                      <div style={{ display:'flex', justifyContent:'space-between', fontSize:12, marginBottom:3, alignItems:'center' }}>
                        <span style={{ color:'var(--ink)', fontWeight:500 }}>{EMOJI[m.metodo]||'💶'} {m.metodo}</span>
                        <span style={{ color:'var(--muted)', fontSize:11 }}>€{m.importo.toLocaleString('it-IT')} · {m.count} mov.</span>
                      </div>
                      <div style={{ height:6, background:'var(--surface-2)', borderRadius:3, overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${(m.importo/maxM)*100}%`, background:col, borderRadius:3 }} />
                      </div>
                    </div>
                  );
                })
              }
            </div>
          </div>

          {/* Tabella movimenti ultimi 30 */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, overflow:'hidden' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', padding:'14px 18px', borderBottom:'1px solid var(--border)' }}>
              Ultimi 30 movimenti · {year}
            </div>
            <div style={{ overflowX:'auto' }}>
              <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
                <thead>
                  <tr style={{ background:'var(--surface-2)' }}>
                    {['Data','Cliente','Tipo','Metodo','Importo','Nota'].map(h => (
                      <th key={h} style={{ padding:'7px 12px', textAlign:'left', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {[...(d.allK||[])].sort((a,b) => (b.data||'').localeCompare(a.data||'')).slice(0,30).map((k,i) => {
                    const TIPO_COL = { acconto:'#b87333', saldo:'#2e6e3e', deposito:'#1f5d83', rimborso:'#c85050' };
                    const col = TIPO_COL[k.tipo] || 'var(--muted)';
                    return (
                      <tr key={k.id||i} style={{ borderTop:'1px solid var(--border)', background: i%2===0 ? 'transparent':'var(--surface-2)' }}>
                        <td style={{ padding:'8px 12px', fontFamily:'monospace', fontSize:11, color:'var(--muted)' }}>{k.data}</td>
                        <td style={{ padding:'8px 12px', fontWeight:500 }}>{k.clienteNome || '—'}</td>
                        <td style={{ padding:'8px 12px' }}>
                          <span style={{ fontSize:10, padding:'2px 8px', borderRadius:10, background:col+'18', color:col, fontWeight:600 }}>{k.tipo||'—'}</span>
                        </td>
                        <td style={{ padding:'8px 12px', color:'var(--ink-2)' }}>{k.metodo||'—'}</td>
                        <td style={{ padding:'8px 12px', fontWeight:700, fontFamily:'monospace', color:k.tipo==='rimborso'?'#c85050':'#2e6e3e' }}>
                          {k.tipo==='rimborso'?'−':'+'}{k.importo!=null?`€${Number(k.importo).toLocaleString('it-IT')}`:'—'}
                        </td>
                        <td style={{ padding:'8px 12px', color:'var(--muted)', fontSize:11, maxWidth:200, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{k.nota||''}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* ── FLOTTA 🚗 ─────────────────────────────────────────────── */}
      {tab === 'flotta' && (
        <div style={{ display:'flex', flexDirection:'column', gap:16 }}>
          {d.perVeicolo.length === 0 ? (
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'40px 24px', textAlign:'center', color:'var(--muted)', fontSize:13 }}>
              Nessun dato veicolo per {year}. Le statistiche si popolano man mano che si creano prenotazioni con mezzo assegnato.
            </div>
          ) : (
            <>
              {/* Top veicoli per revenue */}
              <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
                <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:18 }}>
                  Top veicoli per revenue stimata · {year}
                </div>
                {d.perVeicolo.slice(0,10).map((v,i) => {
                  const TIPO_EMOJI = { auto:'🚗', scooter:'🛵', moto:'🛵', quad:'🏎', ebike:'⚡', bici:'🚲' };
                  const pct = Math.round((v.revenue / d.maxVRevenue) * 100);
                  return (
                    <div key={v.id} style={{ marginBottom:12 }}>
                      <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:4 }}>
                        <span style={{ fontSize:11, color:'var(--muted)', width:18, textAlign:'center' }}>{i+1}</span>
                        <span style={{ fontSize:13 }}>{TIPO_EMOJI[v.tipo]||'🚗'}</span>
                        <span style={{ fontWeight:600, fontSize:13, flex:1 }}>{v.label}</span>
                        <span style={{ fontSize:11, color:'var(--muted)' }}>{v.giorni}gg · {v.noleggi} noleggi</span>
                        <span style={{ fontWeight:700, color:'#2e6e3e', fontSize:13, minWidth:70, textAlign:'right' }}>
                          {v.revenue > 0 ? `€${v.revenue.toLocaleString('it-IT')}` : '—'}
                        </span>
                      </div>
                      <div style={{ height:5, background:'var(--surface-2)', borderRadius:3, overflow:'hidden', marginLeft:26 }}>
                        <div style={{ height:'100%', width:`${pct}%`, background:'#1f5d83', borderRadius:3 }} />
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Tabella completa */}
              <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, overflow:'hidden' }}>
                <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', padding:'14px 18px', borderBottom:'1px solid var(--border)' }}>
                  Tabella veicoli · {year}
                </div>
                <div style={{ overflowX:'auto' }}>
                  <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
                    <thead>
                      <tr style={{ background:'var(--surface-2)' }}>
                        {['#','Veicolo','Tipo','Noleggi','Giorni totali','Revenue stimata','Media/noleggio'].map(h => (
                          <th key={h} style={{ padding:'8px 12px', textAlign: h==='#'||h==='Noleggi'||h==='Giorni totali'?'center':'left', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>{h}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {d.perVeicolo.map((v,i) => (
                        <tr key={v.id} style={{ borderTop:'1px solid var(--border)', background:i%2===0?'transparent':'var(--surface-2)' }}>
                          <td style={{ padding:'8px 12px', textAlign:'center', color:'var(--muted)', fontSize:11 }}>{i+1}</td>
                          <td style={{ padding:'8px 12px', fontWeight:500 }}>{v.label}</td>
                          <td style={{ padding:'8px 12px', color:'var(--muted)' }}>{v.tipo}</td>
                          <td style={{ padding:'8px 12px', textAlign:'center' }}>{v.noleggi}</td>
                          <td style={{ padding:'8px 12px', textAlign:'center' }}>{v.giorni}</td>
                          <td style={{ padding:'8px 12px', fontWeight:700, color:'#2e6e3e' }}>{v.revenue>0?`€${v.revenue.toLocaleString('it-IT')}`:'—'}</td>
                          <td style={{ padding:'8px 12px', color:'#1f5d83' }}>{v.noleggi>0&&v.revenue>0?`€${Math.round(v.revenue/v.noleggi)}`:'—'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </>
          )}
        </div>
      )}

      {/* ── MIX 📊 ────────────────────────────────────────────────── */}
      {tab === 'mix' && (
        <div style={{ display:'flex', flexDirection:'column', gap:16 }}>
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16 }}>

            {/* Fonti prenotazione */}
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'18px 20px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
                Fonti prenotazione
              </div>
              {d.fonti.length === 0
                ? <div style={{ fontSize:12, color:'var(--muted)', fontStyle:'italic' }}>Nessun dato disponibile</div>
                : d.fonti.map(([fonte, n], i) => {
                  const maxF = d.fonti[0][1] || 1;
                  const COLORS = ['#1f5d83','#2e6e3e','#b87333','#6a3d8f','#c85050','#4a8aac','#888'];
                  return (
                    <div key={fonte} style={{ marginBottom:10 }}>
                      <div style={{ display:'flex', justifyContent:'space-between', fontSize:12, marginBottom:3 }}>
                        <span style={{ color:'var(--ink)', fontWeight:500 }}>{fonteLabel(fonte)}</span>
                        <span style={{ color:'var(--muted)' }}>{n} ({Math.round((n/d.allP.length)*100)}%)</span>
                      </div>
                      <div style={{ height:7, background:'var(--surface-2)', borderRadius:3, overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${(n/maxF)*100}%`, background:COLORS[i%COLORS.length], borderRadius:3 }} />
                      </div>
                    </div>
                  );
                })
              }
            </div>

            {/* Distribuzione durate */}
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'18px 20px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
                Distribuzione durate noleggio
              </div>
              {(() => {
                const entries = Object.entries(d.durBuckets).filter(([,n]) => n > 0);
                const maxD = Math.max(...entries.map(([,n]) => n), 1);
                const totD = entries.reduce((s,[,n]) => s+n, 0) || 1;
                const DUR_COLORS = ['#4a6a30','#2e6e3e','#1f5d83','#6a3d8f','#b87333'];
                return entries.length === 0
                  ? <div style={{ fontSize:12, color:'var(--muted)', fontStyle:'italic' }}>Nessun dato</div>
                  : entries.map(([label, n], i) => (
                    <div key={label} style={{ marginBottom:12 }}>
                      <div style={{ display:'flex', justifyContent:'space-between', fontSize:12, marginBottom:4 }}>
                        <span style={{ color:'var(--ink)', fontWeight:600 }}>{label}</span>
                        <span style={{ color:'var(--muted)' }}>{n} noleggi · {Math.round((n/totD)*100)}%</span>
                      </div>
                      <div style={{ height:8, background:'var(--surface-2)', borderRadius:4, overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${(n/maxD)*100}%`, background:DUR_COLORS[i%DUR_COLORS.length], borderRadius:4 }} />
                      </div>
                    </div>
                  ));
              })()}
            </div>
          </div>

          {/* Funnel prenotazioni */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:18 }}>
              Funnel stati · {year}
            </div>
            {d.allP.length === 0
              ? <div style={{ fontSize:13, color:'var(--muted)', fontStyle:'italic' }}>Nessuna prenotazione per {year}</div>
              : (
                <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
                  {d.funnel.filter(f => f.n > 0).map(f => {
                    const pct = Math.round((f.n / d.allP.length) * 100);
                    return (
                      <div key={f.label}>
                        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:4 }}>
                          <span style={{ fontSize:13, fontWeight:600, color:f.color }}>{f.label}</span>
                          <div style={{ display:'flex', gap:10, alignItems:'center' }}>
                            <span style={{ fontSize:11, color:'var(--muted)' }}>{pct}%</span>
                            <span style={{ fontSize:14, fontWeight:700, color:f.color, width:32, textAlign:'right' }}>{f.n}</span>
                          </div>
                        </div>
                        <div style={{ height:10, background:'var(--surface-2)', borderRadius:5, overflow:'hidden' }}>
                          <div style={{ height:'100%', width:`${pct}%`, background:f.color, borderRadius:5, transition:'width .4s' }} />
                        </div>
                      </div>
                    );
                  })}
                  <div style={{ marginTop:4, fontSize:11, color:'var(--muted)', borderTop:'1px solid var(--border)', paddingTop:8 }}>
                    Tasso completamento: <strong style={{ color:'#2e6e3e' }}>
                      {d.allP.length > 0 ? Math.round((d.funnel.find(f=>f.label==='Completate')?.n||0)/d.allP.length*100) : 0}%
                    </strong>
                    {' · '}
                    Tasso annullamento: <strong style={{ color:d.tassoAnnullamento>15?'#c85050':'var(--ink)' }}>
                      {d.tassoAnnullamento}%
                    </strong>
                  </div>
                </div>
              )
            }
          </div>

          {/* Distribuzione per giorno della settimana + metodi pagamento */}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16 }}>

            {/* Giorno settimana */}
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'18px 20px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
                📅 Check-in per giorno
              </div>
              <div style={{ display:'flex', alignItems:'flex-end', gap:6, height:80 }}>
                {d.giorniSettimana.map((g, i) => {
                  const h = Math.max(g.n > 0 ? 6 : 2, (g.n / d.maxDow) * 72);
                  const isWeekend = i === 0 || i === 6;
                  return (
                    <div key={g.label} title={`${g.label}: ${g.n} prenotazioni`}
                      style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:2 }}>
                      <div style={{ fontSize:9, color:'var(--muted)', fontWeight:600 }}>{g.n||''}</div>
                      <div style={{ width:'100%', borderRadius:'3px 3px 0 0', height:`${h}px`,
                        background: isWeekend ? '#b87333' : '#1f5d83',
                        opacity: isWeekend ? 0.75 : 0.6 + (g.n/d.maxDow)*0.4 }} />
                      <div style={{ fontSize:9, color: isWeekend?'#b87333':'var(--muted)', fontWeight: isWeekend?700:400 }}>{g.label}</div>
                    </div>
                  );
                })}
              </div>
              <div style={{ marginTop:8, fontSize:10, color:'var(--muted)' }}>
                Giorno di inizio noleggio · arancio = weekend
              </div>
            </div>

            {/* Metodi pagamento */}
            <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'18px 20px' }}>
              <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:14 }}>
                💳 Metodi di pagamento
              </div>
              {d.metodi.length === 0
                ? <div style={{ fontSize:12, color:'var(--muted)', fontStyle:'italic' }}>Nessun dato disponibile</div>
                : (() => {
                  const totMetodi = d.metodi.reduce((s, m) => s + m.importo, 0);
                  const M_COLORS = { contanti:'#2e6e3e', carta:'#1f5d83', bonifico:'#6a3d8f', altro:'#888' };
                  const M_ICONS  = { contanti:'💵', carta:'💳', bonifico:'🏦', altro:'💶' };
                  return d.metodi.map((m, i) => (
                    <div key={m.metodo} style={{ marginBottom:9 }}>
                      <div style={{ display:'flex', justifyContent:'space-between', fontSize:12, marginBottom:3 }}>
                        <span style={{ color:'var(--ink)', fontWeight:500 }}>
                          {M_ICONS[m.metodo]||'💶'} {m.metodo.charAt(0).toUpperCase()+m.metodo.slice(1)}
                        </span>
                        <span style={{ color:'var(--muted)' }}>
                          <strong style={{ color: M_COLORS[m.metodo]||'#888' }}>€{m.importo.toLocaleString('it-IT')}</strong>
                          {' '}({totMetodi>0?Math.round((m.importo/totMetodi)*100):0}%)
                        </span>
                      </div>
                      <div style={{ height:7, background:'var(--surface-2)', borderRadius:3, overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${totMetodi>0?(m.importo/totMetodi)*100:0}%`,
                          background: M_COLORS[m.metodo]||'#888', borderRadius:3 }} />
                      </div>
                    </div>
                  ));
                })()
              }
            </div>
          </div>

          {/* Panoramica mensile comparativa */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:18 }}>
              Confronto prenotazioni vs incassi per mese · {year}
            </div>
            <div style={{ overflowX:'auto' }}>
              <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
                <thead>
                  <tr style={{ background:'var(--surface-2)' }}>
                    {['Mese','Prenotazioni','Preventivi €','Cassa €','Diff. €','Conv. %'].map(h => (
                      <th key={h} style={{ padding:'7px 12px', textAlign: h==='Mese'?'left':'center', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {d.mesi.map((m,i) => {
                    const diff = m.revCassa - m.revPreno;
                    const conv = m.revPreno > 0 ? Math.round((m.revCassa/m.revPreno)*100) : null;
                    return (
                      <tr key={m.ym} style={{ borderTop:'1px solid var(--border)', background:i%2===0?'transparent':'var(--surface-2)' }}>
                        <td style={{ padding:'8px 12px', fontWeight:500 }}>{m.label}</td>
                        <td style={{ padding:'8px 12px', textAlign:'center' }}>{m.preno||'—'}</td>
                        <td style={{ padding:'8px 12px', textAlign:'center', color:'var(--ink-2)' }}>{m.revPreno>0?`€${m.revPreno.toLocaleString('it-IT')}`:'—'}</td>
                        <td style={{ padding:'8px 12px', textAlign:'center', fontWeight:600, color:m.revCassa>0?'#2e6e3e':'var(--muted)' }}>{m.revCassa>0?`€${m.revCassa.toLocaleString('it-IT')}`:'—'}</td>
                        <td style={{ padding:'8px 12px', textAlign:'center', color:diff>=0?'#2e6e3e':diff<0?'#c85050':'var(--muted)', fontWeight:diff!==0?600:400 }}>
                          {m.revPreno>0&&m.revCassa>0?(diff>=0?'+':'')+`€${diff.toLocaleString('it-IT')}`:'—'}
                        </td>
                        <td style={{ padding:'8px 12px', textAlign:'center', color:conv&&conv<70?'#c85050':conv&&conv<100?'#b87333':'#2e6e3e', fontWeight:conv?600:400 }}>
                          {conv!=null?`${conv}%`:'—'}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* ── STAGIONALE ─────────────────────────────────────────── */}
      {tab === 'stagionale' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:16 }}>
              Revenue mensile · {year}
            </div>
            {/* Barre revenue */}
            <div style={{ display:'flex', alignItems:'flex-end', gap:6, height:120, marginBottom:8 }}>
              {(() => {
                const maxR = Math.max(...datiMensili.map(m => m.revenue), 1);
                return datiMensili.map(m => {
                  const h = Math.round((m.revenue / maxR) * 100);
                  const isAgo = m.mese.endsWith('-08');
                  return (
                    <div key={m.mese} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:3 }}>
                      <div style={{ fontSize:9, color:'var(--muted)', fontWeight:600 }}>
                        {m.revenue > 0 ? `€${m.revenue >= 1000 ? Math.round(m.revenue/1000)+'k' : m.revenue}` : ''}
                      </div>
                      <div style={{ width:'100%', height:`${Math.max(h,2)}%`, background: isAgo ? 'var(--accent)' : 'var(--sea)', borderRadius:'3px 3px 0 0', minHeight:2 }} />
                      <div style={{ fontSize:9, color:'var(--muted)' }}>{m.label}</div>
                    </div>
                  );
                });
              })()}
            </div>
          </div>
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:16 }}>
              Occupazione % mensile · {year}
            </div>
            <div style={{ display:'flex', alignItems:'flex-end', gap:6, height:100 }}>
              {datiMensili.map(m => {
                const isAgo = m.mese.endsWith('-08');
                const col = m.occupazione > 80 ? '#c83434' : m.occupazione > 50 ? '#b07820' : '#4a6a30';
                return (
                  <div key={m.mese} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:3 }}>
                    <div style={{ fontSize:9, color:'var(--muted)', fontWeight:600 }}>{m.occupazione > 0 ? `${m.occupazione}%` : ''}</div>
                    <div style={{ width:'100%', height:`${Math.max(m.occupazione,2)}%`, background: isAgo ? col : col + '99', borderRadius:'3px 3px 0 0', minHeight:2 }} />
                    <div style={{ fontSize:9, color:'var(--muted)' }}>{m.label}</div>
                  </div>
                );
              })}
            </div>
          </div>
          {/* Tabella riepilogo */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, overflow:'hidden' }}>
            <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
              <thead>
                <tr style={{ background:'var(--surface-2)' }}>
                  {['Mese','Prenotazioni','Revenue','Cassa incassata','Occupazione'].map(h => (
                    <th key={h} style={{ padding:'8px 14px', textAlign:'left', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {datiMensili.map((m,i) => (
                  <tr key={m.mese} style={{ borderTop:'1px solid var(--border)', background: m.mese.endsWith('-08') ? 'rgba(200,52,52,.04)' : i%2===0 ? 'transparent' : 'var(--surface-2)' }}>
                    <td style={{ padding:'8px 14px', fontWeight: m.mese.endsWith('-08') ? 700 : 400 }}>{m.label}{m.mese.endsWith('-08') && ' ☀️'}</td>
                    <td style={{ padding:'8px 14px' }}>{m.prenotazioni || '—'}</td>
                    <td style={{ padding:'8px 14px', fontWeight:600, color: m.revenue > 0 ? '#2e6e3e' : 'var(--muted)' }}>{m.revenue > 0 ? `€${m.revenue.toLocaleString('it-IT')}` : '—'}</td>
                    <td style={{ padding:'8px 14px', color: m.cassa > 0 ? 'var(--ink)' : 'var(--muted)' }}>{m.cassa > 0 ? `€${m.cassa.toLocaleString('it-IT')}` : '—'}</td>
                    <td style={{ padding:'8px 14px' }}>
                      <div style={{ display:'flex', alignItems:'center', gap:8 }}>
                        <div style={{ width:60, height:6, background:'var(--surface-2)', borderRadius:3, overflow:'hidden' }}>
                          <div style={{ height:'100%', width:`${m.occupazione}%`, background: m.occupazione>80?'var(--accent)':m.occupazione>50?'#b07820':'#4a6a30', borderRadius:3 }} />
                        </div>
                        <span>{m.occupazione}%</span>
                      </div>
                    </td>
                  </tr>
                ))}
                <tr style={{ borderTop:'2px solid var(--border-strong)', fontWeight:700, background:'var(--surface-2)' }}>
                  <td style={{ padding:'10px 14px' }}>Totale {year}</td>
                  <td style={{ padding:'10px 14px' }}>{datiMensili.reduce((s,m)=>s+m.prenotazioni,0)}</td>
                  <td style={{ padding:'10px 14px', color:'#2e6e3e' }}>€{datiMensili.reduce((s,m)=>s+m.revenue,0).toLocaleString('it-IT')}</td>
                  <td style={{ padding:'10px 14px' }}>€{datiMensili.reduce((s,m)=>s+m.cassa,0).toLocaleString('it-IT')}</td>
                  <td style={{ padding:'10px 14px' }}>{Math.round(datiMensili.reduce((s,m)=>s+m.occupazione,0)/12)}% media</td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ── YoY: Confronto Anno su Anno ──────────────────────────────── */}
      {tab === 'yoy' && (
        <div style={{ display:'flex', flexDirection:'column', gap:20 }}>
          {/* Totali a confronto */}
          <div style={{ display:'flex', gap:12, flexWrap:'wrap' }}>
            {[
              { label:'Revenue', curr: datiMensili.reduce((s,m)=>s+m.revenue,0), prev: datiMensiliPrev.reduce((s,m)=>s+m.revenue,0), fmt: v=>`€${v.toLocaleString('it-IT')}` },
              { label:'Prenotazioni', curr: datiMensili.reduce((s,m)=>s+m.prenotazioni,0), prev: datiMensiliPrev.reduce((s,m)=>s+m.prenotazioni,0), fmt: v=>String(v) },
              { label:'Cassa incassata', curr: datiMensili.reduce((s,m)=>s+m.cassa,0), prev: datiMensiliPrev.reduce((s,m)=>s+m.cassa,0), fmt: v=>`€${v.toLocaleString('it-IT')}` },
            ].map(({ label, curr, prev, fmt }) => {
              const delta = prev > 0 ? Math.round((curr - prev) / prev * 100) : null;
              const up = curr >= prev;
              return (
                <div key={label} style={{ flex:1, minWidth:180, background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'14px 18px' }}>
                  <div style={{ fontSize:11, color:'var(--muted)', textTransform:'uppercase', letterSpacing:'.06em', marginBottom:6 }}>{label}</div>
                  <div style={{ display:'flex', alignItems:'baseline', gap:10, flexWrap:'wrap' }}>
                    <span style={{ fontSize:22, fontWeight:700, fontFamily:'var(--font-serif)', color:'var(--ink)' }}>{fmt(curr)}</span>
                    {delta !== null && (
                      <span style={{ fontSize:13, fontWeight:700, color: up ? '#2e6e3e' : '#b22222' }}>
                        {up ? '▲' : '▼'} {Math.abs(delta)}%
                      </span>
                    )}
                  </div>
                  <div style={{ fontSize:11, color:'var(--muted)', marginTop:4 }}>
                    {prevYear}: <strong>{fmt(prev)}</strong>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Grafico barre affiancate — Revenue mensile */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, padding:'20px 22px' }}>
            <div style={{ fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--ink-2)', marginBottom:12 }}>
              Revenue mensile · {year} vs {prevYear}
            </div>
            <div style={{ display:'flex', gap:3, alignItems:'flex-end', height:130, marginBottom:4 }}>
              {(() => {
                const maxR = Math.max(...datiMensili.map(m=>m.revenue), ...datiMensiliPrev.map(m=>m.revenue), 1);
                return datiMensili.map((m, i) => {
                  const mp = datiMensiliPrev[i];
                  const hC = Math.round((m.revenue / maxR) * 100);
                  const hP = Math.round((mp.revenue / maxR) * 100);
                  return (
                    <div key={m.mese} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:2 }}>
                      <div style={{ width:'100%', display:'flex', gap:2, alignItems:'flex-end', height:110 }}>
                        <div title={`${prevYear}: €${mp.revenue}`} style={{ flex:1, height:`${Math.max(hP,2)}%`, background:'#b8d0ee', borderRadius:'2px 2px 0 0', minHeight:2 }} />
                        <div title={`${year}: €${m.revenue}`} style={{ flex:1, height:`${Math.max(hC,2)}%`, background:'var(--sea)', borderRadius:'2px 2px 0 0', minHeight:2 }} />
                      </div>
                      <div style={{ fontSize:8, color:'var(--muted)' }}>{m.label}</div>
                    </div>
                  );
                });
              })()}
            </div>
            <div style={{ display:'flex', gap:14, fontSize:10, color:'var(--muted)' }}>
              <span><span style={{ display:'inline-block', width:10, height:10, background:'#b8d0ee', borderRadius:2, marginRight:4 }} />{prevYear}</span>
              <span><span style={{ display:'inline-block', width:10, height:10, background:'var(--sea)', borderRadius:2, marginRight:4 }} />{year}</span>
            </div>
          </div>

          {/* Tabella comparativa mensile */}
          <div style={{ background:'var(--bg)', border:'1px solid var(--border)', borderRadius:8, overflow:'hidden' }}>
            <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
              <thead>
                <tr style={{ background:'var(--surface-2)' }}>
                  <th style={{ padding:'8px 14px', textAlign:'left', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>Mese</th>
                  <th style={{ padding:'8px 14px', textAlign:'right', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>Revenue {prevYear}</th>
                  <th style={{ padding:'8px 14px', textAlign:'right', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>Revenue {year}</th>
                  <th style={{ padding:'8px 14px', textAlign:'right', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>Δ</th>
                  <th style={{ padding:'8px 14px', textAlign:'right', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>Pren. {prevYear}</th>
                  <th style={{ padding:'8px 14px', textAlign:'right', fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.06em', color:'var(--muted)' }}>Pren. {year}</th>
                </tr>
              </thead>
              <tbody>
                {datiMensili.map((m, i) => {
                  const mp = datiMensiliPrev[i];
                  const delta = mp.revenue > 0 ? Math.round((m.revenue - mp.revenue) / mp.revenue * 100) : null;
                  const up = m.revenue >= mp.revenue;
                  return (
                    <tr key={m.mese} style={{ borderTop:'1px solid var(--border)', background: i%2===0 ? 'transparent' : 'var(--surface-2)' }}>
                      <td style={{ padding:'8px 14px', fontWeight: m.mese.endsWith('-08') ? 700 : 400 }}>{m.label}{m.mese.endsWith('-08') && ' ☀️'}</td>
                      <td style={{ padding:'8px 14px', textAlign:'right', color:'var(--muted)' }}>{mp.revenue > 0 ? `€${mp.revenue.toLocaleString('it-IT')}` : '—'}</td>
                      <td style={{ padding:'8px 14px', textAlign:'right', fontWeight:600, color: m.revenue > 0 ? '#2e6e3e' : 'var(--muted)' }}>{m.revenue > 0 ? `€${m.revenue.toLocaleString('it-IT')}` : '—'}</td>
                      <td style={{ padding:'8px 14px', textAlign:'right', color: delta === null ? 'var(--muted)' : up ? '#2e6e3e' : '#b22222', fontWeight:600 }}>
                        {delta !== null ? `${up ? '+' : ''}${delta}%` : '—'}
                      </td>
                      <td style={{ padding:'8px 14px', textAlign:'right', color:'var(--muted)' }}>{mp.prenotazioni || '—'}</td>
                      <td style={{ padding:'8px 14px', textAlign:'right' }}>{m.prenotazioni || '—'}</td>
                    </tr>
                  );
                })}
                <tr style={{ borderTop:'2px solid var(--border-strong)', fontWeight:700, background:'var(--surface-2)' }}>
                  <td style={{ padding:'10px 14px' }}>Totale</td>
                  <td style={{ padding:'10px 14px', textAlign:'right', color:'var(--muted)' }}>€{datiMensiliPrev.reduce((s,m)=>s+m.revenue,0).toLocaleString('it-IT')}</td>
                  <td style={{ padding:'10px 14px', textAlign:'right', color:'#2e6e3e' }}>€{datiMensili.reduce((s,m)=>s+m.revenue,0).toLocaleString('it-IT')}</td>
                  <td style={{ padding:'10px 14px', textAlign:'right' }}>
                    {(() => {
                      const cp = datiMensiliPrev.reduce((s,m)=>s+m.revenue,0);
                      const cc = datiMensili.reduce((s,m)=>s+m.revenue,0);
                      if (!cp) return '—';
                      const d = Math.round((cc-cp)/cp*100);
                      return <span style={{ color: cc>=cp?'#2e6e3e':'#b22222', fontWeight:700 }}>{cc>=cp?'+':''}{d}%</span>;
                    })()}
                  </td>
                  <td style={{ padding:'10px 14px', textAlign:'right', color:'var(--muted)' }}>{datiMensiliPrev.reduce((s,m)=>s+m.prenotazioni,0)}</td>
                  <td style={{ padding:'10px 14px', textAlign:'right' }}>{datiMensili.reduce((s,m)=>s+m.prenotazioni,0)}</td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}
// ═══════════════════════════════════════════════════════════════════
// LISTINO EDITOR — gestione prezzi in Impostazioni (v0.17)
// Modifica tariffe giornaliere e settimanali per stagione
// ═══════════════════════════════════════════════════════════════════

function ListinoEditor({ listino, onSave }) {
  const [draft, setDraft] = useState(() => JSON.parse(JSON.stringify(listino)));
  const [dirty, setDirty] = useState(false);

  function setPrice(catId, season, type, val) {
    setDraft(d => d.map(c => c.id === catId
      ? { ...c, [season]: { ...c[season], [type]: parseFloat(val) || 0 } }
      : c
    ));
    setDirty(true);
  }

  const inp = {
    width: 64, padding: '5px 6px', border: '1px solid var(--border)',
    borderRadius: 4, fontSize: 12, fontFamily: 'monospace',
    textAlign: 'right', background: 'var(--bg)', color: 'var(--ink)',
    boxSizing: 'border-box',
  };

  const thS = { padding: '8px 10px', fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.08em', color: 'var(--bg)', background: 'var(--ink)', textAlign: 'center' };
  const tdS = { padding: '8px 10px', borderBottom: '1px solid var(--border)', fontSize: 12 };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--ink)' }}>Tariffe · giorno / settimana per stagione</div>
        {dirty && (
          <button type="button" onClick={() => { onSave(draft); setDirty(false); }}
            style={{ padding: '7px 16px', borderRadius: 5, border: 'none', background: 'var(--accent)', color: 'white', fontWeight: 600, fontSize: 12, cursor: 'pointer' }}>
            Salva modifiche
          </button>
        )}
      </div>
      <div style={{ overflowX: 'auto', border: '1px solid var(--border)', borderRadius: 8 }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 620 }}>
          <thead>
            <tr>
              <th style={{ ...thS, textAlign: 'left', width: 160 }}>Mezzo</th>
              {['Bassa', 'Media', 'Alta'].map(s => (
                <th key={s} style={thS} colSpan={2}>{s}</th>
              ))}
            </tr>
            <tr style={{ background: 'var(--surface-2)' }}>
              <th style={{ ...tdS, fontWeight: 600, fontSize: 10, color: 'var(--muted)' }}></th>
              {['bassa','media','alta'].map(s => (
                <>
                  <th key={s+'d'} style={{ ...tdS, textAlign: 'center', fontSize: 9, color: 'var(--muted)', fontWeight: 600 }}>Giorno</th>
                  <th key={s+'w'} style={{ ...tdS, textAlign: 'center', fontSize: 9, color: 'var(--muted)', fontWeight: 600 }}>Settimana</th>
                </>
              ))}
            </tr>
          </thead>
          <tbody>
            {draft.map(c => (
              <tr key={c.id}>
                <td style={{ ...tdS, fontWeight: 600, fontFamily: 'var(--font-serif)' }}>{c.nome}</td>
                {['bassa','media','alta'].map(s => (
                  <>
                    <td key={s+'d'} style={{ ...tdS, textAlign: 'center' }}>
                      <input style={inp} type="number" min="0" value={c[s].daily}
                        onChange={e => setPrice(c.id, s, 'daily', e.target.value)} />
                    </td>
                    <td key={s+'w'} style={{ ...tdS, textAlign: 'center' }}>
                      <input style={inp} type="number" min="0" value={c[s].weekly}
                        onChange={e => setPrice(c.id, s, 'weekly', e.target.value)} />
                    </td>
                  </>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div style={{ fontSize: 10, color: 'var(--muted)', marginTop: 8 }}>
        Le modifiche si sincronizzano automaticamente con il backend e aggiornano i preventivi in tempo reale.
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// RENTME INTEGRATION
// Sync live con il gestionale RentMe (Altervista).
// RENTME_USER_ID: UUID azienda Edonoleggio (sola lettura).
// RENTME_PROXY: PHP proxy su Altervista che bypassa CORS.
// ═══════════════════════════════════════════════════════════════════
const RENTME_API_BASE = 'https://rentmealtervista.duckdns.org/api/rest';
const RENTME_PROXY    = 'https://rentme.altervista.org/edox-proxy.php';
// RENTME_USER_ID (UUID azienda) NON è più nel codice del sito: vive solo sul
// backend (env RENTME_USER_ID). I veicoli si leggono da GET /api/rentme/veicoli,
// che li restituisce già filtrati per Edonoleggio.

// ── calcAvailability ─────────────────────────────────────────────
// Funzione pura: dato un periodo dal/al, restituisce array di categorie
// con { id, nome, tipo, categoria, total, booked, free, threshold, alert }.
// v0.43.1: grouping per tipo+categoria (usa getVehicleCategoria sul pool
// unificato fleet+RentMe), così le sotto-categorie auto (5 Posti, Cabrio,
// ecc.) appaiono come card distinte nel Banco Rapido / Walk-in.
function calcAvailability(dal, al, rentmeVehicles, prenotazioni, fleet, fermiFlotta) {
  const dalS = dal || todayISO();
  const alS  = al  || dalS;

  // ── Pool unificato: fleet locale + RentMe, dedup per id ─────────
  // Fleet ha precedenza (dati più precisi su categoria/cc/targa)
  const allVehicles = [];
  const seenIds = new Set();

  (fleet || []).forEach(v => {
    if (v.stato === 'venduto' || v.stato === 'fuori_uso') return;
    const id = v.id || v.targa;
    if (!id) return;
    if (seenIds.has(id)) return;
    seenIds.add(id);
    allVehicles.push(v);
  });

  (rentmeVehicles || []).forEach(v => {
    // I veicoli RentMe non hanno v.id — usano v.targa come chiave univoca
    const id = v.id || v.targa || v.rentmeCode;
    if (!id) return;
    if (seenIds.has(id)) return;   // già in flotta locale → skip (dedup)
    seenIds.add(id);
    allVehicles.push({ ...v, id });  // inietta id per il resto della pipeline
  });

  if (allVehicles.length > 0) {
    // ── Raggruppa per tipo + categoria ──────────────────────────
    const TIPO_ORDER = ['auto','scooter','moto','quad','ebike','bici','altro'];
    const byKey = {};
    // Mapping targa→key per retrocompatibilità: prenotazioni pre-fix salvano vehicleId=TARGA
    // (PrenoForm usava targa come id quando RentMe era sincronizzato). Questo mapping
    // permette di riconoscerle anche se grp.ids contiene l'UUID/migrated-id del veicolo.
    const targaToKey = {};
    allVehicles.forEach(v => {
      const tipo = (v.tipo || '').toLowerCase();
      let cat = getVehicleCategoria(v) || 'BASE';
      // normalizeAutoCategoria: mantiene categorie LISTINO distinte (5POSTI, 6POSTI, 7POSTI, SERIE2, AUTOMATICA, APERTA…)
      // e mappa solo gli alias legacy (CHIUSA, STANDARD) a BASE.
      if (tipo === 'auto') cat = normalizeAutoCategoria(cat);
      const key = `${tipo}|${cat}`;
      if (!byKey[key]) {
        // Display name da LISTINO, altrimenti composto
        const listinoEntry = (LISTINO || []).find(l => l.tipo === tipo && l.categoria === cat);
        const nome = listinoEntry ? listinoEntry.nome : `${tipo} ${cat}`.trim();
        byKey[key] = { key, tipo, categoria: cat, nome, ids: new Set() };
      }
      const id = v.id || v.targa;
      if (id) byKey[key].ids.add(id);
      // Registra targa→key (uppercase, senza spazi) per match retrocompatibile
      if (v.targa) targaToKey[v.targa.toUpperCase().trim()] = key;
    });

    return Object.values(byKey).map(grp => {
      const total = grp.ids.size;
      const busy  = new Set();
      let   busyNoId = 0;
      (prenotazioni || []).forEach(b => {
        if (!b.dal || !b.al) return;
        if (b.stato === 'annullata' || b.stato === 'completata' || b.stato === 'cancellata') return;
        if (b.al < dalS || b.dal > alS) return;
        const vidB = b.vehicleId || '';
        if (vidB && grp.ids.has(vidB)) {
          // Match diretto: vehicleId = fleet v.id (UUID o migrated-xxx)
          busy.add(vidB);
        } else if (vidB && targaToKey[vidB.toUpperCase()] === grp.key) {
          // Match retrocompatibile: vehicleId era la targa (booking pre-v0.43.10 o da RentMe sync)
          busy.add(vidB);
        } else if (!vidB && b.vehicleType === grp.tipo) {
          // Prenotazione tipo-only senza vehicleId: consuma 1 slot generico
          busyNoId++;
        }
        if (b.vehicleSchedule) {
          b.vehicleSchedule.forEach(s => {
            if (!s.vehicleId || s.dal > alS || s.al < dalS) return;
            if (grp.ids.has(s.vehicleId) || targaToKey[s.vehicleId.toUpperCase()] === grp.key) busy.add(s.vehicleId);
          });
        }
      });
      // Fermi flotta: blocchi manutenzione che riducono disponibilità
      (fermiFlotta || []).forEach(fermo => {
        if (!fermo.vehicleId || !fermo.dal || !fermo.al) return;
        if (fermo.al < dalS || fermo.dal > alS) return; // no overlap
        if (grp.ids.has(fermo.vehicleId) || targaToKey[(fermo.vehicleId||'').toUpperCase()] === grp.key) {
          busy.add(fermo.vehicleId);
        }
      });
      const booked    = busy.size + busyNoId;
      const free      = Math.max(0, total - booked);
      const threshold = Math.max(1, Math.ceil(total * 0.25));
      return {
        id: grp.key, nome: grp.nome, tipo: grp.tipo, categoria: grp.categoria,
        total, booked, free, threshold, alert: free <= threshold && total > 0
      };
    }).filter(c => c.total > 0).sort((a, b) => {
      const ta = TIPO_ORDER.indexOf(a.tipo);
      const tb = TIPO_ORDER.indexOf(b.tipo);
      if (ta !== tb) return (ta === -1 ? 99 : ta) - (tb === -1 ? 99 : tb);
      return a.nome.localeCompare(b.nome, 'it');
    });
  }

  // Ultimo fallback: stima dai dati prenotazioni (senza fleet né RentMe)
  const catMap = {};
  (prenotazioni || []).forEach(b => {
    if (!b.vehicleLabel || b.stato === 'annullata' || b.stato === 'completata' || b.stato === 'cancellata') return;
    const cat = b.vehicleLabel.split('·')[0].trim() || b.vehicleLabel;
    if (!catMap[cat]) catMap[cat] = { id: b.vehicleId || cat, nome: cat, tipo: b.vehicleType || '', total: 0, booked: 0 };
    if (b.vehicleId && !catMap[cat].known) { catMap[cat].total++; catMap[cat].known = true; }
    if (!(b.al < dalS || b.dal > alS)) catMap[cat].booked++;
  });
  return Object.values(catMap).map(c => ({
    ...c, free: Math.max(0, c.total - c.booked), threshold: 1, alert: false
  }));
}

// ── useRentMeSync ─────────────────────────────────────────────────
// Hook: gestisce il ciclo di vita della sync RentMe.
// Restituisce { status, lastSync, errorMsg, vehicles, sync }.
// Auto-sync al mount + ogni 5 minuti, se enabled = true.
//
// ┌─────────────────────────────────────────────────────────────────┐
// │  ROADMAP — INDIPENDENZA DA RENTME                               │
// │                                                                 │
// │  Fase 1 (ora):   RentMe = fonte di verità, Pratica legge       │
