// Indice ausiliario "solo numero" → entry. Molte chiavi sono "prefisso NN"
// (es. "superior 78", "liberty 214"), ma RentMe a volte manda solo il numero
// ("78"). Qui mappiamo ogni numero alla sua entry, derivandolo dalle chiavi
// "prefisso NN". I range non si sovrappongono (standard 1-31, superior 33-80+
// 308-310, liberty 170-261, quad 155-166), quindi nessuna collisione: il primo
// vince. Usato come fallback quando la chiave esatta non matcha → risolve la
// targa reale degli scooter/moto anche quando arriva il solo numero.
const RENTME_TARGA_BY_NUM = (() => {
  const idx = {};
  for (const [k, v] of Object.entries(RENTME_TARGA_MAP)) {
    const num = k.split(' ').pop();
    if (/^\d+$/.test(num) && num !== k && !idx[num]) idx[num] = v;
  }
  return idx;
})();

// Risolve un codice RentMe (es. "78", "superior 78", "panda 81") nella targa
// reale, SOLO per la visualizzazione. NON cambia il codice salvato sulle
// prenotazioni (cambiarlo scollegherebbe le consegne RentMe già fatte).
// Ritorna la targa o null se non mappata (es. e-bike, che targa non hanno).
function rentmeCodeToTarga(code) {
  const k = String(code || '').toLowerCase().trim();
  if (!k) return null;
  const num = k.split(' ').pop();
  const entry = RENTME_TARGA_MAP[k] || RENTME_TARGA_BY_NUM[k]
    || RENTME_TARGA_MAP[num] || RENTME_TARGA_BY_NUM[num];
  return entry?.targa || null;
}

//
// Le prenotazioni RentMe vengono mergiate con quelle locali:
//   - ID prefissato 'rm_' per riconoscerle
//   - fonte: 'rentme' — non editabili dall'operatore
function useRentMeSync({ fleet, rentmeVehicles, setRentmeVehicles, setPrenotazioni, pushToast, enabled = true, intervalMins = 5, proxyUrl = '' }) {
  const [status,      setStatus]      = useState('idle'); // idle|syncing|ok|error
  const [lastSync,    setLastSync]    = useState(() => {
    try { return localStorage.getItem('edo:rentme:lastSync') || null; } catch { return null; }
  });
  const [nextSyncAt,  setNextSyncAt]  = useState(null);
  const [errorMsg,    setErrorMsg]    = useState(null);
  const timerRef = useRef(null);

  const sync = useCallback(async () => {
    setStatus('syncing');
    setErrorMsg(null);
    try {
      // Veicoli letti dal nostro backend: l'UUID azienda resta sul server, non
      // più nel codice del sito. Il backend restituisce già SOLO i veicoli di Edonoleggio.
      const base = getApiBase();
      const r = await fetch(`${base}/rentme/veicoli`);
      if (!r.ok) throw new Error(`Errore server RentMe: ${r.status}`);
      const data = await r.json();
      const veicoli = data.veicoli || [];

      // Mappa codice RentMe → targa reale
      // Priorità: 1) mappa statica censimento  2) fleet locale (edit manuale ha precedenza)
      const rentmeToTarga = {};
      // Seed dalla mappa statica
      Object.entries(RENTME_TARGA_MAP).forEach(([k, v]) => { rentmeToTarga[k] = v.targa; });
      // Override con dati flotta locale (modifiche manuali prevalgono)
      (fleet || []).forEach(v => {
        const rmId = v.idRentme || v.rentmeId; // flotta locale usa idRentme, RentMe API usa rentmeId
        if (rmId && v.targa) {
          rentmeToTarga[rmId.toLowerCase().trim()] = v.targa.toUpperCase();
          const num = rmId.trim().split(' ').pop();
          if (num && !rentmeToTarga[num]) rentmeToTarga[num.toLowerCase()] = v.targa.toUpperCase();
        }
      });

      // Normalizza lista veicoli
      const mapped = veicoli.map(v => {
        const rmCode  = (v.targa || '').trim(); // codice RentMe es. "mehari 130"
        const realTar = rentmeToTarga[rmCode.toLowerCase()] || rentmeToTarga[rmCode.trim().split(' ').pop()?.toLowerCase()] || rmCode;
        return {
        rentmeCode:          rmCode,             // codice interno RentMe (quello che torna dall'API)
        idRentme:            rmCode,             // alias usato da getVehicleCategoria per matching (es. "mxu 168", "xwolf 311")
        targa:               realTar,            // targa reale (da fleet locale o codice RentMe come fallback)
        uuidDittaAssociata:  v.uuidDittaAssociata,
        nome:                [v.tipo, v.marca, v.modello, v.cilindrata].filter(Boolean).join(' '),
        slug:                [v.tipo, v.marca, v.modello, v.cilindrata].join('-').toLowerCase().replace(/\s+/g,'').replace(/[^a-z0-9-]/g,''),
        tipo:                canonicalTipo({ tipo: v.tipo, modello: v.modello }),
        cc:                  parseInt(v.cilindrata || 0, 10),  // cilindrata → numero per filtro QUAD150/QUAD300
        impegni:             (v.dateImpegno || []).map(di => {
          const p = di.split('|');
          return p.length >= 2 ? { dal: p[0], al: p[1], cliente: (p[2]||'').trim(), acconto: parseFloat(p[3])||0, importo: parseFloat(p[4])||0, note: (p[5]||'').trim() } : null;
        }).filter(Boolean)
        };
      });
      setRentmeVehicles(mapped);

      // Costruisce prenotazioni RentMe da mergare
      // vehicleId = targa (univoco per veicolo, non slug che colliede tra stessi modelli)
      const rentmeRows = [];
      veicoli.forEach(v => {
        const rmCode  = (v.targa || '').trim();
        const targaId = rentmeToTarga[rmCode.toLowerCase()] || rentmeToTarga[rmCode.trim().split(' ').pop()?.toLowerCase()] || rmCode.toUpperCase();
        const label   = [v.tipo, v.marca, v.modello, v.cilindrata].filter(Boolean).join(' ');
        (v.dateImpegno || []).forEach(di => {
          const p = di.split('|');
          if (p.length >= 2 && p[0] && p[1]) {
            const clienteFull = (p[2]||'').trim();
            const parti = clienteFull.split(' ');
            rentmeRows.push({
              id:            `rm_${targaId}_${p[0].replace(/-/g,'')}`,
              createdAt:     new Date().toISOString(),
              updatedAt:     new Date().toISOString(),
              clienteNome:   parti[0] || '',
              clienteCognome:parti.slice(1).join(' ') || clienteFull,
              clienteTel:    '',
              vehicleId:     targaId,          // targa = ID univoco per veicolo
              vehicleLabel:  label,
              vehicleType:   v.tipo || '',
              dal:           p[0],
              al:            p[1],
              stato:         'confermata',
              fonte:         'rentme',
              prezzo:        parseFloat(p[4])||0,
              acconto:       parseFloat(p[3])||0,
              note:          (p[5]||'').trim(),
              rentmeTarga:   targaId,
              rentmeCode:    rmCode,   // codice originale RentMe
            });
          }
        });
      });

      // Merge: mantieni prenotazioni locali + sostituisce quelle RentMe.
      // IMPORTANTE: preserva il codice già assegnato ai booking RentMe esistenti
      // (il codice viene usato come ID contratto EDO-YYYY-{codice}) —
      // senza questo, ogni sync rigenerava un codice diverso spezzando il link contratto.
      setPrenotazioni(prev => {
        const existingRentme = (prev || []).filter(p => p.fonte === 'rentme');
        const local          = (prev || []).filter(p => p.fonte !== 'rentme');
        // Rank stato per non far REGREDIRE quello impostato dall'operatore.
        const RANK = { attesa: 0, confermata: 1, in_corso: 2, completata: 3, cancellata: 3, annullata: 3 };
        const rentmeWithCodes = rentmeRows.map(r => {
          const found = existingRentme.find(e => e.id === r.id);
          if (!found) return { ...r, codice: generateBookingCode() };
          // RentMe è "padrone" solo dei SUOI campi (date, cliente, prezzo, note RentMe).
          // Tutto il resto sul booking esistente è lavoro dell'operatore (consegna,
          // km, carburante, luogo, firma, contratto, riconsegna…) e va PRESERVATO:
          // prima la sync rigenerava il booking da zero (stato→confermata) cancellando
          // la consegna → "confermo ma non resta".
          const rentmeOwned = {
            clienteNome: r.clienteNome, clienteCognome: r.clienteCognome,
            dal: r.dal, al: r.al, prezzo: r.prezzo, acconto: r.acconto,
            note: r.note, vehicleType: r.vehicleType,
            rentmeTarga: r.rentmeTarga, rentmeCode: r.rentmeCode, fonte: 'rentme',
            updatedAt: r.updatedAt,
          };
          // Stato: tieni il locale se più avanzato (in_corso/completata/cancellata).
          const stato = (RANK[found.stato] ?? 0) > (RANK[r.stato] ?? 0) ? found.stato : r.stato;
          // Veicolo: se l'operatore ha già consegnato, vince il mezzo assegnato localmente;
          // altrimenti usa quello di RentMe.
          const veh = found.consegnaAt
            ? { vehicleId: found.vehicleId || r.vehicleId, vehicleLabel: found.vehicleLabel || r.vehicleLabel, vehicleTarga: found.vehicleTarga || r.vehicleTarga }
            : { vehicleId: r.vehicleId, vehicleLabel: r.vehicleLabel, vehicleTarga: r.vehicleTarga };
          return { ...found, ...rentmeOwned, ...veh, stato, codice: found.codice || generateBookingCode() };
        });
        return [...local, ...rentmeWithCodes];
      });

      const now = new Date().toISOString();
      setLastSync(now);
      try { localStorage.setItem('edo:rentme:lastSync', now); } catch {}
      setStatus('ok');
      pushToast && pushToast({
        tone: 'success',
        title: `RentMe ✓`,
        message: `${veicoli.length} mezzi · ${rentmeRows.length} prenotazioni sincronizzate`,
      });
      return { ok: true, vehicles: mapped.length, bookings: rentmeRows.length };
    } catch(e) {
      setStatus('error');
      setErrorMsg(e.message);
      pushToast && pushToast({ tone: 'warning', title: 'Sync RentMe fallito', message: e.message });
      return { ok: false, error: e.message };
    }
  }, [setRentmeVehicles, setPrenotazioni, pushToast]);

  // Auto-sync al mount + ogni N minuti — si riavvia se enabled o intervalMins cambiano
  useEffect(() => {
    if (!enabled) {
      setStatus('idle');
      setNextSyncAt(null);
      return;
    }
    const ms = Math.max(1, intervalMins) * 60 * 1000;
    const scheduleNext = () => setNextSyncAt(new Date(Date.now() + ms).toISOString());
    sync().then(scheduleNext);
    timerRef.current = setInterval(() => { sync().then(scheduleNext); }, ms);
    return () => { clearInterval(timerRef.current); setNextSyncAt(null); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, intervalMins]);

  // Manda prenotazione a RentMe (PUSH — solo aggiunte, mai modifiche)
  // proxyUrl configurable: usa quello in rentmeConfig se disponibile,
  // altrimenti fallback al PHP proxy su Altervista.
  const pushBooking = useCallback(async (booking, slug) => {
    const veicoli = rentmeVehicles || [];
    const catVehs = veicoli.filter(v => v.slug === slug);
    if (!catVehs.length) throw new Error('Nessun mezzo RentMe per questa categoria');
    // Marca occupati i veicoli che hanno già impegni sovrapposti alle date richieste
    const busy = new Set();
    catVehs.forEach(v => {
      const overla = (v.impegni || []).some(imp => imp.al >= booking.dal && imp.dal <= booking.al);
      if (overla) busy.add(v.targa);
    });
    const freeVeh = catVehs.find(v => !busy.has(v.targa)) || catVehs[0];
    const payload = {
      uuidDittaAssociata: freeVeh.uuidDittaAssociata,
      targa:              freeVeh.targa,
      descrizione:        [booking.clienteCognome, booking.clienteNome].filter(Boolean).join(' '),
      dal:                booking.dal,
      al:                 booking.al,
      acconto:            parseFloat(booking.acconto) || 0,
      prezzoPrenotazione: parseFloat(booking.prezzo)  || 0,
      note:               (booking.note || '').replace(/\|/g,' '),
      bloccata:           'false',
    };
    // Usa proxy configurato (Node.js su Render) o fallback al PHP proxy Altervista
    const effectiveProxy = (proxyUrl || '').trim() || RENTME_PROXY;
    let r;
    try {
      r = await fetch(`${effectiveProxy}?path=veicoli/add/reservetion`, {
        method:  'PUT',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify(payload),
      });
    } catch (networkErr) {
      // CORS o rete: distingui il tipo di errore per dare istruzioni utili
      const msg = networkErr?.message || String(networkErr);
      if (msg.includes('CORS') || msg.includes('Failed to fetch') || msg.includes('NetworkError')) {
        throw new Error(
          `CORS bloccato: il proxy RentMe non risponde da questa origine.\n` +
          `Verifica che "${effectiveProxy}" risponda correttamente con Access-Control-Allow-Origin: *\n` +
          `Oppure configura un proxy alternativo in Impostazioni → RentMe Bridge.`
        );
      }
      throw networkErr;
    }
    if (!r.ok) throw new Error(`RentMe API: ${r.status}`);
    return r.json();
  }, [rentmeVehicles, proxyUrl]);

  // ─── Coda retry prenotazioni fallite ───
  const RETRY_KEY = 'rentme_pending_queue';

  const savePendingBooking = (booking, slug) => {
    const queue = JSON.parse(localStorage.getItem(RETRY_KEY) || '[]');
    const id = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    queue.push({ id, booking, slug, attempts: 0, savedAt: new Date().toISOString() });
    localStorage.setItem(RETRY_KEY, JSON.stringify(queue));
  };

  const retryPendingBookings = useCallback(async () => {
    const queue = JSON.parse(localStorage.getItem(RETRY_KEY) || '[]');
    if (!queue.length) return;
    const remaining = [];
    for (const item of queue) {
      try {
        await pushBooking(item.booking, item.slug);
      } catch {
        if (item.attempts < 5) remaining.push({ ...item, attempts: item.attempts + 1 });
      }
    }
    localStorage.setItem(RETRY_KEY, JSON.stringify(remaining));
  }, [pushBooking]);

  // Riprova al mount e ogni sync
  useEffect(() => {
    retryPendingBookings();
  }, [retryPendingBookings]);

  return { status, lastSync, nextSyncAt, errorMsg, sync, pushBooking, savePendingBooking, retryPendingBookings };
}

// ═══════════════════════════════════════════════════════════════════
// BANCO RAPIDO — walk-in desk
// Schermata veloce per il banco: seleziona date, vedi cosa è libero,
// un tap → apre il form prenotazione prefillato per quella categoria.
// ═══════════════════════════════════════════════════════════════════
function BancoRapidoPage({ rentmeVehicles, prenotazioni, fleet, setPage, setPrenotazioniPrefill, listino, pushToast, rentmeSyncStatus, onRentmeSync, rentmeLastSync, fermiFlotta }) {
  const today = todayISO();
  const [dal, setDal] = useState(today);
  const [al,  setAl]  = useState(today);
  // Modal veicoli: categoria selezionata o null
  const [vehicleModal, setVehicleModal] = useState(null); // null | { cat, vehicles }

  const availability = useMemo(
    () => calcAvailability(dal, al, rentmeVehicles, prenotazioni, fleet, fermiFlotta),
    [dal, al, rentmeVehicles, prenotazioni, fleet, fermiFlotta]
  );

  // Alert: categorie sotto soglia
  const alerts = availability.filter(c => c.alert);

  // Calcola veicoli liberi per una categoria nelle date selezionate
  function getVehiclesForCat(cat) {
    const ct = (cat.tipo || '').toLowerCase();
    const tipoMatch = t => {
      const tl = (t || '').toLowerCase();
      return tl === ct || (tl === 'moto' && ct === 'scooter') || (tl === 'scooter' && ct === 'moto');
    };
    // Filtro categoria: mostra solo i veicoli della sotto-categoria corretta
    const catMatch = v => {
      if (!cat.categoria) return true;
      let vcat = getVehicleCategoria(v) || '';
      const isAuto = (v.tipo || '').toLowerCase() === 'auto';
      if (isAuto) vcat = normalizeAutoCategoria(vcat);
      const targetCat = isAuto ? normalizeAutoCategoria(cat.categoria) : cat.categoria;
      return vcat === targetCat;
    };

    // Fleet locale: filtra per tipo + categoria, arricchisci label e targa
    const fleetVehicles = (fleet || [])
      .filter(v => v.stato !== 'venduto' && v.stato !== 'fuori_uso' && tipoMatch(v.tipo) && catMatch(v))
      .map(v => ({
        ...v,
        label: (v.marca && v.modello) ? `${v.marca} ${v.modello}` : (v.nome || v.targa || v.id),
        targa: resolveVehicleDisplay(v).targa || v.targa || '',
      }));

    // RentMe: filtra per tipo + categoria
    const rmVehicles = (rentmeVehicles || [])
      .filter(v => tipoMatch(v.tipo) && catMatch(v))
      .map(v => ({
        ...v,
        label: v.nome || v.modello || v.marca || '',
        targa: resolveVehicleDisplay(v).targa || v.targa || '',
      }));

    // Dedup by id — fleet ha precedenza
    const seen = new Set();
    const merged = [];
    for (const v of [...fleetVehicles, ...rmVehicles]) {
      const id = v.id || v.targa;
      if (!id || seen.has(id)) continue;
      seen.add(id);
      merged.push(v);
    }

    // Mark occupati nelle date selezionate (inclusi segmenti vehicleSchedule multi-mezzo)
    const occupati = new Set();
    (prenotazioni || [])
      .filter(p => p.dal <= al && p.al >= dal && p.stato !== 'annullata' && p.stato !== 'cancellata' && p.stato !== 'completata')
      .forEach(p => {
        if (p.vehicleId) occupati.add(p.vehicleId);
        (p.vehicleSchedule || []).forEach(s => {
          if (s.vehicleId && s.dal <= al && s.al >= dal) occupati.add(s.vehicleId);
        });
      });
    // Fermi programmati: manutenzione blocca il veicolo
    (fermiFlotta || []).forEach(f => {
      if (f.vehicleId && f.dal <= al && f.al >= dal) occupati.add(f.vehicleId);
    });
    return merged.map(v => ({ ...v, libero: !occupati.has(v.id) }));
  }

  const handleSelect = (cat) => {
    if (cat.free <= 0) {
      pushToast({ tone: 'warning', title: 'Categoria esaurita', message: `Nessun ${cat.nome} libero per le date selezionate` });
      return;
    }
    // Mostra modal con veicoli individuali
    const vehicles = getVehiclesForCat(cat);
    setVehicleModal({ cat, vehicles });
  };

  function handleVehicleBook(cat, v) {
    setVehicleModal(null);
    const label = v.label || v.targa || cat.nome;
    const targa = v.targa || '';
    setPrenotazioniPrefill({
      vehicleId:    v.id,
      vehicleLabel: label,
      vehicleTarga: targa,
      vehicleType:  cat.tipo,
      dal, al,
      fonte: 'walk_in',
    });
    setPage('prenotazioni');
    pushToast({ tone: 'success', title: '🚶 Walk-in', message: `${label}${targa ? ' · ' + targa : ''} · ${dal === al ? dal : dal + ' → ' + al}` });
  }

  const fmtLastSync = (iso) => {
    if (!iso) return null;
    const d = new Date(iso);
    return d.toLocaleTimeString('it-IT', { hour:'2-digit', minute:'2-digit' });
  };

  const catColor = (cat) => {
    if (cat.free <= 0) return { bg: '#fdecea', border: '#c0392b', text: '#c0392b', label: 'Esaurito' };
    if (cat.alert)     return { bg: '#fff8e6', border: '#e67e22', text: '#d35400', label: 'Quasi esaurito' };
    return { bg: '#eafaf1', border: '#27ae60', text: '#1e8449', label: 'Disponibile' };
  };

  const nGiorni = (() => {
    const d1 = new Date(dal + 'T12:00:00');
    const d2 = new Date(al  + 'T12:00:00');
    const diff = Math.round((d2 - d1) / 86400000) + 1;
    return diff <= 1 ? 'Giornaliero' : `${diff} giorni`;
  })();

  return (
    <>
    <div style={{ padding: '28px 32px', maxWidth: 960, margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 24 }}>
        <div>
          <div className="label" style={{ color: 'var(--edo-sea)', marginBottom: 2 }}>Walk-in · oggi</div>
          <h1 style={{ margin: 0, fontSize: 22, fontFamily: 'var(--font-serif)', fontWeight: 600, color: 'var(--ink)', letterSpacing: '-0.01em' }}>
            Banco rapido
          </h1>
          <p style={{ margin: '4px 0 0', fontSize: 13, color: 'var(--muted)' }}>
            Verifica disponibilità in tempo reale e crea una prenotazione in un tap.
          </p>
        </div>
        {/* RentMe status */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, color: 'var(--ink-2)' }}>
          <span style={{
            width: 8, height: 8, borderRadius: '50%',
            background: rentmeSyncStatus === 'ok' ? '#27ae60' : rentmeSyncStatus === 'syncing' ? '#e67e22' : rentmeSyncStatus === 'error' ? '#c0392b' : '#aaa',
            display: 'inline-block',
          }} />
          <span>RentMe {rentmeSyncStatus === 'ok' ? `· sync ${fmtLastSync(rentmeLastSync)}` : rentmeSyncStatus === 'syncing' ? '· sincronizzazione…' : rentmeSyncStatus === 'error' ? '· errore' : '· non connesso'}</span>
          <button type="button" onClick={onRentmeSync}
            disabled={rentmeSyncStatus === 'syncing'}
            style={{ padding: '3px 10px', fontSize: 11, border: '1px solid var(--border)', borderRadius: 4, background: 'var(--bg)', cursor: 'pointer', color: 'var(--ink-2)' }}>
            ↻ Sync
          </button>
        </div>
      </div>

      {/* Alert banner */}
      {alerts.length > 0 && (
        <div style={{ background: '#fff8e6', border: '1px solid #f39c12', borderLeft: '4px solid #e67e22', borderRadius: 6, padding: '10px 14px', marginBottom: 20, display: 'flex', alignItems: 'center', gap: 10 }}>
          <AlertTriangle style={{ width: 16, height: 16, color: '#e67e22', flexShrink: 0 }} />
          <span style={{ fontSize: 13, color: '#7d4e0a' }}>
            <strong>Attenzione:</strong> {alerts.map(c => c.nome).join(', ')} {alerts.length === 1 ? 'è quasi esaurita' : 'sono quasi esaurite'} per il periodo selezionato.
          </span>
        </div>
      )}

      {/* Date picker */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 24, padding: '14px 18px', background: 'var(--surface-2)', borderRadius: 8, border: '1px solid var(--border)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <label style={{ fontSize: 12, fontWeight: 600, color: 'var(--ink-2)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Dal</label>
          <input type="date" value={dal} min={today}
            onChange={e => { setDal(e.target.value); if (e.target.value > al) setAl(e.target.value); }}
            style={{ padding: '6px 10px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 14, background: 'var(--bg)', color: 'var(--ink)', fontFamily: 'var(--font-sans)' }} />
        </div>
        <span style={{ color: 'var(--muted)', fontSize: 18 }}>→</span>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <label style={{ fontSize: 12, fontWeight: 600, color: 'var(--ink-2)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Al</label>
          <input type="date" value={al} min={dal}
            onChange={e => setAl(e.target.value)}
            style={{ padding: '6px 10px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 14, background: 'var(--bg)', color: 'var(--ink)', fontFamily: 'var(--font-sans)' }} />
        </div>
        <span style={{ fontSize: 12, color: 'var(--muted)', marginLeft: 4 }}>{nGiorni}</span>
        <div style={{ flex: 1 }} />
        <button type="button" onClick={() => { setDal(today); setAl(today); }}
          style={{ fontSize: 12, color: 'var(--ink-2)', background: 'none', border: '1px solid var(--border)', borderRadius: 5, padding: '5px 12px', cursor: 'pointer' }}>
          Oggi
        </button>
      </div>

      {/* Griglia disponibilità */}
      {availability.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '60px 20px', color: 'var(--muted)' }}>
          <div style={{ fontSize: 32, marginBottom: 12 }}>🔌</div>
          <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 6, color: 'var(--ink-2)' }}>Nessun dato disponibile</div>
          <div style={{ fontSize: 13 }}>Sincronizza RentMe o inserisci prenotazioni per vedere la disponibilità.</div>
          <button type="button" onClick={onRentmeSync} style={{ marginTop: 16, padding: '8px 20px', background: 'var(--ink)', color: 'var(--paper)', border: 'none', borderRadius: 5, fontSize: 13, cursor: 'pointer' }}>
            ↻ Sincronizza RentMe
          </button>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 14 }}>
          {availability.map(cat => {
            const c = catColor(cat);
            const pct = cat.total > 0 ? Math.round((cat.free / cat.total) * 100) : 0;
            return (
              <button
                key={cat.id}
                type="button"
                onClick={() => handleSelect(cat)}
                disabled={cat.free <= 0}
                className="walk-in-btn"
                style={{
                  background: c.bg, border: `1.5px solid ${c.border}`, borderRadius: 10,
                  padding: '16px 18px', textAlign: 'left', cursor: cat.free > 0 ? 'pointer' : 'not-allowed',
                  position: 'relative', overflow: 'hidden',
                  opacity: cat.free <= 0 ? 0.75 : 1,
                }}
              >
                <div style={{ fontSize: 12, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: c.text, marginBottom: 6 }}>
                  {c.label}
                </div>
                <div style={{ fontSize: 15, fontWeight: 600, color: 'var(--ink)', marginBottom: 8, lineHeight: 1.3 }}>
                  {cat.nome}
                </div>
                <div style={{ display: 'flex', alignItems: 'baseline', gap: 4, marginBottom: 10 }}>
                  <span style={{ fontSize: 36, fontWeight: 700, fontFamily: 'var(--font-serif)', color: c.text, lineHeight: 1 }}>{cat.free}</span>
                  <span style={{ fontSize: 14, color: 'var(--muted)' }}>/ {cat.total} liberi</span>
                </div>
                {/* Barra progressione */}
                <div style={{ height: 4, background: 'rgba(0,0,0,.08)', borderRadius: 2, overflow: 'hidden' }}>
                  <div style={{ height: '100%', width: `${pct}%`, background: c.border, borderRadius: 2, transition: 'width 0.4s' }} />
                </div>
                {cat.free > 0 && (
                  <div style={{ position: 'absolute', right: 12, bottom: 12, fontSize: 11, color: c.text, fontWeight: 600 }}>
                    Prenota →
                  </div>
                )}
              </button>
            );
          })}
        </div>
      )}

      {/* Legenda */}
      {availability.length > 0 && (
        <div style={{ marginTop: 24, display: 'flex', gap: 20, fontSize: 11, color: 'var(--muted)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
            <span style={{ width: 10, height: 10, borderRadius: 2, background: '#27ae60', display: 'inline-block' }} />
            Disponibile
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
            <span style={{ width: 10, height: 10, borderRadius: 2, background: '#e67e22', display: 'inline-block' }} />
            Quasi esaurito (≤25% liberi)
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
            <span style={{ width: 10, height: 10, borderRadius: 2, background: '#c0392b', display: 'inline-block' }} />
            Esaurito
          </div>
          {(rentmeVehicles||[]).length === 0 && (
            <span style={{ marginLeft: 'auto', fontStyle: 'italic' }}>
              ⚠ Dati solo locali · sync RentMe per disponibilità reale
            </span>
          )}
        </div>
      )}
    </div>

    {/* ── Modal veicoli individuali ───────────────────────────────── */}
    {vehicleModal && (
      <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.55)', zIndex:1000,
        display:'flex', alignItems:'center', justifyContent:'center', padding:20 }}
        onClick={() => setVehicleModal(null)}>
        <div style={{ background:'var(--bg)', borderRadius:14, width:'100%', maxWidth:480,
          maxHeight:'80vh', display:'flex', flexDirection:'column', boxShadow:'0 24px 60px rgba(0,0,0,.35)' }}
          onClick={e => e.stopPropagation()}>
          {/* Modal header */}
          <div style={{ padding:'18px 22px', borderBottom:'1px solid var(--border)', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
            <div>
              <div style={{ fontFamily:'var(--font-serif)', fontWeight:600, fontSize:17, color:'var(--ink)' }}>
                {vehicleModal.cat.nome}
              </div>
              <div style={{ fontSize:12, color:'var(--muted)', marginTop:2 }}>
                Scegli il mezzo · {dal} → {al}
              </div>
            </div>
            <button type="button" onClick={() => setVehicleModal(null)}
              style={{ background:'none', border:'none', cursor:'pointer', color:'var(--muted)', fontSize:22, lineHeight:1 }}>
              ×
            </button>
          </div>
          {/* Lista veicoli */}
          <div style={{ overflowY:'auto', flex:1, padding:'10px 14px' }}>
            {vehicleModal.vehicles.length === 0 && (
              <div style={{ padding:'32px 20px', textAlign:'center', color:'var(--muted)', fontSize:13 }}>
                Nessun veicolo trovato in questa categoria.<br/>
                <button type="button" onClick={() => {
                  setVehicleModal(null);
                  // Prenota generica per categoria
                  setPrenotazioniPrefill({ vehicleType: vehicleModal.cat.tipo, vehicleLabel: vehicleModal.cat.nome, dal, al, fonte: 'walk_in' });
                  setPage('prenotazioni');
                }} style={{ marginTop:12, padding:'8px 18px', background:'var(--ink)', color:'var(--paper)', border:'none', borderRadius:6, fontSize:13, cursor:'pointer', fontWeight:600 }}>
                  Prenota senza mezzo specifico →
                </button>
              </div>
            )}
            {vehicleModal.vehicles.map(v => {
              const TIPO_EMOJI = { auto:'🚗', scooter:'🛵', moto:'🛵', quad:'🏎', ebike:'⚡', bici:'🚲' };
              const emoji = TIPO_EMOJI[v.tipo] || '🚗';
              // label e targa già risolti da getVehiclesForCat
              const label = v.label || v.targa || v.id;
              const targa = v.targa || '';
              return (
                <button key={v.id || label} type="button"
                  onClick={() => v.libero ? handleVehicleBook(vehicleModal.cat, v) : null}
                  disabled={!v.libero}
                  style={{
                    width:'100%', display:'flex', alignItems:'center', gap:12,
                    padding:'12px 14px', borderRadius:8, border:'1.5px solid var(--border)',
                    marginBottom:8, textAlign:'left', cursor: v.libero ? 'pointer' : 'not-allowed',
                    background: v.libero ? 'var(--bg)' : 'var(--surface-2)',
                    opacity: v.libero ? 1 : 0.55,
                    transition: 'border-color 0.15s, box-shadow 0.15s',
                  }}
                  onMouseEnter={e => { if (v.libero) { e.currentTarget.style.borderColor='var(--accent)'; e.currentTarget.style.boxShadow='0 2px 10px rgba(0,0,0,.1)'; }}}
                  onMouseLeave={e => { e.currentTarget.style.borderColor='var(--border)'; e.currentTarget.style.boxShadow=''; }}
                >
                  <span style={{ fontSize:24 }}>{emoji}</span>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontWeight:600, fontSize:14, color:'var(--ink)', display:'flex', alignItems:'center', gap:6 }}>
                      {label}
                      {targa && targa !== label && (
                        <span style={{ fontFamily:'monospace', fontSize:11, padding:'1px 6px', background:'var(--surface-2)', borderRadius:4, border:'1px solid var(--border)', color:'var(--ink-2)' }}>
                          {targa}
                        </span>
                      )}
                    </div>
                    <div style={{ fontSize:12, color:'var(--muted)', marginTop:2 }}>
                      {v.tipo ? v.tipo.charAt(0).toUpperCase() + v.tipo.slice(1) : ''}
                      {v.anno && ` · ${v.anno}`}
                      {v.colore && ` · ${v.colore}`}
                    </div>
                  </div>
                  <div style={{
                    fontSize:11, fontWeight:700, padding:'3px 10px', borderRadius:10,
                    background: v.libero ? '#eafaf1' : '#fdecea',
                    color: v.libero ? '#1e8449' : '#c0392b',
                    flexShrink: 0,
                  }}>
                    {v.libero ? 'Libero' : 'Occupato'}
                  </div>
                  {v.libero && <span style={{ color:'var(--accent)', fontWeight:700, fontSize:16, flexShrink:0 }}>→</span>}
                </button>
              );
            })}
          </div>
          {/* Footer */}
          <div style={{ padding:'12px 22px', borderTop:'1px solid var(--border)' }}>
            <button type="button" onClick={() => {
              setVehicleModal(null);
              setPrenotazioniPrefill({ vehicleType: vehicleModal.cat.tipo, vehicleLabel: vehicleModal.cat.nome, dal, al, fonte: 'walk_in' });
              setPage('prenotazioni');
            }} style={{ width:'100%', padding:'9px', borderRadius:7, border:'1px solid var(--border)',
              background:'transparent', color:'var(--ink-2)', cursor:'pointer', fontSize:13 }}>
              Prenota senza mezzo specifico
            </button>
          </div>
        </div>
      </div>
    )}
    </>
  );
}

// ═══════════════════════════════════════════════════════════════════
// PDF EXPORT — Preventivo
// Apre una nuova finestra con HTML formattato e lancia window.print().
// Nessuna dipendenza esterna — funziona ovunque.
// ═══════════════════════════════════════════════════════════════════
function exportPreventivoPDF(quote, agencyInfo, lang = 'it') {
  const i18n = PREVENTIVO_I18N[lang] || PREVENTIVO_I18N.it;
  const agency = agencyInfo || {};
  const nomeAzienda = agency.nome || 'Edonoleggio';
  const indirizzo   = agency.indirizzoLegale ? `${agency.indirizzoLegale}, ${agency.citta || ''}` : 'Via Emerico Amari, 8 — Lampedusa (AG)';
  const telefono    = agency.telefono || '';
  const email       = agency.email || '';
  const piva        = agency.piva ? `P.IVA ${agency.piva}` : '';

  const locale = lang === 'es' ? 'es-ES' : lang === 'en' ? 'en-GB' : 'it-IT';
  const today = new Date().toLocaleDateString(locale, { day:'2-digit', month:'long', year:'numeric' });
  const fmtDate = (d) => d ? new Date(d + 'T12:00:00').toLocaleDateString(locale, { day:'2-digit', month:'long', year:'numeric' }) : '—';

  const rows = (quote.breakdown || []).map(b =>
    `<tr><td>${b.label}</td><td style="text-align:right">${b.gg} gg</td><td style="text-align:right">€${b.price.toFixed(2)}</td><td style="text-align:right;font-weight:600">€${b.subtotal.toFixed(2)}</td></tr>`
  ).join('');

  const html = `<!DOCTYPE html>
<html lang="${lang}">
<head>
<meta charset="UTF-8">
<title>${i18n.docTitle} · ${nomeAzienda}</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,600;1,400&family=DM+Sans:wght@400;600&display=swap');
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:'DM Sans',system-ui,sans-serif;color:#1a1815;background:#fff;padding:40px 48px;max-width:760px;margin:0 auto}
  h1{font-family:'Fraunces',Georgia,serif;font-weight:600;font-size:28px;color:#1a1815;margin-bottom:4px}
  .sub{font-size:13px;color:#6a6057;margin-bottom:32px}
  .header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:36px;padding-bottom:20px;border-bottom:2px solid #1a1815}
  .logo-area h2{font-family:'Fraunces',serif;font-size:22px;font-weight:600;color:#1a1815}
  .logo-area p{font-size:12px;color:#6a6057;margin-top:3px}
  .doc-meta{text-align:right;font-size:12px;color:#6a6057}
  .doc-meta strong{font-size:15px;font-weight:600;color:#1a1815;display:block}
  .section{margin-bottom:28px}
  .section h3{font-family:'Fraunces',serif;font-size:14px;font-weight:600;color:#1a1815;text-transform:uppercase;letter-spacing:.08em;margin-bottom:10px;padding-bottom:6px;border-bottom:1px solid #e8e0cc}
  .info-row{display:flex;gap:8px;font-size:13px;margin-bottom:5px;color:#3a352e}
  .info-label{font-weight:600;width:120px;flex-shrink:0;color:#6a6057;font-size:12px;text-transform:uppercase;letter-spacing:.05em}
  table{width:100%;border-collapse:collapse;font-size:13px}
  thead tr{background:#f5f0e8}
  th{padding:8px 10px;text-align:left;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#6a6057;border-bottom:2px solid #e8e0cc}
  td{padding:9px 10px;border-bottom:1px solid #f0ebe0;color:#3a352e}
  .total-row td{font-weight:700;color:#1a1815;border-top:2px solid #1a1815;font-size:15px;padding-top:12px}
  .footer{margin-top:48px;padding-top:16px;border-top:1px solid #e8e0cc;font-size:11px;color:#9a9085;text-align:center;line-height:1.6}
  .highlight{background:#f5f0e8;border-radius:6px;padding:14px 16px;margin-bottom:20px;display:flex;justify-content:space-between;align-items:center}
  .highlight .price{font-family:'Fraunces',serif;font-size:32px;font-weight:600;color:#1a1815}
  .highlight .price-label{font-size:12px;color:#6a6057;text-transform:uppercase;letter-spacing:.06em}
  @page{size:A4;margin:1.5cm}
  @media print{body{padding:0}button{display:none!important}}
</style>
</head>
<body>
<div class="header">
  <div class="logo-area">
    <h2>${nomeAzienda}</h2>
    <p>${indirizzo}${telefono ? ' · Tel. '+telefono : ''}${email ? ' · '+email : ''}</p>
    ${piva ? `<p>${piva}</p>` : ''}
  </div>
  <div class="doc-meta">
    <strong>${i18n.docTitle}</strong>
    <span>${today}</span>
    ${quote.codice ? `<div style="margin-top:6px;font-family:monospace;font-size:18px;font-weight:700;letter-spacing:.12em;color:#1a1815">${quote.codice}</div>` : ''}
  </div>
</div>

${quote.cliente && (quote.cliente.nome || quote.cliente.tel || quote.cliente.email) ? `
<div class="section">
  <h3>${lang === 'en' ? 'Customer' : lang === 'es' ? 'Cliente' : 'Cliente'}</h3>
  ${quote.cliente.nome  ? `<div class="info-row"><span class="info-label">${lang==='en'?'Name':'Nominativo'}</span><span><strong>${quote.cliente.nome}</strong></span></div>` : ''}
  ${quote.cliente.tel   ? `<div class="info-row"><span class="info-label">${lang==='en'?'Phone':'Telefono'}</span><span>${quote.cliente.tel}</span></div>` : ''}
  ${quote.cliente.email ? `<div class="info-row"><span class="info-label">Email</span><span>${quote.cliente.email}</span></div>` : ''}
  ${quote.cliente.note  ? `<div class="info-row"><span class="info-label">Note</span><span>${quote.cliente.note}</span></div>` : ''}
</div>` : ''}

<div class="section">
  <h3>${i18n.dettagliTitle}</h3>
  <div class="info-row"><span class="info-label">${i18n.categoria}</span><span>${quote.catName || '—'}</span></div>
  <div class="info-row"><span class="info-label">${i18n.dal}</span><span>${fmtDate(quote.dal)}</span></div>
  <div class="info-row"><span class="info-label">${i18n.al}</span><span>${fmtDate(quote.al)}</span></div>
  <div class="info-row"><span class="info-label">${i18n.stagione}</span><span>${quote.stagione ? quote.stagione.charAt(0).toUpperCase() + quote.stagione.slice(1) : '—'}</span></div>
  <div class="info-row"><span class="info-label">${i18n.tariffaTipo}</span><span>${quote.isWeekly ? i18n.settimanale : i18n.giornaliera}</span></div>
</div>

${(quote.breakdown||[]).length > 0 ? `
<div class="section">
  <h3>${i18n.tariffeTitle}</h3>
  <table>
    <thead><tr><th>${i18n.periodo}</th><th style="text-align:right">${i18n.giorni}</th><th style="text-align:right">${i18n.tariffa}</th><th style="text-align:right">${i18n.subtotale}</th></tr></thead>
    <tbody>${rows}</tbody>
  </table>
</div>` : ''}

<div class="highlight">
  <div>
    <div class="price-label">${i18n.totaleLabel}</div>
    <div class="price">€${(quote.total||0).toFixed(2)}</div>
  </div>
  <div style="font-size:12px;color:#6a6057;text-align:right">
    ${quote.totalDays || 0} ${lang==='en'?'days':'lang'==='es'?'días':'giorni'} · ${i18n.ivaInclusa}<br>
    ${i18n.disponibilita}
  </div>
</div>

<div class="footer">
  ${i18n.disclaimer}<br>
  ${nomeAzienda} · ${indirizzo} · Lampedusa, Isole Pelagie
</div>

<div style="text-align:center;margin-top:24px">
  <button onclick="window.print()" style="padding:10px 28px;background:#1a1815;color:#fff;border:none;border-radius:6px;font-size:14px;font-weight:600;cursor:pointer;font-family:'DM Sans',sans-serif">
    🖨 ${lang==='en'?'Print / Save PDF':lang==='es'?'Imprimir / Guardar PDF':'Stampa / Salva PDF'}
  </button>
</div>
</body>
</html>`;

  const win = window.open('', '_blank', 'width=800,height=900,scrollbars=yes');
  if (win) {
    win.document.write(html);
    win.document.close();
    setTimeout(() => win.print(), 800);
  }
}

// ═══════════════════════════════════════════════════════════════════
// STAGIONI EDITOR — configura quali mesi appartengono a quale stagione
// Consente all'admin di modificare la distribuzione stagionale senza
// toccare il codice. Persistente su edo:v1:stagioni.
// ═══════════════════════════════════════════════════════════════════
const DEFAULT_STAGIONI_CONFIG = {
  bassa: [0,1,2,3,9,10,11],    // gen-apr, ott-dic
  media: [4,5,6,8],            // mag-lug, set
  alta:  [7],                  // ago
};
const MESI_IT = ['Gen','Feb','Mar','Apr','Mag','Giu','Lug','Ago','Set','Ott','Nov','Dic'];
const STAGIONE_LABELS = { bassa: 'Bassa stagione', media: 'Media stagione', alta: 'Alta stagione' };
const STAGIONE_COLORS = { bassa: '#1f5d83', media: '#b87333', alta: '#c14a2b' };

function StagioniEditor({ stagioni, onSave }) {
  const [draft, setDraft] = useState(() => JSON.parse(JSON.stringify(stagioni || DEFAULT_STAGIONI_CONFIG)));
  const [saved, setSaved] = useState(false);

  const getStagioneForMonth = (m) => {
    if (draft.alta.includes(m))  return 'alta';
    if (draft.media.includes(m)) return 'media';
    if (draft.bassa.includes(m)) return 'bassa';
    return null;
  };

  const cycleMonth = (m) => {
    const order = ['bassa','media','alta'];
    const cur   = getStagioneForMonth(m);
    const nextS = order[(order.indexOf(cur) + 1) % order.length];
    const nd = { bassa: [...draft.bassa], media: [...draft.media], alta: [...draft.alta] };
    ['bassa','media','alta'].forEach(s => { nd[s] = nd[s].filter(x => x !== m); });
    nd[nextS].push(m);
    nd[nextS].sort((a,b)=>a-b);
    setDraft(nd);
    setSaved(false);
  };

  const handleSave = () => {
    onSave(draft);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  return (
    <div style={{ background: 'var(--bg)', border: '1px solid var(--border)', borderRadius: 8, padding: '20px 24px' }}>
      <div style={{ fontSize: 12, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--ink-2)', marginBottom: 6 }}>
        Distribuzione stagionale
      </div>
      <p style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 16 }}>
        Clicca su ogni mese per cambiare stagione (cicla: Bassa → Media → Alta). Le modifiche influenzano subito il calcolo dei preventivi.
      </p>

      {/* Legenda */}
      <div style={{ display: 'flex', gap: 14, marginBottom: 16 }}>
        {['bassa','media','alta'].map(s => (
          <div key={s} style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 12 }}>
            <span style={{ width: 12, height: 12, borderRadius: 3, background: STAGIONE_COLORS[s], display: 'inline-block' }} />
            <span style={{ color: 'var(--ink-2)' }}>{STAGIONE_LABELS[s]}</span>
          </div>
        ))}
      </div>

      {/* Mesi */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(12, 1fr)', gap: 6, marginBottom: 20 }}>
        {MESI_IT.map((nome, m) => {
          const s = getStagioneForMonth(m);
          const col = s ? STAGIONE_COLORS[s] : '#aaa';
          return (
            <button key={m} type="button" onClick={() => cycleMonth(m)}
              title={s ? STAGIONE_LABELS[s] : '—'}
              style={{
                padding: '10px 4px', border: `2px solid ${col}`, borderRadius: 6,
                background: s ? col + '22' : '#f5f5f5',
                cursor: 'pointer', textAlign: 'center', transition: 'all .15s',
              }}
            >
              <div style={{ fontSize: 10, fontWeight: 700, color: col, textTransform: 'uppercase', letterSpacing: '.04em' }}>{nome}</div>
            </button>
          );
        })}
      </div>

      {/* Riepilogo */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 10, marginBottom: 18 }}>
        {['bassa','media','alta'].map(s => (
          <div key={s} style={{ padding: '10px 12px', background: STAGIONE_COLORS[s] + '18', borderRadius: 6, border: `1px solid ${STAGIONE_COLORS[s]}44` }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: STAGIONE_COLORS[s], textTransform: 'uppercase', letterSpacing: '.05em', marginBottom: 4 }}>{STAGIONE_LABELS[s]}</div>
            <div style={{ fontSize: 12, color: 'var(--ink)' }}>
              {draft[s].length === 0 ? '—' : draft[s].map(m => MESI_IT[m]).join(', ')}
            </div>
          </div>
        ))}
      </div>

      <button type="button" onClick={handleSave}
        style={{ padding: '8px 20px', background: saved ? '#27ae60' : 'var(--ink)', color: '#fff', border: 'none', borderRadius: 5, fontSize: 13, fontWeight: 600, cursor: 'pointer', transition: 'background .2s' }}>
        {saved ? '✓ Salvato' : 'Salva configurazione stagioni'}
      </button>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// Mappa il tipo EDOX (es. "mehari", "panda", "mxu") → tipo Pratica (auto/scooter/quad/ebike)
function normalizzaTipoEdox(idRentme, modello, cc) {
  const id  = (idRentme || '').toLowerCase().trim();
  const mod = (modello  || '').toLowerCase().trim();
  const raw = id.split(' ')[0] || '';

  // ── Quad / ATV — PRIMA degli scooter (Kymco fa sia quad MXU che scooter) ──
  if (['mxu','xwolf','quad','atv'].includes(raw)
    || id.includes('quad') || id.includes('mxu') || id.includes('xwolf')
    || mod.includes('quad')) return 'quad';

  // ── Scooter / Moto — brand noti ─────────────────────────────────────
  // NON usare CC come fallback: i quad possono avere motori da 50–700 cc
  // e verrebbero classificati erroneamente come scooter.
  const SCOOTER_BRANDS = [
    'scooter','moto','vespa','maxi',
    'piaggio','honda','yamaha','aprilia','kymco','sym','tgb',
    'peugeot','italjet','daelim','benelli','suzuki','kawasaki',
    'gilera','derbi','malaguti','bmw','scarabeo','atlantic',
  ];
  if (SCOOTER_BRANDS.includes(raw) || mod.includes('scooter') || mod.includes('moto')) return 'scooter';

  // ── Bici muscolari (senza motore): solo muscolare e piega ────────────
  if (['muscolare','piega'].includes(raw)
    || mod.includes('muscolare') || mod.includes('piega')) return 'bici';
  // ── E-bike / fat-bike / city-bike / bicicletta assistita ─────────────
  // fat = fat-bike elettrica → ebike; city = citybike assistita → ebike
  if (['ebike','fat','city','bici','bicicletta'].includes(raw)
    || mod.includes('ebike') || mod.includes('e-bike') || mod.includes('bicicletta')
    || mod.includes('fat') || mod.includes('city')) {
    return 'ebike';
  }

  // ── Auto (mehari, panda, citroen, fiat, smart, rav4, ecc.) ──────────
  return 'auto';
}

// FLEET CSV IMPORT — carica flotta da file CSV
// Formati supportati:
//   1. Formato EDOX/RentMe:  ID RENTME;Modello;Targa;Colore;;CC;
//   2. Formato generico:     targa, categoria, alias, anno, stato
// Il separatore viene rilevato automaticamente (virgola o punto-e-virgola).
// ═══════════════════════════════════════════════════════════════════
function FleetCSVImport({ fleet, onImport, onClose }) {
  const [step, setStep]       = useState('upload'); // upload | preview | done
  const [preview, setPreview] = useState([]);
  const [error, setError]     = useState(null);
  const [added, setAdded]     = useState(0);
  const [updated, setUpdated] = useState(0);
  const [formato, setFormato] = useState('');
  const [mode, setMode]       = useState('update'); // 'update' = aggiorna+aggiungi | 'replace' = sostituisci tutto
  const fileRef = useRef();

  const parseCSV = (text) => {
    const lines = text.trim().split(/\r?\n/).filter(l => l.trim());
    if (lines.length < 2) throw new Error('Il file deve avere almeno un\'intestazione e una riga dati');
    const sep   = lines[0].includes(';') ? ';' : ',';
    const heads = lines[0].split(sep).map(h => h.trim().toLowerCase().replace(/"/g,''));

    // ── Rileva formato EDOX: prima colonna contiene "id rentme" o "id" ──
    const isEdox = heads[0].includes('id rentme') || heads[0] === 'id' ||
                   (heads.includes('modello') && heads.includes('targa') && heads.includes('colore'));

    if (isEdox) {
      // Formato: ID RENTME;Modello;Targa;Colore;;CC;
      // NOTA: il CSV EDOX può avere un ; iniziale che crea una colonna vuota in pos. 0
      // → usiamo gli indici delle intestazioni invece di posizioni fisse
      const idCol  = heads.findIndex(h => h.includes('id rentme') || h === 'id');
      const modCol = heads.indexOf('modello');
      const tarCol = heads.indexOf('targa');
      const colCol = heads.indexOf('colore');
      const ccCol  = heads.findIndex(h => h.includes('cilindrata') || h === 'cc');
      // Fallback alle posizioni originali se le intestazioni non trovate
      const gc = (cells, idx, fb) => (cells[idx > -1 ? idx : fb] || '').trim();

      const rows = lines.slice(1).map(l => {
        const cells = l.split(sep).map(c => c.trim().replace(/"/g,''));
        return {
          idRentme: gc(cells, idCol, 0),
          modello:  gc(cells, modCol, 1),
          targa:    gc(cells, tarCol, 2).toUpperCase(),
          colore:   gc(cells, colCol, 3),
          cc:       gc(cells, ccCol, 5),
        };
      }).filter(r => (r.targa && r.targa !== 'TARGA') || r.idRentme);

      if (!rows.length) throw new Error('Nessuna riga valida trovata (colonna "Targa" obbligatoria)');

      setFormato('EDOX');
      return rows.map(r => {
        const tipo = normalizzaTipoEdox(r.idRentme, r.modello, r.cc);
        // Veicoli senza targa (bici/ebike) usano idRentme come id univoco
        const id = r.targa || r.idRentme.replace(/\s+/g, '_');
        return {
          id,
          targa:     r.targa || '',                  // vuota per bici senza targa/targa
          idRentme:  r.idRentme,                     // es. "standard 1", "superior 33", "liberty 170"
          tipo,
          modello:   r.modello,
          colore:    r.colore,
          marca:     '',
          cc:        r.cc,
          stato:     'available',
          anno:      null,
        };
      });
    }

    // ── Formato generico ──────────────────────────────────────────────
    const rows = lines.slice(1).map(l => {
      const cells = l.split(sep).map(c => c.trim().replace(/"/g,''));
      const obj = {};
      heads.forEach((h,i) => { obj[h] = cells[i] || ''; });
      return obj;
    }).filter(r => r.targa || r['targa/id']);
    if (!rows.length) throw new Error('Nessuna riga valida trovata (colonna "targa" obbligatoria)');
    setFormato('Generico');
    return rows.map(r => ({
      id:        (r.targa || r['targa/id'] || '').toUpperCase() || ('VEH_' + Math.random().toString(36).slice(2,7).toUpperCase()),
      targa:     (r.targa || r['targa/id'] || '').toUpperCase(),
      tipo:      r.categoria || r.category || r.tipo || '',
      modello:   r.alias || r.modello || r.nome || '',
      marca:     '',
      colore:    r.colore || '',
      stato:     r.stato || r.status || 'available',
      anno:      parseInt(r.anno || r.year || '0') || null,
    }));
  };

  const handleFile = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setError(null);
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const rows = parseCSV(ev.target.result);
        setPreview(rows);
        setStep('preview');
      } catch(err) {
        setError(err.message);
      }
    };
    reader.readAsText(file, 'UTF-8');
  };

  const handleImport = () => {
    if (mode === 'replace') {
      // Sostituisce tutta la flotta con i dati del CSV
      onImport(preview);
      setAdded(preview.length);
      setUpdated(0);
      setStep('done');
      return;
    }
    // ── Modalità "Aggiorna + aggiungi" ──────────────────────────────────
    // Aggiorna i campi tecnici (tipo, modello, colore, cc, idRentme) dei mezzi
    // già in flotta abbinando per targa — NON tocca stato, scadenze, note.
    const previewMap = new Map(preview.map(r => [(r.targa || '').toUpperCase(), r]));
    let nUpdated = 0;
    const updatedFleet = (fleet || []).map(v => {
      const t = (v.targa || '').toUpperCase();
      if (!previewMap.has(t)) return v;
      nUpdated++;
      const fresh = previewMap.get(t);
      return {
        ...v,
        tipo:     fresh.tipo     || v.tipo,
        modello:  fresh.modello  || v.modello,
        idRentme: fresh.idRentme || v.idRentme,
        colore:   fresh.colore   || v.colore,
        cc:       fresh.cc       || v.cc,
      };
    });
    const existingTargas = new Set((fleet || []).map(v => (v.targa || '').toUpperCase()));
    const toAdd = preview.filter(r => !existingTargas.has((r.targa || '').toUpperCase()));
    onImport([...updatedFleet, ...toAdd]);
    setAdded(toAdd.length);
    setUpdated(nUpdated);
    setStep('done');
  };

  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.45)', zIndex: 600, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div className="modal-box" style={{ background: 'var(--bg)', borderRadius: 10, padding: '28px 32px', width: 560, maxWidth: '95vw', maxHeight: '80vh', overflow: 'auto', boxShadow: '0 20px 60px rgba(0,0,0,.25)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
          <div>
            <h2 style={{ margin: 0, fontSize: 18, fontFamily: 'var(--font-serif)', fontWeight: 600 }}>Import flotta CSV</h2>
            <p style={{ margin: '4px 0 0', fontSize: 12, color: 'var(--muted)' }}>Carica un file .csv con le colonne: targa, categoria, alias, anno, stato</p>
          </div>
          <button type="button" onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--muted)', fontSize: 20, lineHeight: 1 }}>×</button>
        </div>

        {step === 'upload' && (
          <div>
            {error && (
              <div style={{ background: '#fdecea', border: '1px solid #c0392b', borderRadius: 5, padding: '10px 14px', marginBottom: 14, fontSize: 13, color: '#c0392b' }}>
                ❌ {error}
              </div>
            )}
            <div
              onClick={() => fileRef.current?.click()}
              style={{ border: '2px dashed var(--border)', borderRadius: 8, padding: '40px 20px', textAlign: 'center', cursor: 'pointer', background: 'var(--surface-2)', transition: 'border-color .2s' }}
              onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--ink-2)'}
              onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
            >
              <Upload style={{ width: 32, height: 32, color: 'var(--muted)', margin: '0 auto 12px', display: 'block' }} />
              <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--ink)', marginBottom: 4 }}>Clicca per scegliere il file</div>
              <div style={{ fontSize: 12, color: 'var(--muted)' }}>CSV con separatore virgola o punto-e-virgola · UTF-8</div>
              <input ref={fileRef} type="file" accept=".csv,.txt" onChange={handleFile} style={{ display: 'none' }} />
            </div>
            <div style={{ marginTop: 14, fontSize: 12, color: 'var(--muted)' }}>
              <strong>Formati supportati:</strong><br/>
              <code style={{ display: 'block', background: 'var(--surface-2)', padding: '8px 10px', borderRadius: 4, marginTop: 6, fontFamily: 'monospace', fontSize: 11 }}>
                <span style={{ color: 'var(--accent)', fontWeight: 700 }}>Formato EDOX (automatico):</span><br/>
                ID RENTME;Modello;Targa;Colore<br/>
                mehari 130;MEHARI;SV256194;ARANCIONE<br/>
                panda 81;PANDA;CY937XX;GRIGIA MET<br/>
                <br/>
                <span style={{ color: 'var(--ink-2)', fontWeight: 700 }}>Formato generico:</span><br/>
                targa,tipo,modello,colore,stato<br/>
                AG001AA,scooter,Piaggio Liberty,rosso,available
              </code>
            </div>
          </div>
        )}

        {step === 'preview' && (
          <div>
            <div style={{ marginBottom: 10, fontSize: 13, color: 'var(--ink-2)' }}>
              <strong>{preview.length}</strong> mezzi trovati
              {formato && <span style={{ marginLeft: 8, fontSize: 11, background: formato === 'EDOX' ? '#e8f4e8' : 'var(--surface-2)', color: formato === 'EDOX' ? '#2e6e3e' : 'var(--muted)', padding: '2px 8px', borderRadius: 10, fontWeight: 600 }}>Formato {formato}</span>}
            </div>
            {/* Modalità import */}
            <div style={{ display: 'flex', gap: 8, marginBottom: 14 }}>
              {[
                { id: 'update',  label: '🔄 Aggiorna + aggiungi', desc: 'Aggiorna tipo/modello dei mezzi esistenti, aggiunge i nuovi' },
                { id: 'replace', label: '⚠️ Sostituisci tutto',   desc: 'Sostituisce l\'intera flotta con il contenuto del CSV' },
              ].map(m => (
                <button key={m.id} type="button" onClick={() => setMode(m.id)}
                  title={m.desc}
                  style={{ flex: 1, padding: '8px 10px', borderRadius: 6, border: `2px solid ${mode === m.id ? 'var(--accent)' : 'var(--border)'}`,
                    background: mode === m.id ? 'var(--accent-soft)' : 'var(--bg)', cursor: 'pointer',
                    fontSize: 12, fontWeight: mode === m.id ? 700 : 400, color: 'var(--ink)', textAlign: 'center' }}>
                  {m.label}
                </button>
              ))}
            </div>
            <div style={{ maxHeight: 280, overflow: 'auto', border: '1px solid var(--border)', borderRadius: 6 }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ background: 'var(--surface-2)' }}>
                    {formato === 'EDOX'
                      ? ['ID RENTME','Modello','Targa','Colore'].map(h => (
                          <th key={h} style={{ padding: '6px 10px', textAlign: 'left', fontWeight: 600, fontSize: 10, textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--ink-2)', borderBottom: '1px solid var(--border)' }}>{h}</th>
                        ))
                      : ['Targa','Tipo','Modello','Colore','Stato'].map(h => (
                          <th key={h} style={{ padding: '6px 10px', textAlign: 'left', fontWeight: 600, fontSize: 10, textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--ink-2)', borderBottom: '1px solid var(--border)' }}>{h}</th>
                        ))
                    }
                  </tr>
                </thead>
                <tbody>
                  {preview.map((r, i) => (
                    <tr key={i} style={{ background: i % 2 === 0 ? 'var(--bg)' : 'var(--surface-2)' }}>
                      {formato === 'EDOX' ? <>
                        <td style={{ padding: '5px 10px', color: 'var(--muted)', borderBottom: '1px solid var(--border)', fontSize: 11 }}>{r.idRentme}</td>
                        <td style={{ padding: '5px 10px', borderBottom: '1px solid var(--border)' }}>{r.modello}</td>
                        <td style={{ padding: '5px 10px', fontWeight: 600, borderBottom: '1px solid var(--border)' }}>{r.targa}</td>
                        <td style={{ padding: '5px 10px', color: 'var(--muted)', borderBottom: '1px solid var(--border)' }}>{r.colore}</td>
                      </> : <>
                        <td style={{ padding: '5px 10px', fontWeight: 600, borderBottom: '1px solid var(--border)' }}>{r.targa}</td>
                        <td style={{ padding: '5px 10px', borderBottom: '1px solid var(--border)' }}>{r.tipo}</td>
                        <td style={{ padding: '5px 10px', borderBottom: '1px solid var(--border)' }}>{r.modello}</td>
                        <td style={{ padding: '5px 10px', color: 'var(--muted)', borderBottom: '1px solid var(--border)' }}>{r.colore}</td>
                        <td style={{ padding: '5px 10px', borderBottom: '1px solid var(--border)' }}>
                          <span style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', color: '#27ae60' }}>{r.stato}</span>
                        </td>
                      </>}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div style={{ display: 'flex', gap: 10, marginTop: 18 }}>
              <button type="button" onClick={handleImport}
                style={{ flex: 1, padding: '10px', background: mode === 'replace' ? '#c0392b' : 'var(--ink)', color: '#fff', border: 'none', borderRadius: 5, fontSize: 14, fontWeight: 600, cursor: 'pointer' }}>
                {mode === 'replace' ? `⚠️ Sostituisci flotta (${preview.length} mezzi)` : `✓ Conferma import (${preview.length} mezzi)`}
              </button>
              <button type="button" onClick={() => { setStep('upload'); setPreview([]); }}
                style={{ padding: '10px 20px', background: 'var(--surface-2)', color: 'var(--ink)', border: '1px solid var(--border)', borderRadius: 5, fontSize: 14, cursor: 'pointer' }}>
                Indietro
              </button>
            </div>
          </div>
        )}

        {step === 'done' && (
          <div style={{ textAlign: 'center', padding: '20px 0' }}>
            <div style={{ fontSize: 48, marginBottom: 14 }}>✅</div>
            <div style={{ fontSize: 16, fontWeight: 600, marginBottom: 6 }}>Import completato</div>
            <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 24 }}>
              {mode === 'replace'
                ? `Flotta sostituita con ${added} mezzi dal CSV.`
                : `${updated > 0 ? `${updated} aggiornati` : ''}${updated > 0 && added > 0 ? ' · ' : ''}${added > 0 ? `${added} nuovi aggiunti` : ''}${updated === 0 && added === 0 ? 'Nessuna modifica (flotta già aggiornata).' : '.'}`}
            </div>
            <button type="button" onClick={onClose}
              style={{ padding: '10px 28px', background: 'var(--ink)', color: '#fff', border: 'none', borderRadius: 5, fontSize: 14, fontWeight: 600, cursor: 'pointer' }}>
              Chiudi
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// REGISTRO CASSA
// Traccia ogni incasso: acconto, saldo, rimborso.
// Persistente su edo:v1:cassa — sincronizzato su tutti i dispositivi.
// ═══════════════════════════════════════════════════════════════════
const CASSA_METODI = {
  contanti: { label: 'Contanti',  icon: '💵', color: '#27ae60' },
  carta:    { label: 'Carta',     icon: '💳', color: '#1f5d83' },
  bonifico: { label: 'Bonifico',  icon: '🏦', color: '#7d3c98' },
  paypal:   { label: 'PayPal',    icon: '🅿',  color: '#0070ba' },
  altro:    { label: 'Altro',     icon: '•',  color: '#7a7068' },
};
const CASSA_TIPI = {
  acconto:  { label: 'Acconto',   pill: 'pill-warn' },
  saldo:    { label: 'Saldo',     pill: 'pill-ok'   },
  rimborso: { label: 'Rimborso',  pill: 'pill-err'  },
  deposito: { label: 'Caparra',   pill: 'pill-sea'  },
  extra:    { label: 'Extra',     pill: 'pill-neutral' },
};

function CassaFormModal({ onSave, onClose, prenotazioni, customers, operator }) {
  const today = todayISO();
  const [form, setForm] = useState({
    data: today, clienteNome: '', prenotazioneId: '',
    importo: '', metodo: 'contanti', tipo: 'saldo', nota: '',
  });
  const [errors, setErrors] = useState({});

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  // Auto-compila cliente da prenotazione selezionata
  const handlePrenoChange = (id) => {
    set('prenotazioneId', id);
    const p = (prenotazioni||[]).find(x => x.id === id);
    if (p) set('clienteNome', [p.clienteCognome, p.clienteNome].filter(Boolean).join(' '));
  };

  const validate = () => {
    const e = {};
    if (!form.importo || isNaN(parseFloat(form.importo))) e.importo = 'Importo non valido';
    if (!form.clienteNome.trim()) e.clienteNome = 'Cliente obbligatorio';
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSubmit = () => {
    if (!validate()) return;
    const p = (prenotazioni||[]).find(x => x.id === form.prenotazioneId);
    onSave({
      id: 'cassa_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
      createdAt: new Date().toISOString(),
      data: form.data,
      clienteNome: form.clienteNome.trim(),
      prenotazioneId: form.prenotazioneId || null,
      vehicleLabel: p?.vehicleLabel || '',
      importo: parseFloat(form.importo),
      metodo: form.metodo,
      tipo: form.tipo,
      nota: form.nota.trim(),
      operatorId: operator?.id || '',
      operatorName: operator?.nome || '',
    });
  };

  const inputStyle = { width: '100%', padding: '8px 10px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 14, background: 'var(--bg)', color: 'var(--ink)', fontFamily: 'var(--font-sans)', boxSizing: 'border-box' };
  const labelStyle = { fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--ink-2)', display: 'block', marginBottom: 4 };
  const fieldStyle = { marginBottom: 14 };

  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.45)', zIndex: 700, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div className="modal-box" style={{ background: 'var(--bg)', borderRadius: 10, padding: '28px 32px', width: 480, maxWidth: '95vw', boxShadow: '0 20px 60px rgba(0,0,0,.25)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <h2 style={{ margin: 0, fontSize: 18, fontFamily: 'var(--font-serif)', fontWeight: 600 }}>Nuovo incasso</h2>
          <button type="button" onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--muted)', fontSize: 20 }}>×</button>
        </div>

        <div style={fieldStyle}>
          <label style={labelStyle}>Data</label>
          <input type="date" value={form.data} onChange={e => set('data', e.target.value)} style={inputStyle} />
        </div>

        <div style={fieldStyle}>
          <label style={labelStyle}>Collega prenotazione <span style={{ fontWeight: 400, textTransform: 'none' }}>(opzionale)</span></label>
          <select value={form.prenotazioneId} onChange={e => handlePrenoChange(e.target.value)} style={inputStyle}>
            <option value="">— senza prenotazione —</option>
            {(prenotazioni||[]).filter(p => p.stato !== 'cancellata' && p.fonte !== 'rentme').map(p => (
              <option key={p.id} value={p.id}>
                {[p.clienteCognome, p.clienteNome].filter(Boolean).join(' ')} · {p.vehicleLabel} · {p.dal}
              </option>
            ))}
          </select>
        </div>

        <div style={fieldStyle}>
          <label style={labelStyle}>Cliente *</label>
          <input type="text" value={form.clienteNome} onChange={e => set('clienteNome', e.target.value)}
            placeholder="Cognome Nome" style={{ ...inputStyle, borderColor: errors.clienteNome ? '#c0392b' : 'var(--border)' }} />
          {errors.clienteNome && <div style={{ fontSize: 11, color: '#c0392b', marginTop: 3 }}>{errors.clienteNome}</div>}
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 14 }}>
          <div>
            <label style={labelStyle}>Importo € *</label>
            <input type="number" min="0" step="0.01" value={form.importo} onChange={e => set('importo', e.target.value)}
              placeholder="0.00" style={{ ...inputStyle, borderColor: errors.importo ? '#c0392b' : 'var(--border)' }} />
            {errors.importo && <div style={{ fontSize: 11, color: '#c0392b', marginTop: 3 }}>{errors.importo}</div>}
          </div>
          <div>
            <label style={labelStyle}>Tipo</label>
            <select value={form.tipo} onChange={e => set('tipo', e.target.value)} style={inputStyle}>
              {Object.entries(CASSA_TIPI).map(([k,v]) => <option key={k} value={k}>{v.label}</option>)}
            </select>
          </div>
        </div>

        <div style={fieldStyle}>
          <label style={labelStyle}>Metodo di pagamento</label>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            {Object.entries(CASSA_METODI).map(([k,v]) => (
              <button key={k} type="button" onClick={() => set('metodo', k)}
                style={{
                  padding: '6px 12px', borderRadius: 5, fontSize: 12, fontWeight: 600, cursor: 'pointer',
                  border: `2px solid ${form.metodo === k ? v.color : 'var(--border)'}`,
                  background: form.metodo === k ? v.color + '18' : 'var(--bg)',
                  color: form.metodo === k ? v.color : 'var(--ink-2)',
                }}>
                {v.icon} {v.label}
              </button>
            ))}
          </div>
        </div>

        <div style={fieldStyle}>
          <label style={labelStyle}>Nota interna <span style={{ fontWeight: 400, textTransform: 'none' }}>(opzionale)</span></label>
          <input type="text" value={form.nota} onChange={e => set('nota', e.target.value)} placeholder="Es. saldo finale, caparra rimborsata…" style={inputStyle} />
        </div>

        <div style={{ display: 'flex', gap: 10, marginTop: 8 }}>
          <button type="button" onClick={handleSubmit}
            style={{ flex: 1, padding: '10px', background: 'var(--ink)', color: '#fff', border: 'none', borderRadius: 5, fontSize: 14, fontWeight: 600, cursor: 'pointer' }}>
            Registra incasso
          </button>
          <button type="button" onClick={onClose}
            style={{ padding: '10px 20px', background: 'var(--surface-2)', color: 'var(--ink)', border: '1px solid var(--border)', borderRadius: 5, fontSize: 14, cursor: 'pointer' }}>
            Annulla
          </button>
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────
// CHIUSURA GIORNALIERA — riepilogo cassa per data con stampa
// ─────────────────────────────────────────────────────────────────────
function ChiusuraGiornalieraModal({ cassa, initialDate, onClose }) {
  const [selectedDate, setSelectedDate] = useState(initialDate || todayISO());

  const dayEntries = useMemo(() => (cassa || []).filter(r => r.data === selectedDate), [cassa, selectedDate]);

  const perTipo = useMemo(() => {
    const res = {};
    Object.keys(CASSA_TIPI).forEach(k => { res[k] = dayEntries.filter(r => r.tipo === k).reduce((s,r) => s + (Number(r.importo)||0), 0); });
    return res;
  }, [dayEntries]);

  const perMetodo = useMemo(() => {
    const res = {};
    Object.keys(CASSA_METODI).forEach(k => { res[k] = dayEntries.filter(r => r.metodo === k && r.tipo !== 'rimborso').reduce((s,r) => s + (Number(r.importo)||0), 0); });
    return res;
  }, [dayEntries]);

  const totaleIncassato = dayEntries.filter(r => r.tipo !== 'rimborso').reduce((s,r) => s + (Number(r.importo)||0), 0);
  const totaleRimborsi  = dayEntries.filter(r => r.tipo === 'rimborso').reduce((s,r) => s + (Number(r.importo)||0), 0);
  const netto    = totaleIncassato - totaleRimborsi;
  const mov      = dayEntries.length;

  const fmtEur = v => `€${v.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`;
  const fmtDate = d => { const [y,m,dd] = d.split('-'); return `${dd}/${m}/${y}`; };

  return (
    <div className="edo-chiusura-modal" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.55)', zIndex: 1000, display: 'flex', alignItems: 'flex-start', justifyContent: 'center', padding: '40px 20px', overflowY: 'auto' }}>
      <div className="modal-box" style={{ background: 'var(--bg)', borderRadius: 10, width: '100%', maxWidth: 520, padding: '28px 30px', boxShadow: '0 8px 40px rgba(0,0,0,.22)' }}>

        {/* Intestazione */}
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 18 }}>
          <div>
            <h2 style={{ margin: 0, fontSize: 17, fontFamily: 'var(--font-serif)', fontWeight: 700 }}>🖨 Chiusura giornaliera</h2>
            <p style={{ margin: '3px 0 0', fontSize: 12, color: 'var(--muted)' }}>Riepilogo incassi per chiusura cassa</p>
          </div>
          <button type="button" onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: 16, color: 'var(--muted)', lineHeight: 1, padding: 4 }}>✕</button>
        </div>

        {/* Selettore data */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 18 }}>
          <label style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em', color: 'var(--ink-2)' }}>Data</label>
          <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)}
            style={{ padding: '6px 10px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 13, background: 'var(--bg)', color: 'var(--ink)', fontFamily: 'monospace' }} />
        </div>

        {/* Contenuto stampabile */}
        <div id="chiusura-print-area">

          {/* Solo per stampa */}
          <div className="chiusura-print-header" style={{ display: 'none', textAlign: 'center', marginBottom: 14 }}>
            <div style={{ fontSize: 15, fontWeight: 700, letterSpacing: '.04em' }}>EDONOLEGGIO · LAMPEDUSA</div>
            <div style={{ fontSize: 12, color: '#555', marginTop: 2 }}>Chiusura cassa del {fmtDate(selectedDate)}</div>
            <hr style={{ margin: '8px 0', borderColor: '#ccc' }} />
          </div>

          {/* Riepilogo top */}
          <div style={{ background: 'var(--surface-2)', borderRadius: 8, padding: '12px 16px', marginBottom: 16, borderLeft: '3px solid var(--ink)' }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.07em', color: 'var(--muted)', marginBottom: 4 }}>
              Riepilogo · {fmtDate(selectedDate)}
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
              <span style={{ fontSize: 24, fontWeight: 700, fontFamily: 'var(--font-serif)', color: netto >= 0 ? '#27ae60' : '#c0392b' }}>{fmtEur(netto)}</span>
              <span style={{ fontSize: 12, color: 'var(--muted)' }}>{mov} movimento{mov !== 1 ? 'i' : ''}</span>
            </div>
          </div>

          {/* Per tipo */}
          <div style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em', color: 'var(--muted)', marginBottom: 7 }}>Per tipo</div>
            <div style={{ border: '1px solid var(--border)', borderRadius: 7, overflow: 'hidden' }}>
              {Object.entries(CASSA_TIPI).map(([k, v], i, arr) => {
                const val = perTipo[k] || 0;
                const isRimborso = k === 'rimborso';
                return (
                  <div key={k} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '8px 14px', background: i % 2 === 0 ? 'var(--bg)' : 'var(--surface-2)', borderBottom: i < arr.length-1 ? '1px solid var(--border)' : 'none' }}>
                    <span className={v.pill} style={{ fontSize: 10, padding: '2px 7px', borderRadius: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.04em' }}>{v.label}</span>
                    <span style={{ fontFamily: 'monospace', fontWeight: 700, fontSize: 14, color: isRimborso ? '#c0392b' : (val > 0 ? '#27ae60' : 'var(--muted)') }}>
                      {isRimborso ? '−' : '+'}{fmtEur(val)}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Per metodo */}
          <div style={{ marginBottom: 16 }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em', color: 'var(--muted)', marginBottom: 7 }}>Per metodo di pagamento</div>
            <div style={{ border: '1px solid var(--border)', borderRadius: 7, overflow: 'hidden' }}>
              {Object.entries(CASSA_METODI).map(([k, m], i, arr) => {
                const val = perMetodo[k] || 0;
                return (
                  <div key={k} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '8px 14px', background: i % 2 === 0 ? 'var(--bg)' : 'var(--surface-2)', borderBottom: i < arr.length-1 ? '1px solid var(--border)' : 'none' }}>
                    <span style={{ fontSize: 13, fontWeight: 600, color: m.color }}>{m.icon} {m.label}</span>
                    <span style={{ fontFamily: 'monospace', fontWeight: 700, fontSize: 14, color: val > 0 ? m.color : 'var(--muted)' }}>{fmtEur(val)}</span>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Netto finale */}
          <div style={{ background: netto >= 0 ? '#27ae6014' : '#c0392b14', border: `1px solid ${netto >= 0 ? '#27ae6044' : '#c0392b44'}`, borderRadius: 7, padding: '11px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: 12, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--ink)' }}>Totale netto</span>
            <span style={{ fontFamily: 'monospace', fontSize: 18, fontWeight: 700, color: netto >= 0 ? '#27ae60' : '#c0392b' }}>{fmtEur(netto)}</span>
          </div>

          {/* Footer stampa */}
          <div className="chiusura-print-footer" style={{ display: 'none', marginTop: 20, textAlign: 'center', fontSize: 10, color: '#999', borderTop: '1px solid #ddd', paddingTop: 8 }}>
            Stampato il {new Date().toLocaleDateString('it-IT')} · {new Date().toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' })}
          </div>
        </div>

        {/* Azioni */}
        <div style={{ display: 'flex', gap: 10, marginTop: 20, justifyContent: 'flex-end' }}>
          <button type="button" onClick={onClose}
            style={{ padding: '9px 18px', background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 5, fontSize: 13, cursor: 'pointer', color: 'var(--ink-2)' }}>
            Chiudi
          </button>
          <button type="button" onClick={() => window.print()}
            style={{ padding: '9px 18px', background: 'var(--ink)', color: '#fff', border: 'none', borderRadius: 5, fontSize: 13, fontWeight: 700, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6 }}>
            🖨 Stampa
          </button>
        </div>
      </div>

      {/* Print styles */}
      <style>{`
        @media print {
          body > * { display: none !important; }
          .edo-chiusura-modal {
            position: static !important; background: none !important;
            padding: 0 !important; display: block !important; overflow: visible !important;
          }
          .edo-chiusura-modal > div {
            box-shadow: none !important; border: none !important;
            max-width: 100% !important; width: 100% !important; padding: 10px !important;
          }
          .chiusura-print-header { display: block !important; }
          .chiusura-print-footer { display: block !important; }
          button, input[type="date"], label { display: none !important; }
          [style*="display: flex"][style*="gap: 10"][style*="marginTop: 20"] { display: none !important; }
          div[style*="justifyContent: flex-end"] { display: none !important; }
        }
      `}</style>
    </div>
  );
}

function RegistroCassaPage({ cassa, setCassa, prenotazioni, customers, operator, pushToast }) {
  const [periodo, setPeriodo] = useState('oggi');
  const [metodoFilter, setMetodoFilter] = useState('tutti');
  const [showForm, setShowForm] = useState(false);
  const [showChiusura, setShowChiusura] = useState(false);

  const today = todayISO();

  const getRange = () => {
    const d = new Date();
    if (periodo === 'oggi')      return [today, today];
    if (periodo === 'settimana') {
      const lun = new Date(d); lun.setDate(d.getDate() - ((d.getDay()+6)%7));
      // Usa ora locale (non UTC) per evitare offset notturno
      const lunISO = `${lun.getFullYear()}-${String(lun.getMonth()+1).padStart(2,'0')}-${String(lun.getDate()).padStart(2,'0')}`;
      return [lunISO, today];
    }
    if (periodo === 'mese') return [`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`, today];
    return [null, null];
  };
  const [dal, al] = getRange();

  const filtered = useMemo(() => {
    return (cassa || []).filter(r => {
      if (dal && r.data < dal) return false;
      if (al  && r.data > al)  return false;
      if (metodoFilter !== 'tutti' && r.metodo !== metodoFilter) return false;
      return true;
    }).sort((a,b) => (b.data||'').localeCompare(a.data||'') || (b.createdAt||'').localeCompare(a.createdAt||''));
  }, [cassa, dal, al, metodoFilter]);

  // Totali
  const totale     = filtered.filter(r => r.tipo !== 'rimborso').reduce((s,r) => s + (Number(r.importo)||0), 0);
  const rimborsi   = filtered.filter(r => r.tipo === 'rimborso').reduce((s,r) => s + (Number(r.importo)||0), 0);
  const netto      = totale - rimborsi;
  const perMetodo  = Object.fromEntries(Object.keys(CASSA_METODI).map(k => [k, filtered.filter(r => r.metodo === k && r.tipo !== 'rimborso').reduce((s,r)=>s+(Number(r.importo)||0),0)]));

  const handleSave = (record) => {
    setCassa(prev => [record, ...(prev||[])]);
    setShowForm(false);
    pushToast({ tone: 'success', title: 'Incasso registrato', message: `€${(Number(record.importo)||0).toFixed(2)} · ${CASSA_METODI[record.metodo]?.label}` });
  };

  const handleDelete = (id) => {
    setCassa(prev => (prev||[]).filter(r => r.id !== id));
    pushToast({ tone: 'warning', title: 'Incasso rimosso', message: 'Record eliminato dal registro' });
  };

  const exportCSV = () => {
    const header = 'Data,Cliente,Mezzo,Tipo,Metodo,Importo,Nota,Operatore';
    const rows = filtered.map(r =>
      [r.data, r.clienteNome, r.vehicleLabel||'', CASSA_TIPI[r.tipo]?.label||r.tipo, CASSA_METODI[r.metodo]?.label||r.metodo, (Number(r.importo)||0).toFixed(2), r.nota||'', r.operatorName||''].map(x => `"${String(x).replace(/"/g,'""')}"`).join(',')
    );
    const blob = new Blob([[header, ...rows].join('\n')], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = `cassa_${today}.csv`; a.click();
    URL.revokeObjectURL(url);
  };

  const periodoLabel = { oggi: 'Oggi', settimana: 'Questa settimana', mese: 'Questo mese', tutto: 'Tutto' };

  return (
    <div style={{ padding: '28px 32px', maxWidth: 1000, margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 24 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 22, fontFamily: 'var(--font-serif)', fontWeight: 600 }}>Registro cassa</h1>
          <p style={{ margin: '4px 0 0', fontSize: 13, color: 'var(--muted)' }}>
            Tracciamento incassi · acconti · saldi · rimborsi
          </p>
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <button type="button" onClick={() => setShowChiusura(true)}
            style={{ padding: '8px 14px', background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 5, fontSize: 12, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6, color: 'var(--ink-2)' }}>
            🖨 Chiusura
          </button>
          <button type="button" onClick={exportCSV}
            style={{ padding: '8px 14px', background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 5, fontSize: 12, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6, color: 'var(--ink-2)' }}>
            <Download className="w-4 h-4" /> CSV
          </button>
          <button type="button" onClick={() => setShowForm(true)}
            style={{ padding: '8px 18px', background: 'var(--ink)', color: '#fff', border: 'none', borderRadius: 5, fontSize: 13, fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6 }}>
            <Plus className="w-4 h-4" /> Incasso
          </button>
        </div>
      </div>

      {/* Filtri periodo */}
      <div style={{ display: 'flex', gap: 6, marginBottom: 20, flexWrap: 'wrap', alignItems: 'center' }}>
        {['oggi','settimana','mese','tutto'].map(p => (
          <button key={p} type="button" onClick={() => setPeriodo(p)}
            style={{ padding: '6px 14px', borderRadius: 5, fontSize: 12, fontWeight: 600, cursor: 'pointer', border: '1px solid var(--border)', background: periodo === p ? 'var(--ink)' : 'var(--bg)', color: periodo === p ? '#fff' : 'var(--ink-2)' }}>
            {periodoLabel[p]}
          </button>
        ))}
        <div style={{ width: 1, height: 20, background: 'var(--border)', margin: '0 4px' }} />
        {['tutti', ...Object.keys(CASSA_METODI)].map(m => (
          <button key={m} type="button" onClick={() => setMetodoFilter(m)}
            style={{ padding: '5px 12px', borderRadius: 5, fontSize: 12, cursor: 'pointer', border: `1px solid ${metodoFilter === m ? 'var(--ink)' : 'var(--border)'}`, background: metodoFilter === m ? 'var(--ink)' : 'var(--bg)', color: metodoFilter === m ? '#fff' : 'var(--ink-2)' }}>
            {m === 'tutti' ? 'Tutti' : CASSA_METODI[m]?.icon + ' ' + CASSA_METODI[m]?.label}
          </button>
        ))}
      </div>

      {/* KPI cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12, marginBottom: 24 }}>
        {[
          { label: 'Incassato', value: `€${totale.toLocaleString('it-IT', {minimumFractionDigits:2})}`, sub: periodoLabel[periodo], color: '#27ae60' },
          { label: 'Rimborsi', value: `€${rimborsi.toLocaleString('it-IT', {minimumFractionDigits:2})}`, sub: 'da sottrarre', color: '#c0392b' },
          { label: 'Netto', value: `€${netto.toLocaleString('it-IT', {minimumFractionDigits:2})}`, sub: 'incasso - rimborsi', color: '#1f5d83' },
          { label: 'Movimenti', value: filtered.length, sub: `${periodoLabel[periodo].toLowerCase()}`, color: 'var(--ink)' },
        ].map(k => (
          <div key={k.label} style={{ background: 'var(--bg)', border: '1px solid var(--border)', borderRadius: 8, padding: '14px 16px' }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em', color: 'var(--muted)', marginBottom: 4 }}>{k.label}</div>
            <div style={{ fontSize: 22, fontWeight: 700, fontFamily: 'var(--font-serif)', color: k.color }}>{k.value}</div>
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 2 }}>{k.sub}</div>
          </div>
        ))}
      </div>

      {/* Breakdown per metodo */}
      {filtered.length > 0 && (
        <div style={{ display: 'flex', gap: 10, marginBottom: 20, flexWrap: 'wrap' }}>
          {Object.entries(perMetodo).filter(([,v]) => v > 0).map(([k,v]) => {
            const m = CASSA_METODI[k];
            return (
              <div key={k} style={{ padding: '8px 14px', background: m.color+'14', border: `1px solid ${m.color}44`, borderRadius: 6, fontSize: 13 }}>
                <span style={{ color: m.color, fontWeight: 700, marginRight: 6 }}>{m.icon} {m.label}</span>
                <span style={{ fontFamily: 'monospace', fontWeight: 600 }}>€{v.toLocaleString('it-IT', {minimumFractionDigits:2})}</span>
              </div>
            );
          })}
        </div>
      )}

      {/* Lista movimenti */}
      {filtered.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '60px 20px', color: 'var(--muted)' }}>
          <Wallet style={{ width: 36, height: 36, margin: '0 auto 12px', opacity: .4 }} />
          <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--ink-2)', marginBottom: 4 }}>
            Nessun movimento
          </div>
          <div style={{ fontSize: 13 }}>Registra il primo incasso con il bottone qui sopra.</div>
        </div>
      ) : (
        <div style={{ border: '1px solid var(--border)', borderRadius: 8, overflow: 'hidden' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
            <thead>
              <tr style={{ background: 'var(--surface-2)' }}>
                {['Data','Cliente','Mezzo','Tipo','Metodo','Importo','Nota',''].map(h => (
                  <th key={h} style={{ padding: '8px 12px', textAlign: 'left', fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--ink-2)', borderBottom: '1px solid var(--border)', whiteSpace: 'nowrap' }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((r, i) => {
                const metodo = CASSA_METODI[r.metodo];
                const tipo   = CASSA_TIPI[r.tipo];
                return (
                  <tr key={r.id} style={{ background: i%2===0 ? 'var(--bg)' : 'var(--surface-2)' }}>
                    <td style={{ padding: '8px 12px', fontFamily: 'monospace', fontSize: 12, borderBottom: '1px solid var(--border)', whiteSpace: 'nowrap', color: 'var(--ink-2)' }}>{r.data}</td>
                    <td style={{ padding: '8px 12px', fontWeight: 600, borderBottom: '1px solid var(--border)' }}>{r.clienteNome}</td>
                    <td style={{ padding: '8px 12px', color: 'var(--muted)', fontSize: 12, borderBottom: '1px solid var(--border)' }}>{r.vehicleLabel||'—'}</td>
                    <td style={{ padding: '8px 12px', borderBottom: '1px solid var(--border)' }}>
                      <span className={tipo?.pill||'pill-neutral'} style={{ fontSize: 10, padding: '2px 7px', borderRadius: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.04em' }}>{tipo?.label||r.tipo}</span>
                    </td>
                    <td style={{ padding: '8px 12px', borderBottom: '1px solid var(--border)', whiteSpace: 'nowrap' }}>
                      <span style={{ color: metodo?.color, fontWeight: 600, fontSize: 12 }}>{metodo?.icon} {metodo?.label}</span>
                    </td>
                    <td style={{ padding: '8px 12px', fontFamily: 'monospace', fontWeight: 700, textAlign: 'right', borderBottom: '1px solid var(--border)', whiteSpace: 'nowrap', color: r.tipo==='rimborso' ? '#c0392b' : '#27ae60' }}>
                      {r.tipo==='rimborso' ? '-' : '+'}€{(Number(r.importo)||0).toFixed(2)}
                    </td>
                    <td style={{ padding: '8px 12px', color: 'var(--muted)', fontSize: 11, borderBottom: '1px solid var(--border)' }}>{r.nota||'—'}</td>
                    <td style={{ padding: '8px 12px', borderBottom: '1px solid var(--border)' }}>
                      <button type="button" onClick={() => handleDelete(r.id)}
                        style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--muted)', padding: 4 }}
                        title="Elimina movimento">
                        <Trash2 style={{ width: 13, height: 13 }} />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {showForm && (
        <CassaFormModal
          onSave={handleSave}
          onClose={() => setShowForm(false)}
          prenotazioni={prenotazioni}
          customers={customers}
          operator={operator}
        />
      )}

      {showChiusura && (
        <ChiusuraGiornalieraModal
          cassa={cassa}
          initialDate={today}
          onClose={() => setShowChiusura(false)}
        />
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// STORICO CLIENTE — pannello espandibile nella lista clienti
// Mostra: visite, spesa totale, ultima visita, categorie preferite,
// lista prenotazioni collegate.
// ═══════════════════════════════════════════════════════════════════
function ClienteStoricoPanel({ cliente, prenotazioni, contracts, onClose }) {
  const preno = useMemo(() => {
    return (prenotazioni||[]).filter(p => {
      if (p.fonte === 'rentme') return false;
      const nome = [p.clienteCognome, p.clienteNome].filter(Boolean).join(' ').toLowerCase();
      const cNome = [cliente.cognome, cliente.nome].filter(Boolean).join(' ').toLowerCase();
      return p.clienteId === cliente.id || nome === cNome;
    }).sort((a,b) => b.dal.localeCompare(a.dal));
  }, [prenotazioni, cliente]);

  const contr = useMemo(() => {
    return (contracts||[]).filter(c => c.record?.cognome?.toLowerCase() === (cliente.cognome||'').toLowerCase()).sort((a,b) => b.createdAt.localeCompare(a.createdAt));
  }, [contracts, cliente]);

  const spesaTotale  = preno.reduce((s,p) => s + safePrezzo(p), 0);
  const accontiTotali = preno.reduce((s,p) => s + (Number(p.acconto)||0), 0);
  const ultimaVisita = preno.length > 0 ? preno[0].dal : null;
  const catCount     = {};
  preno.forEach(p => { if (p.vehicleLabel) catCount[p.vehicleLabel] = (catCount[p.vehicleLabel]||0)+1; });
  const topCat       = Object.entries(catCount).sort((a,b)=>b[1]-a[1]).slice(0,3);

  const fmtDate = (d) => d ? new Date(d+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short',year:'numeric'}) : '—';
  const statoPill = (s) => {
    const m = { attesa:'#e67e22', confermata:'#1f5d83', in_corso:'#27ae60', completata:'#7a7068', cancellata:'#c0392b' };
    return <span style={{ fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:'.05em', color:'#fff', background: m[s]||'#aaa', padding:'1px 7px', borderRadius:10 }}>{s?.replace('_',' ')}</span>;
  };

  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.45)', zIndex: 700, display: 'flex', alignItems: 'flex-start', justifyContent: 'flex-end' }}>
      <div style={{ background: 'var(--bg)', width: 480, maxWidth: '95vw', height: '100vh', overflow: 'auto', boxShadow: '-8px 0 40px rgba(0,0,0,.2)', padding: '28px 28px' }}>
        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
          <div>
            <h2 style={{ margin: 0, fontSize: 20, fontFamily: 'var(--font-serif)', fontWeight: 600 }}>
              {cliente.cognome} {cliente.nome}
            </h2>
            <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 3 }}>
              {cliente.cittadinanza} · {cliente.docTipo}: {cliente.docNum}
            </div>
          </div>
          <button type="button" onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--muted)', fontSize: 22 }}>×</button>
        </div>

        {/* KPI */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginBottom: 20 }}>
          {[
            { label: 'Prenotazioni', value: preno.length },
            { label: 'Pratiche', value: contr.length },
            { label: 'Spesa totale', value: `€${spesaTotale.toLocaleString('it-IT')}` },
            { label: 'Acconti', value: `€${accontiTotali.toLocaleString('it-IT')}` },
          ].map(k => (
            <div key={k.label} style={{ background: 'var(--surface-2)', borderRadius: 6, padding: '10px 14px' }}>
              <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--muted)', marginBottom: 4 }}>{k.label}</div>
              <div style={{ fontSize: 18, fontWeight: 700, fontFamily: 'var(--font-serif)', color: 'var(--ink)' }}>{k.value}</div>
            </div>
          ))}
        </div>

        {ultimaVisita && (
          <div style={{ fontSize: 12, color: 'var(--ink-2)', marginBottom: 16, padding: '8px 12px', background: 'var(--surface-2)', borderRadius: 6 }}>
            <span style={{ fontWeight: 600 }}>Ultima visita:</span> {fmtDate(ultimaVisita)}
            {topCat.length > 0 && <span style={{ marginLeft: 12 }}>· <span style={{ fontWeight: 600 }}>Preferisce:</span> {topCat.map(([c]) => c).join(', ')}</span>}
          </div>
        )}

        {/* Contatti */}
        {(cliente.tel || cliente.email) && (
          <div style={{ marginBottom: 20, padding: '10px 14px', background: 'var(--surface-2)', borderRadius: 6, fontSize: 13 }}>
            {cliente.tel && <div style={{ marginBottom: 4 }}><Phone style={{ width: 13, height: 13, display: 'inline', marginRight: 6 }} /><span className="mono">{cliente.tel}</span></div>}
            {cliente.email && <div><Mail style={{ width: 13, height: 13, display: 'inline', marginRight: 6 }} />{cliente.email}</div>}
          </div>
        )}

        {/* Lista prenotazioni */}
        <div style={{ fontSize: 12, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em', color: 'var(--ink-2)', marginBottom: 10 }}>
          Prenotazioni ({preno.length})
        </div>
        {preno.length === 0 ? (
          <div style={{ fontSize: 12, color: 'var(--muted)', fontStyle: 'italic', marginBottom: 20 }}>Nessuna prenotazione</div>
        ) : (
          <div style={{ marginBottom: 24 }}>
            {preno.map(p => (
              <div key={p.id} style={{ borderBottom: '1px solid var(--border)', padding: '10px 0', display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 10 }}>
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600, fontSize: 13, marginBottom: 3 }}>{p.vehicleLabel}</div>
                  <div style={{ fontSize: 11, color: 'var(--muted)' }}>{fmtDate(p.dal)} → {fmtDate(p.al)}</div>
                  {p.acconto > 0 && <div style={{ fontSize: 11, color: 'var(--muted)' }}>Acconto €{p.acconto}</div>}
                </div>
                <div style={{ textAlign: 'right', flexShrink: 0 }}>
                  {statoPill(p.stato)}
                  {p.prezzo > 0 && <div style={{ fontSize: 13, fontWeight: 700, fontFamily: 'monospace', color: 'var(--ink)', marginTop: 4 }}>€{p.prezzo}</div>}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Lista pratiche */}
        {contr.length > 0 && (
          <>
            <div style={{ fontSize: 12, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em', color: 'var(--ink-2)', marginBottom: 10 }}>
              Pratiche CARGOS ({contr.length})
            </div>
            {contr.map(c => (
              <div key={c.contractId} style={{ borderBottom: '1px solid var(--border)', padding: '8px 0', display: 'flex', justifyContent: 'space-between', fontSize: 12 }}>
                <div>
                  <span style={{ fontFamily: 'monospace', fontSize: 11, color: 'var(--muted)' }}>{c.contractId}</span>
                  <span style={{ marginLeft: 8 }}>{c.record?.tipoVeicolo || '—'}</span>
                </div>
                <span style={{ color: 'var(--muted)' }}>{fmtDate(c.createdAt?.slice(0,10))}</span>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// SCADENZE FLOTTA
// Traccia revisione, assicurazione, tagliando, bollo per ogni mezzo.
// Persistente su edo:v1:scadenze — sincronizzato su tutti i tablet.
// Badge colorato in FleetPage; widget riassuntivo in Dashboard.
// ═══════════════════════════════════════════════════════════════════
const SCADENZE_TIPI = {
  revisione:      { label: 'Revisione',     icon: '🔧', urgencyDays: 30 },
  assicurazione:  { label: 'Assicurazione', icon: '🛡',  urgencyDays: 30 },
  tagliando:      { label: 'Tagliando',     icon: '⚙️',  urgencyDays: 14 },
  bollo:          { label: 'Bollo',         icon: '📄',  urgencyDays: 30 },
};

// Restituisce 'scaduto' | 'urgente' | 'ok' | null per una data ISO
function scadenzaStatus(dataISO) {
  if (!dataISO) return null;
  const today  = new Date(); today.setHours(0,0,0,0);
  const target = new Date(dataISO + 'T00:00:00');
  const diffDays = Math.round((target - today) / 86400000);
  if (diffDays < 0)  return 'scaduto';
  if (diffDays <= 30) return 'urgente';
  return 'ok';
}

const SCAD_COLOR = {
  scaduto: { bg: '#fdecea', border: '#c0392b', text: '#c0392b', dot: '#c0392b' },
  urgente: { bg: '#fff8e6', border: '#e67e22', text: '#d35400', dot: '#e67e22' },
  ok:      { bg: '#eafaf1', border: '#27ae60', text: '#1e8449', dot: '#27ae60' },
};

// Calcola il peggiore stato scadenze per un veicolo
function worstScadenza(vehScadenze) {
  if (!vehScadenze) return null;
  const statuses = Object.values(vehScadenze).map(s => scadenzaStatus(s?.data)).filter(Boolean);
  if (statuses.includes('scaduto')) return 'scaduto';
  if (statuses.includes('urgente')) return 'urgente';
  if (statuses.includes('ok'))      return 'ok';
  return null;
}

// Badge inline per FleetPage
function ScadenzaBadge({ stato }) {
  if (!stato) return null;
  const c = SCAD_COLOR[stato];
  const label = stato === 'scaduto' ? 'Scaduto' : stato === 'urgente' ? 'In scadenza' : null;
  if (!label) return null;
  return (
    <span style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.04em', padding: '2px 7px', borderRadius: 10, background: c.bg, color: c.text, border: `1px solid ${c.border}`, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
      <span style={{ width: 5, height: 5, borderRadius: '50%', background: c.dot, display: 'inline-block' }} />
      {label}
    </span>
  );
}

// Modal per gestire tutte le scadenze di un veicolo
function ScadenzeModal({ vehicle, scadenze, onSave, onClose }) {
  const initVeh = scadenze?.[vehicle.id] || {};
  const [draft, setDraft] = useState(() =>
    Object.fromEntries(Object.keys(SCADENZE_TIPI).map(k => [k, { data: initVeh[k]?.data || '', note: initVeh[k]?.note || '' }]))
  );
  const [saved, setSaved] = useState(false);

  const set = (tipo, field, val) => setDraft(d => ({ ...d, [tipo]: { ...d[tipo], [field]: val } }));

  const handleSave = () => {
    onSave({ ...scadenze, [vehicle.id]: draft });
    setSaved(true);
    setTimeout(() => { setSaved(false); onClose(); }, 900);
  };

  const oggi = todayISO();
  const inputStyle = { width: '100%', padding: '7px 10px', border: '1px solid var(--border)', borderRadius: 5, fontSize: 13, background: 'var(--bg)', color: 'var(--ink)', fontFamily: 'var(--font-sans)', boxSizing: 'border-box' };

  return (
    <div className="modal-overlay" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.45)', zIndex: 800, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div className="modal-box" style={{ background: 'var(--bg)', borderRadius: 10, padding: '28px 32px', width: 520, maxWidth: '95vw', maxHeight: '90vh', overflow: 'auto', boxShadow: '0 20px 60px rgba(0,0,0,.25)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
          <div>
            <h2 style={{ margin: 0, fontSize: 18, fontFamily: 'var(--font-serif)', fontWeight: 600 }}>Scadenze mezzo</h2>
            <div style={{ fontSize: 13, color: 'var(--muted)', marginTop: 3 }}>
              {vehicle.targa} · {vehicle.marca} {vehicle.modello}
            </div>
          </div>
          <button type="button" onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--muted)', fontSize: 22 }}>×</button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {Object.entries(SCADENZE_TIPI).map(([tipo, def]) => {
            const val  = draft[tipo];
            const stato = scadenzaStatus(val.data);
            const c = stato ? SCAD_COLOR[stato] : null;
            const diffDays = val.data ? Math.round((new Date(val.data+'T00:00:00') - new Date(oggi+'T00:00:00')) / 86400000) : null;
            return (
              <div key={tipo} style={{ padding: '14px 16px', border: `1.5px solid ${c ? c.border : 'var(--border)'}`, borderRadius: 8, background: c ? c.bg : 'var(--surface-2)' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
                  <span style={{ fontSize: 16 }}>{def.icon}</span>
                  <span style={{ fontWeight: 700, fontSize: 14, color: c ? c.text : 'var(--ink)' }}>{def.label}</span>
                  {stato && <ScadenzaBadge stato={stato} />}
                  {diffDays !== null && (
                    <span style={{ fontSize: 11, color: 'var(--muted)', marginLeft: 'auto' }}>
                      {diffDays < 0 ? `${Math.abs(diffDays)}gg fa` : diffDays === 0 ? 'Oggi' : `tra ${diffDays} gg`}
                    </span>
                  )}
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                  <div>
                    <label style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--ink-2)', display: 'block', marginBottom: 4 }}>Data scadenza</label>
                    <input type="date" value={val.data} onChange={e => set(tipo, 'data', e.target.value)} style={inputStyle} />
                  </div>
                  <div>
                    <label style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--ink-2)', display: 'block', marginBottom: 4 }}>Nota</label>
                    <input type="text" value={val.note} onChange={e => set(tipo, 'note', e.target.value)} placeholder="Officina, riferimento…" style={inputStyle} />
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        <div style={{ display: 'flex', gap: 10, marginTop: 20 }}>
          <button type="button" onClick={handleSave}
            style={{ flex: 1, padding: '10px', background: saved ? '#27ae60' : 'var(--ink)', color: '#fff', border: 'none', borderRadius: 5, fontSize: 14, fontWeight: 600, cursor: 'pointer', transition: 'background .2s' }}>
            {saved ? '✓ Salvato' : 'Salva scadenze'}
          </button>
          <button type="button" onClick={onClose}
            style={{ padding: '10px 20px', background: 'var(--surface-2)', color: 'var(--ink)', border: '1px solid var(--border)', borderRadius: 5, fontSize: 14, cursor: 'pointer' }}>
            Annulla
          </button>
        </div>
      </div>
    </div>
  );
}

// Widget scadenze per Dashboard — mostra i mezzi con problemi
function ScadenzeWidget({ fleet, scadenze, onGoFlotta }) {
  const today = todayISO();

  const problemi = useMemo(() => {
    const result = [];
    (fleet || []).forEach(v => {
      if (v.stato === 'venduto') return;
      const vScad = scadenze?.[v.id];
      if (!vScad) return;
      Object.entries(SCADENZE_TIPI).forEach(([tipo, def]) => {
        const data = vScad[tipo]?.data;
        if (!data) return;
        const stato = scadenzaStatus(data);
        if (stato === 'ok') return;
        const diffDays = Math.round((new Date(data+'T00:00:00') - new Date(today+'T00:00:00')) / 86400000);
        result.push({ vehicle: v, tipo, def, data, stato, diffDays });
      });
    });
    return result.sort((a,b) => a.diffDays - b.diffDays).slice(0, 6);
  }, [fleet, scadenze, today]);

  if (problemi.length === 0) return null;

  const scaduti = problemi.filter(p => p.stato === 'scaduto').length;
  const urgenti = problemi.filter(p => p.stato === 'urgente').length;

  return (
    <div className="card-paper" style={{ marginBottom: 20 }}>
      <div className="px-5 py-4 border-b flex items-center justify-between" style={{ borderColor: 'var(--border)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <AlertTriangle className="w-4 h-4" style={{ color: scaduti > 0 ? '#c0392b' : '#e67e22' }} />
          <h3 className="serif text-lg font-medium">Scadenze mezzo</h3>
          {scaduti > 0 && <span style={{ fontSize: 10, fontWeight: 700, background: '#fdecea', color: '#c0392b', border: '1px solid #c0392b', padding: '1px 7px', borderRadius: 10 }}>{scaduti} SCADUTI</span>}
          {urgenti > 0 && <span style={{ fontSize: 10, fontWeight: 700, background: '#fff8e6', color: '#d35400', border: '1px solid #e67e22', padding: '1px 7px', borderRadius: 10 }}>{urgenti} urgenti</span>}
        </div>
        <button type="button" onClick={onGoFlotta}
          style={{ fontSize: 12, color: 'var(--ink-2)', background: 'none', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 4 }}>
          Gestisci <ChevronRight className="w-3 h-3" />
        </button>
      </div>
      <div style={{ padding: '8px 0' }}>
        {problemi.map((p, i) => {
          const c = SCAD_COLOR[p.stato];
          return (
            <div key={`${p.vehicle.id}-${p.tipo}`} style={{ padding: '8px 20px', display: 'flex', alignItems: 'center', gap: 12, borderBottom: i < problemi.length-1 ? '1px solid var(--border)' : 'none' }}>
              <span style={{ fontSize: 14 }}>{p.def.icon}</span>
              <div style={{ flex: 1 }}>
                <span style={{ fontWeight: 600, fontSize: 13 }}>{p.vehicle.targa}</span>
                <span style={{ fontSize: 12, color: 'var(--muted)', marginLeft: 6 }}>{p.vehicle.marca} {p.vehicle.modello}</span>
                <span style={{ fontSize: 12, color: 'var(--muted)', marginLeft: 6 }}>· {p.def.label}</span>
              </div>
              <div style={{ textAlign: 'right' }}>
                <ScadenzaBadge stato={p.stato} />
                <div style={{ fontSize: 10, color: 'var(--muted)', marginTop: 2 }}>
                  {p.diffDays < 0 ? `${Math.abs(p.diffDays)} giorni fa` : p.diffDays === 0 ? 'Oggi' : `${p.diffDays} giorni`}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// REMINDER WHATSAPP — ritiri e rientri del giorno
// Widget Dashboard: mostra prenotazioni con ritiro oggi/domani
// e rientri attesi oggi. Link WhatsApp pre-compilato per ogni cliente.
// ═══════════════════════════════════════════════════════════════════
function buildWAReminder(preno, agency, tipo) {
  const nome   = [preno.clienteNome, preno.clienteCognome].filter(Boolean).join(' ') || 'cliente';
  const mezzo  = preno.vehicleLabel || 'mezzo';
  const agenzia = agency?.nome || 'Edonoleggio';
  const tel     = agency?.telefono ? `\nInfo: ${agency.telefono}` : '';

  let testo = '';
  if (tipo === 'ritiro_oggi') {
    testo = `Ciao ${nome}! 👋\nTi confermiamo il noleggio di un/una *${mezzo}* per *oggi ${preno.dal}*.\nPuoi ritirare il mezzo presso ${agenzia}, Lampedusa.${tel}\n\nA presto! 🌊`;
  } else if (tipo === 'ritiro_domani') {
    testo = `Ciao ${nome}! 👋\nTi ricordiamo che domani inizia il tuo noleggio: *${mezzo}* dal *${preno.dal}*.\nPassaci a trovare domani mattina presso ${agenzia}, Lampedusa.${tel}\n\nA presto! 🌊`;
  } else if (tipo === 'rientro') {
    testo = `Ciao ${nome}! 👋\nTi ricordiamo che oggi *${preno.al}* è l'ultimo giorno del tuo noleggio.\nPuoi riconsegnare il mezzo presso ${agenzia} entro le ore 19:00.${tel}\n\nGrazie e arrivederci! 🌊`;
  }

  const rawPhone = (preno.clienteTel || '').replace(/\D/g,'').replace(/^0+/,'');
  const phone = rawPhone.startsWith('390') ? rawPhone.replace(/^390/,'39') : rawPhone;
  const base  = phone ? `https://wa.me/${phone.startsWith('39') ? phone : '39'+phone}` : 'https://wa.me/';
  return `${base}?text=${encodeURIComponent(testo)}`;
}

function RitiriWidget({ prenotazioni, agency, setPage }) {
  const today    = todayISO();
  const tomorrow = localDateISO(1);

  const ritiriOggi   = (prenotazioni||[]).filter(p => p.dal === today    && p.stato !== 'cancellata' && p.fonte !== 'rentme');
  const ritiriDomani = (prenotazioni||[]).filter(p => p.dal === tomorrow  && p.stato !== 'cancellata' && p.fonte !== 'rentme');
  const rientriOggi  = (prenotazioni||[]).filter(p => p.al === today     && p.stato !== 'cancellata' && p.fonte !== 'rentme' && p.stato !== 'completata');

  const total = ritiriOggi.length + ritiriDomani.length + rientriOggi.length;
  if (total === 0) return null;

  const fmtName = (p) => [p.clienteCognome, p.clienteNome].filter(Boolean).join(' ') || '—';

  const Row = ({ p, tipo }) => {
    const waUrl   = buildWAReminder(p, agency, tipo);
    const hasTel  = !!(p.clienteTel || '').trim();
    const tipoLabel = tipo === 'ritiro_oggi' ? 'Consegna oggi' : tipo === 'ritiro_domani' ? 'Consegna domani' : 'Rientro oggi';
    const tipoColor = tipo === 'rientro' ? '#7d3c98' : tipo === 'ritiro_oggi' ? '#27ae60' : '#1f5d83';
    return (
      <div style={{ padding: '10px 20px', display: 'flex', alignItems: 'center', gap: 12, borderBottom: '1px solid var(--border)' }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 600, fontSize: 13, display: 'flex', alignItems: 'center', gap: 8 }}>
            {fmtName(p)}
            <span style={{ fontSize: 10, fontWeight: 700, background: tipoColor+'18', color: tipoColor, border: `1px solid ${tipoColor}44`, padding: '1px 7px', borderRadius: 10, textTransform: 'uppercase', letterSpacing: '.04em' }}>{tipoLabel}</span>
          </div>
          <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 2 }}>
            {p.vehicleLabel}
            {p.clienteTel && <span style={{ marginLeft: 8 }}>· {p.clienteTel}</span>}
          </div>
        </div>
        <a href={waUrl} target="_blank" rel="noopener noreferrer"
          title={hasTel ? `WhatsApp a ${p.clienteTel}` : 'Nessun telefono — si aprirà WhatsApp vuoto'}
          style={{ display: 'inline-flex', alignItems: 'center', gap: 5, padding: '5px 12px', background: hasTel ? '#25d366' : '#aaa', color: '#fff', borderRadius: 5, textDecoration: 'none', fontSize: 12, fontWeight: 600, flexShrink: 0 }}>
          <Send className="w-3 h-3" /> WhatsApp
        </a>
      </div>
    );
  };

  const [aperto, setAperto] = useState(false);

  return (
    <div className="card-paper" style={{ marginBottom: 20 }}>
      {/* Header cliccabile — collassa/espande il widget */}
      <button
        type="button"
        onClick={() => setAperto(o => !o)}
        style={{ width: '100%', padding: '10px 20px', display: 'flex', alignItems: 'center', gap: 10,
          background: 'none', border: 'none', cursor: 'pointer', textAlign: 'left' }}
      >
        <PhoneCall className="w-4 h-4" style={{ color: '#27ae60' }} />
        <span className="serif font-medium" style={{ fontSize: 15 }}>Reminder WhatsApp</span>
        <span style={{ fontSize: 11, color: 'var(--muted)', background: 'var(--surface-2)',
          padding: '1px 7px', borderRadius: 10, fontWeight: 600 }}>
          {total}
        </span>
        <ChevronDown className="w-4 h-4 ml-auto" style={{ color: 'var(--muted)',
          transform: aperto ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s' }} />
      </button>

      {/* Contenuto espandibile */}
      {aperto && (
        <div style={{ borderTop: '1px solid var(--border)' }}>
          {ritiriOggi.map(p   => <Row key={p.id} p={p} tipo="ritiro_oggi" />)}
          {rientriOggi.map(p  => <Row key={p.id} p={p} tipo="rientro" />)}
          {ritiriDomani.map(p => <Row key={p.id} p={p} tipo="ritiro_domani" />)}
        </div>
      )}
    </div>
  );
}

